INSERT INTO `scholar_posts` (`id`, `content`, `mediaUrls`, `fileUrls`, `scholarId`, `createdAt`, `updatedAt`) VALUES ('22ee306b-c158-4030-aec0-21474ff048be', 'Medine halkının ameli, bizim için delildir. Onların yaptığını yapmak, terk ettiğini terk etmek gerekir.', '', '', 2, '2025-09-10 22:17:51.447365', '2025-09-10 22:17:51.447365');
INSERT INTO `scholar_posts` (`id`, `content`, `mediaUrls`, `fileUrls`, `scholarId`, `createdAt`, `updatedAt`) VALUES ('2451d0e8-5f42-4d06-a394-9c8ab321d31d', 'Hadis öğrenmek, Peygamber\'i tanımaktır. Peygamber\'i tanımak, Allah\'ı tanımaktır.', '', '', 9, '2025-09-10 22:17:51.468928', '2025-09-10 22:17:51.468928');
INSERT INTO `scholar_posts` (`id`, `content`, `mediaUrls`, `fileUrls`, `scholarId`, `createdAt`, `updatedAt`) VALUES ('34533bb2-ed5c-49d4-a158-1bd75b34ab4b', 'Hadis ilmi, dinin en önemli ilmidir. Bu ilim olmadan fıkıh olmaz.', '', '', 9, '2025-09-10 22:17:51.468165', '2025-09-10 22:17:51.468165');
INSERT INTO `scholar_posts` (`id`, `content`, `mediaUrls`, `fileUrls`, `scholarId`, `createdAt`, `updatedAt`) VALUES ('3a901cd1-f13f-400b-96b4-a337018c4ca2', 'Gel, ne olursan ol, gel! Kafir, putperest, ateist olsan da gel! Bizim dergahımız umutsuzluk dergahı değil.', '', '', 10, '2025-09-10 22:17:51.470617', '2025-09-10 22:17:51.470617');
INSERT INTO `scholar_posts` (`id`, `content`, `mediaUrls`, `fileUrls`, `scholarId`, `createdAt`, `updatedAt`) VALUES ('4a3747c1-b969-438a-baa4-b647e4acedba', 'İlim öğrenmek, namaz kılmaktan daha faziletlidir. Çünkü ilim, hem kendine hem de başkalarına faydalıdır.', '', '', 1, '2025-09-10 22:17:51.441677', '2025-09-10 22:17:51.441677');
INSERT INTO `scholar_posts` (`id`, `content`, `mediaUrls`, `fileUrls`, `scholarId`, `createdAt`, `updatedAt`) VALUES ('4c9676f2-84b4-4e2b-b66b-10432c0861e2', 'Tasavvuf, kalbi temizlemek ve Allah\'a yaklaşmaktır. Bu olmadan gerçek iman olmaz.', '', '', 5, '2025-09-10 22:17:51.457645', '2025-09-10 22:17:51.457645');
INSERT INTO `scholar_posts` (`id`, `content`, `mediaUrls`, `fileUrls`, `scholarId`, `createdAt`, `updatedAt`) VALUES ('52705b57-23c3-4474-959a-249e00ed3a54', 'Allah\'ın dininde bid\'at çıkarmak, dini bozmaktır. Bid\'atçılar, dini tahrif ederler.', '', '', 4, '2025-09-10 22:17:51.454819', '2025-09-10 22:17:51.454819');
INSERT INTO `scholar_posts` (`id`, `content`, `mediaUrls`, `fileUrls`, `scholarId`, `createdAt`, `updatedAt`) VALUES ('64dccd62-466d-4cab-9598-c1458a5ef653', 'Felsefe ve din, aynı hakikati farklı yollardan arar. İkisi de Allah\'ı tanımaya götürür.', '', '', 7, '2025-09-10 22:17:51.462918', '2025-09-10 22:17:51.462918');
INSERT INTO `scholar_posts` (`id`, `content`, `mediaUrls`, `fileUrls`, `scholarId`, `createdAt`, `updatedAt`) VALUES ('702085f0-7733-4651-867d-198cfd1a8335', 'Dünya, ahiret tarlasıdır. Burada ne ekersen, orada onu biçersin.', '', '', 5, '2025-09-10 22:17:51.456915', '2025-09-10 22:17:51.456915');
INSERT INTO `scholar_posts` (`id`, `content`, `mediaUrls`, `fileUrls`, `scholarId`, `createdAt`, `updatedAt`) VALUES ('78d8858d-2dd3-4522-97df-fb223be7acdb', 'İlim, insanı kemale erdirir. Kemal, Allah\'a yakınlıktır.', '', '', 6, '2025-09-10 22:17:51.460097', '2025-09-10 22:17:51.460097');
INSERT INTO `scholar_posts` (`id`, `content`, `mediaUrls`, `fileUrls`, `scholarId`, `createdAt`, `updatedAt`) VALUES ('7e5a601e-614b-435b-8341-a1f93e41761b', 'Fıkıh, Allah\'ın emirlerini ve yasaklarını bilmektir. Bu ilim olmadan ibadetlerin kabul olması mümkün değildir.', '', '', 1, '2025-09-10 22:17:51.446055', '2025-09-10 22:17:51.446055');
INSERT INTO `scholar_posts` (`id`, `content`, `mediaUrls`, `fileUrls`, `scholarId`, `createdAt`, `updatedAt`) VALUES ('7eb8673a-5222-4395-ab04-fc502643074e', 'Hadis, Peygamber\'in sözü, fiili ve takriridir. Bu üçü de dinin kaynağıdır.', '', '', 8, '2025-09-10 22:17:51.464627', '2025-09-10 22:17:51.464627');
INSERT INTO `scholar_posts` (`id`, `content`, `mediaUrls`, `fileUrls`, `scholarId`, `createdAt`, `updatedAt`) VALUES ('7f3139b6-c381-4d8e-96a0-d505e43ea170', 'İlim öğrenmek isteyen, önce kendini tanımalıdır. Kendini tanıyan, Allah\'ı tanır.', '', '', 3, '2025-09-10 22:17:51.451295', '2025-09-10 22:17:51.451295');
INSERT INTO `scholar_posts` (`id`, `content`, `mediaUrls`, `fileUrls`, `scholarId`, `createdAt`, `updatedAt`) VALUES ('96ffb993-348c-40b4-bbab-c4c834b4c532', 'Fıkıh usulü, şer\'i hükümleri çıkarmanın yollarını öğretir. Bu olmadan doğru hüküm verilemez.', '', '', 3, '2025-09-10 22:17:51.452169', '2025-09-10 22:17:51.452169');
INSERT INTO `scholar_posts` (`id`, `content`, `mediaUrls`, `fileUrls`, `scholarId`, `createdAt`, `updatedAt`) VALUES ('9b55294d-e17e-454e-833c-d3291581334f', 'Hadis ricali, dinin koruyucularıdır. Onlar olmasa, din bozulurdu.', '', '', 8, '2025-09-10 22:17:51.465287', '2025-09-10 22:17:51.465287');
INSERT INTO `scholar_posts` (`id`, `content`, `mediaUrls`, `fileUrls`, `scholarId`, `createdAt`, `updatedAt`) VALUES ('a3522a12-9232-41b2-8086-eb829610ad27', 'Sahih hadis, kesin bilgi verir. Bu bilgi olmadan din olmaz.', '', '', 8, '2025-09-10 22:17:51.465960', '2025-09-10 22:17:51.465960');
INSERT INTO `scholar_posts` (`id`, `content`, `mediaUrls`, `fileUrls`, `scholarId`, `createdAt`, `updatedAt`) VALUES ('aa204c9d-4388-4177-9772-08ed2f2f57f3', 'Felsefe, varlığın hakikatini araştırmaktır. Bu araştırma, Allah\'ı tanımaya götürür.', '', '', 6, '2025-09-10 22:17:51.459410', '2025-09-10 22:17:51.459410');
INSERT INTO `scholar_posts` (`id`, `content`, `mediaUrls`, `fileUrls`, `scholarId`, `createdAt`, `updatedAt`) VALUES ('ab38233a-7b58-4216-bc6e-77bae6be0937', 'İnsan, aynada kendini görür. Allah\'ı görmek isteyen, kendi kalbine baksın.', '', '', 10, '2025-09-10 22:17:51.471268', '2025-09-10 22:17:51.471268');
INSERT INTO `scholar_posts` (`id`, `content`, `mediaUrls`, `fileUrls`, `scholarId`, `createdAt`, `updatedAt`) VALUES ('bbc61e35-be1b-49d8-95f5-f0a669f2a308', 'Akıl, Allah\'ın insana verdiği en büyük nimettir. Aklı kullanmak, ibadettir.', '', '', 7, '2025-09-10 22:17:51.463700', '2025-09-10 22:17:51.463700');
INSERT INTO `scholar_posts` (`id`, `content`, `mediaUrls`, `fileUrls`, `scholarId`, `createdAt`, `updatedAt`) VALUES ('cc06abf0-7b31-4144-bd6f-fb34c7d1ba4a', 'Kur\'an\'ı anlamak için Arap dilini bilmek şarttır. Arapça bilmeyen, Kur\'an\'ı tam anlayamaz.', '', '', 3, '2025-09-10 22:17:51.450081', '2025-09-10 22:17:51.450081');
INSERT INTO `scholar_posts` (`id`, `content`, `mediaUrls`, `fileUrls`, `scholarId`, `createdAt`, `updatedAt`) VALUES ('d189782b-cac5-4364-8d69-95fc8f346a95', 'Tıp, insan sağlığını koruma sanatıdır. Sağlık, en büyük nimettir.', '', '', 6, '2025-09-10 22:17:51.458680', '2025-09-10 22:17:51.458680');
INSERT INTO `scholar_posts` (`id`, `content`, `mediaUrls`, `fileUrls`, `scholarId`, `createdAt`, `updatedAt`) VALUES ('d51a3e03-1a84-4ed2-9bd8-f5a51f796a95', 'Aşk, her şeyin anahtarıdır. Aşk olmadan hiçbir şey anlaşılmaz.', '', '', 10, '2025-09-10 22:17:51.469932', '2025-09-10 22:17:51.469932');
INSERT INTO `scholar_posts` (`id`, `content`, `mediaUrls`, `fileUrls`, `scholarId`, `createdAt`, `updatedAt`) VALUES ('dd450d55-1dc8-4955-b11b-e1fb19b05cf2', 'İlim, kalbi aydınlatır. Kalbi aydınlanan, Allah\'ı görür gibi bilir.', '', '', 5, '2025-09-10 22:17:51.456150', '2025-09-10 22:17:51.456150');
INSERT INTO `scholar_posts` (`id`, `content`, `mediaUrls`, `fileUrls`, `scholarId`, `createdAt`, `updatedAt`) VALUES ('e729ee62-ad12-4c8d-aa66-4c84e1be12d2', 'İlim, Allah\'tan korkmakla başlar. Allah\'tan korkmayanın ilmi, kendisine fayda vermez.', '', '', 2, '2025-09-10 22:17:51.448284', '2025-09-10 22:17:51.448284');
INSERT INTO `scholar_posts` (`id`, `content`, `mediaUrls`, `fileUrls`, `scholarId`, `createdAt`, `updatedAt`) VALUES ('f1e5a475-a593-417a-bcb0-8c3905cae390', 'Allah\'ın rızasını kazanmak için çalışan kimse, dünyada da ahirette de mutlu olur.', '', '', 1, '2025-09-10 22:17:51.444710', '2025-09-10 22:17:51.444710');
INSERT INTO `scholar_posts` (`id`, `content`, `mediaUrls`, `fileUrls`, `scholarId`, `createdAt`, `updatedAt`) VALUES ('fe02d9ee-d5c9-48f9-aef4-c875f61ab7b3', 'Hadis, dinin temelidir. Hadis olmadan din olmaz. Bu yüzden hadis öğrenmek farzdır.', '', '', 4, '2025-09-10 22:17:51.453687', '2025-09-10 22:17:51.453687');
