INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (20452, 'ABDULLAH BİN MUHAMMED BİN ASKER', 'Hadîs âlimi. İsmi, Abdullah bin Muhammed bin Asker bin Muzaffer bin Necm  bin  fâdî  bin  Hilâl  olup,  künyesi  Ebû  Muhammed’dir.  Lakabı ferefüddîn’dir. Allâme Burhânüddîn’in babasıdır. 672 (m. 1273) senesinde Belbis adlı köyde doğdu. 739 (m. 1338) senesinde Dımeşk’da vefât etti. Abdullah bin Muhammed; ed-Dimyâtî, İbn-i Dakîk-ıl-Iyd, fihâb bin Ali el- Mahsinî, Ebü’l-Hasen bin Hârûn ve bir çok âlimden hadîs-i şerîf dinledi ve rivâyet etti. Fıkıh ilmini, İbn-i Rif’a ve İbn-i Kammah’dan öğrendi. 700 (m. 1300)  senesinde  İskenderiyye’ye  gitti  ve  orada  usûl  ilmini  el-Bâcî  ve  el- Cezerî’den, Arab dili ve edebiyatının inceliklerini Ebû Hayyân’dan öğrendi. Abdullah  bin  Muhammed;  Dimyât  Esyût  ve  el-Menûfiyye’de  kadılık görevinde bulundu. Bunun yanında el-Medreset-ül-Mücâvira ve el-Meşhed- ün-Nefîsî’de ders okuttu. Haleb kadılığına ta’yin olduğu zaman, sultandan özür diliyerek bu vazîfeyi kabûl etmedi. Bundan sonra Câmi’ul-ezher’de bir müddet ilimle meşgûl oldu. Abdullah bin Muhammed, huyu ve ahlâkı güzel bir zât idi. Kendi eliyle eserler  yazdı.  Bir  şiirinde  özetle  şöyle  demektedir:  “Hayâtımın güzelliklerine,  onlardan  ayrılırken  veda  ettim.  fimdi  gözlerim  ağlamakta, kalbim  yanmaktadır.  Hayâtımın  günleri  heder  olup  gitti.  Ancak  geriye hayâller kaldı.”', '739 (m. 1338)', '700 (m. 1300)', '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:32.513779', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Hadîs âlimi. İsmi, Abdullah bin Muhammed bin Asker bin Muzaffer bin Necm  bin  fâdî  bin  Hilâl  olup,  künyesi  Ebû  Muhammed’dir.  Lakabı ferefüddîn’dir. Allâme Burhânüddîn’in babasıdır. 672 (m. 1273) senesinde Belbis adlı köyde doğdu. 739 (m. 1338) senesinde Dımeşk’da vefât etti. Abdullah bin Muhammed; ed-Dimyâtî, İbn-i Dakîk-ıl-Iyd, fihâb bin Ali el- Mahsinî, Ebü’l-Hasen bin Hârûn ve bir çok âlimden hadîs-i şerîf dinledi ve rivâyet etti. Fıkıh ilmini, İbn-i Rif’a ve İbn-i Kammah’dan öğrendi. 700 (m. 1300)  senesinde  İskenderiyye’ye  gitti  ve  orada  usûl  ilmini  el-Bâcî  ve  el- Cezerî’den, Arab dili ve edebiyatının inceliklerini Ebû Hayyân’dan öğrendi. Abdullah  bin  Muhammed;  Dimyât  Esyût  ve  el-Menûfiyye’de  kadılık görevinde bulundu. Bunun yanında el-Medreset-ül-Mücâvira ve el-Meşhed- ün-Nefîsî’de ders okuttu. Haleb kadılığına ta’yin olduğu zaman, sultandan özür diliyerek bu vazîfeyi kabûl etmedi. Bundan sonra Câmi’ul-ezher’de bir müddet ilimle meşgûl oldu. Abdullah bin Muhammed, huyu ve ahlâkı güzel bir zât idi. Kendi eliyle eserler  yazdı.  Bir  şiirinde  özetle  şöyle  demektedir:  “Hayâtımın güzelliklerine,  onlardan  ayrılırken  veda  ettim.  fimdi  gözlerim  ağlamakta, kalbim  yanmaktadır.  Hayâtımın  günleri  heder  olup  gitti.  Ancak  geriye hayâller kaldı.”');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (20453, 'ABDULLAH BİN MUHAMMED BELHÎ', 'Hadîs  âlimi  ve  tarihçi.  İsmi  Abdullah  bin  Muhammed  bin  Sûre  bin Muhammed bin İbrâhîm el-Belhî olup künyesi, Ebû Ali’dir. Belh’de doğmuş olup doğum târihi tesbit edilememiştir. Uzun müddet Bağdâd’da kalmıştır. 295 (m. 907)’de vefât etti. Mekkî bin İbrâhîm el-Belhî, Ali bin Muhammed el-Hanzâlî,  Abdüssamed  bin  Hassan  el-Mervezî,  İbrâhîm  bin  femmâs  es- Semerkandî, Assam bin Yûsuf el-Kâdî ve daha birçok âlimden ilim öğrenmiş ve rivâyette bulunmuştur. Ebû Bekir bin Ebî’d-Dünyâ, Mûsâ bin Hârûn ve bir çok âlim de ondan ilim almışdır. Muhammed bin Muhalled O’nun sika (sağlam, güvenilir) bir râvi olduğunu söylemiştir. Büyük bir  muhaddis  olan  Abdullah  bin  Muhammed  aynı  zamanda hafızdır.  Ya’nî  yüzbin  hadîs-i  şerîfi  sened  ve  râvileriyle  bilen  bir  zâttır. Bunun yanında önemli bir tarihçidir. Kitâb-ül-i’lel ve Kitâb-üt-târih isimli iki Abdullah bin Muhammed el-Belhî, Ali bin Muhammed, Ebû Ca’fer er-Râdî Hişâm  bin  Urve’den,  o  da  babasından,  o  da  Hazret-i  Âişeden  rivâyetle Resûlullah  (aleyhisselâm)  “Secde-i  sehv,  namazdaki  her  noksanlık  ve ziyâdelikten dolayı bir cezadır” buyurdu.', NULL, '907', '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:32.515954', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Hadîs  âlimi  ve  tarihçi.  İsmi  Abdullah  bin  Muhammed  bin  Sûre  bin Muhammed bin İbrâhîm el-Belhî olup künyesi, Ebû Ali’dir. Belh’de doğmuş olup doğum târihi tesbit edilememiştir. Uzun müddet Bağdâd’da kalmıştır. 295 (m. 907)’de vefât etti. Mekkî bin İbrâhîm el-Belhî, Ali bin Muhammed el-Hanzâlî,  Abdüssamed  bin  Hassan  el-Mervezî,  İbrâhîm  bin  femmâs  es- Semerkandî, Assam bin Yûsuf el-Kâdî ve daha birçok âlimden ilim öğrenmiş ve rivâyette bulunmuştur. Ebû Bekir bin Ebî’d-Dünyâ, Mûsâ bin Hârûn ve bir çok âlim de ondan ilim almışdır. Muhammed bin Muhalled O’nun sika (sağlam, güvenilir) bir râvi olduğunu söylemiştir. Büyük bir  muhaddis  olan  Abdullah  bin  Muhammed  aynı  zamanda hafızdır.  Ya’nî  yüzbin  hadîs-i  şerîfi  sened  ve  râvileriyle  bilen  bir  zâttır. Bunun yanında önemli bir tarihçidir. Kitâb-ül-i’lel ve Kitâb-üt-târih isimli iki Abdullah bin Muhammed el-Belhî, Ali bin Muhammed, Ebû Ca’fer er-Râdî Hişâm  bin  Urve’den,  o  da  babasından,  o  da  Hazret-i  Âişeden  rivâyetle Resûlullah  (aleyhisselâm)  “Secde-i  sehv,  namazdaki  her  noksanlık  ve ziyâdelikten dolayı bir cezadır” buyurdu.');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (20454, 'ABDULLAH BİN MUHAMMED BUHÂRÎ', 'fafiî mezhebinde meşhûr fıkıh âlimlerinden. Künyesi, Ebû Muhammed el-Buhârî, eş-fâfiî’dir. Bağdâd’da yaşamıştır. 398 (m. 1007) senesinde vefât etti. Fıkıh ilminde zamanının en meşhûr âlimi idi. Fıkıh ilmini Ebû Ali bin Ebî Hüreyre ve Ebû İshâk el-Mervezî’den öğrendi. Kendisinden ise Kâdı Ebû Tayyib Mâverdî ve pek çok kimse fıkıh ilmini öğrendi. Abdullah bin Muhammed, fıkıh ilminden başka nahiv ve edebiyatta üstün derecede idi. Fasîh ve belîğ konuşan, hoş sohbet bir âlim idi. Ayrıca şâir olup, şiirleri meşhûrdur. fiirlerinden ba’zı beyitler şunlardır: “faşıyorum kendini beğenene, Dün bir nutfe iken bugün hâli ne! Yarın bu güzellik bir son bulacak, Kabrinde kokuşup bir leş olacak. Yyle gurûrlanıp nasıl yaşıyor, iki gün arası pislik', NULL, '1007', '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:32.516009', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'fafiî mezhebinde meşhûr fıkıh âlimlerinden. Künyesi, Ebû Muhammed el-Buhârî, eş-fâfiî’dir. Bağdâd’da yaşamıştır. 398 (m. 1007) senesinde vefât etti. Fıkıh ilminde zamanının en meşhûr âlimi idi. Fıkıh ilmini Ebû Ali bin Ebî Hüreyre ve Ebû İshâk el-Mervezî’den öğrendi. Kendisinden ise Kâdı Ebû Tayyib Mâverdî ve pek çok kimse fıkıh ilmini öğrendi. Abdullah bin Muhammed, fıkıh ilminden başka nahiv ve edebiyatta üstün derecede idi. Fasîh ve belîğ konuşan, hoş sohbet bir âlim idi. Ayrıca şâir olup, şiirleri meşhûrdur. fiirlerinden ba’zı beyitler şunlardır: “faşıyorum kendini beğenene, Dün bir nutfe iken bugün hâli ne! Yarın bu güzellik bir son bulacak, Kabrinde kokuşup bir leş olacak. Yyle gurûrlanıp nasıl yaşıyor, iki gün arası pislik');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (20455, 'ABDULLAH BİN MUHAMMED FAKÎH', 'fafiî mezhebi âlimlerinden. Hadîs ve fıkıh âlimlerinin meşhûrlarındandır. İsmi,  Abdullah  bin  Muhammed  bin  Ziyâd  bin  Vâsil  bin  Meymûn  en- Nişâbûrî’dir.  Künyesi,  Ebû  Bekr’dir.  238  (m.  852)  senesinde  Nişâbûr’da doğdu. “İbn-i Ziyâd” adıyla meşhûr oldu. Nişâbûr âlimlerindendir. Buradan Irak, fam,  Mısır  şehirlerine  giderek  ilim  tahsil  etti.  Son  olarak  Bağdâd’a yerleşti. Müzenî’nin “Muhtasar” kitabına zeyl, ilâve yazmıştır. 324 (m. 936) senesinde Rebî’ul-evvel ayında vefât etti. Kûfe’ye yakın bir yere defn edildi. Irak  âlimlerinin meşhûrlarından  olan  Abdullah  bin  Muhammed; Muhammed  bin  Yahyâ  ez-Zühlî,  Ahmed  bin  Yûsuf  es-Sülemî,  Ahmed  bin Ezher,  Ahmed  bin  Hafs  bin  Abdullah  en-Nişâbûreyn, Abdullah bin Hâşim-i Tûsî,  Muhammed  bin  Hüseyn  bin  Eşkâk,  Hasen  bin  Muhammed, Muhammed-ez-Za’ferânî,  Ahmed  bin  Mensûr  er-Ramâdî  ve  daha  başka famlı, Mısırlı, Bağdâdlı pek çok âlimden ilim aldı, hadîs-i şerîf rivâyetinde bulundu.  Kendisinden  de,  Da’lec  bin  Ahmed,  Ebû  Ymer  bin  Hayve, Muhammed  bin  Muzaffer,  Dâre  Kutnî,  İbn-i  fâhîn,  Ymer  bin  İbrâhîm  el- Kattân, Yûsuf el-Kavvâs, Ebû Tâhir el-Muhallîs ve daha pek çok âlim ilim aldılar, hadîs-i şerîf rivâyetinde bulundular. Abdullah  bin  Muhammed,  zamanının  en  meşhûr  fafiî  âlimi  idi.  Hadîs ilminde güvenilir, rivâyetleri sağlam, fıkıh ilminde derin bilgisi olan, hafızası ve müzâkeresi kuvvetli, çok ibâdet eden bir âlimdir. Geceleri hiç uyumaz, ibâdet ederdi. Kırk sene yatsının abdestiyle sabah namazını kıldı. Yemeği çok az yerdi. Dâre Kutnî şöyle anlattır: “Âlimlerimiz arasında, hadîs-i şerîf metinlerini  ve  senedlerini ondan daha iyi bilen birisini görmedim. O, fıkıh ilmini  en  iyi  bilendi.  Müzenî  ve  Rebî’den  ders  aldı.  Hadîs-i  şerîf metnine sonradan yapılan ilâveleri iyi bilen birisi idi. Hadîs-i şerîf okumaya oturduğu zaman  ona  “Bize  hadîs-i  şerîf  rivâyet  edin!” dediler.    Abdullah    bin Muhammed “Peki öyleyse siz sorunuz!” dedi. Hadîs-i şerîfler soruldu, O da cevaplandırdı ve yazdırdı. Hâkim  şöyle  anlatır:  “Abdullah  bin  Muhammed,  zamanının  fıkıh mes’elelerinde ve Sahabenin değişik ictihâdlarında çözüm yolu bulan Irak’ın en meşhûr fafiî âlimi idi.” İbn-i Huzeym, ilim meclisinde: “Onun benzeri birisini görmedim” diye bildirdi. Dâre Kutnî anlatıyor: “Birgün Bağdâd’da bir ilim meclisinde, Ebû Bekr  bin  Ce’ânî,  Ebû  Tâlib  el-Hâfız  ve  daha  başkaları  sohbet  ediyordu. Büyük  bir fıkıh  âlimi  geldi.  Oradakilere:  “Yeryüzünün  her  tarafı  benim ümmetim için mescid, onun toprağı da bizim için temizleyici kılındı” hadîs-i şerîfini  kim  rivâyet  etti?  dedi.  Orada  bulunanlar  da,  filân  filân  kimseler rivâyet ettiler diyerek, teker teker isimlerini söylediler. Bu zât: “fu şu lâfzı soruyorum” dedi. Oradakilerden hiç birisi cevap veremeyip, “Bu sorunuzu Ebû Bekr en-Nişâbûrî’den başkası bilemez” dediler. Gidip ona sordular. O da, o anda ezberinden “fu şu kimsedir ve Sahîh-i Müslim’de bu kısımları Yûsuf bin Amr bin Mesrûr, kendisinin şöyle dediğini bildirdi: “Siz, kırk sene  ayakta  duran,  uyumayan,  beş  buğday  tanesiyle  yetinen,  yatsının abdestiyle  diğer  günün  namazını  kılan  birisini  bilir  misiniz?  işte  ben,  o Kendisi  şöyle  anlatıyor: “Hazret-i  Ymer şöyle  bildirdi:  Ali  (radıyallahü anh)  en  iyi  hüküm  verenimiz,  Ubey  bin  Ka’b  da  en  iyi  Kur’ân-ı  kerîm Onun  rivâyet  ettiği  hadîs-i  şerîflerde  Peygamber  efendimiz  şöyle buyuruyorlar: “Kadın, amcası ve dayısına nikahlanmasın!” “Biz insanlar üzerine üç şey ile üstün kılındık: 1. Saflarımız meleklerin safları gibi yapıldı. 2. Yeryüzünün her tarafı, bizim için mescid kılındı. 3. Su bulamadığımız zaman, toprak da bize temizleyici bir vâsıta oldu.” Eserlerinden ikisi şunlardır: 1. Ziyâdâtü kitâb-il Müzenî, 2. Kitâb-ür-ribâ.', NULL, '852', '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:32.516079', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'fafiî mezhebi âlimlerinden. Hadîs ve fıkıh âlimlerinin meşhûrlarındandır. İsmi,  Abdullah  bin  Muhammed  bin  Ziyâd  bin  Vâsil  bin  Meymûn  en- Nişâbûrî’dir.  Künyesi,  Ebû  Bekr’dir.  238  (m.  852)  senesinde  Nişâbûr’da doğdu. “İbn-i Ziyâd” adıyla meşhûr oldu. Nişâbûr âlimlerindendir. Buradan Irak, fam,  Mısır  şehirlerine  giderek  ilim  tahsil  etti.  Son  olarak  Bağdâd’a yerleşti. Müzenî’nin “Muhtasar” kitabına zeyl, ilâve yazmıştır. 324 (m. 936) senesinde Rebî’ul-evvel ayında vefât etti. Kûfe’ye yakın bir yere defn edildi. Irak  âlimlerinin meşhûrlarından  olan  Abdullah  bin  Muhammed; Muhammed  bin  Yahyâ  ez-Zühlî,  Ahmed  bin  Yûsuf  es-Sülemî,  Ahmed  bin Ezher,  Ahmed  bin  Hafs  bin  Abdullah  en-Nişâbûreyn, Abdullah bin Hâşim-i Tûsî,  Muhammed  bin  Hüseyn  bin  Eşkâk,  Hasen  bin  Muhammed, Muhammed-ez-Za’ferânî,  Ahmed  bin  Mensûr  er-Ramâdî  ve  daha  başka famlı, Mısırlı, Bağdâdlı pek çok âlimden ilim aldı, hadîs-i şerîf rivâyetinde bulundu.  Kendisinden  de,  Da’lec  bin  Ahmed,  Ebû  Ymer  bin  Hayve, Muhammed  bin  Muzaffer,  Dâre  Kutnî,  İbn-i  fâhîn,  Ymer  bin  İbrâhîm  el- Kattân, Yûsuf el-Kavvâs, Ebû Tâhir el-Muhallîs ve daha pek çok âlim ilim aldılar, hadîs-i şerîf rivâyetinde bulundular. Abdullah  bin  Muhammed,  zamanının  en  meşhûr  fafiî  âlimi  idi.  Hadîs ilminde güvenilir, rivâyetleri sağlam, fıkıh ilminde derin bilgisi olan, hafızası ve müzâkeresi kuvvetli, çok ibâdet eden bir âlimdir. Geceleri hiç uyumaz, ibâdet ederdi. Kırk sene yatsının abdestiyle sabah namazını kıldı. Yemeği çok az yerdi. Dâre Kutnî şöyle anlattır: “Âlimlerimiz arasında, hadîs-i şerîf metinlerini  ve  senedlerini ondan daha iyi bilen birisini görmedim. O, fıkıh ilmini  en  iyi  bilendi.  Müzenî  ve  Rebî’den  ders  aldı.  Had