INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (20723, 'BAKIYYE BİN VELÎD', 'Hicrî  ikinci  asırda  fam’da  yetişen  meşhûr  hadîs ve  fıkıh  âlimlerinden. Künyesi, Ebû Yuhmid Külâî’dir. 115 yılında (m. 733) doğdu. 197 (m. 812) senesinde vefât etti. Atiyye isminde bir oğlu vardı. Zürriyeti bu oğlu ile devam etmiştir. Bakıyye hazretleri kuvvetli bir tahsil görmüştür. Muhammed bin Ziyâd, Buhayr  bin  Sa’d,  Ubeydullah  bin  Amr,  Sevr  bin  Yezîd  ve  daha  bir  çok âlimden  ilim  öğrenip  hadîs-i  şerîf  rivâyet  etmiştir.  Hadîste  hafız  yani yüzbinin  üzerinde  hadîs-i  şerîfi  râvîleri  ile  birlikte  ezbere  bilirdi. Kendisinden Evzâî, Nuaym bin Hammâd, Dâvûd İbn-i Reşîd, Ali bin Hacer, Amr bin Osman ve daha bir çok âlim hadîs-i şerîf rivâyet etmiştir. Yahyâ bin Muin,  Ebû  Zur’a  ve  zamanın  diğer  âlimleri;  “Bakıyye  bin  Velîd’in  sika (güvenilir,  sağlam)  âlimlerden  rivâyette  bulunduğu  hadîsler  huccet,  delîl olarak  kabûl  edilir”  demişlerdir.  Abdullah  bin  Mübârek  buyuruyor  ki; “İsmail  bin  Iyaş  ile  Bakıyye’nin  hadîsleri  bir  araya  toplansa,  Bakıyye’nin hadîsleri  bana  daha  sevimli  gelirdi.”  Bakıyye  hazretleri  buyuruyor  ki, Hammâd bin Zeyd ile hadîs müzâkere ettik. Bana buyurdu ki: “Senin rivâyet ettiğin hadîsler ne kadar kıymetli...” Bildirdiği   hadîs-i   şerîfler   Müslim’de,   Buhârî   üzerine   yapılan açıklamalarda, Sünen-i Ebî Dâvûd, Nesâî, Tirmîzî ve Sünen-i İbn-i Mâce adlı eserlerde yer almaktadır. Rivâyet ettiği hadîs-i şeriflerden bazıları: “Kim (bir müslümanın) düğün ve benzeri yerlere davet edilirse icabet “fafak sökmeden önce hilâl kaybolursa gecedendir.”', NULL, '812', '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:32.668129', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Hicrî  ikinci  asırda  fam’da  yetişen  meşhûr  hadîs ve  fıkıh  âlimlerinden. Künyesi, Ebû Yuhmid Külâî’dir. 115 yılında (m. 733) doğdu. 197 (m. 812) senesinde vefât etti. Atiyye isminde bir oğlu vardı. Zürriyeti bu oğlu ile devam etmiştir. Bakıyye hazretleri kuvvetli bir tahsil görmüştür. Muhammed bin Ziyâd, Buhayr  bin  Sa’d,  Ubeydullah  bin  Amr,  Sevr  bin  Yezîd  ve  daha  bir  çok âlimden  ilim  öğrenip  hadîs-i  şerîf  rivâyet  etmiştir.  Hadîste  hafız  yani yüzbinin  üzerinde  hadîs-i  şerîfi  râvîleri  ile  birlikte  ezbere  bilirdi. Kendisinden Evzâî, Nuaym bin Hammâd, Dâvûd İbn-i Reşîd, Ali bin Hacer, Amr bin Osman ve daha bir çok âlim hadîs-i şerîf rivâyet etmiştir. Yahyâ bin Muin,  Ebû  Zur’a  ve  zamanın  diğer  âlimleri;  “Bakıyye  bin  Velîd’in  sika (güvenilir,  sağlam)  âlimlerden  rivâyette  bulunduğu  hadîsler  huccet,  delîl olarak  kabûl  edilir”  demişlerdir.  Abdullah  bin  Mübârek  buyuruyor  ki; “İsmail  bin  Iyaş  ile  Bakıyye’nin  hadîsleri  bir  araya  toplansa,  Bakıyye’nin hadîsleri  bana  daha  sevimli  gelirdi.”  Bakıyye  hazretleri  buyuruyor  ki, Hammâd bin Zeyd ile hadîs müzâkere ettik. Bana buyurdu ki: “Senin rivâyet ettiğin hadîsler ne kadar kıymetli...” Bildirdiği   hadîs-i   şerîfler   Müslim’de,   Buhârî   üzerine   yapılan açıklamalarda, Sünen-i Ebî Dâvûd, Nesâî, Tirmîzî ve Sünen-i İbn-i Mâce adlı eserlerde yer almaktadır. Rivâyet ettiği hadîs-i şeriflerden bazıları: “Kim (bir müslümanın) düğün ve benzeri yerlere davet edilirse icabet “fafak sökmeden önce hilâl kaybolursa gecedendir.”');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (20724, 'BÂKÎ EFENDİ', 'Osmanlılar zamanında yetişen âlimlerden ve şâirlerden. İsmi, Mahmûd Abdülbâkî’dir.  Bâkî  mahlasıyla  tanınan  Mahmûd  Abdülbâkî, Kanuni’den sonra sıra ile padişah olan İkinci Selim, oçüncü Murad ve oçüncü Mehmed Han zamanlarında da zamanının şâir ve edipleri arasında ve ülkenin her tarafında  fairler  Sultanı “Sultân-üş-şu’arâ”  diye  de  meşhûr  olmuştur. Süleymâniyye medresesinde müderris idi. Reîsül-ulemâ oldu. Nişâncı pâşayı cedîd  yanında (Bâkî  efendi  mescidi)ni  yapdırdı. Fâtih  Câmii müezzinlerinden  Mehmed  Efendi’nin  oğludur.  933  (m.  1526)  senesinde İstanbul’da doğdu.  1008  (m.  1600)  senesinde  İstanbul’da  vefât  etti. Edirnekapı  dışında  Eyyûb  Sultan’a  giden  yol  üzerindeki  kabristana  defn Çocukluğunda  bir  müddet  saraç  çıraklığında  çalıştıktan  sonra fıtratındaki  yüksek  kabiliyeti  onu medrese  tahsiline  sevk etti.  Medresede kısa  zamanda  akranları arasında  yükselip,  keskin  zekâsını  ve  kabiliyetini ortaya  koydu.  Zamanının  meşhûr  âlimlerinden  Ahaveyn  diye  bilinen Karamanlı Ahmed ve Mehmed efendilerden aklî ve naklî ilimleri tahsîl edip istifâde etti. 19 yaşlarında iken İstanbul’un genç şâirleri arasında “Sünbül” kasidesi  ile  şöhreti  fazlalaştı.  Medresedeki  ders  arkadaşları  arasında  şâir Nev’î,  osküplü  şâir  Vâlihî,  Hoca  Sa’deddîn  Efendi  gibi  kabiliyetli  gençler 960  (m.  1552) senesinde  Süleymâniye Medresesi  müderrisi  Kâdı-zâde femseddîn Ahmed Efendi’nin tedris halkasına dâhil olup, ondan çok istifâde etti.  Bu  arada  devrin  üstâd  şâiri  Zâtî’nin  şiir  meclislerinde  bulundu.  Zâtî tarafından ondaki şiir kabiliyeti ortaya çıkarılıp teşvik edildi. 960 (m. 1552) senesinde  Nahcivan  seferinden  dönüşünde,  Kanunî  Sultan  Süleymân’a takdim ettiği kaside sebebiyle pâdişâhın lütuf ve ihsânlarına kavuştu. 963 (m. 1555) senesinde hocası Kâdı-zâde Ahmed Efendi, Haleb kadılığına ta’yin olununca  o  da  beraberinde  gitti. hocasına Râiyye; Haleb beylerbeyi Kubâd Paşa’ya da Hilâl kasîdelerini sunmuştur. Dört senelik bir ayrılıktan sonra, İstanbul’a  dönerken  büyük  âlim  Ebüssü’ûd  Efendi’nin  en  büyük  oğlu Mehmed  Çelebi  ile  Konya’da  karşılaşmıştır. 967  (m.  1559)’de  tekrar İstanbul’a döndü. Haleb beylerbeyi Kubâd Paşa’ya takdim ettiği “Hilâl” ve hocası  Kâdı-zâde’ye  takdim  ettiği  “Raiye”  kasidesi  bu  sırada  yazdığı şiirlerdendir,  İstanbul’a  dönerken  Konya’da  feyhülislâm  Ebüssü’ûd Efendi’nin  oğlu  Mehmed  Çelebî  ile  tanıştı.  Ebüssü’ûd  Efendi için  yazmış olduğu “Lâmiyye” kasidesini İstanbul’a gelince takdim etti. 969 (m. 1561) senesinde  Ebüssü’ûd  Efendi’nin  hizmetinde  bulunduğu  sırada  Sadrazam Semiz  Ali  Paşa’ya  takdim  edildi. 969   Safer (m.  1562)  yılında  Molla Merhûm’a  dânişmend,  971  Ramazan  (m. 1563)’de  de  yirmi  beş  akçe  ile müderris  olmuştur. 971   (m.   1563)   senesinde fevval  ayı  ortalarında Silivri’de bulunan Pîri Paşa Medresesi müderrisliğine ta’yin edildi. Rüstem Paşa’dan sonra sadrâzamlığa getirilen Semiz Ali Paşa’ya da kasîdeler sunan Bakî oldukça takdîr gördü. Semiz Ali Paşa ve Mîrâhor Ferhad Ağa vâsıtasıyle Pâdişâh’a  yaklaşarak,  kasîdeler  sunmaya  başladı.  Netîcede  sultânın gönderdiği gazellere söylediği nazîreler sayesinde şöhreti gittikçe arttı ve meslek  hayatındaki  yükselişleri  devam  etti.  Hattâ  maaşı  iki  katına çıkarılarak, 972  (m.  1564)’de  İstanbul  Murâd  Paşa  Medresesi müderrisliğine nakl edildi. 973 (m. 1565)’de terfi etti. Kanunî Sultan Süleymân, Bâkî’ye çok iltifât edip ihsânlarda bulunuyordu. Bu  durum  ba’zı  kimselerin  kıskanmasına  sebep  olmuştu.  Çünkü  Kanunî Sultan Süleymân yazdığı şiirleri ona gönderiyor, onlara nazireler yazmasını emr  ediyor,  ihsânlarını  ve  iltifâtlarını eksik  etmiyordu. 973  (m.  1565)’de hacca  gitmiş  olan  babasının  ölümü  haberini  aldı.  974  (m.  1566)  senesi içinde,  Kanunî  Sultan  Süleymân’ın  vefâtı,  Bâkî’yi  son  derece  üzmüştü. Pâdişâhın ölümü, Bakî için bir dönüm noktası oldu. Bu hâdiseden duyduğu teessürü bildiren    meşhûr  mersiyesini  yazmak  sûretiyle  pâdişâhına bağlılığını anlattı. Yeni sultâna yer vermesine rağmen vazifesinden alındı. Böylece 974 (m. 1566)’de müderrislik vazîfesinden ayrıldı. Aynı sene içinde tahta geçen İkinci Selim Hân’a cülus kasidesi yazarak takdim etti. 977 (m. 1569) senesinde Murâd Paşa Medresesi müderrisliğine, 979 (m. 1571)’da Eyyûb Medresesi müderrisliğine ta’yin olundu. 981 (m. 1573) senesinde Sahn-ı semân medreselerinden birine yükseltildi. O sırada İkinci Selim Hân’dan kabûl gören Bakî Efendi, pâdişâhın husûsî meclislerine da’vet olunmağa başladı. 982 (m. 1574) senesinde oçüncü Murâd Hân’ın tahta  geçişinden  sonra  yükselerek,  983  (m.  1575)’de  Süleymâniye Medresesi  müderrisliğine  getirildi. Aynı  senenin  faban  ayında,  üçüncü Murâd  Han’ın  tahta  geçmesi  üzerine,  bir  cülûsiye  sunmasına  rağmen, çekemeyenleri tarafından iftiraya uğradı ve; Cihânın nimetinden kendü âb u dânemüz yiğdür İlün kâşanesinden gûşe-i virânemüz yiğdür. beyti  ile  başlayan  bir  şiirle  pâdişâhın  ihsânlarını  küçümsediği  öne sürüldü. Hiç ummadığı bu iftira sonunda vazîfeden alındı. Neticede işinden olduğu gibi, İstanbul’dan da uzaklaştırıldı. Ancak sevenleri, bu şiirin Nâmî mahlaslı bir şâirin olduğunu ispatta gecikmediler. Bakî’nin haklılığı ortaya çıkınca, 984 (m. 1576)’de Bakî Efendi’nin suçsuz olduğu anlaşılarak, Edirne Selîmiye Medresesi’ne ta’yin edildi. hemen ardından Sultan Selîm-i kadîm Medresesi müderrisliğine getirildi. 987 (m. 1579) senesinde Mekke kadılığına, 988 (m. 1580)’de Medîne-i münevvere  kadılığına  nakledildi  ise  de,  989  (m.  1582)’de  vazîfeden azl edilince İstanbul’a döndü. 992 (m. 1584)’de İstanbul kadılığına ta’yin edildi. 993 (m. 1585)’de bu vazîfeden alınıp, 994 (m. 1586)’de tekrar aynı vazîfeye getirildi. Aynı sene içinde Anadolu kadıaskerliğine terfi ettirildi, iki seneden sonra bu vazîfeden de alındı. 999 (m. 1590) senesinde tekrar aynı vazîfeye getirildi  ve  1591  (m.  1000)’de Rumeli  kadıaskerliğine  getirildi.  Aynı  yıl içinde emekliye ayrıldı. oçüncü  Murâd  Han  devrinin  son  senesinde  yeniden  Rumeli  kazaskeri oldu ise de istifa etti. 1003 (m. 1595) senesinde pâdişâh olan Sultan oçüncü Mehmed  Hânın tahta  geçmesi  ile  yazdığı  cülûsiye  üzerine  üçüncü  defa Rumeli   kadıaskerliğine  ta’yin edildi.  Aynı  sene  içinde  vazîfeden  alındı. Aslında şeyhülislâm olmak ümîdi vardı. Ancak önce Hoca Sâdeddîn, onun ölümü ile de Sun’ullah Efendi’nin bu makama gelişleri Bâkî’yi bu ümidinden vaz  geçirdi. Bundan  sonra  evine  çekilip  şiirleriyle  ve  ilmî  çalışmalarla meşgûl  oldu.  1006  (m.  1597)  senesinde  tekrar  Rumeli  kadıaskerliğine getirildi.  Ba’zı  hâdiseler  üzerine  1007  (m.  1598)’de  istifâ  etmek  zorunda Bir  müddet  kendi  köşesine  çekilip  ibâdet,  tâat  ve  şiirle  meşgûl  iken tutulduğu hastalıktan kurtulamayıp nihayet 29 Rebîü’l-âhir 1009 (7 Kasım 1600) tarihinde vefât  etti.  Cenâze  namazını  feyhülislâm  Sun’ullah  Efendi kıldırdı.  Bütün  devlet  erkânı,  vezirler,  âlimler  ve  şâirler  ile  büyük  bir kalabalık bu cenâze namazında bulundu. Hayatının sonuna yakın evlenen Bakî Efendi’nin, feyhî mahlasıyla bilinen Mehmed Efendi ve Abdurrahmân Efendi adında iki oğlu var idi. Kanunî Sultan Süleymân, İkinci Selîm, oçüncü Murâd ve oçüncü Mehmed Hân  zamanlarında  yaşamış  olan  Mahmûd  Abdülbâkî  Efendi,  aklî  ve  naklî ilimlerde  derin  âlim  ve  güzel  ahlâk  sahibi  idi.  Dîni  ilimlerdeki  üstünlüğü feyhülislâm olabilecek derecedeydi. Ancak sırası gelmediği için bu vazîfeye ta’yin olunamadı. Tatlı dilli, güler yüzlü ve hoş sohbet idi. Açık kalbli, temiz yürekli,  nâzik  ve  kibar  mizaçlı  olduğu  için  nükteli  ta’rizlerinde  zarafet haddîni  aşmazdı.  Herkese  iyi  muâmele  eder,  istemiyerek  kalbini  kırdığı kimselerin  gönlünü  almağa  çalışırdı.  Hayırsever  bir  zât  idi.  İstanbul’da Nişancı Paşa-i Cedîd yanında Bakî Efendi Mescidi’ni yaptırmıştı. Bâkî’nin  hayatındaki  adım  adım  yükseliş,  şeyhülislâmlık  mevkiine ulaşamasa  bile,  şiirde  padişahlığa  ulaşmasına  sebep  olmuş,  Kânûnî’ye arkadaşlık etmiş ve birlikte şiir musahabelerinde bulunmuşlardır. Kısaca bu devrin tanınan iki pâdişâhı vardır. Biri Sultan Süleymân Hân, diğeri ise şiirin sultânı  olan  Bâkî’dir.  Ona  Türk  târihinin  en  yüksek  devrinde  “Sultân-üş- şu’arâ” denilmesi boşuna değildir. Çocukluğunda  çok  fakir  olması  sebebiyle,  şiirinde  hayatın  içinden getirdiği  husûslar  vardır.  Hattâ  şiiri bu  yönden  ele  alınınca  ba’zı  sözleri atasözü hükmündedir. fiirdeki bu kuvvetliliği, yaşadığı ve içinden geldiği hayâttan getirmiştir. fiirde  Zâtî  tarafından  yetiştirilen  Bâkî’nin  sanatı,  mükemmel  olup, gazellerinde  büyük  bir  ustalık  hakimdir.  fiirlerinde konular,  diğer  divan şairlerine  nisbetle  daha  serbesttir. fiir  diline  renklilik  ve  akıcılık  getiren Bakî,  İran  edebiyatı  te’sîrinin  de  ortadan  kalkmasına  sebeb  olmuş  ve bulunduğu asra şiirde millîliği getirmiştir. Zaten devrin İstanbul Türkçesini kullanmış ve şiirleriyle mahallileşmeyi getirmiştir. Bu sebeple gazellerinde atasözleri ve halk tabirlerine yer vermiştir. Uzun yıllar taklid edilmesi bu mükemmel söyleyişinden ileri gelmektedir. Yaratılıştan kibar ve zarif oluşu, nükteleri ile şiirini atbaşı götürmesine sebeb  olmuştur.  fiirinin  yanında,  dillerde  dolaşan  nükteleri  de  şiir mecmû’aları ve kitapları kaydedilmiştir. Bâkî  san’atta,  Osmanlı  Türkçesi  Edebiyâtı’nın  en  büyük  şâiri  olma durumunu  dâima  muhafaza  etmiş,  şöhreti  İmparatorluğun  bütün hudutlarına yayılmıştır. Ayrıca şiirinin halvâ gibi gıda olduğunu ve ellerden ellere dolaştığını zikreden kaynaklar mevcûttur: Çü güftâr-ı Bâkî-i şîrin-edâ Edip hûb halvâyı âhir gıda Geze elleri câm-ı sâkî gibi Düşe dillere şi’r-i Bâkî gibi beytleri bunun açık delîlidir. Araştırıldığı takdîrde bu kabil mısra ve beyitlerin,  devrin  diğer  müelliflerinde  daha  fazla  görülmesi  mümkündür. Bâkî’yi bu duruma getiren, dili ustaca kullanmasıdır. Kelimeler yerli yerinde ve  bütün  söz  sanatları  ifadelerinde  kendini  gösterecek  şekilde  yer  alırdı. fiirlerinde  zeka  oyunlarına  büyük  önem  verirdi. Ses  ve  ma’nâyı  şiirinde birleştiren şâir,  ahenkli ve  temiz  bir üslûb  ortaya  koymuştur. Kelimelere birçok anlamlar vermekte, mısra ahenginin üst derecelerine ulaşmakta eşsiz bir  sanatkardı. fiirlerinde  hep  ölçülü  ve hesaplıdır.  Mısraları  dilde  hiçbir takıntı ve kulakta hiçbir tırmalama yapılmaksızın söylenir. Onun şiiri ölçülü ve  bilgi  hudutları içinde kullanılan bir dilin mahsûlü idi. fiirinde kullandığı kelime, ta’bîr ve deyimlerin menşei halkın dili, ev ve aile Türkçesi idi. Kısaca Bâkî, muhtevâ ve şekil i’tibâriyle Türkçe’nin cümle yapısına değer vermiş ve millî nazım cümlesini korumasını bilmiştir. Bâkî san’atın gözü ile eşyaya bakar. Ba’zan resme ulaşan şiirleri vardır. Bu, bir asır sonra Nedim’e de te’sîr eder. Onun gazelleri bitmemiş hissini verir. Bâkî’de güzellik ve mükemmellik esastır. Kullandığı her kelime, şâiri güzeli yakalamaya götürür. Gazellerinin  muhtevâsı  genişlik  gösterir.  Her  ne  kadar  neş’e,  zevk  ve yaşama  yönünde  şiirler  yazmışsa  da  onun  şiirlerinde  dînî  taraf  da  ağır basar. Sabr, Bâkî’de üzerinde durulması gereken bir unsur olup, bu sayede şikâyetten uzaktır. Ba’zı gazelleri kendinden bahseder, hele “Bana” redifli gazeli tamamen şâiri verir ve “İşte Bâkî budur” hükmüne götürür. Tabî ki bütün bunlarda kalemin ve sözün gidişini de hesaba katmak gerekir. “Cana” redifli gazeli kendisini tamamlayan şiirleri arasında zikredilebilir. Bâkî’ye  göre  şâir,  âlem  bağının  bülbülüdür,  bülbül  ise  gülbahçesinde bulunur. Âşıkın gerçek ta’rîfini de yapmaktan çekinmez: Vaktine mâlik olan dervîşdir sultân-ı vakt İzz-ü-câh-ı saltanat değmez cihan gavgâsına derken, tasavvuf neş’esi içinde her şeyden geçtiğini de görürüz. Zâten bu gazelin tamâmı, tasavvufta yer alan “sûfî-i ibnü’l-vakt” umdesine sıkı sıkıya Hakîkat  sırrına  vâkıf  değilsin  Alâkan  var  ise  aşk-ı  mecaza  derken  de gerçek tasavvufa gider ve ilâhî taraf ağır basar. fâir ayrıca cehâletten ve câhillerden  şikâyet  etmektedir.  Bir  bakıma  zamanları  devirleri  bunlar Devr-i zamane cünbüşü nadanlık üzredir Nadan komaz ki merdüm-i dana huzûr ede beyti ile şâir bütün zamânların hastalığına teşhis koymuştur. Bâkî’nin  şiiri bir  bakıma  ilâhî  aşka  açılan  mecazî  bir  penceredir.  O, güzelliklerle  oynayan  bir  şâirdir.  Eski  edebiyatın  mazmunları  gerçek ma’nâda  onun  şiirinde  seslenirler.  Bâkî  ba’zı  gazellerinde,  kasideleri  bir tarafa, devrinin pâdişâhlarına ve devlet adamlarına da yer vermiştir. Devrin âdetleri,  dîvânında  yer  yer  göze  çarpar.  “Gönül”  redifli  gazelinde  az  çok şiirinin sırrını açıklar: ommîd-i vasl-ı yârdan el çekme Bâkîyâ fâyed ki destgîr ola bir merhabâ-y-ıla beytinde ümidsizliğe düşmemeyi, Hâk-ı râh olduğum görüp ayağın Yerlere basmaz oldu cânâne derken  de  sevgilinin  eziyetlerine  ne  derece  katlanacağını  heber fiirinin muhtevâsı, görüldüğü gibi duygu ve düşüncenin, hattâ inancın yanında bilgi ve san’at unsurları ile yüklüdür. Her mısra’ ve beytte bunun tezahürü ayrı ayrıdır. Onun için Bâkî’nin şiiri bitmemiş hissini verir. Fakat şâir, işlenmesi gereken unsurları büyük bir titizlik, san’at endişesi ve zekâ gücü ile yerine koymuş; asırlar ötesine sesini bırakmıştır. Tâbutu başında bulunanları ağlatan beytinden sonra; Bâkî kalan bu kubbede bir hoş sada imiş derken,  kendisinden  hâlâ  ses  gelmektedir.  Onun,  bunlara  ilâve  olarak diğer  şâirlerimizde  görüldüğü  gibi,  atasözü  mahiyetindeki  beyitleri  ve mısrâları zikre değer. Fermân-ı aşka can ile var inkıyadımız Hükm-i kazaya zerre kadar yok inadımız şeklinde başlayan gazeli, tevekküle çeken ve tevekkül içinde olan şâirin gerçek hâlini verir. fiirleri içinde asıl Bâkî’yi, yukarıdaki gazele de yaklaştıran Kanuni Sultan Süleyman’ın  ölümü  için  yazdığı  meşhur Mersiye’si   o   devrin   edebiyat şaheseridir. fâir  bu  mersiye  ile  sâdece  Sultan  Süleymân  Hân’ın  vefâtını değil, bundan sonraki Osmanlı Devleti’nin hâlini de terennüme başlamıştır. Mersiye yedi bendden meydana gelmekte, ağır, vakarlı, heybetli bir hüzün ve ızdırabla hâtırâları birleştirmektedir. Bendin ikinci bölümü her yönü ile büyük Sultânı ele almış, üçüncü bendde mahlûkât böyle bir pâdişâhın kaybı ile  ağlamaya  çağırılmıştır.  Manzûmenin  en  dikkat  çekici  ve  güzel  bendi altıncı  kısmıdır.  fâir  burada  büyük  Sultânın  savaş  meydanlarındaki zaferlerini, cihâd aşkını ve Türk-İslâm dünyâsına kazandırdığı üstünlükleri dile getirmektedir. Yedinci bend ise yeni hükümdâra ayrılmıştır. Dîvân’ının  tertîbinde  dikkat  çeken  husûslar  da  vardır.  Diğer  dîvanlar olsun, eserler olsun başta münâcaat ve na’atlarla başladığı halde, bu durum Bâkî’de  görülmemektedir.  Ya’nî  Dîvân’ı  doğrudan  doğruya  kasidelerle Bâkî’nin Dîvân’ından başka eserleri de vardır. Bunlar: Fedâil-ül-cihâd:  Ahmed  bin  İbrâhim’in  yazdığı  Meşâri-ül-eşvâk  ilâ mesâir-il-uşşâk adlı eserin Türkçe tercümesidir. Müslümanları cihâda teşvik eden bir eserdir. Hadîs-i erba’în tercümesi: Eyyûb müderrisliğinde bulunduğu sırada, Ebû Eyyûb  Ensârî’den  rivâyet  edilen  hadîs-i  şerîfleri  toplamış  ve  tercüme Meâlim-ül-yakîn  fî  Sîret-i  Seyyid  il-mürselîn:  İmâm-ı  Kastalânî’nin  “El- Mevâhib-ül-Ledünniyye” adlı  meşhûr  eseri  esas  alınarak  yazılan  bu  siyer kitabı  tercüme  olmaktan  ziyâde  te’lîf  bir  eserdir.  Bâkî  Efendi  bu  kitabı yazarken yüzden fazla kitaba müracaat ederek, müellifîn fafiî mezhebine göre yazdığı ba’zı mes’eleleri, Hanefî mezhebine göre de yazmıştır. Zarurî ve faydalı gördüğü ba’zı ilâveleri yapmıştır. Sokullu Mehmed Paşa’nın emir ve isteği üzerine yazılan bu eser, aynı zamanda Mahmûd Abdülbâkî Efendi’nin, dînî  mes’elelere  ve  Hanefî  fıkhına  vukûfunu  göstermesi  bakımından  da Fezâil-i Mekke: Kutbüddîn Muhammed bin Ahmed Mekkî’nin “El-İ’lâm fî ahvâl-il-beledillah-il-haram”  adlı  eserinin  tercümesidir.  Sokullu  Mehmed Paşa’nın emri ile yapılan bu tercüme, Abdülbâkî Efendi’nin Mekke kadılığı esnasında  tamamlanmıştır.  Mekke  târihinden  ve  bilhassa  Osmanlı pâdişâhlarının  oradaki  te’sislerinden  bahs  eden  bu  eser  akıcı  bir  üslûbla Fermân-ı aşka can ile var inkıyadımız Hükm-i kazaya zerre kadar yok inadımız Baş eğmezüz edâniye dünyâ-ı dûn içün Allahadur tevekkülümüz i’timâdımız Biz müttekâ-yı zerkeş-i câha dayanmazız Hakk’ın kemâl-i lütfunadur istinadımız Zühd-ü-salâha eylemeziz iltica hele Tutdı egerçi âlem-i kevni fesadımız Meyden safâ-yı bâtın-ı hummdur garaz hemân Erbâb-ı zâhir anlayamazlar muradımız Minnet Huda’ya devlet-i dünyâ fenâ bulur Bâkî kalur sahîfe-i âlemde adımız Aşkın  fermanına  (buyruğuna)  candan  baş  eğmişiz,  bu  yüzden  kazanın hükmüne (kadere) zerre kadar inadımız yoktur (biz Haktan gelene râzıyız.) Alçak kimselere alçak ve fânî dünyâ için baş eğmeyiz (dünyalık, makam, mevkî  için  baş  eğmez,  minnet  etmeyiz),  bizim  vekîlimiz  ve  i’timâd  edip güvendiğimiz tek varlık Allahü teâlâ’dır. Biz  mevkînin,  makamın  altın  işlemeli  koltuk  deyneğine  dayanmayız, bizim dayandığımız yer Allahü teâlânın lütfunun en üst derecesidir. Biz  insanız,  insan  noksanlıklarla  doludur,  varlık  âlemini  fesadımız kaplamışken, zühd ile dîne bağlı bir şekilde görünüp insanları aldatmayız. Ne isek öyle görünürüz. farâbdan maksad küpün içinin temizliğidir, çünkü küp temiz olunca ya’nî bedenin içi temizlenince gönül temizdir. Gönül gözü ile bakmayıp baş gözü ile bakan, görünüşe aldanan kimselerin bizim meramımızı anlaması zordur. Ne derlerse desinler; dünyâ devleti, makamı, mevkii, kısaca vücûd varlığı son bulacaktır, Allahü teâlâya şükürler olsun ki âlemin sayfasında Bâkî’nin Var mı bir dîvâne kim geşt-i gülistan istemez Uzlet idüp Hakk’dan bir beyt-i vîrân istemez Fakr gencin ihtiyâr etdi şu kim kani olur fem’ası şems olsa yakmaz tâk-ı eyvan istemez Dûdunu serv eyleyip kanlu yaşın gülşen idüp Eylemez serve nazar seyr-i gülistan istemez Hoş gelür ana rebâb âvâzesi gavgâsı yok Pâdişâh-ı aşk olan dergâh u dîvân istemez Derd-i yâr ile kim başı hoşdur Bâkîyâ Ylmeğe canlar virür derdine derman istemez Levmedilmiş, taşlanmış bir kimse (bir deli) gösterin ki, gül bahçesinde gezip tozmak istemesin ve bir köşeye çekilerek Allahü teâlâdan yıkık bir ev istemesin.  Çünkü  hazîne  viranelerde  bulunur  ve  yıkık  gönüllerin  duâsı Fakr hazînesini seçen her şeye rızâ göstermiştir; onun fitili güneş olursa; yüksek binaların takı, kemeri neye yarar. Fakirlikle yetinen ahını göğe uzatan servi, gözlerinden akan kanlı yaşı gülşen ederek; serve bakmaz ve gül bahçesinde gezmeyi de istemez. Ona rebâbın kavgası olmayan sesi güzel görünür; zâten aşkın pâdişâhı için ne dergâh ne de dîvân gerekir. Ey  Bâkî!  fu  âşığın  (şunun)  başı  sevgiliyi  düşündüğünden  dolayı,  hep onunla meşgûl olduğu için hoştur; bu sevgi yüzünden ölür de derdine ilâç istemez. Eğer ilâç edilirse o sevgi kalmayacaktır. Vecize hükmündeki ba’zı beyt ve mısra’ları: Derûnun pür maârif hem-nişînin merd-i ârif kıl Açılma ey yüzü gül şahs-ı nadana kitâb-âsâ “İçini  (gönlünü)  irfanla  doldur,  arkadaşın  da  ârif  kimse  olsun;  ey  gül yüzlü sevgili (dost), câhil kimseye kitap gibi hemen açılıverme.” Zer-efşân ol kef-i ihsân ile seyr eyle âlemde Cihân-gerd-ü-civânmerd-i cihan ol âfitâb-âsâ “Güneş nasıl dünyâya bol bol cömertçe ışıklarını gönderir, dolaşarak hiç birini  ihmâl  etmeden  bütün  mahlûkâta  faydalı  oluyorsa;  Ey  dost!  Sen  de âlemde ihsân elini açarak altınlar saç, faydalı ol.” feref vermez dür-ü-gevher kemâl olmaz zer-ü-zîver Hüner kesb et hüner bahr-ı fazilet kân-ı irfândur “İnci, mercan, kıymetli şeyler insana asâlet ve şeref vermez, altınla ve süsle olgunluk, yücelik olmaz; iş, san’at ve hüner kazanıp herkese faydalı olmaktır. Çünkü hüner, faziletin denizi ve irfanın ocağıdır.” Gark eder âlemleri bir katre âb-ı mağfiret Var kıyâs et vüs’at-ı deryâ-ı rahmet neydügin “Âlemleri bir damla mağfiret suyu basar, sen buna kıyâsla cenâb-ı Hakkın rahmet denizinin genişliğini düşün.” Himmet-i merdân ile asan olur her müşkil iş “Allah adamlarının ma’nevî yardımı ile bütün güçlükler kolaylaşır.” Söz güherdir, ne bilir kadrini nadan güherin “Söz incidir, câhil onun kıymetini bilemez.” Bîmâr hâlini, yine bîmâr olandan sor “Hastanın hâlini hasta bilir, eğer sormak istersen hastadan sor.” Gerdûn-ı dûna âkil isen kılma i’timâd “Akıllıyım dersen, geçici dünyâya güvenme.” Dânâ-dil isen sırrını nadana duyurma “Gönülle biliyorsan (arif isen) sırrını câhillere açma.” Âkîl etmez, abes yere hande “Akıllı kişi, yok yere boşu boşuna gülmez.” Kerem gördükçe ey Bâkî recâ artar gedâlardan “Ey Bâkî! Dilencilere ihsânda bulundukça onlardaki istek daha da artar.” İnsân-ı kâmil olmağa sa’y eyle âdem ol “Mükemmel insan olmak için çalış ve insan ol” Çok olur yâr velî yâr-ı vefâdar olmaz “Görünüşte pek çok dost vardır, fakat vefalısı bulunmaz.” İnâyet hazret-i Hak’dan, kerem Feyyâz-ı mutlakdan “Lütuf  ve  ihsân  ancak  mutlak  feyz  sahibi  olan  Allahü  teâlânın  yüce zâtından olur, başkaları vâsıtadır, insanın bunu bilmesi gerekir.” Mahmûd  Abdülbâkî  Efendi  Mevâhib-i  Ledünniyye  tercümesinde, Resûlullahı (aleyhisselâm) sevmenin alâmetlerini anlatırken diyor ki: “Resûlullah (aleyhisselâm) efendimizi seven kimse O’nun bildirdiği İslâm dînine candan bağlı olur. Yyle bir derecede olmalı ki; neye hüküm ederse can ve gönülde onu güzelce kabûl ve ona edeble itaat eder. Nitekim Allahü teâlâ Nisa sûresi 65. âyet-i kerîmesinde meâlen: “Hayır, Rabbin hakkı için aralarındaki  ihtilâfta,  seni  hakem  yapıp,  sonra  da  senin  verdiğin  hükmü nefslerine ağır bulmayarak, tam teslimiyetle teslim ve râzı olmadıkça îmân etmiş olmazlar” buyuruyor. Gönlünde,  Peygamber  efendimizin  verdiği  hükümden  dolayı  ağırlık, ızdırap ve darlık olan, ya’nî O’nun hükmü kendi dileğine uymadığı takdîrde hatırı  incinen  kimseden,  Hak  teâlâ  hazretleri  îmânı  gidermiştir.  Bu  türlü kimseler mü’min olmazlar diye buyurulmuştur. Sehl   bin   Abdullah   Tüsterî  buyurdu  ki:  “Bir  kimse  bütün  hâllerinde Resûlullahı (aleyhisselâm) kendisine örnek almayıp nefsinin kendi elinde sansa  o  kimse  o  sünnete  uymanın  tadını  duyamaz.  Zîrâ  Resûlullah (aleyhisselâm)  efendimiz;  “Sizden  biriniz,  ben  ona  kendi  nefsinden  daha sevgili olmadıkça îmân etmiş olmaz” buyurmuştur. Fahr-i kâinat efendimiz kişiye kendi nefsinden daha sevgili olmadıkça îmân iddiasında bulunması Peygamber efendimizi (aleyhisselâm) sevenler; sözlerinde ve işlerinde O’nun dînine yardım ederler. O’nun ahlâkı ile ahlâklanırlar. Cömertlik, iyilik, yumuşak davranmak, tevâzu, sabır ve ahlâkda O’na özenirler. Musibetlere sabr edip O’nun muhabbeti ile teselli bulurlar. Zîrâ seven kimse  sevginin  lezzetiyle  musibetin  şiddetini  unutur.  O’nu  seven  kimse Peygamber  efendimizi  (aleyhisselâm)  çok  zikr  eder.  Zîrâ  seven  kimse sevdiğini  çok  yâd  eder.  Çünkü  seven  kimsenin  üç  alâmeti  olur:  1-Sözü sevdiğinin  zikri  olur,  konuştukça  onu  yâd  eder.  2-Sustuğu  zaman  onu düşünür. 3-İşi gücü ona itaat etmek olur demişlerdir. Nakl edilir ki: Birgün Râbi’a-i Adviyye’nin meclisinde âbid (ibâdet eden) ve  zâhidlerden  (düyâdan  yüz  çeviren)  birkaç  kişi  toplanıp  dünyâyı kötülemeye  başladılar.  Râbi’a  susup  dinliyordu.  Onlar  konuşmalarını bitirdikten sonra: “Kişi sevdiği şeyi çok zikreder” buyurdu. Sevilenin zikri sevenlerin kalblerine yerleşir. Peygamber efendimizi (aleyhisselâm) sevmenin alâmetlerinden biri de O’nun ismi anıldığı zaman saygı, sevgi, alçak gönüllülük ve kendini küçük görmekdir.   Sahâbe-i   Kirâm,   Resûlullah   efendimiz   (aleyhisselâm) hatırlanınca, O’nun sevgi ve saygısıyla gönüllerini alçaltıp ağlarlardı. Tabiîn ve onlardan sonra gelen iyi hâlli kimseler de bu yolda gitmişlerdir. Safvan bin Süleym, çok ibâdet eden ve gece namazına devamlı kalkan kimselerdendi. Yanında Resûlullah (aleyhisselâm) zikr edildiğinde o kadar ağlardı ki, o mecliste oturanlar kalkıp giderlerdi de ağlaması dinmezdi. Peygamber efendimizi sevmenin alametlerinden biri de O’nu görmeğe, O’na kavuşmağa iştiyâk duymaktır. Zîrâ her seven sevdiği ile buluşmayı çok ister.  Abde  binti  Hâlid  bin  Ma’dân:  “Babam  Hâlid  her  ne  zaman  yatağı üzerine gelse, Peygamber efendimizi hatırlayıp: “Yâ Rabbî! Benim rûhumu kabz  etmekte  acele  eyle”  derdi.  Tâki  uyku  galebe  edinceye  kadar  böyle söylerdi” diye anlatır. Bilâl-i Habeşî (radıyallahü anh) vefât etmek üzere olduğu zaman, hanımı üzüntüsünden  feryâd  ediyordu.  O  ise  sevinerek;  “Yarın  dostlarla, Muhammed (aleyhisselâm) ve arkadaşlarıyla buluşuruz” buyurdu. Peygamber efendimizi (aleyhisselâm) sevmenin alâmetlerinden birisi de, O’nun getirdiği yüce Kur’ân-ı sevmektir. Hazret-i Osman buyurdu ki: “Eğer bizim  kalbimiz  temiz  olsaydı,  asla  Kur’ân-ı  kerîm  okumaktan  doymazdı. Seven  kimse sevdiğinin kelâmından  nasıl  doyar ki,  O’nun  en  çok  istediği Sevgili   Peygamberimiz (aleyhisselâm)  birgün  Abdullah  bin  Mes’ûd’a (radıyallahü  anh): “Yâ  Abdullah! Kur’ân oku da dinliyelim”buyurdu.  İbn-i Mes’ûd: “Kur’ân size indi O’nu ben mi okuyayım dedi. Peygamber efendimiz (aleyhisselâm):  “Ben  başkasından  işitmeyi  severim”  buyurdu.  Bunun üzerine İbn-i Mes’ûd (radıyallahü anh) Nisa sûresinin başından başlayarak okudu. “Her ümmetten biri şâhid, seni de bunlara şâhid getirdiğimiz zaman hâlleri  nice  olur”  meâlindeki  41.  âyete  gelince,  Peygamber  efendimiz (aleyhisselâm)  “Yeter  yâ  Abdullah”  buyurdu.  İbn-i  Mes’ûd  başını  kaldırıp baktı  ki  Resûlullah  efendimizin  mübârek  gözlerinden  durmadan  yaş Bir kimse Kur’ân-ı kerîmi can kulağıyla dinlese, elbette ona te’sîr edip gözünden yaş gelir. Peygamber  efendimizi  sevmenin  bir  alâmeti  de  O’nun  sünnetine muhabbet edip hadîs-i şerîfini dinlemekten zevk almaktır. Zîrâ kişi sevdiği kimsenin sözünü işitmekten mutluluk duyar. O’nun güzel ismini anmak ve salevât-ı şerîfe getirmek O’nu sevmenin alâmetlerindendir. “Bir  kimse  sabaha  ve  akşama  yetiştiği  zamanda  bana  on  kere  salevât okusa;  kıyâmet  günü  şefaatime  müstehâk  olur”  ve  yine;  “Bir  şeyi unuttuğunuz  zaman  beni  hatırlayın  ve  bana  salât  edin.  Allah  dilerse  onu hatırlatır”  ve  “Cum’a  günü,  sizin  en  üstün  günlerinizdendir.  Adem aleyhisselâm o günde yaratıldı, o günde kabzolundu. Sûr’un üflenmesi ve ansızın helak oluş o günde olur. O hâlde, o günde bana salâh çok edin. Zîrâ salâtınız arz olunur” buyurdu.', '1008  (m.  1600)', '960  (m.  1552)', '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:32.668263', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Osmanlılar zamanında yetişen âlimlerden ve şâirlerden. İsmi, Mahmûd Abdülbâkî’dir.  Bâkî  mahlasıyla  tanınan  Mahmûd  Abdülbâkî, Kanuni’den sonra sıra ile padişah olan İkinci Selim, oçüncü Murad ve oçüncü Mehmed Han zamanlarında da zamanının şâir ve edipleri arasında ve ülkenin her tarafında  fairler  Sultanı “Sultân-üş-şu’arâ”  diye  de  meşhûr  olmuştur. Süleymâniyye medresesinde müderris idi. Reîsül-ulemâ oldu. Nişâncı pâşayı cedîd  yanında (Bâkî  efendi  mescidi)ni  yapdırdı. Fâtih  Câmii müezzinlerinden  Mehmed  Efendi’nin  oğludur.  933  (m.  1526)  senesinde İstanbul’da doğdu.  1008  (m.  1600)  senesinde  İstanbul’da  vefât  etti. Edirnekapı  dışında  Eyyûb  Sultan’a  giden  yol  üzerindeki  kabristana  defn Çocukluğunda  bir  müddet  saraç  çıraklığında  çalıştıktan  sonra fıtratındaki  yüksek  kabiliyeti  onu medrese  tahsiline  sevk etti.  Medresede kısa  zamanda  akranları arasında  yükselip,  keskin  zekâsını  ve  kabiliyetini ortaya  koydu.  Zamanının  meşhûr  âlimlerinden  Ahaveyn  diye  bilinen Karamanlı Ahmed ve Mehmed efendilerden aklî ve naklî ilimleri tahsîl edip istifâde etti. 19 yaşlarında iken İstanbul’un genç şâirleri arasında “Sünbül” kasidesi  ile  şöhreti  fazlalaştı.  Medresedeki  ders  arkadaşları  arasında  şâir Nev’î,  osküplü  şâir  Vâlihî,  Hoca  Sa’deddîn  Efendi  gibi  kabiliyetli  gençler 960  (m.  1552) senesinde  Süleymâniye Medresesi  müderrisi  Kâdı-zâde femseddîn Ahmed Efendi’nin tedris halkasına dâhil olup, ondan çok istifâde etti.  Bu  arada  devrin  üstâd  şâiri  Zâtî’nin  şiir  meclislerinde  bulundu.  Zâtî tarafından ondaki şiir kabiliyeti ortaya çıkarılıp teşvik edildi. 960 (m. 1552) senesinde  Nahcivan  seferinden  dönüşünde,  Kanunî  Sultan  Süleymân’a takdim ettiği kaside sebebiyle pâdişâhın lütuf ve ihsânlarına kavuştu. 963 (m. 1555) senesinde hocası Kâdı-zâde Ahmed Efendi, Haleb kadılığına ta’yin olununca  o  da  beraberinde  gitti. hocasına Râiyye; Haleb beylerbeyi Kubâd Paşa’ya da Hilâl kasîdelerini sunmuştur. Dört senelik bir ayrılıktan sonra, İstanbul’a  dönerken  büyük  âlim  Ebüssü’ûd  Efendi’nin  en  büyük  oğlu Mehmed  Çelebi  ile  Konya’da  karşılaşmıştır. 967  (m.  1559)’de  tekrar İstanbul’a döndü. Haleb beylerbeyi Kubâd Paşa’ya takdim ettiği “Hilâl” ve hocası  Kâdı-zâde’ye  takdim  ettiği  “Raiye”  kasidesi  bu  sırada  yazdığı şiirlerdendir,  İstanbul’a  dönerken  Konya’da  feyhülislâm  Ebüssü’ûd Efendi’nin  oğlu  Mehmed  Çelebî  ile  tanıştı.  Ebüssü’ûd  Efendi için  yazmış olduğu “Lâmiyye” kasidesini İstanbul’a gelince takdim etti. 969 (m. 1561) senesinde  Ebüssü’ûd  Efendi’nin  hizmetinde  bulunduğu  sırada  Sadrazam Semiz  Ali  Paşa’ya  takdim  edildi. 969   Safer (m.  1562)  yılında  Molla Merhûm’a  dânişmend,  971  Ramazan  (m. 1563)’de  de  yirmi  beş  akçe  ile müderris  olmuştur. 971   (m.   1563)   senesinde fevval  ayı  ortalarında Silivri’de bulunan Pîri Paşa Medresesi müderrisliğine ta’yin edildi. Rüstem Paşa’dan sonra sadrâzamlığa getirilen Semiz Ali Paşa’ya da kasîdeler sunan Bakî oldukça takdîr gördü. Semiz Ali Paşa ve Mîrâhor Ferhad Ağa vâsıtasıyle Pâdişâh’a  yaklaşarak,  kasîdeler  sunmaya  başladı.  Netîcede  sultânın gönderdiği gazellere söylediği nazîreler sayesinde şöhreti gittikçe arttı ve meslek  hayatındaki  yükselişleri  devam  etti.  Hattâ  maaşı  iki  katına çıkarılarak, 972  (m.  1564)’de  İstanbul  Murâd  Paşa  Medresesi müderrisliğine nakl edildi. 973 (m. 1565)’de terfi etti. Kanunî Sultan Süleymân, Bâkî’ye çok iltifât edip ihsânlarda bulunuyordu. Bu  durum  ba’zı  kimselerin  kıskanmasına  sebep  olmuştu.  Çünkü  Kanunî Sultan Süleymân yazdığı şiirleri ona gönderiyor, onlara nazireler yazmasını emr  ediyor,  ihsânlarını  ve  iltifâtlarını eksik  etmiyordu. 973  (m.  1565)’de hacca  gitmiş  olan  babasının  ölümü  haberini  aldı.  974  (m.  1566)  senesi içinde,  Kanunî  Sultan  Süleymân’ın  vefâtı,  Bâkî’yi  son  derece  üzmüştü. Pâdişâhın ölümü, Bakî için bir dönüm noktası oldu. Bu hâdiseden duyduğu teessürü bildiren    meşhûr  mersiyesini  yazmak  sûretiyle  pâdişâhına bağlılığını anlattı. Yeni sultâna yer vermesine rağmen vazifesinden alındı. Böylece 974 (m. 1566)’de müderrislik vazîfesinden ayrıldı. Aynı sene içinde tahta geçen İkinci Selim Hân’a cülus kasidesi yazarak takdim etti. 977 (m. 1569) senesinde Murâd Paşa Medresesi müderrisliğine, 979 (m. 1571)’da Eyyûb Medresesi müderrisliğine ta’yin olundu. 981 (m. 1573) senesinde Sahn-ı semân medreselerinden birine yükseltildi. O sırada İkinci Selim Hân’dan kabûl gören Bakî Efendi, pâdişâhın husûsî meclislerine da’vet olunmağa başladı. 982 (m. 1574) senesinde oçüncü Murâd Hân’ın tahta  geçişinden  sonra  yükselerek,  983  (m.  1575)’de  Süleymâniye Medresesi  müderrisliğine  getirildi. Aynı  senenin  faban  ayında,  üçüncü Murâd  Han’ın  tahta  geçmesi  üzerine,  bir  cülûsiye  sunmasına  rağmen, çekemeyenleri tarafından iftiraya uğradı ve; Cihânın nimetinden kendü âb u dânemüz yiğdür İlün kâşanesinden gûşe-i virânemüz yiğdür. beyti  ile  başlayan  bir  şiirle  pâdişâhın  ihsânlarını  küçümsediği  öne sürüldü. Hiç ummadığı bu iftira sonunda vazîfeden alındı. Neticede işinden olduğu gibi, İstanbul’dan da uzaklaştırıldı. Ancak sevenleri, bu şiirin Nâmî mahlaslı bir şâirin olduğunu ispatta gecikmediler. Bakî’nin haklılığı ortaya çıkınca, 984 (m. 1576)’de Bakî Efendi’nin suçsuz olduğu anlaşılarak, Edirne Selîmiye Medresesi’ne ta’yin edildi. hemen ardından Sultan Selîm-i kadîm Medresesi müderrisliğine getirildi. 987 (m. 1579) senesinde Mekke kadılığına, 988 (m. 1580)’de Medîne-i münevvere  kadılığına  nakledildi  ise  de,  989  (m.  1582)’de  vazîfeden azl edilince İstanbul’a döndü. 992 (m. 1584)’de İstanbul kadılığına ta’yin edildi. 993 (m. 1585)’de bu vazîfeden alınıp, 994 (m. 1586)’de tekrar aynı vazîfeye getirildi. Aynı sene içinde Anadolu kadıaskerliğine terfi ettirildi, iki seneden sonra bu vazîfeden de alındı. 999 (m. 1590) senesinde tekrar aynı vazîfeye getirildi  ve  1591  (m.  1000)’de Rumeli  kadıaskerliğine  getirildi.  Aynı  yıl içinde emekliye ayrıldı. oçüncü  Murâd  Han  devrinin  son  senesinde  yeniden  Rumeli  kazaskeri oldu ise de istifa etti. 1003 (m. 1595) senesinde pâdişâh olan Sultan oçüncü Mehmed  Hânın tahta  geçmesi  ile  yazdığı  cülûsiye  üzerine  üçüncü  defa Rumeli   kadıaskerliğine  ta’yin edildi.  Aynı  sene  içinde  vazîfeden  alındı. Aslında şeyhülislâm olmak ümîdi vardı. Ancak önce Hoca Sâdeddîn, onun ölümü ile de Sun’ullah Efendi’nin bu makama gelişleri Bâkî’yi bu ümidinden vaz  geçirdi. Bundan  sonra  evine  çekilip  şiirleriyle  ve  ilmî  çalışmalarla meşgûl  oldu.  1006  (m.  1597)  senesinde  tekrar  Rumeli  kadıaskerliğine getirildi.  Ba’zı  hâdiseler  üzerine  1007  (m.  1598)’de  istifâ  etmek  zorunda Bir  müddet  kendi  köşesine  çekilip  ibâdet,  tâat  ve  şiirle  meşgûl  iken tutulduğu hastalıktan kurtulamayıp nihayet 29 Rebîü’l-âhir 1009 (7 Kasım 1600) tarihinde vefât  etti.  Cenâze  namazını  feyhülislâm  Sun’ullah  Efendi kıldırdı.  Bütün  devlet  erkânı,  vezirler,  âlimler  ve  şâirler  ile  büyük  bir kalabalık bu cenâze namazında bulundu. Hayatının sonuna yakın evlenen Bakî Efendi’nin, feyhî mahlasıyla bilinen Mehmed Efendi ve Abdurrahmân Efendi adında iki oğlu var idi. Kanunî Sultan Süleymân, İkinci Selîm, oçüncü Murâd ve oçüncü Mehmed Hân  zamanlarında  yaşamış  olan  Mahmûd  Abdülbâkî  Efendi,  aklî  ve  naklî ilimlerde  derin  âlim  ve  güzel  ahlâk  sahibi  idi.  Dîni  ilimlerdeki  üstünlüğü feyhülislâm olabilecek derecedeydi. Ancak sırası gelmediği için bu vazîfeye ta’yin olunamadı. Tatlı dilli, güler yüzlü ve hoş sohbet idi. Açık kalbli, temiz yürekli,  nâzik  ve  kibar  mizaçlı  olduğu  için  nükteli  ta’rizlerinde  zarafet haddîni  aşmazdı.  Herkese  iyi  muâmele  eder,  istemiyerek  kalbini  kırdığı kimselerin  gönlünü  almağa  çalışırdı.  Hayırsever  bir  zât  idi.  İstanbul’da Nişancı Paşa-i Cedîd yanında Bakî Efendi Mescidi’ni yaptırmıştı. Bâkî’nin  hayatındaki  adım  adım  yükseliş,  şeyhülislâmlık  mevkiine ulaşamasa  bile,  şiirde  padişahlığa  ulaşmasına  sebep  olmuş,  Kânûnî’ye arkadaşlık etmiş ve birlikte şiir musahabelerinde bulunmuşlardır. Kısaca bu devrin tanınan iki pâdişâhı vardır. Biri Sultan Süleymân Hân, diğeri ise şiirin sultânı  olan  Bâkî’dir.  Ona  Türk  târihinin  en  yüksek  devrinde  “Sultân-üş- şu’arâ” denilmesi boşuna değildir. Çocukluğunda  çok  fakir  olması  sebebiyle,  şiirinde  hayatın  içinden getirdiği  husûslar  vardır.  Hattâ  şiiri bu  yönden  ele  alınınca  ba’zı  sözleri atasözü hükmündedir. fiirdeki bu kuvvetliliği, yaşadığı ve içinden geldiği hayâttan getirmiştir. fiirde  Zâtî  tarafından  yetiştirilen  Bâkî’nin  sanatı,  mükemmel  olup, gazellerinde  büyük  bir  ustalık  hakimdir.  fiirlerinde konular,  diğer  divan şairlerine  nisbetle  daha  serbesttir. fiir  diline  renklilik  ve  akıcılık  getiren Bakî,  İran  edebiyatı  te’sîrinin  de  ortadan  kalkmasına  sebeb  olmuş  ve bulunduğu asra şiirde millîliği getirmiştir. Zaten devrin İstanbul Türkçesini kullanmış ve şiirleriyle mahallileşmeyi getirmiştir. Bu sebeple gazellerinde atasözleri ve halk tabirlerine yer vermiştir. Uzun yıllar taklid edilmesi bu mükemmel söyleyişinden ileri gelmektedir. Yaratılıştan kibar ve zarif oluşu, nükteleri ile şiirini atbaşı götürmesine sebeb  olmuştur.  fiirinin  yanında,  dillerde  dolaşan  nükteleri  de  şiir mecmû’aları ve kitapları kaydedilmiştir. Bâkî  san’atta,  Osmanlı  Türkçesi  Edebiyâtı’nın  en  büyük  şâiri  olma durumunu  dâima  muhafaza  etmiş,  şöhreti  İmparatorluğun  bütün hudutlarına yayılmıştır. Ayrıca şiirinin halvâ gibi gıda olduğunu ve ellerden ellere dolaştığını zikreden kaynaklar mevcûttur: Çü güftâr-ı Bâkî-i şîrin-edâ Edip hûb halvâyı âhir gıda Geze elleri câm-ı sâkî gibi Düşe dillere şi’r-i Bâkî gibi beytleri bunun açık delîlidir. Araştırıldığı takdîrde bu kabil mısra ve beyitlerin,  devrin  diğer  müelliflerinde  daha  fazla  görülmesi  mümkündür. Bâkî’yi bu duruma getiren, dili ustaca kullanmasıdır. Kelimeler yerli yerinde ve  bütün  söz  sanatları  ifadelerinde  kendini  gösterecek  şekilde  yer  alırdı. fiirlerinde  zeka  oyunlarına  büyük  önem  verirdi. Ses  ve  ma’nâyı  şiirinde birleştiren şâir,  ahenkli ve  temiz  bir üslûb  ortaya  koymuştur. Kelimelere birçok anlamlar vermekte, mısra ahenginin üst derecelerine ulaşmakta eşsiz bir  sanatkardı. fiirlerinde  hep  ölçülü  ve hesaplıdır.  Mısraları  dilde  hiçbir takıntı ve kulakta hiçbir tırmalama yapılmaksızın söylenir. Onun şiiri ölçülü ve  bilgi  hudutları içinde kullanılan bir dilin mahsûlü idi. fiirinde kullandığı kelime, ta’bîr ve deyimlerin menşei halkın dili, ev ve aile Türkçesi idi. Kısaca Bâkî, muhtevâ ve şekil i’tibâriyle Türkçe’nin cümle yapısına değer vermiş ve millî nazım cümlesini korumasını bilmiştir. Bâkî san’atın gözü ile eşyaya bakar. Ba’zan resme ulaşan şiirleri vardır. Bu, bir asır sonra Nedim’e de te’sîr eder. Onun gazelleri bitmemiş hissini verir. Bâkî’de güzellik ve mükemmellik esastır. Kullandığı her kelime, şâiri güzeli yakalamaya götürür. Gazellerinin  muhtevâsı  genişlik  gösterir.  Her  ne  kadar  neş’e,  zevk  ve yaşama  yönünde  şiirler  yazmışsa  da  onun  şiirlerinde  dînî  taraf  da  ağır basar. Sabr, Bâkî’de üzerinde durulması gereken bir unsur olup, bu sayede şikâyetten uzaktır. Ba’zı gazelleri kendinden bahseder, hele “Bana” redifli gazeli tamamen şâiri verir ve “İşte Bâkî budur” hükmüne götürür. Tabî ki bütün bunlarda kalemin ve sözün gidişini de hesaba katmak gerekir. “Cana” redifli gazeli kendisini tamamlayan şiirleri arasında zikredilebilir. Bâkî’ye  göre  şâir,  âlem  bağının  bülbülüdür,  bülbül  ise  gülbahçesinde bulunur. Âşıkın gerçek ta’rîfini de yapmaktan çekinmez: Vaktine mâlik olan dervîşdir sultân-ı vakt İzz-ü-câh-ı saltanat değmez cihan gavgâsına derken, tasavvuf neş’esi içinde her şeyden geçtiğini de görürüz. Zâten bu gazelin tamâmı, tasavvufta yer alan “sûfî-i ibnü’l-vakt” umdesine sıkı sıkıya Hakîkat  sırrına  vâkıf  değilsin  Alâkan  var  ise  aşk-ı  mecaza  derken  de gerçek tasavvufa gider ve ilâhî taraf ağır basar. fâir ayrıca cehâletten ve câhillerden  şikâyet  etmektedir.  Bir  bakıma  zamanları  devirleri  bunlar Devr-i zamane cünbüşü nadanlık üzredir Nadan komaz ki merdüm-i dana huzûr ede beyti ile şâir bütün zamânların hastalığına teşhis koymuştur. Bâkî’nin  şiiri bir  bakıma  ilâhî  aşka  açılan  mecazî  bir  penceredir.  O, güzelliklerle  oynayan  bir  şâirdir.  Eski  edebiyatın  mazmunları  gerçek ma’nâda  onun  şiirinde  seslenirler.  Bâkî  ba’zı  gazellerinde,  kasideleri  bir tarafa, devrinin pâdişâhlarına ve devlet adamlarına da yer vermiştir. Devrin âdetleri,  dîvânında  yer  yer  göze  çarpar.  “Gönül”  redifli  gazelinde  az  çok şiirinin sırrını açıklar: ommîd-i vasl-ı yârdan el çekme Bâkîyâ fâyed ki destgîr ola bir merhabâ-y-ıla beytinde ümidsizliğe düşmemeyi, Hâk-ı râh olduğum görüp ayağın Yerlere basmaz oldu cânâne derken  de  sevgilinin  eziyetlerine  ne  derece  katlanacağını  heber fiirinin muhtevâsı, görüldüğü gibi duygu ve düşüncenin, hattâ inancın yanında bilgi ve san’at unsurları ile yüklüdür. Her mısra’ ve beytte bunun tezahürü ayrı ayrıdır. Onun için Bâkî’nin şiiri bitmemiş hissini verir. Fakat şâir, işlenmesi gereken unsurları büyük bir titizlik, san’at endişesi ve zekâ gücü ile yerine koymuş; asırlar ötesine sesini bırakmıştır. Tâbutu başında bulunanları ağlatan beytinden sonra; Bâkî kalan bu kubbede bir hoş sada imiş derken,  kendisinden  hâlâ  ses  gelmektedir.  Onun,  bunlara  ilâve  olarak diğer  şâirlerimizde  görüldüğü  gibi,  atasözü  mahiyetindeki  beyitleri  ve mısrâları zikre değer. Fermân-ı aşka can ile var inkıyadımız Hükm-i kazaya zerre kadar yok inadımız şeklinde başlayan gazeli, tevekküle çeken ve tevekkül içinde olan şâirin gerçek hâlini verir. fiirleri içinde asıl Bâkî’yi, yukarıdaki gazele de yaklaştıran Kanuni Sultan Süleyman’ın  ölümü  için  yazdığı  meşhur Mersiye’si   o   devrin   edebiyat şaheseridir. fâir  bu  mersiye  ile  sâdece  Sultan  Süleymân  Hân’ın  vefâtını değil, bundan sonraki Osmanlı Devleti’nin hâlini de terennüme başlamıştır. Mersiye yedi bendden meydana gelmekte, ağır, vakarlı, heybetli bir hüzün ve ızdırabla hâtırâları birleştirmektedir. Bendin ikinci bölümü her yönü ile büyük Sultânı ele almış, üçüncü bendde mahlûkât böyle bir pâdişâhın kaybı ile  ağlamaya  çağırılmıştır.  Manzûmenin  en  dikkat  çekici  ve  güzel  bendi altıncı  kısmıdır.  fâir  burada  büyük  Sultânın  savaş  meydanlarındaki zaferlerini, cihâd aşkını ve Türk-İslâm dünyâsına kazandırdığı üstünlükleri dile getirmektedir. Yedinci bend ise yeni hükümdâra ayrılmıştır. Dîvân’ının  tertîbinde  dikkat  çeken  husûslar  da  vardır.  Diğer  dîvanlar olsun, eserler olsun başta münâcaat ve na’atlarla başladığı halde, bu durum Bâkî’de  görülmemektedir.  Ya’nî  Dîvân’ı  doğrudan  doğruya  kasidelerle Bâkî’nin Dîvân’ından başka eserleri de vardır. Bunlar: Fedâil-ül-cihâd:  Ahmed  bin  İbrâhim’in  yazdığı  Meşâri-ül-eşvâk  ilâ mesâir-il-uşşâk adlı eserin Türkçe tercümesidir. Müslümanları cihâda teşvik eden bir eserdir. Hadîs-i erba’în tercümesi: Eyyûb müderrisliğinde bulunduğu sırada, Ebû Eyyûb  Ensârî’den  rivâyet  edilen  hadîs-i  şerîfleri  toplamış  ve  tercüme Meâlim-ül-yakîn  fî  Sîret-i  Seyyid  il-mürselîn:  İmâm-ı  Kastalânî’nin  “El- Mevâhib-ül-Ledünniyye” adlı  meşhûr  eseri  esas  alınarak  yazılan  bu  siyer kitabı  tercüme  olmaktan  ziyâde  te’lîf  bir  eserdir.  Bâkî  Efendi  bu  kitabı yazarken yüzden fazla kitaba müracaat ederek, müellifîn fafiî mezhebine göre yazdığı ba’zı mes’eleleri, Hanefî mezhebine göre de yazmıştır. Zarurî ve faydalı gördüğü ba’zı ilâveleri yapmıştır. Sokullu Mehmed Paşa’nın emir ve isteği üzerine yazılan bu eser, aynı zamanda Mahmûd Abdülbâkî Efendi’nin, dînî  mes’elelere  ve  Hanefî  fıkhına  vukûfunu  göstermesi  bakımından  da Fezâil-i Mekke: Kutbüddîn Muhammed bin Ahmed Mekkî’nin “El-İ’lâm fî ahvâl-il-beledillah-il-haram”  adlı  eserinin  tercümesidir.  Sokullu  Mehmed Paşa’nın emri ile yapılan bu tercüme, Abdülbâkî Efendi’nin Mekke kadılığı esnasında  tamamlanmıştır.  Mekke  târihinden  ve  bilhassa  Osmanlı pâdişâhlarının  oradaki  te’sislerinden  bahs  eden  bu  eser  akıcı  bir  üslûbla Fermân-ı aşka can ile var inkıyadımız Hükm-i kazaya zerre kadar yok inadımız Baş eğmezüz edâniye dünyâ-ı dûn içün Allahadur tevekkülümüz i’timâdımız Biz müttekâ-yı zerkeş-i câha dayanmazız Hakk’ın kemâl-i lütfunadur istinadımız Zühd-ü-salâha eylemeziz iltica hele Tutdı egerçi âlem-i kevni fesadımız Meyden safâ-yı bâtın-ı hummdur garaz hemân Erbâb-ı zâhir anlayamazlar muradımız Minnet Huda’ya devlet-i dünyâ fenâ bulur Bâkî kalur sahîfe-i âlemde adımız Aşkın  fermanına  (buyruğuna)  candan  baş  eğmişiz,  bu  yüzden  kazanın hükmüne (kadere) zerre kadar inadımız yoktur (biz Haktan gelene râzıyız.) Alçak kimselere alçak ve fânî dünyâ için baş eğmeyiz (dünyalık, makam, mevkî  için  baş  eğmez,  minnet  etmeyiz),  bizim  vekîlimiz  ve  i’timâd  edip güvendiğimiz tek varlık Allahü teâlâ’dır. Biz  mevkînin,  makamın  altın  işlemeli  koltuk  deyneğine  dayanmayız, bizim dayandığımız yer Allahü teâlânın lütfunun en üst derecesidir. Biz  insanız,  insan  noksanlıklarla  doludur,  varlık  âlemini  fesadımız kaplamışken, zühd ile dîne bağlı bir şekilde görünüp insanları aldatmayız. Ne isek öyle görünürüz. farâbdan maksad küpün içinin temizliğidir, çünkü küp temiz olunca ya’nî bedenin içi temizlenince gönül temizdir. Gönül gözü ile bakmayıp baş gözü ile bakan, görünüşe aldanan kimselerin bizim meramımızı anlaması zordur. Ne derlerse desinler; dünyâ devleti, makamı, mevkii, kısaca vücûd varlığı son bulacaktır, Allahü teâlâya şükürler olsun ki âlemin sayfasında Bâkî’nin Var mı bir dîvâne kim geşt-i gülistan istemez Uzlet idüp Hakk’dan bir beyt-i vîrân istemez Fakr gencin ihtiyâr etdi şu kim kani olur fem’ası şems olsa yakmaz tâk-ı eyvan istemez Dûdunu serv eyleyip kanlu yaşın gülşen idüp Eylemez serve nazar seyr-i gülistan istemez Hoş gelür ana rebâb âvâzesi gavgâsı yok Pâdişâh-ı aşk olan dergâh u dîvân istemez Derd-i yâr ile kim başı hoşdur Bâkîyâ Ylmeğe canlar virür derdine derman istemez Levmedilmiş, taşlanmış bir kimse (bir deli) gösterin ki, gül bahçesinde gezip tozmak istemesin ve bir köşeye çekilerek Allahü teâlâdan yıkık bir ev istemesin.  Çünkü  hazîne  viranelerde  bulunur  ve  yıkık  gönüllerin  duâsı Fakr hazînesini seçen her şeye rızâ göstermiştir; onun fitili güneş olursa; yüksek binaların takı, kemeri neye yarar. Fakirlikle yetinen ahını göğe uzatan servi, gözlerinden akan kanlı yaşı gülşen ederek; serve bakmaz ve gül bahçesinde gezmeyi de istemez. Ona rebâbın kavgası olmayan sesi güzel görünür; zâten aşkın pâdişâhı için ne dergâh ne de dîvân gerekir. Ey  Bâkî!  fu  âşığın  (şunun)  başı  sevgiliyi  düşündüğünden  dolayı,  hep onunla meşgûl olduğu için hoştur; bu sevgi yüzünden ölür de derdine ilâç istemez. Eğer ilâç edilirse o sevgi kalmayacaktır. Vecize hükmündeki ba’zı beyt ve mısra’ları: Derûnun pür maârif hem-nişînin merd-i ârif kıl Açılma ey yüzü gül şahs-ı nadana kitâb-âsâ “İçini  (gönlünü)  irfanla  doldur,  arkadaşın  da  ârif  kimse  olsun;  ey  gül yüzlü sevgili (dost), câhil kimseye kitap gibi hemen açılıverme.” Zer-efşân ol kef-i ihsân ile seyr eyle âlemde Cihân-gerd-ü-civânmerd-i cihan ol âfitâb-âsâ “Güneş nasıl dünyâya bol bol cömertçe ışıklarını gönderir, dolaşarak hiç birini  ihmâl  etmeden  bütün  mahlûkâta  faydalı  oluyorsa;  Ey  dost!  Sen  de âlemde ihsân elini açarak altınlar saç, faydalı ol.” feref vermez dür-ü-gevher kemâl olmaz zer-ü-zîver Hüner kesb et hüner bahr-ı fazilet kân-ı irfândur “İnci, mercan, kıymetli şeyler insana asâlet ve şeref vermez, altınla ve süsle olgunluk, yücelik olmaz; iş, san’at ve hüner kazanıp herkese faydalı olmaktır. Çünkü hüner, faziletin denizi ve irfanın ocağıdır.” Gark eder âlemleri bir katre âb-ı mağfiret Var kıyâs et vüs’at-ı deryâ-ı rahmet neydügin “Âlemleri bir damla mağfiret suyu basar, sen buna kıyâsla cenâb-ı Hakkın rahmet denizinin genişliğini düşün.” Himmet-i merdân ile asan olur her müşkil iş “Allah adamlarının ma’nevî yardımı ile bütün güçlükler kolaylaşır.” Söz güherdir, ne bilir kadrini nadan güherin “Söz incidir, câhil onun kıymetini bilemez.” Bîmâr hâlini, yine bîmâr olandan sor “Hastanın hâlini hasta bilir, eğer sormak istersen hastadan sor.” Gerdûn-ı dûna âkil isen kılma i’timâd “Akıllıyım dersen, geçici dünyâya güvenme.” Dânâ-dil isen sırrını nadana duyurma “Gönülle biliyorsan (arif isen) sırrını câhillere açma.” Âkîl etmez, abes yere hande “Akıllı kişi, yok yere boşu boşuna gülmez.” Kerem gördükçe ey Bâkî recâ artar gedâlardan “Ey Bâkî! Dilencilere ihsânda bulundukça onlardaki istek daha da artar.” İnsân-ı kâmil olmağa sa’y eyle âdem ol “Mükemmel insan olmak için çalış ve insan ol” Çok olur yâr velî yâr-ı vefâdar olmaz “Görünüşte pek çok dost vardır, fakat vefalısı bulunmaz.” İnâyet hazret-i Hak’dan, kerem Feyyâz-ı mutlakdan “Lütuf  ve  ihsân  ancak  mutlak  feyz  sahibi  olan  Allahü  teâlânın  yüce zâtından olur, başkaları vâsıtadır, insanın bunu bilmesi gerekir.” Mahmûd  Abdülbâkî  Efendi  Mevâhib-i  Ledünniyye  tercümesinde, Resûlullahı (aleyhisselâm) sevmenin alâmetlerini anlatırken diyor ki: “Resûlullah (aleyhisselâm) efendimizi seven kimse O’nun bildirdiği İslâm dînine candan bağlı olur. Yyle bir derecede olmalı ki; neye hüküm ederse can ve gönülde onu güzelce kabûl ve ona edeble itaat eder. Nitekim Allahü teâlâ Nisa sûresi 65. âyet-i kerîmesinde meâlen: “Hayır, Rabbin hakkı için aralarındaki  ihtilâfta,  seni  hakem  yapıp,  sonra  da  senin  verdiğin  hükmü nefslerine ağır bulmayarak, tam teslimiyetle teslim ve râzı olmadıkça îmân etmiş olmazlar” buyuruyor. Gönlünde,  Peygamber  efendimizin  verdiği  hükümden  dolayı  ağırlık, ızdırap ve darlık olan, ya’nî O’nun hükmü kendi dileğine uymadığı takdîrde hatırı  incinen  kimseden,  Hak  teâlâ  hazretleri  îmânı  gidermiştir.  Bu  türlü kimseler mü’min olmazlar diye buyurulmuştur. Sehl   bin   Abdullah   Tüsterî  buyurdu  ki:  “Bir  kimse  bütün  hâllerinde Resûlullahı (aleyhisselâm) kendisine örnek almayıp nefsinin kendi elinde sansa  o  kimse  o  sünnete  uymanın  tadını  duyamaz.  Zîrâ  Resûlullah (aleyhisselâm)  efendimiz;  “Sizden  biriniz,  ben  ona  kendi  nefsinden  daha sevgili olmadıkça îmân etmiş olmaz” buyurmuştur. Fahr-i kâinat efendimiz kişiye kendi nefsinden daha sevgili olmadıkça îmân iddiasında bulunması Peygamber efendimizi (aleyhisselâm) sevenler; sözlerinde ve işlerinde O’nun dînine yardım ederler. O’nun ahlâkı ile ahlâklanırlar. Cömertlik, iyilik, yumuşak davranmak, tevâzu, sabır ve ahlâkda O’na özenirler. Musibetlere sabr edip O’nun muhabbeti ile teselli bulurlar. Zîrâ seven kimse  sevginin  lezzetiyle  musibetin  şiddetini  unutur.  O’nu  seven  kimse Peygamber  efendimizi  (aleyhisselâm)  çok  zikr  eder.  Zîrâ  seven  kimse sevdiğini  çok  yâd  eder.  Çünkü  seven  kimsenin  üç  alâmeti  olur:  1-Sözü sevdiğinin  zikri  olur,  konuştukça  onu  yâd  eder.  2-Sustuğu  zaman  onu düşünür. 3-İşi gücü ona itaat etmek olur demişlerdir. Nakl edilir ki: Birgün Râbi’a-i Adviyye’nin meclisinde âbid (ibâdet eden) ve  zâhidlerden  (düyâdan  yüz  çeviren)  birkaç  kişi  toplanıp  dünyâyı kötülemeye  başladılar.  Râbi’a  susup  dinliyordu.  Onlar  konuşmalarını bitirdikten sonra: “Kişi sevdiği şeyi çok zikreder” buyurdu. Sevilenin zikri sevenlerin kalblerine yerleşir. Peygamber efendimizi (aleyhisselâm) sevmenin alâmetlerinden biri de O’nun ismi anıldığı zaman saygı, sevgi, alçak gönüllülük ve kendini küçük görmekdir.   Sahâbe-i   Kirâm,   Resûlullah   efendimiz   (aleyhisselâm) hatırlanınca, O’nun sevgi ve saygısıyla gönüllerini alçaltıp ağlarlardı. Tabiîn ve onlardan sonra gelen iyi hâlli kimseler de bu yolda gitmişlerdir. Safvan bin Süleym, çok ibâdet eden ve gece namazına devamlı kalkan kimselerdendi. Yanında Resûlullah (aleyhisselâm) zikr edildiğinde o kadar ağlardı ki, o mecliste oturanlar kalkıp giderlerdi de ağlaması dinmezdi. Peygamber efendimizi sevmenin alametlerinden biri de O’nu görmeğe, O’na kavuşmağa iştiyâk duymaktır. Zîrâ her seven sevdiği ile buluşmayı çok ister.  Abde  binti  Hâlid  bin  Ma’dân:  “Babam  Hâlid  her  ne  zaman  yatağı üzerine gelse, Peygamber efendimizi hatırlayıp: “Yâ Rabbî! Benim rûhumu kabz  etmekte  acele  eyle”  derdi.  Tâki  uyku  galebe  edinceye  kadar  böyle söylerdi” diye anlatır. Bilâl-i Habeşî (radıyallahü anh) vefât etmek üzere olduğu zaman, hanımı üzüntüsünden  feryâd  ediyordu.  O  ise  sevinerek;  “Yarın  dostlarla, Muhammed (aleyhisselâm) ve arkadaşlarıyla buluşuruz” buyurdu. Peygamber efendimizi (aleyhisselâm) sevmenin alâmetlerinden birisi de, O’nun getirdiği yüce Kur’ân-ı sevmektir. Hazret-i Osman buyurdu ki: “Eğer bizim  kalbimiz  temiz  olsaydı,  asla  Kur’ân-ı  kerîm  okumaktan  doymazdı. Seven  kimse sevdiğinin kelâmından  nasıl  doyar ki,  O’nun  en  çok  istediği Sevgili   Peygamberimiz (aleyhisselâm)  birgün  Abdullah  bin  Mes’ûd’a (radıyallahü  anh): “Yâ  Abdullah! Kur’ân oku da dinliyelim”buyurdu.  İbn-i Mes’ûd: “Kur’ân size indi O’nu ben mi okuyayım dedi. Peygamber efendimiz (aleyhisselâm):  “Ben  başkasından  işitmeyi  severim”  buyurdu.  Bunun üzerine İbn-i Mes’ûd (radıyallahü anh) Nisa sûresinin başından başlayarak okudu. “Her ümmetten biri şâhid, seni de bunlara şâhid getirdiğimiz zaman hâlleri  nice  olur”  meâlindeki  41.  âyete  gelince,  Peygamber  efendimiz (aleyhisselâm)  “Yeter  yâ  Abdullah”  buyurdu.  İbn-i  Mes’ûd  başını  kaldırıp baktı  ki  Resûlullah  efendimizin  mübârek  gözlerinden  durmadan  yaş Bir kimse Kur’ân-ı kerîmi can kulağıyla dinlese, elbette ona te’sîr edip gözünden yaş gelir. Peygamber  efendimizi  sevmenin  bir  alâmeti  de  O’nun  sünnetine muhabbet edip hadîs-i şerîfini dinlemekten zevk almaktır. Zîrâ kişi sevdiği kimsenin sözünü işitmekten mutluluk duyar. O’nun güzel ismini anmak ve salevât-ı şerîfe getirmek O’nu sevmenin alâmetlerindendir. “Bir  kimse  sabaha  ve  akşama  yetiştiği  zamanda  bana  on  kere  salevât okusa;  kıyâmet  günü  şefaatime  müstehâk  olur”  ve  yine;  “Bir  şeyi unuttuğunuz  zaman  beni  hatırlayın  ve  bana  salât  edin.  Allah  dilerse  onu hatırlatır”  ve  “Cum’a  günü,  sizin  en  üstün  günlerinizdendir.  Adem aleyhisselâm o günde yaratıldı, o günde kabzolundu. Sûr’un üflenmesi ve ansızın helak oluş o günde olur. O hâlde, o günde bana salâh çok edin. Zîrâ salâtınız arz olunur” buyurdu.');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (20725, 'BÂLÎ-ZÂDE MUSTAFA EFENDİ', 'Osmanlılar  zamanında  yetişen  Hanefî  mezhebi  fıkıh  âlimlerinden. Otuzsekizinci  Osmanlı  şeyhülislâmıdır.  Babası,  Bâlî  Efendi’dir.  Bâlî-zâde diye  meşhûr  olmuştur.  Doğum  yeri  ve  târihi  bilinmemektedir.  1072  (m. 1661)  senesinde  İstanbul  Sütlüce’de  vefât  etti.  Orada  defn  edildi.  Bugün kabrinin yeri kaybolmuştur. İlk  tahsilini  babasından  gördükten  sonra,  zamanının  âlimlerinden ilim öğrenip  yükseldi.  İlimde  yüksek  derecelere  ulaştıktan  sonra,  Galata kadılığına ta’yin edildi. Burada bir müddet vazîfe yaptıktan sonra görevden alındı.  1058  (m.  1648)  senesinde  takrar  vazîfeye  alınarak,  Rumeli kadıaskerliğine  terfi  ettirildi.  Bilâhere vazîfeden  uzaklaştırılmışsa  da, Pâdişâh Sultan Dördüncü Mehmed Hân tarafından, Anadolu kadıaskerliğine Beş  yıl  müddetle  bu  vazîfeyi  yürüttükten  sonra,  1067  (m.  1657) senesinde Hanefî Mehmed Efendi yerine şeyhülislâmlık makamına getirildi. Altı  ay  müddetle  bu  vazîfede  kaldıktan  sonra,  aynı  yıl  içinde  vazîfeden alınarak,  Filibe’ye  kadı  olarak  gönderildi.  Daha  sonra  Yanbolu  kadılığına nakl  olundu.  Dört  yıl  Yanbolu’da  kaldıktan  sonra  İstanbul’a  döndü. Sütlüce’de ikâmet etti ve orada vefât etti. Âlim  ve  fıkıh  ilminde  özel  ihtisas  sahibi  olan  Bâlî-zâde  Mustafa Efendi’nin,  yazmış  olduğu  birçok  kıymetli  eserleri  vardır.  Bu  kıymetli eserleri  şunlardır:  1-Mîzân-ül-Fetâvâ:  Fetvâlarının  toplanmış  olduğu eseridir.  2-ferhu  Kenz-üd-Dekâik,  3-ferhu  Kasîde-i Bürde,  4-Es-Seyf-ül- Meslûl  fî  ferh-ir-Resûl,  5-Hâşiyetün  alâ  ferh-i  Miftâh,  6-Ehâdîs-i  şerîfe: Hazret-i  Hâlid  bin  Zeyd  Ebû  Eyyûb  el-Ensârî’den  rivâyet  edilen  hadîs-i şerîfleri topladığı eseridir. Bu eseri Eyyûb Sultan türbesine vakf etmiştir. 7-', '1058  (m.  1648)', '1067  (m.  1657)', '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:32.668894', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Osmanlılar  zamanında  yetişen  Hanefî  mezhebi  fıkıh  âlimlerinden. Otuzsekizinci  Osmanlı  şeyhülislâmıdır.  Babası,  Bâlî  Efendi’dir.  Bâlî-zâde diye  meşhûr  olmuştur.  Doğum  yeri  ve  târihi  bilinmemektedir.  1072  (m. 1661)  senesinde  İstanbul  Sütlüce’de  vefât  etti.  Orada  defn  edildi.  Bugün kabrinin yeri kaybolmuştur. İlk  tahsilini  babasından  gördükten  sonra,  zamanının  âlimlerinden ilim öğrenip  yükseldi.  İlimde  yüksek  derecelere  ulaştıktan  sonra,  Galata kadılığına ta’yin edildi. Burada bir müddet vazîfe yaptıktan sonra görevden alındı.  1058  (m.  1648)  senesinde  takrar  vazîfeye  alınarak,  Rumeli kadıaskerliğine  terfi  ettirildi.  Bilâhere vazîfeden  uzaklaştırılmışsa  da, Pâdişâh Sultan Dördüncü Mehmed Hân tarafından, Anadolu kadıaskerliğine Beş  yıl  müddetle  bu  vazîfeyi  yürüttükten  sonra,  1067  (m.  1657) senesinde Hanefî Mehmed Efendi yerine şeyhülislâmlık makamına getirildi. Altı  ay  müddetle  bu  vazîfede  kaldıktan  sonra,  aynı  yıl  içinde  vazîfeden alınarak,  Filibe’ye  kadı  olarak  gönderildi.  Daha  sonra  Yanbolu  kadılığına nakl  olundu.  Dört  yıl  Yanbolu’da  kaldıktan  sonra  İstanbul’a  döndü. Sütlüce’de ikâmet etti ve orada vefât etti. Âlim  ve  fıkıh  ilminde  özel  ihtisas  sahibi  olan  Bâlî-zâde  Mustafa Efendi’nin,  yazmış  olduğu  birçok  kıymetli  eserleri  vardır.  Bu  kıymetli eserleri  şunlardır:  1-Mîzân-ül-Fetâvâ:  Fetvâlarının  toplanmış  olduğu eseridir.  2-ferhu  Kenz-üd-Dekâik,  3-ferhu  Kasîde-i Bürde,  4-Es-Seyf-ül- Meslûl  fî  ferh-ir-Resûl,  5-Hâşiyetün  alâ  ferh-i  Miftâh,  6-Ehâdîs-i  şerîfe: Hazret-i  Hâlid  bin  Zeyd  Ebû  Eyyûb  el-Ensârî’den  rivâyet  edilen  hadîs-i şerîfleri topladığı eseridir. Bu eseri Eyyûb Sultan türbesine vakf etmiştir. 7-');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (20726, 'BANDIRMALI ALİ RIZÂ BEZZÂZ', 'Osmanlı son dönemi Nakşbendî-Hâlidî meşâyıhından. 1851 (m. 1267)’de, bugün  Bulgaristan’ın  Burgaz  şehri  yakınlarında  kalan  Ahyolu  kentinde doğmuştur.  93  harbi  diye  bilinen  Osmanlı-Rus  savaşında  Bulgaristan’dan Anadolu’ya geçen Ali Rızâ Efendi’nin Bandırma’ya ne zaman yerleştiği tam olarak bilinmemektedir. Kendisi, dönemin meşhur Hâlidî şeyhlerinden Halil Nûrullah  Zağravî’ye  intisâb  etmiş  ve  seyr  u  sülûkunu  tamamlayıp  hilâfet almıştır. Silsileleri Mevlânâ Hâlid Bağdâdî’ye şöyle bağlanır: Ali Rızâ Bezzâz, Halil Nûrullah Zağravî, Yanyalı Mustafa İsmet (Garîbullah), Abdullah Mekkî Erzincânî, Mevlânâ Hâlid Bağdâdî. Halil  Nûrullah  Efendi’nin  vefâtından  sonra  merkez  tekke  İstanbul’dan Bandırma’ya taşınmış ve Ali Rızâ Efendi’nin tekkesi irşâd görevini devam Ynceleri gemilerle nakliye yaptığı söylenen Ali Rızâ Efendi, bilâhare bu işi  bırakıp  kumaş  ticareti  ile  meşgul  olmuş,  bu  yüzden  kendisine manifaturacı anlamındaki Bezzâz lakabı verilmiştir. Rivâyete  göre  Ahıskalı  Ali  Haydar  Efendi  gençliğinde  Bandırma’ya uğramış  ve  vaazlarında  Ali  Rızâ  Bezzâz  hazretlerini  sert  bir  dille  tenkid etmiş.  Bu  tenkidler  Ali  Rızâ  Efendi’ye  aktarılınca,  Efendi:  “O  bizdendir” demekle  yetinmiş.  Bir  süre  sonra  Ali  Haydar  Efendi  sözlerinden  pişman olup  Ali  Rızâ  Efendi’ye  mürid  olmak  istemiş.  Ali  Rızâ  Efendi  onu İstanbul’daki  halifesi  Ahmed  Efendi’ye,  o  da  Topkapı’daki  Ali  Efendi’ye havâle etmiş. Böylece Ali Haydar Efendi bu tarîkata intisâb etmiştir. Bezzâz  Ali  Rızâ  Efendi  hakkında  şifâhî  bir  rivâyete  göre,  bir  sabah tekkede  Hatm-i Hâcegân  esnâsında  müridlerinden  birinin  aklına  bağının budanacağı gelir. Eve dönüp kahvaltı yapan ve biraz istirahat eden mürid, Livatya’daki  bağını  budamak  üzere  yola  çıkar.  Bağa  vardığında  işlerin çokluğunu görüp kederlenir. O arada kendisine bir uyku çöker. Uyandığında günün  bir  hayli  ilerlemiş  olduğunu  gören  müridin  telâşı  daha  da  artar. Ancak o anda bağın budanmış ve demetlerin bağlanıp hazırlanmış olduğunu farkeder.  faşkınlık  içerisinde  evine  dönen  mürid,  ertesi  sabah  yine tekkedeki  Hatm-i Hâcegân’a katılır. O zaman Ali Rızâ Bezzâz hazretlerinin dilinden şu sözler dökülür: “Ehlullah, Allah’ın izniyle insanların yardımına koşabilir, hatta bağını da budayabilir”. Ali Rızâ Efendi 1912 (m. 1330) senesinde vefât ederken geriye iki önemli halife bırakmıştır. Bunlardan birisi Ahıskalı feyh Ali Haydar Efendi’dir ki İstanbul’un Çarşamba semtindeki tekkede irşâda devam etmiştir, diğeri ise Bandırma’daki  tekkede  Ali  Rızâ  Efendi’nin  yerine  postnişîn  olan  Bilâl Efendi’dir. Bilâl Efendi şeyhinden dört sene sonra vefât edince (1334/1916) Bandırma’daki  tekkenin  fonksiyonu  sona  ermiş  ve  İstanbul’daki  tekke merkez hâline gelmiştir. Ali  Rızâ  Bezzâz  hazretleri  bir  evrâd  tanzîm  etmiş,  bunun  dışında herhangi bir eser kaleme almamıştır. Vefâtından sonra da bazı kerâmetleri görülmüştür.  Nakledildiğine  göre;  tekkenin  hazîresinde  bulunan  kabrinin yakınındaki kuyuya bir tavuk düşer. Bir süre sonra tavuk cesedi çürür fakat kimse  farkında  değildir.  Bir  gece  Ali  Rızâ  Efendi,  Eskici  Baba  ismindeki şahsın rüyâsında tecellî eder ve durumu haber verir. Ertesi gün tavuk cesedi çıkarılıp kuyu temizlenir. Yine nakledildiğine göre, Bandırmalı gönül ehli bir halı tüccarı, bir âileye iki adet halı satar. Halılar müşterinin evine götürülüp teslim edilir. Ancak halıları götüren görevli ücreti almayı unutur. Akşam hesaplanan kasa açık verir  ve  mesele  anlaşılır.  Ancak  bu  sefer  müşteri  itirâz  eder  ve  ücreti ödediğini ileri sürer. Çâresiz kalan halıcı, yatsı namazından sonra Ali Rızâ Efendi’nin kabri başında gerçeğin tecellî etmesi için duâ eder. Ertesi  sabah müşteri erkenden gelip parayı teslim eder ve heyecanla: “Lütfen paranızı alın, bu gece beni korkuttular” der. Bandırma’daki   tekkenin   ne   zaman   kurulduğu   kesin   olarak bilinmemektedir. Ali Rızâ Efendi’nin mezar taşında bu tekkenin kurucusu olduğu kayıtlı ise de, hazîredeki diğer mezar taşlarında 1135 (1722-3)  ve 1152 (1739) gibi târihlerin oluşu, orada çok daha önceleri bir tekke ya da en  azından  bir  câmi  olduğunu  göstermektedir.  1925’te  tekkelerin kaldırılışından sonra burası câmiye çevrilmiş ve Tekke Câmii adını almıştır. Bugün Tekke Câmii bahçesinde Ali Rızâ Efendi’nin yanısıra postnişîni Bilâl Efendi  ve  Ali  Rızâ  Efendi’nin  hanımı  Fâtımatü’z-Zehrâ  hanımın  (ö. 1333/1915) kabirleri de bulunmaktadır. Câminin caddeye bakan duvarının yanında  Ali  Rızâ  Efendi’nin  vâlidesi  tarafından  yaptırılan  bir  tulumba Ali Rızâ Efendi’nin evvelce ikâmet etmiş oldukları evin bugünkü sahibi olan  zâtın  öncülüğünde,  Bandırma  ve  civârının  gönül  ehli  insanları tarafından “Bandırma Hacı Ali Rızâ Efendi Vakfı” kurulmuştur. Vakıf, fakir insanlara  ve  talebelere  yardım  etmekte,  bu  sâyede  Bezzâz  Ali  Rızâ Efendi’nin rûhunu şâd etmektedir.', NULL, '1267', '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:32.668965', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Osmanlı son dönemi Nakşbendî-Hâlidî meşâyıhından. 1851 (m. 1267)’de, bugün  Bulgaristan’ın  Burgaz  şehri  yakınlarında  kalan  Ahyolu  kentinde doğmuştur.  93  harbi  diye  bilinen  Osmanlı-Rus  savaşında  Bulgaristan’dan Anadolu’ya geçen Ali Rızâ Efendi’nin Bandırma’ya ne zaman yerleştiği tam olarak bilinmemektedir. Kendisi, dönemin meşhur Hâlidî şeyhlerinden Halil Nûrullah  Zağravî’ye  intisâb  etmiş  ve  seyr  u  sülûkunu  tamamlayıp  hilâfet almıştır. Silsileleri Mevlânâ Hâlid Bağdâdî’ye şöyle bağlanır: Ali Rızâ Bezzâz, Halil Nûrullah Zağravî, Yanyalı Mustafa İsmet (Garîbullah), Abdullah Mekkî Erzincânî, Mevlânâ Hâlid Bağdâdî. Halil  Nûrullah  Efendi’nin  vefâtından  sonra  merkez  tekke  İstanbul’dan Bandırma’ya taşınmış ve Ali Rızâ Efendi’nin tekkesi irşâd görevini devam Ynceleri gemilerle nakliye yaptığı söylenen Ali Rızâ Efendi, bilâhare bu işi  bırakıp  kumaş  ticareti  ile  meşgul  olmuş,  bu  yüzden  kendisine manifaturacı anlamındaki Bezzâz lakabı verilmiştir. Rivâyete  göre  Ahıskalı  Ali  Haydar  Efendi  gençliğinde  Bandırma’ya uğramış  ve  vaazlarında  Ali  Rızâ  Bezzâz  hazretlerini  sert  bir  dille  tenkid etmiş.  Bu  tenkidler  Ali  Rızâ  Efendi’ye  aktarılınca,  Efendi:  “O  bizdendir” demekle  yetinmiş.  Bir  süre  sonra  Ali  Haydar  Efendi  sözlerinden  pişman olup  Ali  Rızâ  Efendi’ye  mürid  olmak  istemiş.  Ali  Rızâ  Efendi  onu İstanbul’daki  halifesi  Ahmed  Efendi’ye,  o  da  Topkapı’daki  Ali  Efendi’ye havâle etmiş. Böylece Ali Haydar Efendi bu tarîkata intisâb etmiştir. Bezzâz  Ali  Rızâ  Efendi  hakkında  şifâhî  bir  rivâyete  göre,  bir  sabah tekkede  Hatm-i Hâcegân  esnâsında  müridlerinden  birinin  aklına  bağının budanacağı gelir. Eve dönüp kahvaltı yapan ve biraz istirahat eden mürid, Livatya’daki  bağını  budamak  üzere  yola  çıkar.  Bağa  vardığında  işlerin çokluğunu görüp kederlenir. O arada kendisine bir uyku çöker. Uyandığında günün  bir  hayli  ilerlemiş  olduğunu  gören  müridin  telâşı  daha  da  artar. Ancak o anda bağın budanmış ve demetlerin bağlanıp hazırlanmış olduğunu farkeder.  faşkınlık  içerisinde  evine  dönen  mürid,  ertesi  sabah  yine tekkedeki  Hatm-i Hâcegân’a katılır. O zaman Ali Rızâ Bezzâz hazretlerinin dilinden şu sözler dökülür: “Ehlullah, Allah’ın izniyle insanların yardımına koşabilir, hatta bağını da budayabilir”. Ali Rızâ Efendi 1912 (m. 1330) senesinde vefât ederken geriye iki önemli halife bırakmıştır. Bunlardan birisi Ahıskalı feyh Ali Haydar Efendi’dir ki İstanbul’un Çarşamba semtindeki tekkede irşâda devam etmiştir, diğeri ise Bandırma’daki  tekkede  Ali  Rızâ  Efendi’nin  yerine  postnişîn  olan  Bi