INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (20858, 'HACI HALİFE KASTAMONİ', 'Bursa velilerinden. Asıl adı Abdullah’tır. Zeniyye yoluna mensuptur. feyh Taceddin’den  tasavvuf  yolunu  almış  ve  Ondan  sonra  Zeyniler  tekkesine Hacı Halife iyi huy ve tevazuda eşşizdi. Lutf ve ihsan kaynağı idi. Keramet ve hikmetli sözleri çoktur. Zamanın ileri gelen âlimleri ile sohbet etmiştir. Mesela Lâmiî Çelebi Fenarizade Ali Çelebi bunlardandır. Hacı Halife buyurdu ki: Bir  tasavvuf  talebesi  başta  nasıl  yürümeyi  niyet  ederse  nihayette  de süluku öyle olur. Yani masiva kalbden çıkarılmalı ve Hak’dan gayri kalbde hiçbir şey bırakılmamalıdır. Hakikati arayan bulur. İslamiyete uymadan Hakkı bulamayacağına itikad Resulullah Efendimiz bir tarafa dönüp bakacağı zaman bütün vücudu ile dönüp  bakardı.  Sadece  mubarek  boynunu  döndürüp  bakmazdı.  Yani  bir kimse neyi tutacak ise tam bir yönelişle o tarafa dönüp tutmalıdır. O zaman matluba kavuşur. Altı ay su içmedim, et yemedim. Kendiliğimden ne yaptı isem faydasını görmedim.  Ancak  Allahü  tealanın  emrettiklerini  yaptığım  zaman  fayda Hacı  halife  hazretleri  1488  (m.  894)  yılında  vefat  etti.  Zeyniler kabristanında Abdüllatif Kudsi’nin yakınındadır.', NULL, '894', '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:32.741773', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Bursa velilerinden. Asıl adı Abdullah’tır. Zeniyye yoluna mensuptur. feyh Taceddin’den  tasavvuf  yolunu  almış  ve  Ondan  sonra  Zeyniler  tekkesine Hacı Halife iyi huy ve tevazuda eşşizdi. Lutf ve ihsan kaynağı idi. Keramet ve hikmetli sözleri çoktur. Zamanın ileri gelen âlimleri ile sohbet etmiştir. Mesela Lâmiî Çelebi Fenarizade Ali Çelebi bunlardandır. Hacı Halife buyurdu ki: Bir  tasavvuf  talebesi  başta  nasıl  yürümeyi  niyet  ederse  nihayette  de süluku öyle olur. Yani masiva kalbden çıkarılmalı ve Hak’dan gayri kalbde hiçbir şey bırakılmamalıdır. Hakikati arayan bulur. İslamiyete uymadan Hakkı bulamayacağına itikad Resulullah Efendimiz bir tarafa dönüp bakacağı zaman bütün vücudu ile dönüp  bakardı.  Sadece  mubarek  boynunu  döndürüp  bakmazdı.  Yani  bir kimse neyi tutacak ise tam bir yönelişle o tarafa dönüp tutmalıdır. O zaman matluba kavuşur. Altı ay su içmedim, et yemedim. Kendiliğimden ne yaptı isem faydasını görmedim.  Ancak  Allahü  tealanın  emrettiklerini  yaptığım  zaman  fayda Hacı  halife  hazretleri  1488  (m.  894)  yılında  vefat  etti.  Zeyniler kabristanında Abdüllatif Kudsi’nin yakınındadır.');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (20859, 'HÂCI HALÎL EFENDİ', 'Osmanlı âlimlerinden. Yüzbirinci Osmanlı şeyhülislâmıdır. İsmi Halîldir. Sultan  oçüncü  Mustafa  Hân’ın  kızı  Hibetullah  Sultan’ın dadısının  küçük oğludur. Kafkasya’da doğdu. Doğum yeri ve doğum târihi ile babasının ismi bilinmemektedir.  1236  (m.  1821)  senesinde  Afyonkarahisar’da  vefât  etti. Orada bulunan Gedik Ahmed Paşa Câmii yakınında defnedildi. Pâdişâhın  emriyle,  çocuk  iken  Kafkasya’dan  getirilip  saraya  alındı.  O günlerde dünyâya gelen oçüncü Selîm ile birlikte büyüdü, saray terbiye ve tahsilinde  yetişti.  oçüncü  Sultan  Selim  Hân  pâdişâh  olunca,  onu  Hazine kethüdâlığına  ta’yın  etti.  oç  sene  sonra  Galata  kadılığına  getirildi.  Kendi isteğiyle  ilmiye  sınıfına  girdi.  Uzun  müddet  Galata  kadılığında  kaldıktan sonra, 1218 (m. 1803) senesinde Mekke-i mükerreme payesine nail oldu. O sene  hac  ibâdetini  yerine  getirip, sevgili  Peygamberimizin  (aleyhisselâm) mübârek kabrini ziyâret ettikten sonra, dönüşünde İstanbul kadılığına, çok geçmeden  Anadolu  kadıaskerliğine  getirildi.  İkinci  Sultan  Mahmûd  Hân devrinde,  1224  (m.  1808)  senesinde  Rumeli  pâyesiyle  “Meclis-i  âliyye” üyeliğinde  vazîfelendirildi.  1228  (m.  1813)  senesinde  Rumeli  kadıaskeri oldu. Bir  müddet  sonra  bu  vazîfeden  ayrıldıysa  da,  1234  (m.  1818) senesinde  tekrar  döndü.  Fakat  aynı  sene  içinde  tekrar  vazîfeden  ayrıldı. Sekiz gün geçtikten sonra Mekki-zâde Mustafa Âsım Efendi’nin ayrılmasıyla boşalan  şeyhülislâmlık  makamına  getirildi.  Yirmi ay  kadar  bu  vazîfeyi doğruluk  ve  adâlet  üzere  yürüttü.  1236  (m.  1821)  senesinde  vazîfeden ayrılıp Afyonkarahisar’a gitti. Afyonkarahisar’da iken, kısa bir müddet sonra Âlim ve fâzıl bir zât olan Halîl Efendi, âdil ve iffet sahibi idi. Eyyûb Sultan Câmii’nde  Ramazan  aylarında,  imsak  vaktinden  sabah  namazına  kadar Kur’ân-ı  kerîm  okuttururdu.  Bundan  başka  hayır  hasenatı  da  var  idi. Kaynaklarda eseri hakkında bilgiye rastlanmamıştır.', '1218 (m. 1803)', '1224  (m.  1808)', '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:32.742215', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Osmanlı âlimlerinden. Yüzbirinci Osmanlı şeyhülislâmıdır. İsmi Halîldir. Sultan  oçüncü  Mustafa  Hân’ın  kızı  Hibetullah  Sultan’ın dadısının  küçük oğludur. Kafkasya’da doğdu. Doğum yeri ve doğum târihi ile babasının ismi bilinmemektedir.  1236  (m.  1821)  senesinde  Afyonkarahisar’da  vefât  etti. Orada bulunan Gedik Ahmed Paşa Câmii yakınında defnedildi. Pâdişâhın  emriyle,  çocuk  iken  Kafkasya’dan  getirilip  saraya  alındı.  O günlerde dünyâya gelen oçüncü Selîm ile birlikte büyüdü, saray terbiye ve tahsilinde  yetişti.  oçüncü  Sultan  Selim  Hân  pâdişâh  olunca,  onu  Hazine kethüdâlığına  ta’yın  etti.  oç  sene  sonra  Galata  kadılığına  getirildi.  Kendi isteğiyle  ilmiye  sınıfına  girdi.  Uzun  müddet  Galata  kadılığında  kaldıktan sonra, 1218 (m. 1803) senesinde Mekke-i mükerreme payesine nail oldu. O sene  hac  ibâdetini  yerine  getirip, sevgili  Peygamberimizin  (aleyhisselâm) mübârek kabrini ziyâret ettikten sonra, dönüşünde İstanbul kadılığına, çok geçmeden  Anadolu  kadıaskerliğine  getirildi.  İkinci  Sultan  Mahmûd  Hân devrinde,  1224  (m.  1808)  senesinde  Rumeli  pâyesiyle  “Meclis-i  âliyye” üyeliğinde  vazîfelendirildi.  1228  (m.  1813)  senesinde  Rumeli  kadıaskeri oldu. Bir  müddet  sonra  bu  vazîfeden  ayrıldıysa  da,  1234  (m.  1818) senesinde  tekrar  döndü.  Fakat  aynı  sene  içinde  tekrar  vazîfeden  ayrıldı. Sekiz gün geçtikten sonra Mekki-zâde Mustafa Âsım Efendi’nin ayrılmasıyla boşalan  şeyhülislâmlık  makamına  getirildi.  Yirmi ay  kadar  bu  vazîfeyi doğruluk  ve  adâlet  üzere  yürüttü.  1236  (m.  1821)  senesinde  vazîfeden ayrılıp Afyonkarahisar’a gitti. Afyonkarahisar’da iken, kısa bir müddet sonra Âlim ve fâzıl bir zât olan Halîl Efendi, âdil ve iffet sahibi idi. Eyyûb Sultan Câmii’nde  Ramazan  aylarında,  imsak  vaktinden  sabah  namazına  kadar Kur’ân-ı  kerîm  okuttururdu.  Bundan  başka  hayır  hasenatı  da  var  idi. Kaynaklarda eseri hakkında bilgiye rastlanmamıştır.');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (20860, 'HÂCI BAYRAM-I VELÎ', 'Akşemse', '740 (m. 1340)', '750 (m. 1349)', '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:32.741886', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'İstanbul’u, Fâtih Sultan Mehmed Hân’ın fethedeceğini müjdeleyen büyük velî.  İsmi,  Nu’mân  bin  Ahmed  bin  Mahmûd olup, lakabları; Hâcı Bayram, Hâcı Paşa,  feyh Hâcı Paşa, Ahî  Sultan, Sultân-ı Rûm, feyh-ü’l  Rûm’dur. Babası,  Koyunluca  Ahmed  olarak  anılır. Ak  Medrese  ve  Kara  Medresede okumuştur. Hacı  Bayram-ı  Velî  ile  ismi  özdeşleşen bu   iki   medrese, günümüzde  Ankara’nın  unutulan tarihi değerlerindendir. Sôfiyye-i aliyyedendir. Somuncu  Baba ismi  ile müsemmâ Hamîd-i Aksarâyî’den feyz alarak,  zâhirî  ve  bâtınî  ilimlerde  üstün  derecelere  yükseldi.  Tasavvufta Bayramî yolunu kurdu. Fâtih Sultan Mehmed Hân’ın hocası Akşemseddîn hazretlerini  yetiştirip,  kemâle  getirdi. 740 (m. 1340)’de ,  Ankara  ilinin Hâcı Bayram-ı Velî’nin doğum tarihini; torunlarından Fuat Bayramoğlu dedesinin 90’ı aşkın sene yaşadığını (Ahdurrahman Askerî’nin rivâyetini) esas alarak 740  (m.  1339- 1340), Ethem Cebecioğlu 740 (m. 1340), Râzî 750 (m. 1349), Salih Dede 751 (m. 1351), Vassâf  758  (1357) olarak  zikretmektedir. Şeyh  İzzeddîn, Hâcı  Bayram-ı  Velî’nin ilk hocalarındandır. Vefâtı  1349’dur.  Dolayısıyla, Fuat  Bayramoğlu ve Ethem Çubuk  çayı kenarındaki Zülfadl  (Sel  Fasıl-Sol-Fasol)  köyünde  doğdu. Abdurrahman Askerî, Mir\'at-ü\'l-aşk isimli kitabında doksanı aşkın yaşlarda vefât ettiğini  bildirmektedir. Kefevî’nin bildirdiğine göre,  842  (m.  1438) senesinde Ankara’da vefât  etti. Hâcı  Bayram  Câmii’nin kıble duvarına olan türbesi ziyârete açıktır. Hâcı Bayram-ı Velî hazretlerinin; Safiyyüddîn ve Abdal Murad isminde iki ince ruhlu erkek kardeşi vardır. Ahmed, Edhem, Baba Sultan, İbrahim ve Ali olmak  üzere  beşi erkek,  üçü  de  kız  olmak  üzere  toplam  sekiz  çocuğu olmustur. Kızlarından ikisinin adı belli değildir. Hayrunnisa adındaki kızı, Eşrefoğlu Rumî ile evlenmiştir. Gül Baba da onun torunlarındandır. Annesinin  karnındayken annesi  onun,  “Allah “dediğini işitmiştir. Daha çocukluğunda akranlarından fark ediliyordu. Kırda-bayırda koyun güderken yalnız başına tefekkür etmekten büyük zevk alıyordu. Çubuk Çayı ile koyun ve  kuzuları  ile  söyleşiyordu. Kavga,  gürültü,  tembellik  nedir  bilmeyen, dedikodudan  nefret  eden,  çalışmayı,  insanlara,  çevresine  faydalı  olmayı seven,  büyüklerine  hürmetkâr,  kendinden  küçüklere,  hayvanata  karşı şefkatli, akranlarına karşı anlayışlı, okumaya meraklı, öğrenmeye kâbiliyetli, “sanki büyümüş de küçülmüş” denilen bir civandı. Bütün köylüler onu  pek seviyordu. Âlime, ulâmaya hayran ve onlar gibi olmaya çalışan bir kişiliğe sahipti. Yedi yaşlarında olgunluk alâmetleri görülmeğe başladı. Nu’mân,  küçük  yaşından  i’tibâren köyünde  Ku’rân-ı  kerîm  okumayı öğrendi.  Engürü’de Melike  Hâtun’un  yaptırdığı Kara   Medrese’de ilim tahsiline başladı. Ak Medresede, Ak femseddin lakaplı feyh İzzeddin’den Arapça öğrendi.  Kara  Medresede  temel  dersleri  bitirdikten sonra Kayseri, Bursa, Aksaray’da bulunan âlimlerin derslerine katılarak; tefsîr, hadîs, fıkıh gibi din ilimlerinde ve o zamanın fen ilimlerinde yetişti. Ak Medrese ve Kara Cebecioğlu’nun verdiği (m.  1340) doğum tarihi Hâcı Bayram-ı Velî’nin, Şeyh İzzeddîn’in talebesi olmasına da uygun düşmektedir. Çubuk çayı üzerindeki *“kenarındaki” olsa; çayın üzerinde yerleşim yeri olmaz, olsa olsa köprü olur.+ Hâcı Bayram-ı Velî’nin vefât tarihini ise; Lâmi’î Çelebi 832 (m. 1428-1429), Tabibzâde 833 (m. 1429)’un Muharrem ayı, Vassâf 833 (m. 1429-1430), Salih Dede 833 (m. 1430), Mehmed Ali Aynî de, \"Bursalı Mehmed Tahir\'in ve Mecdî\'nin verdiği bilgi ve  tahmine göre 833 (m. 1430), Kevefî 842 (m. 1438), Râzî ise 856 (m 1452) olarak zikretmektedir. Fâtih, 27  Receb  835  (30  Mart  1432)’de doğmuştur. Bu durumda Hâcı Bayram, Fatih doğmadan vefât etmiş olmaktadır. Hâcı Bayram-ı Velî’nin vefâtı için zikredilen  tarihler, Fâtih Sultan Mehmed Han’ın doğum tarihi ile çelişmektedir. Söz konusu vefât tarihleri göz önüne alındığında Hâcı Bayram-ı Velî hayatta olmadığı için, Fâtih doğduktan bir süre sonra onu görmesi, kucağına alması ve fetih müjdesi vermesi izah edilemez. Dolayısıyla, Hâcı Bayram-ı Velî’nin Fâtih Sultan Mehmed’i kucağına aldığı ve; “İstanbul’un fethini biz görmeyiz fakat bu Şehzâde ile şu bizim Köse görür” sözü ile verdiği fetih müjdesi, Kevefî’nin bildirdiği 842 (m. 1438) vefât tarihi ile daha uyumludur. Türbesi, Hâcı Bayram Câmii’nin kenarında ziyârete açıktır. Medrese’de müderrislik yaparak, talebe yetiştirmeğe başladı. Kısa zamanda, halk arasında sevilip sayılan bir kimse hâline geldi. İlimdeki bu üstünlüğüne rağmen Müderris Nûmân\'ın rûhunda bir sıkıntı vardı.  O,  bu  sıkıntıdan  ancak  bir  mürşid-i  kâmilin  huzûruna  varmakla kurtulabileceğini biliyor ve bir fırsat gözlüyordu. Nitekim Kara Medrese’de müderrislik  görevini sürdürürken 1392 senesinde bir  gün dersten çıktığında yanına  birisi  geldi ve; “İsmim  fücâ-i  Karamânî’dir.  Hocam Hamîdeddîn-i Velî hazretlerinin size selâmı ve dâveti var\" dedi. Nûmân, bu sözlerin sonunda kendisi için mühim bir haberin olduğunu anlamıştı. \"Hoş geldin,  safâlar  getirdin.  İnşâallah  hayırlı  haberlerle  gelmişsindir.  Anlat! Anlat!\"  diyerek  hayretle  sordu.  \"Beni  şeyhim  ve  mürşidim  Hamîdeddîn-i Velî  hazretleri  gönderdi  ve;  \"Git  Engürü\'de  (Ankara\'da)  Kara  Medresede Nûmân adında bir müderris vardır. Ona selâmımı ve dâvetimi söyle. Al getir. O bize gerek. Ben de bu vazîfe ile huzûrunuza gelmiş bulunuyorum” dedi. O da,  Hamîdeddîn  ismini  duyunca;  “Baş üstüne,  bu  da’vete  icabet lâzımdır. Hemen gidelim” diyerek müderrisliği bıraktı. fücâ-i Karamânî ile Kayseri’ye gittiler. Kayseri’de Hamîdeddîn-i Velî ile bir kurban bayramında buluştular.  O  zaman  Hamîd-i  Velî;  “İki  bayramı  birden  kutluyoruz” buyurarak, Nu’mân’a Bayram lakabını verdi. Hamîd-i  Velî,  Nu’mân  ile  başbaşa  sohbetlere  başlıyarak,  onu  kısa zamanda olgunlaştırdı.  Zâhirî  ve  bâtınî  ilimlerde  yüksek  derecelere kavuşturduktan  sonra  ona;  “Hâcı  Bayram!  Zâhirî  ilimleri  ve  bu  ilimlerde yetişmiş  âlimleri  ve  derecelerini  gördün.  Bâtınî  ilimleri  ve  bu  ilimlerde yükselmiş evliyâyı ve derecelerini de gördün. Hangisini murâd edersen onu seç!” buyurdu. Hâcı Bayram da, velîlerin yüksek hâllerini görerek, kendisini tasavvufa verdi ve bu yolda daha yüksek derecelere kavuşmak için çalıştı. 1394’de Hâmideddîn hazretleri, ma’nevî bir emir üzerine tekrar Tebrîz’e gitti. Tebrîz’den de Anadolu’ya gelip, Bursa’ya yerleşti. Bunun üzerine Hâcı Bayram-ı  Velî de, o   sene Bursa’ya giderek  hocasına  kavuştu.  Oradaki medreslerde hem ilmini ilerletti hem de müderrislik yaptı. Hocası Somuncu Baba’nın 800 Receb (m. 1400 yılının Mart) ayında bir Cumâ günü Bursa Ulu Câmii’nin açılısında okuduğu hutbede Fâtiha sûresine verdiği  çesitli mânâlar ilim erbâbı  ve  halk  arasında  büyük  yankı uyandırmıştır.  Bu  durum,  Ebû  Hamidüddin Aksarayî’nin  istemediği  bir şöhretin  ortasında  kalmasına  sebep  olmuştur. Bunun  üzerine hocası  ile 1400 yılında Bursa’dan ayrılarak, birlikte üç yıl süren bir yolculuğa çıktılar. İlk önce Adana üzerinden fam’a, oradanda Mekke ve Medine’ye gittiler. Hac vazîfelerini yaptıktan sonra 1403’de Aksaray’a geldiler. Hocasının yanında yirmi  sene hizmet edip manevî terbiyesini tamamladıktan sonra 815  (m. 1412)  senesinde,“Halîfem,  vekîlim  sensin”  emri  üzerine,  bu  ağır  vazîfeyi üzerine aldı.  Aynı sene hocası  vefât  edince,  cenâze  işleriyle  meşgûl  olup, cenâze namazını kıldırdı. Defin işlerini bitirdikten sonra Ankara’ya döndü. Dergâhını Ankara kalesi yakınında kalenin batı tarafında Kara Medrese’de talebe iken Arapça dersi aldığı feyd İzzeddin tarafından Ogüst kalıntısına bitişik yaptırılan Akmedrese’nin yanıbaşına inşâ etti. Bir defasında Hâcı Bayram-ı Velî, hocası Somuncu Baba’ya, “Sultanım, ne amel  üzerine  olalım,  sanat  bilmem  ne  işleyelim?”  dediğinde,  “Ekin  ek, burçak  ek”  cevabını  almıştı. Ankara’ya dönünce çiftçilikle  meşgul  oldu. Talebelerini  daha çok  zirâate ve  sanata sevkederdi.  Kendisi  de  geçimini zirâatle temin  ederdi. Hâcı Bayram-ı Velî,  ziraatle  meşgul  olduğu  kadar esnaf  ile  de temas hâlinde idi. Ahi zaviyeleri mensupları da Hâcı Bayram dergâhının müdavimlerindendi. Hâcı  Bayram-ı Velî’ye, Somuncu  baba  vasıtasıyla Erdebîlî  yolundan  da feyz gelmektedir.  Erdebil,  Tebrîz  civârında  bir  kasabadır.  Safiyyüddîn Erdebilî ömrü boyunca Allahü teâlânın dînine hizmet etmek, Selef-i sâlihînin doğru yolu ehl-i sünneti insanlara öğretmek için çalıştı. Talebeleri doğuya ve  batıya  dağılarak,  onun  feyizli   yolunu  yaydılar.  Talebelerinden  oğlu Sadreddîn ve torunu Alâeddîn Ali meşhûrdur. Hâce Alâeddîn Ali’nin talebesi olan Ebû Hâmid-i Aksarâyî yânî Somuncu Baba da, Alâeddîn Ali’den aldığı feyz ve bereketi Anadolu’da yaydı. Hacı Bayram-ı Veli de Somuncu Baba’dan aldığı  yolu, Halvetiyye,  Nakşibendiyye  ve  Ebheriyye’yi Bayramiyye’de birleştirek kendine has bir usulle irşadını sürdürdü. Ankara’da dînin emir ve yasaklarını insanlara anlatmaya, onlara doğru yolu  göstermeye,  yetiştirmeye  başladı.  Hergün  pekçok  kimse  huzûruna gelir, hasta kalblerine şifâ bularak giderlerdi. 1415  senesinde,  feyh  İzzedddin  tarafından  Anadolu’nun  en  eski mabetlerinden  biri  olan  Ogüst binasının yıkıntılarını  restore  ederek  inşa ettirdiği Ak Medrese’nin yanında kendi zaviyesini inşâ etti. Aynı  yıl  Karaman  seferine  giden  Çelebi  Mehmed  yolda  hastalandı  ve Ankara’ya getirilerek Hâcı Bayram Velî’nin müridlerinden feyhî tarafından burada   tedavi   edildi. Onun  zaviyesini  kurmasıyla  Ankara’nın  çehresi değişmiş, talebeleri  gün  geçtikçe  çoğalmaya, insanlar. akın  akın  gelmeye Ankara’ya ve Hâcı Bayram dergâhına gelmeye başladılar. Kısa zamanda ismi her tarafta duyuldu. İsmi  Muhammed,  lakabı  Akşemseddîn  olan  bir  genç,  aklî  ve  naklî ilimlerde yetişip, Osmancık’da müderris olmuştu. Tıb ilmi üzerinde oldukça bilgisi vardı. Talebelerin dersini verdikten sonra, diğer vakitlerinde nefsini terbiye  etmek  için  uğraşırdı.  Ayrıca  bu  konuda  kendisini  yetiştirecek  bir büyük  velîyi  de  araştırıyordu. Yirmi  beş  yaşlarında  iken  kendisine  bir mürşid aramak üzere Horasan ve Maveraünnehir\'e doğru yola çıktı. Ancak geri  döndü. Birkaç  sene  sonra Ankara’dan  gelen  ba’zı kimseler,  Hâcı Bayram-ı Velî’yi medhettiler.  Onların tavsiyeleri  ile medreseyi  bıraktı  ve 824 (m. 1421) senesinde Ankara’ya hareket etti. fehre geldiğinde rastladığı bir  kimseye Hâcı Bayram-ı Velî\'yi nerede bulabileceğini sordu. O da karşı sokakta yanında iki talebesiyle gezen bir zâtı göstererek; \"İşte şu gördüğün, dükkan dükkan gezerek para toplayan kişi Hâcı Bayram\'dır\"  dedi. Demek meşhur  velî Hâcı Bayram  dükkan  dükkan  para  topluyor,  buralara  kadar kendimi  boşuna  yormuşum, diyerek  oradan  uzaklaştı. Doğru  Osmancık’a Haleb’de,  ismi  Zeynüddîn  olan  bir zâtın evliyâlıkta  yüksek  dereceler sahibi olduğunu  işitmişti. Fikrini değiştirerek ona talebe  olmak  gâyesiyle medrese arkadaşı Abdürrahîm ile Haleb\'e doğru yola çıktılar. Günlerce yol aldıktan  sonra Haleb\'e  bir  konak  mesâfeye  geldiğinde  bir  hana  indiler. Akşemseddîn, seher vakti gördüğü rü’yâ üzerine korku, şaşkınlık ve dehşet içerisinde uyandı. Rü’yâsında, boynuna bir zincir takılmıştı. Zincirin diğer ucu  ise Hâcı Bayram\'ın elindeydi.  Akşemseddîn, Haleb\'e  gitmek  istedikçe Hâcı Bayram zinciri çekiyordu. Tam boğulmak üzere iken uyanmıştı. Rüyâ, tâbir gerektirmeyecek kadar açıktı. Bu rü’yâ üzerine, Akşemseddîn yaptığı hatâyı anladı ve sabah namazını edâ ettikten sonra hemen Ankara’ya geri dönmek için yola çıktı. Abdürrahîm de, Mısır’a doğru yoluna devam etti. Akşemseddîn, Hâcı  Bayram-ı  Velî’nin  dergâhına vardı. Hâcı  Bayram-ı Velî’nin,  talebeleriyle  beraber  tarlada  olduğunu  öğrendi.  Hemen  tarlaya gitti.  Hâcı  Bayram-ı  Velî,  onu  görmesine  rağmen,  hiç  iltifât  etmedi. Akşemseddîn, diğer talebeler gibi tarlada çalıştı. Yemek  vakti  gelince,  yine Akşemseddîn’e  kimse  iltifât  etmedi. Yemek  vakti gelince,  Akşemseddîn\'in yüzüne  bakmadı. Hâcı Bayram-ı  Velî,  hazırlanan  yemeği  orada  bulunan talebelerine taksim etti. Artakalan yemeği de köpeklerin çanağına döktürdü. Akşemseddîn bir  onlara  bir  de  kendine  bakarak, nefsine; “Ey  nefsim!  Sen, Allahü teâlânın büyük bir velî kulunu beğenmezsen, işte böyle yüzüne bile bakmazlar. Senin lâyık olduğun yer burasıdır” diyerek, köpeklerin yanına yaklaşıp,  onlarla  beraber  yemeğe  başladı.  Hâcı  Bayram-ı  Velî,  onun  bu tevâzuuna  dayanamıyarak;  “Köse,  kalbimize  girdin,  gel  yanıma”  dedi  ve gönlünü  alıp,   kendi  sofrasına  oturttu.  Sonra  ona; “Zincirle   zorla   gelen misâfiri böyle ağırlarlar” diyerek, onun gördüğü rü’yâyı, kerâmet göstererek anladığını bildirdi. Akşemseddîn, kabûl edildiğine çok sevindi ve hocasının gösterdiği  kerâmetler ile  ona  bağlılığı  daha  da  arttı, kendini  onun  irfan meclisine  verdi. Hocasının sohbetlerini hiç kaçırmayarak, kalblere şifâ olan nasihatlerini zevkle dinlemeye başladı. Hâcı Bayram-ı Velî hazretleri Akşemseddîn\'i diğer talebelerinden daha zor imtihanlara tâbi tuttu. Nefsini terbiye ve ıslah etmekte büyük sıkıntılar çektirdi.  Bir  defâsında  yedi  günde  bir  kaşık  sirkeden  başka  bir  şey yedirmedi. Ancak Akşemseddîn bütün bunlardan memnun ve hattâ kendisi daha fazlasına tâlipti. Nitekim nefsinin istediği şeyleri yapmamakta şeyhinin kendisine buyurduğu tâlim ve terbiyedeki şiddet derecesini kendi isteğiyle artırdığı zaman Hâcı Bayram  hazretleri  ona: \"Yâ Köse nice riyâzet eylersin, nefsin isteklerinden sakınırsın, âkıbet nûr olursun. Vefât ettikten sonra seni kabrinde  bulamazlar!\"  dedi. Böylece Akşemseddîn hazretleri kısa zamanda tasavvuf  yolunun  bütün  inceliklerini  öğrendi. Nefsini   terbiye   etmekte herkesten  daha  ileri  gitti. Hâcı Bayram-ı Velî’nin teveccühleri altında, kısa zamanda  bütün  talebe  arkadaşlarının  önüne  geçti. Ve Hâcı Bayram hazretlerinden icâzetini, diplomasını aldı. Akşemseddîn’e icâzet (diploma) verdiğinde, ba’zıları; “Efendim! Sizden yıllarca  okuyan  talebelere  hilâfet vermediğiniz  hâlde,  bu  yeni  gelen Akşemseddîn’i  kısa  zamanda hilâfet ile  şereflendirdiniz?”  dediler. Hâcı Bayram-ı Velî de; “Bu öyle bir kösedir ki, bizden her ne görüp duydu ise hemen  inandı.  Gördüklerinin  ve  işittiklerinin  hikmetini  de  bizzat  kendisi anladı.  Fakat  yanımda  yıllardır  çalışan  talebeler,  gördüklerinin  ve duyduklarının  hikmetini hemen bana sorarlar.  Ona  hilâfet  vermemizin sebebi işte budur” diye cevap verdi. Hâcı Bayram-ı Velî, bu şekilde hem talebelerini yetiştiriyor, hem de belli saatlerde  câmide insanlara va’z ve nasihat ediyordu. Herkes Hâcı Bayram-ı Velî’nin va’zlarına koşuyor, ba’zı kerâmetlerini de görünce, ona daha çok bağlanıyorlardı.  Bu  şekilde Hâcı Bayram’ın  etrâfında  pekçok  kimsenin toplandığını  gören  ba’zı  hased  ediciler,  Pâdişâh  İkinci  Murâd  Hân’a; “Sultânım!  Ankara’da Hâcı Bayram  isminde  biri,  bir  yol  tutturarak  halkı başına toplamış. Aleyhinizde ba’zı sözler ederek, saltanatınıza kasd edermiş. Bir  isyan  çıkarmasından  korkarız!”  diyerek  iftiralarda  bulundular.  Bunun üzerine  sultan,  durumun  tetkik  edilmesi  için  iki kişi vazîfelendirip;  “O kimseyi  hemen  gidip  getirin.  Emrimize  baş  kaldırıp  isyan  ederse,  zincire vurarak getirin!” emrini verdi. 825 (m.  1422)  senesinde vazifeli çavuşlar, ellerinde pâdişâhın fermanı olduğu  hâlde,  Edirne’den  kalkıp  son  sür’atle  Ankara’ya  doğru  yol  aldılar. Ankara’ya yaklaştıklarında önlerine; Yaşlı, nûr yüzlü bir kimse ile bir genç çıktı.  Selâmlaştıktan  sonra  ihtiyâr  zât;  “Evlâtlarım!  Nereden  gelip  nereye gidiyorsunuz?”  diye  sorunca,  onlar  da;  “Ankara’da  Hâcı  Bayram  isminde biri. Etrâfına adamlar toplayıp, Pâdişâhımıza başkaldırmış. Onu yakalayıp Derse’âdet’e götüreceğiz” dediler. Çavuşların bu sözünü bekliyen ihtiyâr zât; “O aradığınız Hâcı Bayram bu fakirdir” diyerek, kendisini gösterdi. Çavuşlar bir  fermana  baktılar,  bir  de Hâcı Bayram-ı  Velî’ye,  aradıkları  isyancı  bu olamazdı. Çünkü bu  nûr  yüzlü,  hoş  sözlü  zât,  isyan  edecek  bir  kimseye benzemiyordu. Hâcı Bayram-ı Velî’ye tekrar tekrar dikkatle baktıktan sonra, birbirlerine;  “O  zaman  hemen  yola  çıkıp Sultânımıza  gidelim.  Bu  zâtın ma’sûm olduğunu, söylenilenlerin yanlış olduğunu bildirelim” dediler. Fakat Hâcı Bayram; “Evlâtlar! Sizin geleceğinizi biliyorduk. Onun için yola çıkıp sizi bekledik. Pâdişâhımızın fermanı başımız üzerinedir. Haydi durmayınız, elimi  zincirle  bağlayınız  ve  bir  ân  önce  buradan  gidelim”  buyurdu.  Bu sözlere  iyice  hayret  eden  çavuşlar,  “Sizi  yanlış anlatmışlar efendim.  Size karşı  edebsizlik  etmeye  hayâ ederiz.  Hele  zincire  vurmak  hiç  yakışmaz. Madem ki emrediyorsunuz, buyurunuz gidelim” dediler. Hâcı Bayram ile yanındaki genç talebesi Akşemseddîn, çavuşlarla birlikte Edirne’ye doğru yola koyuldular. Hâcı Bayram-ı Velî, yol boyunca çavuşlarla sohbetler etti,  onlara  nasihatlerde  bulundu.  Günler  sonra  Çanakkale boğazından geçip, Edirne’ye geldiler. Sarayda Sultan İkinci Murâd Hân, söylentilere göre devletin selâmetine kasdeden ve tahtına göz diken bir eşkiya beklerken, karşısında: nûr yüzlü, kâmil bir velî gördü. Hayretini hiç saklamayarak, onu baş köşeye oturttu. Sohbete başladılar. Sultan Murâd, şehzâdeliğinden beri ilme pek meraklı idi ve büyük bir âlim olarak yetişmişti. Hâcı Bayram-ı Velî konuştukça, ilminin yüksekliğini,  böyle  kıymetli  bir  âlim  ve  evliyânın  devlete  baş kaldırmayacağını  daha  iyi  anladı.  Tâ  Ankara’dan  buraya  kadar  zahmet çektirip  getirttiğine  çok  üzüldü,  tanışmakla  şereflendiği  için  de  sevindi. Tasavvuftaki  ba’zı  müşküllerini  Hâcı  Bayram-ı  Velî’ye  sordu.  Aldığı cevaplardan ziyadesiyle memnun oldu. Onun ilmine hayran kaldı. Onu apar topar yerinden getirttiği için, nasıl gönlünü alacağını bilemiyordu. Pek çok ihsânda  bulunup,  hediyeler  verdi.  Fakat  Hâcı  Bayram-ı  Velî;  “Sultânım! Bizim  dünyâ  malında  gözümüz  yoktur.  Siz  onları  alıp,  ihtiyâcı olanlara veriniz” diyerek nâzikçe reddetti. Pâdişâh ısrar edince de; “Mutlaka ihsânda bulunmak istiyorsanız, talebelerimizin, devlete vereceği vergilerden muaf tutulmasını arzu ederiz” buyurdu. Pâdişâh da memnuniyetle kabûl etti. Hâcı Bayram-ı Velî’yi günlerce sarayda misâfir etti, izzet ve ikramda bulundu. Hâcı Bayram-ı  Velî  hazretleri, Edirne’de  bulunduğu  müddet  içinde, değişik câmilerde va’z verip, halka nasihatlerde bulundu. Edirneliler de onu çok sevdiler. Onun hangi câmide nasihat edeceğini öğrenip, oraya akın akın giderlerdi. Hâcı Bayram-ı Velî hazretleri, Velî Dede dergâhında çileye girmiş. Çileden çıkınca Eski Câmi’de bir aya yakın va’z vermiştir. Pâdişâh da onun Edirne’de  kalmasını  istiyordu.  Fakat Hâcı Bayram-ı  Velî,  Ankara’ya talebelerinin  başına  dönüp,  onları  yetiştirmeye  devam  etmek  istediğini O zaman Sultan Murâd, ondan nasihat istedi. Hâcı Bayram, nasihat olarak buyurdu  ki:  “Tebe’an içinde  herkesin  yerini  tanı,  ileri  gelenlere  ikramda bulun. İlim  sahiplerine  hürmet  et.  Yaşlılara  saygı,  gençlere  sevgi  göster. Halka  yaklaş  fâsıklardan  uzaklaş,  iyilerle  düşüp  kalk.  Hiç  kimseyi küçümseme  ve  hafife  alma.  İnsanlığında  kusur  etme. Sırrını  hiç  kimseye açma.  İyice  yakınlık  peyda  etmedikçe,  kimsenin  arkadaşlığına  güvenme. Cimri  ve  alçak  insanlarla  ahbablık  kurma.  Kötü  olduğunu  bildiğin  hiçbir şeye  ülfet  etme.  Seninle  başkaları  arasında  bir  toplantı  akdedilir   veya insanlarla  aranızda  ba’zı  mes’eleler  görüşülürse,  yahut  onlar  bu mes’elelerde  senin  bildiğinin  hilâfını  iddia  ederlerse,  onlara  hemen muhalefet etme. Sana birşey sorulursa, ona herkesin bildiği şekilde cevap ver.  Sonra  bu  mes’elede  şu  veya  bu şekilde  görüş  ve  delîllerin  de bulunduğunu söyle. Senin bu türlü açıklamalarını dinleyen halk, hem senin değerini, hem de başka türlü düşünenlerin değerini tanımış olur. Sana bu görüş  kimindir?  diye  sorarlarsa,  fakîhlerin  bir  kısmınındır,  de.  Onlar, verdiğin cevâbı benimserler ve onu sürekli olarak yaparlarsa, senin kadrini daha iyi bilir ve mevkiine daha çok hürmet ederler. Seni ziyârete gelenlere ilimden  birşey  öğret  ki,  bundan  faydalansınlar  ve  herkes,  öğrettiğin  şeyi belleyip  tatbik  etsin.  Onlara  umûmî şeyleri  öğret,  ince  mes’eleleri  açma. Onlara güven ver, ahbablık kur. Zira dostluk, ilme devamı sağlar. Ba’zan da onlara yemek ikram et. İhtiyâçlarını te’min et. Onların değer ve i’tibârlarını iyi  tanı  ve  kusurlarını  görme.  Halka  yumuşak  muâmele  et,  müsamaha göster. Hiç bir kimseye karşı bıkkınlık gösterme, onlardan biriyimişsin gibi Sonra  Sultan  Murâd’ın   verdiği  fermanı  alarak vedalaşır   ve Akşemseddin’le Ankara’ya döndüler. Sıkı bir riyâzet ve mücahededen sonra kemâle gelen Akşemseddin’e hilâfet verip Beypazar’ına gönderdi. Hâcı Bayram-ı Velî,  Ankara’ya  Sultan  Murâd  Hân’ın  verdiği  ferman ile geldi.  Fermanda, Hâcı Bayram-ı Velî hazretlerinin talebelerinin, yalnız ilim ile  meşgûl  olmaları  için,  onların  vergi  ve  askerlikten  muaf  tutulduğu bildiriliyordu. Bunu duyan birçok kişi, vergiden ve askerlikten kurtulmak için Hâcı Bayram-ı Velî’nin talebesi olduğunu söylemeye başladı. Bunlar o kadar çoğaldı ki, Ankara’nın mâlî ve askerî düzeni bozuldu. Yyle oldu ki, devletin vergi memurları Ankara ve civarından vergi toplayamaz hâle geldi. Bunun  üzerine  Sultan, “İnsanların  ekserisi,  suretlerini  cenab-ı  şerifinizin dervişlerinin kılığına girmişler. Ne miktar dervişiniz varsa, bize bildiresiniz ki,  ona  göre  amel  oluna” mealinde  bir  mektubu, Hâcı Bayram  Velî  \'ye gönderip ondan talebelerinin bir listesini istedi. Bunun  üzerine Hâcı Bayram-ı  Velî,  Ankara’nın Kanlıgöl mevkiinde [bugün Numune Hastanesi ve Etnografya müzesinin bulunuduğu bölgede] bir çadır kurdurdu ve; “Bize intisâb edenler burada toplansın” diye ilân etti. Hâcı Bayram-ı Velî’nin talebesi olduğunu söyleyen herkes, akın akın gelip meydanı  doldurdu.  Hâcı  Bayram-ı  Velî;  “Dervişlerim,  müridlerim!  Bana intisâb eden talebelerimi bugün burada kurban etmem gerek. Canını, malını bana feda eden, çadıra girsin” buyurdu. Bütün talebeleri bir korku aldı. Bir uğultu  yükseldi. Vergiden  kaçmak için  talebe  görünenler;  \"Bu  ne biçim mürşid; bu nasıl müridlik\" diye söylenip duruyorlardı. Hâcı Bayram-ı Velî de,  elinde  keskin  bir  bıçak  ile  çadırın  kapısında  beklemeye  başladı.  Bu sırada topluluktan, bir erkek ile bir kadın kalabalığı yararak doğruca çadırın içine  girdiler.  Arkalarından Hâcı Bayram-ı  Velî  de  girdi.  Daha  önceden çadıra koyduğu koyunu içeride hemen kesti. Kırmızı bir kan, çadırdan dışarı çıktı. Kanı gören herkes hemen kaçtı. Meydanda kimse kalmadı. Daha sonra dışarı çıkan Hâcı Bayram-ı Velî buyurdu ki: “Anladık ki, bu kadar talebemiz varmış. Bunlardan başka herkes, vergi vermek ve askerlik yapmak sûretiyle, devlete karşı olan borcunu ödemelidir.” Ve, bir mektup yazarak, \"Biri erkek diğeri kadın iki müridim var,  gayrı yoktur\" diye  durumu  Sultan  II.  Murad\'a Bir  gün Hâcı Bayrâm-ı  Velî\'ye  talebeleri;  \"Sultânım!  Takkeniz  eskimiş. Hediye gelen güzel bir keçe var. Müsâade ederseniz ince keçelerden bir taç diktirelim.\"    dediklerinde;    \"Sabredin    takkeci    gelsin\"    buyurarak Pîr Muhammed\'in  hocası  ile  Anadolu\'ya  gelmekte  olduğunu işâret etti. O günlerde  feyhülislâm  Berdeî,  bir  davet  üzerine  memleketi  Tebrizden Eğirdir’e gitmek  için  talebesi Pîr Muhammed  ve  yanlarında  bulunanlarla birlikte Anadolu’ya doğru yolculuk hâlinde idiler. Onlar şehre yaklaştıkları sırada Hâcı Bayrâm-ı Velî\'ye mâlum olup; \"Takkeci geliyor! Karşılayalım.\" diyerek talebeleri ile birlikte karşılamaya çıktılar. Hâcı Bayrâm-ı Velî gelen misafirleri karşılayıp dergâhına götürdü. Birkaç gün misâfir edip, ziyâfetler verdi. Çok kıymetli sohbetler yaptılar. Bir gün Hâcı Bayrâm-ı Velî talebelerinden, hediye gelen keçeleri getirmelerini istedi. Sonra bunları Pîr Muhammed\'in önüne koyarak; \"Oğlum Pîr Muhammed! Bunlardan  bize  bir  takke  dikiver\"  dedi.  O  da  alıp  güzel  bir  takke  dikti. Getirip önlerine koydu. Hâcı Bayrâm-ı Velî; \"Oğlum Pîr Muhammed! Bu tâcı bana  hocandan  gördüğün  gibi  giydir.\"  dedi.  O  da  alıp salevât ve  tekbir getirerek Hâcı Bayrâm-ı  Velî  hazretlerine  giydirdi.  Bunun  üzerine Hâcı Bayrâm-ı  Velî,  feyhülislâm  Berdeî  hazretlerine; “Hoş  feyhülislâmsın! Altı aylık  müridine, seksen  yaşındaki  bir  ihtiyâra taç  giydirtirsin” diye  lâtife yaptı. Bu misâfirlikten sonra Hâcı Bayrâm Velî ile vedâlaşıp Eğirdir’e doğru yeniden yola revan oldular... 1423 yılının ilk aylarında kardeşi II. Mustafa’ya karşı düzenlediği sefer sırasında Hâcı Bayram Velî ile görüşen II. Murad, kendisine vezirlik tekfinde bulunur, fakat o bu teklifi kabul etmez. 1426 yılında Sultan II. Murad’ın daveti üzerine Hâcı Bayram-ı Velî, tekrar Edirne’ye doğru  yola  çıkar.  Bugünkü  tarihi  Uzunköprü’nün yâni  Ergene Köprüsü’nün temeli dualarla atılır. Hâcı Bayram ile Emir Sultan birlikte dua ederler. Bir gün bir gece Ergene’de kalan Hâcı Bayram,  II.  Murad ve birçok zevâtla  birlikte  Edirne’ye  geçer.  Bir  müddet  kaldıktan  sonra  Ankara’ya döner. 1427-1428 yılında güzel ve iftihar edilecek bir bir câmi inşa etti. Emir  Sultan,  vefât  ettiğinde kendisini Hâcı Bayram’ın  yıkamasını, namazını  kıldırmasını,  defnetmesini  istemiştir. 833  (m. 1429) senesinde Emir Sultan’nın, hastalığı ağırlaşınca Hâcı Bayram Bursa’ya giderek vasiyeti gereği  cenaze  hizmetlerini  yerine  getirdi. Defni  müteakip  oradan   da Ankara’ya döndü. 27 Receb 835 (30 Mart 1432)’de İstanbul’un Fâtih’i, şehzâde Mehmed doğduğu sene güz sonu Hâcı Bayram-ı Velî, Akşemseddin ile birlikte yine Edirne’ye gittiler. Bir sohbet sırasında, Sultan  II. Murâd Hân, bu mübârek zâtın  feyzinden,  küçük  şehzâdesi  Mehmed’in  de  istifâde  etmesini  istedi. fehzâde  Mehmed’i  de  bulundukları  yere  getirdiler. İstanbul’un  fethi hakkında konuşuluyordu. Her İslâm sultânı gibi, Sultan Murâd da, İstanbul’u fethetmeyi düşünüyor, hazırlığını ona göre yapıyor, Resûlullahın müjdesine mazhar  olmak  istiyordu.  Gönlünden  geçen  duyguları,  huzûrunda bulunmakla  şereflendiği Allah  dostuna, Hâcı Bayram-ı Velî’ye  açtı. Sultan İkinci Murâd Han; “Allahü teâlânın izniyle, evliyânın himmet ve bereketleri ile İstanbul’u almak istiyorum. Bu işe birkaç kez girişildi. Rahmetli  dedem Yıldırım Bâyezid Hân da bu işe teşebbüs etti. Fakat şimdiye kadar kesin bir netice  elde  edemediler. İstanbul’un  fethi  müyesser  olmadı. Devlet-i  âl-i Osman’ın topraklarının ortasında bir Bizans devletinin olmasına hiç gönlüm râzı değil. Sevgili Peygamberimizin fethini va’d ettiği İstanbul bize lâzım. Bunu  almak  için  de  himmetinizi,  yardımınızı  bekliyorum. Aceb Kostantiniyye’nin fethi kime müyesser olacak?” dedi. Murâd Hân bu sözleri söylerken, Hâcı Bayram-ı  Velî  derin  bir  tefekküre  dalmış  hâlde onu dinliyordu. Söz bitince, fehzâde Mehmed ve Akşemseddîn’i işâret ederek tane  tane  şöyle  konuştu;  “Sultânım!  Bu  şehrin  alınışı  ne size,  ne  de  bize nasîb  olacak.  İstanbul’un fethini, bu küçük  fehzade ile, şu bizim  Köse görürler” buyurarak büyük müjdeyi verdi. Sultan Murâd Hân, bu müjdeye çok  sevindi.  Oğlu  şehzâde  Mehmed’e  ve  Akşemseddîn’e  artık  başka  bir nazar  ile  bakmağa  başladı. Sohbetler  edilip  ikrâmlar  yapılır. ferbetler içilirken Sultan  Murâd  Han,  Fâtih  için  duâ  isteyince;  “Onu  hocasına bırakmak  lâzım”  diyerek,  Akşemseddîn’in  hâce-i  sultânî  (sultan  hocası) olacağını müjdeler. Küçük  Fâtih’i  kucağına  alıp onun  gözlerine  bakarak, uzun uzun teveccühde  bulunur. Bu teveccüh ve müjdeden çok duygulanan Sultan  Murâd  Hân, Hâcı Bayram-ı  Velî  ile  istişâre  edip,  Akşemseddîn’i şehzâde  Mehmed’e  hoca  ta’yin  etti.  Akşemseddîn,  bir  müddet  şehzâde Mehmed’in eğitim ve terbiyesi ile bizzat ilgilendi, ona teveccüh ederek feyz Hâcı Bayram, dönüşte Gelibolu’ya uğradı. O  günlerde  Bîcân kardeşler mânevî  ilimlerde  de  yükselmek  istiyor,  kendilerini  irşâd  edecek,  doğru yolun mânevî zevklerini tattıracak bir evliyâ arıyorlardı. Hâcı Bayram-ı Velî ile buluştuklarunda büyük velî, onlara muhabbet nazarları ile bakıp duâ etti, sonra; \"Yağ ve kandil hazırmış, bize yalnız kibriti yakmak kalmış.\" buyurdu. Bir müddet onları yetiştirmek için orada kaldı. Onları Bayramiyye yolu  ile irşâd  edip  kısa zamanda  ikisi  de  evliyâlık  derecelerine kavuşturdu. Kısa zamanda  bu  iki  kardeşe  icâzet  (diploma)  vererek,  insanları  yetiştirme vazîfesini  verdi. Sonra  kendisine  katılan  Akşemseddin  ile Gelibolu’dan ayrıldılar. Akşemseddin Göynük’de kaldı. Hâcı Bayram-ı Velî hazretleri de Ankara’ya döndü. Aradan  birkaç  sene  geçmişti. Hâcı Bayram-ı  Velî,  son  hastalığında talebelerini  yanına  çağırdı.  Onlara  nasihatte  bulundu.  Baş ucunda  ve  sağ tarafında en önde gelen talebelerinden Akşemseddîn, biraz gerilerde yine gözde  talebelerinden  Bıçakçı  Ymer  efendi  bulunuyordu.  Herkes  Kur’ân-ı kerîm  okuyup,  sevâblarını  hocalarına  bağışlıyorlardı.  Bir  ara  talebeler; “Acaba  hocamız  son  hastalıklarında  yerine  kimi  vekîl  olarak  bırakacak?” diye düşünürler iken, Hâcı Bayram-ı Velî hazretleri gözlerini açıp; “Emîr! Su getir”  buyurdu.  Talebelerden  biri  koşarak  bir  bardak  su  getirdi. Hâcı Bayram  suyu  alıp,  yanında  bulunan  çiçek  saksısının  içine  döktü.  Tekrar yatıp gözlerini yumdu. Bir müddet sessiz ve dalgın bir hâlde bekledi. Sonra tekrar gözlerini açıp; “Emîr! Su getir” buyurdu. Yine bir bardak su getirdiler. Onu da alıp, saksıya döktü. Tekrar dalgınlaştı. Bir ara yine gözlerini açıp su istedi. O zaman Akşemseddîn; “Ymer! Suyu sen getir” dedi. Bıçakçı Ymer efendi,  gidip  bir  bardak  su  getirdi.  Suyu  alan Hâcı Bayram-ı Velî, biraz içip; “Kalanı sen iç ki, emânet-i kübrâya nail olasın” buyurdu. Ymer efendi de bu suyu içti. Hâcı Bayram-ı Velî tekrar dalgınlaştı. Bir ara gözlerini açtı. Bütün talebelerine  teker  teker bakarak  sessizce  vedâlaştı  ve “Eşhedü enlâ ilahe illallah  ve  eşhedü  enne  Muhammeden abdühü  ve  Resûlühü”  dedi  ve mübârek gözlerini yumdu. Talebeler,  Akşemseddîn  ve  Ymer  efendi’nin  riyaseti  altında  cenâze hazırlığına başladılar. Bunu işiten bütün Ankaralılar, Hâcı Bayram-ı Velî’ye karşı son vazîfelerini yapmak için koştular. Cenâze namazını Akşemseddîn kıldırdı. Bugünkü türbesinin olduğu yere defnettiler. 842 (m. 1438). Hâcı Bayram-ı  Velî  hazretlerinin,  Allahü  teâlânın  pek çok  ihsânlarına kavuştuğunu,  zamanının  Kutb-i  aktâbı  olduğunu  pek çok  âlimlerimiz bildirmişlerdir. Onun   vefâtından   sonra   “Bayramiyye   yolu”nu,   talebelerinden Akşemşeddîn ve Bıçakçı Ymer efendi devam ettirdiler. Hâcı Bayram-ı  Velî’nin; Akşemseddîn, Akbıyık  Sultan, Yazıcızâde Muhammed, Yazıcızâde Ahmed  Bîcân ve Bıçakcı  Ymer Sikkînî’den  başka halîfeleri  de  vardı. Bunlar; Selâhaddîn-i  Bolevî, İnce  Bedreddîn, Kızılca Bedreddîn, Mihaliçli Hızır  Dede,  dâmâdı Eşrefoğlu  Rûmî (Abdullah efendi)’dir. Diğerleri: feyh  Germiyânî (feyhî), feyh Yusuf   Hakikî, feyh Lütfullah İsfendiyârî, ommî Kemal Halvetî, Molla Zeyrek, Ahmed Baba (Hacı Bayram-ı  Velî’nin  oğlu), Seyyid Abdülkadir  İsfehânî, feyh  Baba  Nahhâs Ankaravi, feyh  Elvan-ı  firâzî ve feyh Muslihiddîn’dir. feyh  Ramazan Edirnevî, İzzeddîn  Aksarayî, Abdurrahim Karahisârî ve Baba    Yusuf Sivrihisarî talebelerinin önde gelenlerindendir. Hâcı Bayram-ı  Velî,  ömrünün  sonuna  kadar  İslâmiyeti  yaymak  için uğraştı. Talebelerine ve sohbete gelen herkese, Allahü teâlânın emirlerini bildirip, yasaklarından kaçınmanın şart olduğunu anlattı. Onlara  yapıcı ve ikna   edici bir üslup  kullandı.  İçtimaȋ  dayanışmaya büyük  önem verdi Yoksullar ve ihtiyaç sahipleri için bir vakıf gibi çalışırdı. Güzel âdetlerinden biri  de, dergâhında sürekli bir kazan kaynatmasıdır. Hayatı, hep vera’ ve takvâ  üzere,  haramlardan  şiddetle  kaçıp,  şüpheli  korkusuyla  mubahların fazlasını dahî terketmekle geçti. Hâcı Bayram-ı Velî’nin doğduğu Zülfadl (Sol-Fasol) köyünden bir genç askere çağırıldı. Yetim olan bu temiz genç, babasından kalma birkaç altınını, annesinden  kalan  hâtıra  bilezik  ve  küpeleri  emânet  edecek  bir  kimse bulamadı.  Hepsini  küçük  bir  çekmeceye  koyup,  Hâcı  Bayram-ı  Velî’nin türbesine getirdi. Türbeyi ziyâret edip; “Yâ hazret-i Hâcı Bayram-ı Velî! Beni vatanî vazîfemi yapmak için çağırdılar. Annemden ve babamdan kalma şu hâtıraları emânet edecek bir kimse bulamadım. Bu küçük çekmeceyi zâtı âlinize emânet olarak bırakıyorum. Eğer askerden dönersem, gelir alırım. fayet  dönmezsem,  istediğiniz  bir  kimseye  verebilirsiniz!”  diye  münâcaat etti. Sonra çekmeceyi sandukanın kenarına koyarak ayrıldı. Aradan yıllar geçti. Gencin askerliği bitti ve emânetini almak üzere Hâcı Bayram-ı Velî’ye geldi. Ziyâretini yaptıktan sonra, çekmeceyi koyduğu yerde buldu. Hiç dokunulmamıştı. Orada türbeyi bekleyen türbedâra; “Bu çekmece benimdir. Askere gitmeden önce emânet bırakmıştım. fimdi alıyorum” dedi. Türbedâr;  “Tabî,  alabilirsen  al.  Çünkü  ben,  bir  defasında  bu  çekmecenin yerini  değiştirmek  istedim.  Fakat  bütün  uğraşmalarıma  rağmen  yerinden bile oynatamadım. Bunda bir hikmet olduğunu düşünerek, bir daha elimi bile sürmedim” dedi. Genç, çekmecenin yanına gelip, Hâcı Bayram-ı Velî’ye teşekkür etti ve emânetini alarak köyüne döndü. Hâcı Bayram-ı Velî’nin Edirne’ye ilk gittiğinde Eski Câmi’de vaaz verdiği kürsü teberrüken hâlâ korunmaktadır. Bu kürsünün üzerinde “Burası Hâcı Bayram Velî’nin makâmıdır” şeklinde bir yazı bulunmaktadır Bir  rivayete göre I. Sultan  Ahmet  Han  Edirne’ye  gelir,  câmiyi  gezer.  Kürsünün  neden kapalı  olduğunu  sorar,  durumu  anlatırlar.  Cuma  günü  kürsüde  vaaz edeceğini  söyler  kürsünün  açılmasını  emreder.  Kendisine  bu  geleneği bozmaması hatırlatılır. Ancak dinlemez kürsüye çıkar, Besmele çekip vaaza başlamak ister ancak bir türlü dilini kıpırdatamaz. Cemaat bekler bekler. Bir süre sonra Sultan Ahmed bu işe hem şaşırır hem de pişman olup kürsüden iner. O günden sonra kürsüye vaaz için kimse çıkmaz. Türbelerin kapatılma kararı çıktıktan sonra, her yere olduğu gibi Hâcı Bayram-ı Velî hazretlerinin türbesine de kilit vurulmuştu. Fakat sabahleyin türbenin  önünden geçenler  kilidi  kırılmış,  kapıyı  da  ardına  kadar  açık gördüler. Olayın birkaç defâ tekerrür etmesi üzerine ilgililerden biri; \"Böyle şey olmaz, bu kapıyı elbette bir açan var.\" demiş. Sonra bunun için iki polis vazifelendirmiş  ve;  \"Sabaha  kadar  bekleyin, gözetleyin.  fu  kapıyı  kim açıyorsa, hemen yakalayın.\" diye de emir vermişti. Polisler aldıkları  bu  emir  gereğince,  hazret-i  feyh\'in  türbesi  önünde sabah  ezânı  okununcaya  kadar  beklemişler.  Sabah  vakti  âniden  kilidin çıkardığı \"Çat\" sesi ile irkilmişler. İşte o zaman açılan kapıdan Hâcı Bayram-ı Velî  hazretlerinin  tebessüm  ederek  kendilerine  baktığını  görmüşler. Türbeyi bekleyen polislerden biri şaşkınlıktan düşüp bayılırken, diğerinin dili tutulmuş. Bu olaydan sonra bir daha hiç kimse kapıda nöbet tutmaya cesâret edememiştir. Hâcı Bayram\'ın görünüşünü  yani  hilyesini  yani  Abdüllatîf  Râzî  bir şiirinde şöyle tavsif eder: Gel imdi hılye-i pâkün dilâ nazm iyle terkîm it Beyân eyle serâpâ zikr olunsun cism-i nûrânî Görenler Hâcı Bayram-ı Velî hazretlerin cânâ Didiler ahsen-i vech üzre halk itmiş Hüdâ ânı Şüküfte goncadur gûyâ mübârek levn-i sîmâsı Nücûma ta\'n ider rûyındaki nûr-i fürûzânı Kadd-i merğûb-ı mevzûnı dırâz ne kasîr idi Olup ber-i\'tidâl ol cism-i sîm-i serv-i sâmânı Bî-ekl idi za\'îf ü ne mülahham ol ten-i sîmîn Katı nâdir geyinürdi ânun cisminde mûyânı Ulûm-i fenn-i sûrîde ferîd-i asr idi bizzât Bihâr-ı ma\'nevîde olmış idi fülk-i pûyânı Hâcı  Bayram,  Kara  Medrese’de  okumağa  başladığı  günlerde  Ak Medrese’ye  giderek  feyh  İzzeddîn’den  Arapça  dersleri  almıştır. Hallaç Mahmud (Er    Sultan) hazretleri    de, Hâcı Bayram Velî\'nin  mânevî hocalarındandır. Hâcı  Bayram-ı  Velî  bu  hocasının  türbesinin önünden geçerken ona hürmetinden ayakkabılarını çıkarırdı. Evliyâ Çelebi seyahatnamesine göre; Evliyâ Çelebi, 967 (m. 1560) yılında Ankara şehir merkezinde misafir kaldığı hanede hayırlı bir rüya görür.  Bu rüya, “Seyahatnâme”de şöyle anlatılır: “Ben  riyâsız  Evliyâ,  Engürü’ye  girdiğimiz  gün  doğruca Hâcı Bayram-ı Velî’nin nûrlu türbesine varup ziyareti ile şereflendikten sonra bir hatm-i şerîfe başladım. Misafir kaldığım haneye gelip ibâdet ve duâ edip istihâre yapıp uykuya daldım. Rüyamda gördüm ki, orta boylu, sarı sakallı, bal rengi sof hırka giymiş, başındaki külâh üzerine on iki dolama Muhammedî sarık sarmış bir zât gelip, bana şöyle hitap etti: - Bak  oğlum!  Lâyık  mıdır  ki,  benim  talebem  olan  Bayram-ı Velî’ye giderken beni basıp geçesin? Onu ziyaret edip bir hatm-i şerîfe başlıyorsun da bana bir Fâtiha niçin okumuyorsun? - Ben hayret içinde dedim ki: “Sultanım! Cenâb-ı şerîfiniz kimdir? Ben sizi bilmem, nerde oturuyorsunuz?” O da cevabında dedi ki: - Sen  uyanık  iken  Güreşçiler  Tekkesi’nde  ve  Sultan  Dördüncü  Murad huzurunda  pehlivanlara  duacılık  ederken,  “Engürü’de  Er  Sultan  yatar, Rum’da Sarı Saltuk” demez mi idin? İşte, Engürü’deki Er Sultan benim. Kale altı yakınında, Odunpazarı’nda bir kalın kubbe içinde kaldım. Gelip ziyaret edip, bir Fâtiha ile beni memnun edesin. Dünyada ve âhirette istediğini elde edesin. Sabah namazından sonra sana bir adam göndereyim. Bana  benzer. Onunla el ele verip bana gel, beni ziyaret eyle. Esselamü aleyküm\" deyip kayboldu. Hemen uykudan uyandım. Ve abdest alıp  sabah  namazı  vaktini  bekledim.  Namazdan  sonra  Paşa\'dan  Enderun mehteri gelip, \"Buyrun kahvaltıya\" dedi. \"Hayır oğlum, bugün oruçluyum.\" diyerek mehteri savdım. Sonra  baktım,  akşam  rüyamda  gördüğüm  kimse  çıkageldi.  Ynceden rüyamda gördüğüm gibi, Er Sultan şekliyle gelip selâm verdi. Ben de onun selâmını aldıktan sonra bana: \"Evliyâ Çelebi siz misiniz? buyurun, Er Dede Sultan rüyamda beni size gönderdi. Ziyaretine gidelim\" dedi. Amma sözü sanki  yeraltından  geliyordu.  Yüzü  nûrlu,  sözü  tesirli  bir  zât  idi.  Hemen ferâcemi  giyip,  Bismillah  ile  kapıdan  dışarı  çıktım.  Yaya  giderken  ileride şehir içinde on bir yerde, evliyânın büyüklerini isim ve künyeleri ile tanıtıp ziyaret  ettirdi.  Bazısına,  \"Bizim  çırağımızdır\"  der  idi.  Bazısına,  \"Azizim Hamid  Efendinin  halifesidir\"  derdi.  Böylece  türbe  türbe  gezdik.  Hemen elime yapıştı. Yokladım, elinde hiç kemik yoktu. Ne tarafa eğsem, hamur gibi eğiliyordu. Hemen elini elimden çekip sağ eliyle bir türbe gösterdi ve yine elimden tuttu. Sonra âhirete ait şeyler konuşarak, Odunpazarı denilen yere vardık. Meydanın batı tarafında küçük bir kubbe göründü. \"İşte Er Sultan kubbesi şudur\"  diye sağ eliyle  gösterdi.  Ben o  tarafa  bakıp,  sonra  tekrar yanıma  baktım.  O sırada  o kimse  kaybolmuştu.  Bre  meded!  O\'nun  elini elimden bırakmasam gerekti. O, Hızır aleyhisselâm idi. Doğru  Er  Sultan  kubbesine  vardım.  Kapısını  açıp  içeriye  girerek: \"Esselâmü aleyküm aziz pir!\" diye ağlayarak eşiğine bu asi yüzümü sürdüm. Sonra, Ey sultanım! Rüyama girip “Sana kâmil bir yol gösterici gönderirim\" dedin. Evet,  sözünde durup gönderdin. Henüz irşâd olmadan aldın. Çünkü onu  elimden  kaçırdım.  fimdi  sizi ziyarete, kapına  yüz  sürmeye  geldim. Habib-i  Huda  aşkına,  beni  dünya  ve  âhirette  boş  koma.  Allah  ile  ahdım olsun, mübârek ruhun için size de bir hatm-i şerîf okuyacağım\" dedim. O da hemen söze başlayarak; \"Hafız  olduğundan  ve  velileri  sevip  onların  mezarlarına  yüz sürdüğün için mahrum kalmazsın. Biz sana olan sevgimizden rüyana girip sana adam göndeririz. Onun eline yapışıp bize gel dediğim sabahı, yine biz varıp eline yapıştık.  Seni  Hak  yoluna  getiren  yol  göstericinim,  üzülme.  Akıbet,  yolun sırat-ı müstekimdir. Amma sen de fukara ve zayıflara merhamet üzere ol. Onları bunlardan kurtarmaya çalış. Engürü Paşa\'na da söyle, benim himayemde Engürücük\'te kapanın celâli olmasın.  Allah\'ın  kullarına  zulmetmesin.  Sana  Cenâb-ı  Hak  dünyada  tam seyahat, son nefesinde imân-ı kâmil verip, Hazret-i Peygamber\'in sallallahü aleyhi  ve  sellem  şefaâtini  nasip  ede.  Vücut  sağlığı ile  dünyayı  gezip dolaştıkça, az yemek ye, az konuş, az uyu, ilim ile çok amel eyle. Doğru yolu bulmak için lazım olan ameldir ki, Cenâb-ı Hak Kur\'ân-ı kerîm\'inde  “İleyhi yesadül kelimüttayyib...  [Fatır sûresi, 10] Meâlen, “Güzel kelimeler ancak O’na yükselir. Onu da iyi amel yükseltir” buyurmuştur. Bu  nasihatlerimi  tut. Ana-baba  hakkını  ve  bizi  hayır  duada  unutma. Pirlere riayet eyle. Yürü Allah işin râst getirüp âkıbetin hayr ola” dedi. Ben   de   bu   niyyete   el-Fâtiha  deyüp  Fâtiha-i  şerîfi  tilâvet  edüp  elini öperken nûr dolu türbenin kapısından bir kütürtü koptu... \"Yahu, bu   türbenin  türbedarı  yok mu?\"   derken halvetten  çıkup Er Sultan\'ın  sandukası  sofu  altından kalkıp oturdum.  Kendimden  geçmiş  ve sırıl sıklam tere batmışım. Meğer türbeye çok ziyaretçiler gelip; \"Siz türbedar mısınız\" dediler. \"Evet bu âsitanenin hademesi olduk\" dedim. Onlar da ziyaret ettiler. Hakir, veda Fâtiha\'sını okuyup yine mübârek kapıyı kapattım. Ağlayarak konağıma gidip dosdoğru bu rüyayı paşaya anlattım. Hemen paşa \"Tam bir sıdk-u hulûsa mâlik bir tevbe ile Allah\'a dönün\" [Tahrim, 8] deyip, \"Tez bölükbaşılara,  sekban  ve  sarıca  askerlerine  verilen  cebhane, tüfenkleri  ve  silâhlarını  getirsinler.  Bize  Ankara  Kalesi\'ne  kapanıp  celâlî olmak şimden gerü haramdır\" diye bütün silâhları askerî taifelerinden alıp rahatladı. Tövbeler edüp hamd-ü senâlar etmeye başladı. Meğer  paşa  da  benim  gördüğüm  Er Sultan rüyasını  gördüğünü  hakire anlattı. Tevafuk   rüyalarımız  gerçekleşip biribirine uygun  geldi.  Meğer paşanın aklında Ankara\'da kapanıp celâlî olmak düşüncesi var imiş. Bundan böyle Er Sultan\'ı ve Hâcı Bayram-ı Velî Sultan\'ı ziyaret etmeyi üzerime vazife bilüp sonra bu başladığım hatm-i şerîfleri tamamladım.” Hâcı Bayram-ı Velî’nin talebelerine nasihatlerinden ba’zıları şunlardır: “İnsanların fitnesinden kurtulmak istiyorsanız, çarşı ve pazarlarda sık sık “Hiddet ve kin, hakîkatleri gören gözleri kör eder. Yfke, iyi düşünmeyi daraltır, yanıltır.” “Allahü teâlâya isyan yolunda, hiçbir kimseye yardım etmeyiniz.” “Küçük  çocukları  seviniz,  başlarını  okşayınız.  Onları  sevindiriniz  ki, Peygamber efendimizin emrini yerine getirmiş olasınız.” “Çarşıda ve câmi avlusunda birşey yemeyiniz. Yol ortasında durmayınız. Ticâret erbâbının dükkânlarında uzun müddet oturmayınız.” “Hiçbir günâhı küçümsemeyin, çok çalışın. Boş gezenler, zengin dahî olsa, arkadaşları şeytan, kalbleri şeytanın konağı olur.” “Çok  gülmeyiniz  ki,  kalbiniz  kararmasın.  Sakin  ve  ağırbaşlı  olunuz  ki, vekarınız bozulmasın.” “Nefsinizi dâima kontrol altında tutunuz. Onu boş bırakmayasınız ki, sizi ateşe sürüklemesin.” “Helâlinden kazanıp, ondan fakirlere cömertçe veriniz.” “Ylümü çok hatırlayınız, ölüm gelmeden hesabınızı yapınız. Tövbe ediniz ki, affa kavuşasınız.” “Âlim ve evliyânın kabirlerini ziyâret ediniz. Zîrâ o büyükler, kendilerini ziyâret edenlere şefaat ederler.” “Dünyâ  gamından,  nefsin  sıkıştırmasından  hafifleyip  kurtulmak istiyorsanız, kabristanları sık sık ziyâret ediniz.” “Ayıp  ve  kusurlarını  gördüğünüz  arkadaşlarınızın,  komşularınızın, sırlarını  ifşa  etmeyiniz.  Çünkü  gördüğünüz  bu  sırlar,  size  emânettir. Emânete hiyânet ise, çirkin bir harekettir.” Hâcı Bayram-ı  Velî  hazretleri,  Yûnus  Emre  ile  aynı  asırda  yaşamışdır. Yûnus Emre’nin söylediği şiirlerin tarzında şiirler söylemiştir. Dilden dile söylenegelen şiirlerinin ba’zıları şöyledir: Bilmek istersen seni, Can içinde ara canı. Geç canından bul ânı, Sen seni bil, sen seni. Kim bildi ef’âlini, Ol bildi sıfatını, Anda gördü zâtını, Sen seni bil, sen seni. Görünen sıfatındır, O’nu gören zâtındır, Gayri ne hacetindir, Sen seni bil, sen seni. Kim ki hayrete vardı, Nûra müstagrak oldu, Tevhîd-i zâtı buldu, Sen seni bil, sen seni. Bayram özünü bildi, Bileni anda buldu, Bulan ol kendi oldu, Sen seni bil, sen seni. N’oldu bu gönlüm, n’oldu bu gönlüm? Derd-ü-gâmınla doldu bu gönlüm. Yandı bu gönlüm, yandı bu gönlüm, Yanmada dermân buldu bu gönlüm. Yan ey gönül yan, yan ey gönül yan! Yanmadan oldu derdine derman. Pervâne gibi, pervâne gibi, Aşk ateşiyle yandı bu gönlüm. Gerçi ki yandı, gerçeğe yandı, Rengine aşkın, cümle boyandı. Kendinde buldu, kendinde buldu, Matlûbunu hoş buldu bu gönlüm. El fakr-u fahrî, el fakr-u fahrî, Demedi mi ol âlemler fahrî? Fakrını zikrin, fakrını zikrin, Mahv-u fenâda buldu bu gönlüm. Sevâd-ı a’zam, sevâd-ı a’zam, Bana gelipdür Arş-ı muazzam. Meskeni cânân, meskeni cânân, Olsa acep mi şimdi bu gönlüm? Bayram’ım imdi, Bayram’ım imdi, Bayram ederler, yâr ile şimdi. Hamd-ü-senâlar, hamd-ü-senâlar, Yâr ile bayram kıldı bu gönlüm. ***************** Hiç kimse çekebilmez pekdir feleğin yayı Derdine gönül verme bir gün götürür vâyı Gelür güle oynaya aldır seni çapüktür Bir bunculayın fitne kande bulunur âyı Bir fânî vefâsızdır kavline inanma hiç Gâh yohsulu bay eyler gâh yoksul eder bayı Çün yüzünü döndürüdü bir lâhza karâr etmez Nice seri pây eder döner ser eder pâyı Denir vâhid vahdetde kesretde kanı tefrîk Hızr ermedi bu sırra bildirmedi Mûsâ’yı Hayran kamu âlimler bu mâninin altında Kaf’dan kafa hükmeden bilmez bu muammayı Miskin Hâcı Bayram sen dünyaya gönül verme Bir ulu imârettir alma başa sevdâyı Çalabım bir şâr yaratmış, İki cihân âresinde. Bakıcak Didâr görünür, Ol şârın kenâresinde. Nagihân bir şâra vardım, Ânı ben yapılır gördüm, Ben dahî bile yapıldım, Taş ve toprak ârasinde. Şâkirdleri taş yonarlar, Yonup üstâda sunarlar, Mevlânın adın anarlar, Taşın her pâresinde Ol şârdan oklar atılır, Gelür sineme batılır, Âşıklar cânı satılır, Ol şârın bâzâresinde. Şâr dedikleri gönüldür, Ne âlimdür ne câhildür, Âşıklar kânı sebildür, Ol şârın kenâresinde. Bu sözümü ârif anlar, Câhiller bilmeyüp tanlar, Hâcı Bayram kendi banlar, Ol şârın minâresinde. Benim maksûdum bu âlem, Değildir, lâkin illâ Hû. Bu benim derdime dermân, Değildir, lâkin illâ Hû. Değildir ol, hûr-i gılmân, Ne Cennet, köşk, ne de Rıdvân, Bu benim, gönlüme sultan, Değildir, lâkin illâ Hû. Ânın nakşı hayâlinden, Cihân bir zerre olmuştur. Nazar etsen o zerreden, Görünmez, lâkin illâ Hû. Bu Bayram’ı, eğer idrâk, Edersen, sen bu âlemde. Bu sının sırrına kimse, Eremez, lâkin illâ Hû. Eğer görmezse kişi bunda yârin, O gözsüz kande görür yârı yarın Bilişen dost ile bunda bilişür Göremez yâd olan yârın nigârın O gördü dahi buldu bunda yârı Fedâ kıla yoluna cümle vârın Merhabâ ey ayn-ı Zât’ın mazhar ü mihmânesi Zât-ı pâkinden görünür nûr-ı Hakk’ın şu’lesi Rehberi dergâh-ı izzet olduğuyçün ey Habîb Enbiyâ vü evliyânın oldı bâbın kıblesi Işkına gönül veren bulsa aceb değül murâd Çün cemâlin şem’-i Hakk’dır ehl-i Hakk pervânesi Dü cihân buldu nizâmı feyz-i pâkinden Şehâ Unsûr-ı hâssın olupdur gevheri yekdânesi Eyle boynuma hamâyıl ışkunun zencîrini Olmasun bendsiz Habîbâ ışkunun dîvânesi Vâridâtı veddinün kalbi imâret ideli Kenz-i ışk olmışdurur bu gönlümün virânesi İçmişim bezm-i ezelden yâr elinden cür’a kim Mest-i efkârım dil oldu ol meyin peymânesi Bûy-i vaslın mest iderse tan değildir âlemi Feyz-i Hakk’dan esrimişdir ter gibi mestânesi Nakd-i cânı vasl-ı cânâna fedâ etdim velî Ger ola yüz bin fedâ olmak anın şükrânesi Fenn-i ışk içre terakkî kıl taleb ağyâr-ı Hakk Âşıkın yârı olmaz vasl-ı Hakk bîgânesi Ey gönül (yarinden alı) bilmek isteyen haber Terk-i kevneyn idüp oldu râh-ı Hakk Merdânesi Bula Bayrâmî visâlin lezzetinde kurb-ı üns Ey olan bayrâm kalbinde dolu cânânesi');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (20861, 'HACI HIDIR EFGÂN', NULL, NULL, '1625', '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:32.747973', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Hindistan’da yetişen evliyânın büyüklerinden. İsmi Hıdır’dır. Hacı Hıdır Efgân  diye  bilinir.  Aslen  Afganistanlıdır.  Serhend’e  bağlı  Behlülpûr kasabasında doğdu. Doğum târihi bilinmemektedir. Behlülpûr’da 1035 (m. 1625) senesinde vefât edip, orada defnedildi. Küçük  yaşından  i’tibâren  ilim  ve  irfan  ehlinin  sohbetlerinde  bulunup, istifâde etti ve feyz aldı. Hindistan âlimlerinden feyh Meyânciyûn’un uzun müddet  derslerinde  ve  sohbetinde  bulunup  istifâde  etti.  İmâm-ı  Rabbânî hazretlerinin  yüksek  nazarlarına  muhâtab  olup  sohbetleriyle  şereflendi. Kısa zaman içinde feyz alıp yükseldi ve tasavvuf derecelerini geçti. İmâm-ı  Rabbânî  hazretleri  tarafından  icâzet  verilip,  Allahü  teâlâ’nın dînini  yaymak  ve  sevgili  Peygamberimizin  güzel  ahlâkını  anlatmakla vazîfelendirildi.  Hicaz’a  gidip  hac  ibâdetini yerine   getirdi   ve   sevgili Peygamberimizin   kabr-i  şerîfini  ziyâret  etti.  Bu  sırada  birçok  Arab memleketlerini de gezip gördü ve insanlara faydalı olmaya gayret etti. Onun ilim ve sohbet meclisinde birçok kişi hidâyete kavuşup feyz aldı ve yüksek derecelere ulaştılar, İmâm-ı Rabbânî hazretlerinin vefâtından sonra, onun ayrılığına dayanamayıp kısa zaman sonra vefât etti. Hacı  Hıdır  Efgân,  ilmiyle  âmil  olan  bir  âlim  ve  tasavvuf  derecelerinde yüksek bir veli idi. Serhend yakınlarındaki Behlülpûr kasabasında bulunur, sık  sık  İmâm-ı  Rabbânî  hazretlerinin  yüksek  dergâhlarına  gelir, sohbetleriyle  şereflenir  ve  tekrar  dönerdi.  Gecelerini,  Allahü  teâlânın rızâsına  kavuşmak  için  ibâdetle  geçirirdi.  Vakitlerini  Kur’ân-ı  kerîm okumak, zikir, tesbih ve namaz kılmakla zînetlendirirdi. Tatlı ve gür sesiyle okuduğu ezan, kalblere te’sîr ederdi. İmâm-ı Rabbânî hazretlerinin hizmetinde bulunduğu sırada ezanı dâima o okurdu. Ba’zan seher  vakitlerinde,  ba’zan  da  bütün  gece  boyu,  yanık  sesiyle  beytler  ve kasideler okur, ağlardı. Resûlullah (aleyhisselâm) efendinize çok salevât-ı İmâm-ı Rabbânî hazretlerinin talebelerinden birisi şöyle anlattı: İmâm-ı Rabbânî (kuddise sirruh) buyurdu ki; “Birgün şeytanı gördüm. Kendisine bir takım suâller sordum. Allahü teâlânın hükmü ile doğrusunu söyledi. Bu arada; “Talebelerim arasından, doğru yoldan saptırmak için en az musallat olduğun  ve  kandıramadığın  hangisidir?”  diye  sordum.  Cevâbında;  “Hacı Hıdır’dır” dedi.” Hacı Hıdır Efgân, Serhend’e yakın bir köyde bulunduğu sırada, İmâm-ı Rabbânî hazretlerinin vefât ettiği haberini duydu. Bu haber üzerine içli göz yaşları  dökerek  Serhend’e  gitti.  Bu  gelişinde  yanık  ve  tatlı  sesiyle  ezan okudu. Ezan sesini duyan İmâm-ı Rabbânî hazretlerinin talebe ve sevenleri toplanıp, o büyük velî’nin vefât ettiği gün gibi bir gün yaşadılar. Hadarât-ül-Kuds  adlı  eserin  müellifi  Bedreddîn  Serhendî,  bu  hâdiseyi Peygamber  efendimizin  (aleyhisselâm)  vefâtından  sonra,  ayrılık  ateşiyle yanan Bilâl-ı Habeşî’nin (radıyallahü anh) durumuna benzetir. Sevgili  Peygamberimizin vefâtından sonra, müezzini olan Bilâl-ı Habeşî (radıyallahü  anh),  Efendimizin  (aleyhisselâm)  ayrılığına  dayanamayıp fam’a  gitmişti.  Ymrünün  sonuna  yakın,  Peygamberimizin  (aleyhisselâm) rü’yâda  da’veti üzerine, kabrini  ziyârete  gelmişti.  Peygamber  efendimizin (aleyhisselâm)  torunları,  Hazret-i  Hasen  ve  Hazret-i  Hüseyn’in  ısrarları üzerine, yanık ve tatlı sesiyle ezan okumuştu. Ezân’ın sesini duyan Eshâb-ı Kirâm,  Mescid-i  Nebi’ye  gelerek,  Efendimizin  (aleyhisselâm)  zamanını hatırlayıp ağlaşmışlardı. İmâm-ı  Rabbânî  hazretlerinin, Hacı  Hıdır  Efgân’a  yazmış  olduğu “Kıymetli  mektûbunuz  geldi.  İçindekiler  anlaşıldı,  ibâdetlerden  zevk duymak  ve  bunların  yapılması  güç  gelmemek,  Allahü  teâlânın  en  büyük ni’metlerindendir.  Hele  namazın  tadını  duymak,  nihâyete  yetişmiyenlere nasîb olmaz. Hele farz namazların tadını almak, ancak onlara mahsûsdur. Çünkü  nihâyete  yaklaşanlara,  Nihâyette  ise  yalnız  farz  namazların  tadı duyulur. Nafile namazlar zevksiz olup, farzların kılınması büyük kâr, kazanç bilinir. Fârisî mısra’tercümesi; Bu iş, büyük ni’mettir. Acaba kime verirler. (Nafile  namaz;  farz  ve  vâcibden  ziyâde  başka  namazlar  demektir.  Beş vakit  namazın sünnetleri  ve  diğer  vacip olmayan  namazlar  hep  nafiledir. Müekked  olan  ve  olmayan  bütün  sünnetler  nafiledir.  (Dürr-ül-muhtâr), (İbn-i Âbidin) ve (Halebî) Namazların hepsinde hâsıl olan lezzetten, nefse bir pay yoktur, insan bu tadı duyarken, nefsi inlemekte, feryâd etmektedir. Yâ Rabbî! Bu ne büyük rütbedir. Arabî mısra’ tercümesi: “Ni’mete kavuşanlara afiyet olsun.” Bizim  gibi  rûhları  hasta  olanların  bu  sözleri  duyması  da,  büyük  bir ni’mettir ve hakîki saadettir. Fârisî mısra’ tercümesi: “Bari kalbimize bir teselli olsun” İyi biliniz ki, dünyâda namazın rütbesi, derecesi, âhıretde, Allahü teâlâyı görmenin yüksekliği  gibidir.  Dünyâda  insanın  Allahü  teâlâya  en  yakın bulunduğu  zaman,  namaz  kıldığı  zamandır.  Âhırette  en  yakın  olduğu  da, “rü’yet” ya’nî Allahü teâlâyı gördüğü zamandır. Dünyâdaki bütün ibâdetler, insanı  namaz  kılabilecek  bir  hâle  getirmek  içindir. Asıl  maksad  namaz kılmakdır. Saâdet-i ebediyye ve sonsuz ni’metlere kavuşmanızı dilerim.” (1. cild, 137. Mektûp)');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (20862, 'HACI İBRÂHİM EFENDİ', 'Osmanlıların son zamanlarında yetişen evliyâdan. İsmi, İbrâhim Bolevî Efendi olup, babası Ali Kavun-zâde diye tanınmış olan Hasen bin İbrâhim Efendi’dir.  Bolu’da  doğdu.  Doğum  târihi  bilinmemektedir.  Tasavvufta Kâdiriyye  yolunun  büyüklerindendir.  Kaygusuz  İbrâhim  Efendi  diye  de tanınır. 1289 (m. 1872) senesi Zilka’de ayının onikisinde Perşembe günü İstanbul’da vefât etti. İlk  zamanlarında  İstanbul’un  Ayasofya  semtinde  bir  tüccârın  yanında çırak olarak çalışırken, bir taraftan da ilim tahsiline gayret etti. Tasavvuf yolunun büyüklerinden Mustafa Efendi isminde bir zâtın talebesi olan Ymer el-Vasfî  ile  tanıştı.  Daha  sonra  Mustafa  Efendi’nin  huzûruna  gidip sohbetlerinde bulundu. Kemâle gelerek o zâttan hilâfet aldı. Hocasından hilâfet aldıktan sonra hacca giden İbrâhim Efendi, Mekke ve Medîne’yi  ziyâret  etti.  Yol  esnasında  evliyâdan  pekçok  zât  ile  karşılaşıp, sohbetlerinde  bulundu.  Hacdan sonra İstanbul’a gelerek, Sultan Ahmed’de Karslıoğlu  Mehmed  Ağa  Hanı’nda  bir  odada  yerleşti.  Orada  ikâmet  etti. Talebelerinin yükseği ve halîfesi Mustafa fevkî Efendi’nin delâlet ve yardımı ile, 1275 (m. 1858) senesinde, yine o civarda bulunan Toprak sokağında bir dergâh  bina  edildi.  İbrâhim  Efendi  oraya  geçerek,  talebe  yetiştirmeye devam etti. Ondört sene kadar orada vazîfe yaptıktan sonra 1289 (m. 1872) senesinde  vefât  edince,  vasıyyeti  îcâbı  osküdar’daki  Karacaahmed mezarlığında defnolundu. Âlim, âmil, sâlih bir zât idi. Fakirlerin ve ihtiyâç sahiplerinin sığınağı idi. İlme çok hizmet etti. Binlerce talebe yetiştirdi. Talebelerinden onbir tanesi kendisinden  hilâfet  aldı. En  yüksek  halîfesi,  yukarıda  ismi  geçen  Mustafa fevkî Efendi idi.', '1275 (m. 1858)', '1289 (m. 1872)', '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:32.748204', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Osmanlıların son zamanlarında yetişen evliyâdan. İsmi, İbrâhim Bolevî Efendi olup, babası Ali Kavun-zâde diye tanınmış olan Hasen bin İbrâhim Efendi’dir.  Bolu’da  doğdu.  Doğum  târihi  bilinmemektedir.  Tasavvufta Kâdiriyye  yolunun  büyüklerindendir.  Kaygusuz  İbrâhim  Efendi  diye  de tanınır. 1289 (m. 1872) senesi Zilka’de ayının onikisinde Perşembe günü İstanbul’da vefât etti. İlk  zamanlarında  İstanbul’un  Ayasofya  semtinde  bir  tüccârın  yanında çırak olarak çalışırken, bir taraftan da ilim tahsiline gayret etti. Tasavvuf yolunun büyüklerinden Mustafa Efendi isminde bir zâtın talebesi olan Ymer el-Vasfî  ile  tanıştı.  Daha  sonra  Mustafa  Efendi’nin  huzûruna  gidip sohbetlerinde bulundu. Kemâle gelerek o zâttan hilâfet aldı. Hocasından hilâfet aldıktan sonra hacca giden İbrâhim Efendi, Mekke ve Medîne’yi  ziyâret  etti.  Yol  esnasında  evliyâdan  pekçok  zât  ile  karşılaşıp, sohbetlerinde  bulundu.  Hacdan sonra İstanbul’a gelerek, Sultan Ahmed’de Karslıoğlu  Mehmed  Ağa  Hanı’nda  bir  odada  yerleşti.  Orada  ikâmet  etti. Talebelerinin yükseği ve halîfesi Mustafa fevkî Efendi’nin delâlet ve yardımı ile, 1275 (m. 1858) senesinde, yine o civarda bulunan Toprak sokağında bir dergâh  bina  edildi.  İbrâhim  Efendi  oraya  geçerek,  talebe  yetiştirmeye devam etti. Ondört sene kadar orada vazîfe yaptıktan sonra 1289 (m. 1872) senesinde  vefât  edince,  vasıyyeti  îcâbı  osküdar’daki  Karacaahmed mezarlığında defnolundu. Âlim, âmil, sâlih bir zât idi. Fakirlerin ve ihtiyâç sahiplerinin sığınağı idi. İlme çok hizmet etti. Binlerce talebe yetiştirdi. Talebelerinden onbir tanesi kendisinden  hilâfet  aldı. En  yüksek  halîfesi,  yukarıda  ismi  geçen  Mustafa fevkî Efendi idi.');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (20863, 'HACI KARA HALÎL EFENDİ', 'Son   devir   Osmanlı âlimlerinden.   Yüzondördüncü   Osmanlı şeyhülislâmıdır.  İsmi  Halîl’dir.  Çorum  ili,  Mecitözü  ilçesi,  Varay  bucağına bağlı Kürt köyünden Mustafa Efendi’nin oğludur. 1219 (m. 1804) senesinde Mecitözü’nde doğdu. 1298 (m. 1881) senesinde İstanbul’da vefât etti. Fâtih Câmii bahçesindeki eski şeyhülislâmlardan Mehmed Refîk Efendi ve Ymer Hilmi Efendi’nin mezarlarının yakınında defnedildi. İlim öğrenme çağına gelince, ilk önce Amasya’ya, daha sonra Konya’ya giderek ilim öğrendi. Hasen Fehmî Efendi ile birlikte aynı medresede talebe oldular. Konya’da ba’zı ilimleri öğrendikten sonra İstanbul’a geldi. Vidinli Mustafa Efendi’nin derslerine devam etti. ostün bir gayret sahibi olup, tatil zamanlarını  dahî  boş  geçirmezdi.  Abdürrahmân  Efendi’den  de  ders  aldı. 1250  (m.  1834)  senesinde aklî ve naklî ilimlerde yüksek dereceye ulaşıp, icâzet (diploma) aldı. 1251 (m. 1835) senesinde ruûs imtihanını kazanıp müderris oldu. Ders okutup talebe yetiştirdi. 1255 (m. 1839) senesinde ilk olarak  “Hâriç”  rütbesiyle  Sırrı-zâde  Mescidi’nde  ders  verdi.  Daha  sonra derece  derece  yükselerek  fetvâhâneye  devam  edip  müsevvid  (fetvâ müsveddelerini yazan) oldu. 1278 (m. 1861) senesinde İstanbul kadılığı kapı naipliğine getirildi. 1279 (m. 1862) senesinde fetvâ emînliği başmüsevvidliğine yükseldi. 1282 (m. 1865)  senesinde  Askeri  kassam  kadılığına  (vefât  eden  kimselerin  kalan mirasını  mirasçılara  taksim  eden  kadı)  ta’yin  edildi.  Aynı  sene  içinde Yenişehir  kadılığına  nakledildi.  1283  (m.  1866)  senesinde,  Filibeli  Halîl Efendi’nin  ders  vekîlliğine  getirilmesi  üzerine  boşalan  Fetvâ  emînliğine ta’yin edildi. Aynı zamanda Edirne mevleviyyeti pâyesiyle 1284 (m. 1867) senesinde  Haremeyn  pâyesiyle,  1285  (m.  1868)  senesinde  İstanbul pâyesiyle  taltif  edildi.  Aynı  sene  içinde  Evkâf-ı  Hümâyûn  (vakıflar) müfettişliğine ta’yin  edildi.  1286  (m.  1869)  senesinde  bu  vazîfeden ayrılarak  hacca  gitti.  Hac  ibâdetini  îfâ,  Peygamber  efendimizin (aleyhisselâm)  Kabr-i  şerîfini  ziyâret  edip  döndükten  sonra  “fer’iyye Tedkikler Meclisi” ve kısa bir müddet sonra “Mecelle Cemiyeti” üyeliğine getirildi. Bu arada Mecelle Cemiyeti başkanı Ahmed Cevdet Paşa ile uzun müddet beraber kalıp birlikte çalıştı. Ahmed Cevdet Paşa onun ilminden çok istifâde etti. 1288 (m. 1871) senesinde ikinci defa Fetvâ emînliğine ta’yin edildi. Arkasından da “fer’î Hâkimler Seçim Meclisi” üyeliğine getirildi. 1290 (m.  1873)  senesinde  Anadolu  kadıaskeri  payesi  verildi.  1294  (m.  1877) senesinde açılan Birinci Meclis-i Meb’usân’a üye olarak girdi. Aynı yıl içinde Hasen Hayrullah Efendi’nin vazîfeden ayrılması üzerine boşalan şeyhülislâmlık makamına, Sultan İkinci Abdülhamîd Hân tarafından ta’yin edildi, 1 yıl 9 ay kadar bu makamda kaldıktan sonra, 1295 (m. 1878) senesinde  bu  vazîfeden  ayrıldı.  Bu  sırada  A’yân  üyeliği  devam  ediyordu. Kendi evine çekilip ibâdet ve tâat ile meşgûl iken vefât etti. El-Hâc Kara Halîl Efendi, aklî ve naklî ilimlerde derin âlim, fıkıh ilminde özel ihtisas sahibi idi. İlmiyle amel eden fazilet sahibi müttekî (haramlardan sakınan) ve Allahü teâlâya çok ibâdet eden bir zât idi. Ba’zı mu’teber fıkıh kitaplarına Arabça takrizleri vardır.', '1298 (m. 1881)', '1250  (m.  1834)', '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:32.748258', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Son   devir   Osmanlı âlimlerinden.   Yüzondördüncü   Osmanlı şeyhülislâmıdır.  İsmi  Halîl’dir.  Çorum  ili,  Mecitözü  ilçesi,  Varay  bucağına bağlı Kürt köyünden Mustafa Efendi’nin oğludur. 1219 (m. 1804) senesinde Mecitözü’nde doğdu. 1298 (m. 1881) senesinde İstanbul’da vefât etti. Fâtih Câmii bahçesindeki eski şeyhülislâmlardan Mehmed Refîk Efendi ve Ymer Hilmi Efendi’nin mezarlarının yakınında defnedildi. İlim öğrenme çağına gelince, ilk önce Amasya’ya, daha sonra Konya’ya giderek ilim öğrendi. Hasen Fehmî Efendi ile birlikte aynı medresede talebe oldular. Konya’da ba’zı ilimleri öğrendikten sonra İstanbul’a geldi. Vidinli Mustafa Efendi’nin derslerine devam etti. ostün bir gayret sahibi olup, tatil zamanlarını  dahî  boş  geçirmezdi.  Abdürrahmân  Efendi’den  de  ders  aldı. 1250  (m.  1834)  senesinde aklî ve naklî ilimlerde yüksek dereceye ulaşıp, icâzet (diploma) aldı. 1251 (m. 1835) senesinde ruûs imtihanını kazanıp müderris oldu. Ders okutup talebe yetiştirdi. 1255 (m. 1839) senesinde ilk olarak  “Hâriç”  rütbesiyle  Sırrı-zâde  Mescidi’nde  ders  verdi.  Daha  sonra derece  derece  yükselerek  fetvâhâneye  devam  edip  müsevvid  (fetvâ müsveddelerini yazan) oldu. 1278 (m. 1861) senesinde İstanbul kadılığı kapı naipliğine getirildi. 1279 (m. 1862) senesinde fetvâ emînliği başmüsevvidliğine yükseldi. 1282 (m. 1865)  senesinde  Askeri  kassam  kadılığına  (vefât  eden  kimselerin  kalan mirasını  mirasçılara  taksim  eden  kadı)  ta’yin  edildi.  Aynı  sene  içinde Yenişehir  kadılığına  nakledildi.  1283  (m.  1866)  senesinde,  Filibeli  Halîl Efendi’nin  ders  vekîlliğine  getirilmesi  üzerine  boşalan  Fetvâ  emînliğine ta’yin edildi. Aynı zamanda Edirne mevleviyyeti pâyesiyle 1284 (m. 1867) senesinde  Haremeyn  pâyesiyle,  1285  (m.  1868)  senesinde  İstanbul pâyesiyle  taltif  edildi.  Aynı  sene  içinde  Evkâf-ı  Hümâyûn  (vakıflar) müfettişliğine ta’yin  edildi.  1286  (m.  1869)  senesinde  bu  vazîfeden ayrılarak  hacca  gitti.  Hac  ibâdetini  îfâ,  Peygamber  efendimizin (aleyhisselâm)  Kabr-i  şerîfini  ziyâret  edip  döndükten  sonra  “fer’iyye Tedkikler Meclisi” ve kısa bir müddet sonra “Mecelle Cemiyeti” üyeliğine getirildi. Bu arada Mecelle Cemiyeti başkanı Ahmed Cevdet Paşa ile uzun müddet beraber kalıp birlikte çalıştı. Ahmed Cevdet Paşa onun ilminden çok istifâde etti. 1288 (m. 1871) senesinde ikinci defa Fetvâ emînliğine ta’yin edildi. Arkasından da “fer’î Hâkimler Seçim Meclisi” üyeliğine getirildi. 1290 (m.  1873)  senesinde  Anadolu  kadıaskeri  payesi  verildi.  1294  (m.  1877) senesinde açılan Birinci Meclis-i Meb’usân’a üye olarak girdi. Aynı yıl içinde Hasen Hayrullah Efendi’nin vazîfeden ayrılması üzerine boşalan şeyhülislâmlık makamına, Sultan İkinci Abdülhamîd Hân tarafından ta’yin edildi, 1 yıl 9 ay kadar bu makamda kaldıktan sonra, 1295 (m. 1878) senesinde  bu  vazîfeden  ayrıldı.  Bu  sırada  A’yân  üyeliği  devam  ediyordu. Kendi evine çekilip ibâdet ve tâat ile meşgûl iken vefât etti. El-Hâc Kara Halîl Efendi, aklî ve naklî ilimlerde derin âlim, fıkıh ilminde özel ihtisas sahibi idi. İlmiyle amel eden fazilet sahibi müttekî (haramlardan sakınan) ve Allahü teâlâya çok ibâdet eden bir zât idi. Ba’zı mu’teber fıkıh kitaplarına Arabça takrizleri vardır.');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (20864, 'HACI MEHMED REFÎK EFENDİ', 'Son devir Osmanlı âlimlerinden. Yüzdokuzuncu Osmanlı şeyhülislâmıdır. İsmi  Refîk  olup,  El-Hâc  Mehmed  Refîk  Efendi  diye  bilinir.  Bosnalı  Hacı Abdullah  Efendi’nin  torunu  ve  Ali  Efendi’nin  oğludur.  Bugün  Yugoslavya sınırları içinde bulunan Bosna’ya bağlı Çelebîpazarı kasabasında, 1229 (m. 1813) senesinde doğdu. 1288 (m. 1872) senesinde İstanbul’da vefât etti. Fâtih Sultan Mehmed Hân türbesi civârında defnedildi. İlk  öğrenimini  yaparken  babası  vefât  ettiğinden  yetim  kaldı.  Bosna Sarayı’na gelip hem tahsiline devam etti. Hem de şer’iyye mahkemesinde me’mûr  olarak  çalıştı.  Bosna  kadısı  Ispartalı  Hüseyn  Efendi,  Mehmed Refîk’in  zekâ  ve  kabiliyetini  takdîr  edip,  1249  (m.  1833)  senesinde İstanbul’a  getirdi.  Bu  sırada  Ispartalı  Hüseyn  Efendi’nin  kızıyla  evlendi. Zamanının  âlimlerinin  ders  meclislerinde  bulunup,  aklî  ve  naklî  ilimleri tahsil etti. Müzellef Ahmed Efendi’den âlet ilimlerini ve dînî ilimleri tahsil etti.  Ferâiz  ilmini  Mehmed  Sâkıb  Efendi’den  öğrendi.  1253  (m.  1837) senesinde kayınpederinin fam kadılığına ta’yini esnasında onunla birlikte fam’a  gitti.  Orada  feyh-i  ekber  Muhyiddîn-i  Arabî,  hazretlerinin  kabrini ziyâret  edip  eserlerini  mütâlâa  etti.  Muhyiddîn-i  Arabî’yi  birkaç  defa rü’yâsında  gördü.  Yine  fam’da  medfûn  bulunan  Nakşibendiyye  yolu büyüklerinden  Mevlânâ  Hâlid-i  Bağdadî  hazretlerinin  seçkin  talebesi, Abdülfettâh-ı Bağdadî Akrî’nin sohbetlerinde bulunup, ona  talebe  oldu  ve ma’nevî  feyz  aldı.  1254  (m.  1838)  senesinde  kayınpederi  fam’da  vefât edince, İstanbul’a dönüp fıkıh ilmi tahsiline ve diğer ilmî eserleri incelemeye devam etti. Kendini daha iyi yetiştirmek için Evkaf (vakıflar) idâresi teftiş kaleminde  vazîfe  aldı.  1256  (m.  1840)  senesinde “Fetevâhâne-i  âliyye”de vazîfelendirildi. 1257 (m. 1841) senesinde Eyyûb fer’iyye mahkemesi kadı vekîlliğine  ta’yin  edildi. 1260  (m.  1844) senesinde Varna  kadı  vekîlliğine gönderildi. 1261 (m. 1845) senesinde müddetini tamamlayarak İstanbul’a dönüp,  “Fetevâhâne-i  âliyye”  yazı  işlerinde  vazîfelendirildi.  Fetvâ  emîni Meşreb-zâde  Mehmed  Ârif  Efendi’nin  vazîfeden  ayrılması  üzerine şeyhülislâm  olan  Mekkî-zâde  Mehmed  Âsım  Efendi  tarafından  imtihan edilerek, âlim, fâzıl ve fıkıh ilmindeki üstünlüğünden dolayı, 1262 (m. 1846) senesinde Fetvâ emîni olarak ta’yin edildi. Aynı sene vefât eden Mekkî-zâde Mustafa  Âsım  Efendi’nin  yerine  şeyhülislâm  olan  Ârif  Hikmet  Efendi  de onun ilmine ve ahlâkına hayran olup, vazîfesine devam etmesini istedi. 1264  (m.  1847)  senesinde,  İzmir  pâyesiyle,  Bosna,  1265  (m.  1848) senesinde Edirne, 1266 (m. 1849) senesinde Haremeyn (Mekke ve Medîne) kadılıklarında  bulundu.  1270  (m.  1853)  senesinde  İstanbul  kadılığına getirildi.  1272  (m.  1855)  senesinde  Evkaf  müfettişliğinde bulundu ise de, 1274 (m. 1857) senesinde tekrar Fetvâ emînliği vazîfesine getirildi. Aynı sene  içinde  Anadolu  kadıaskerliğine  yükseldi.  1276  (m.  1859)  senesinde sevgili  Peygamberimizin  (aleyhisselâm)  Ravda-i  mütahherâsının  ta’miri yapılıyordu. feyhülislâmlık makamında toplanan âlimler meclisinde Ravda-i mütahheranın  kapısı  üzerine;  “Benim  mescidimde  kılınan  bir  namaz, Mescid-i  Haram  hâriç  diğer  mescidlerde  kılınan  bin  namazdan  daha efdaldir” hadîs-i şerîfinin yazılmasını teklif etti. Bu teklif âlimler meclisinde kabûl  edildi.  Bu  vesileyle,  Sultan  Abdülmecîd  Hân’ın  takdîr  ve  tasvibini kazandı.  1282  (m.  1865)  senesinde  fer’iyye  Hâkimleri  Seçim  Meclisi başkanlığı (Meclis-i İntihâb-ı Hükkâm Riyaseti) vazîfesiyle birlikte, “Meclis-i Vâlây-ı  Ahkâm-ı Adliyye”  üyeliğine  getirildi.  Aynı  sene  içinde  Hicaz’a giderek  hac  ibâdetini  îfâ  edip,  Peygamber  efendimizin  (aleyhisselâm) mübârek kabrini ziyâret etmekle şereflendi. Bu sebeple “El-Hâc” ünvanıyla anıldı. 1283 (m. 1866) senesinde feyhülislâm Âtıf-zâde Ymer Hüsâmeddîn Efendi’nin  vazîfeden  ayrılmasıyla  boşalan  şeyhülislâmlık  makamına getirildi. 1 yıl 9 ay 9 gün bu şerefli ve yüce vazîfeyi yürüttükten sonra, 1285 (m. 1868) senesinde vazîfeden alındı. Aynı sene içinde “Meclis-i Mahsûsı vekîle” (özel vekîller meclisi) üyeliğine getirildi. Bu vazîfesi esnasında ateşli humma  hastalığına  yakalandı.  Bu  hastalıktan  kurtulamayarak  vefât  etti. Kabri,  sur  dışında  Mustafa  Paşa  dergâhındaki  feyhülislâm  Meşreb-zâde Mehmed  Ârif  Efendi’nin  kabri  yanında  hazırlandı:  Ancak  Pâdişâh  Sultan Abdülazîz  Hân’ın  emri  ile  Fâtih  Sultan  Mehmed  Hân  türbesi  civarında defnedildi.  Cenâze  namazında  zamanın  vezirleri,  devlet  ileri  gelenleri, âlimler ve kalabalık bir cemâat hazır bulundu. Ahmed Cevdet Paşa; “Fıkıh hazînesini buraya defnediyoruz” dedi. Mezar taşında, Sami Paşa’nın söylediği; “Ebûyu abayı emcâd târihe etti imdâd, Gitti Refîk Efendi dergâh-ı lâ yezâle” beyti yazılıdır. Mehmed Refîk Efendi, âlim ve fazilet sahibi bir zât idi. Dürüst, özü sözüne uygun,  ilmiyle  âmil  ve  vakarlı  idi. İlim  ehline  uymayan  davranışlardan kaçınır.  Yaptığı  işlerde  Allahü  teâlânın  rızâsına  kavuşmayı  dilerdi.  Fıkıh ilminde özel ihtisası olup, bütün fıkhı mes’elelere vâkıf idi. “Ya hayır konuş veya sus” hadîs-i şerîfini ön plânda tutup pek az konuşurdu. Güler yüzlü ve tatlı  sözlü  olup,  herkes  tarafından  sevilir  ve  sayılırdı.  Mühür  üzerinde; “Ni’me’r-refîk Muhammed” (Muhammed ne güzel dosttur, arkadaştır) yazılı idi. Ellidokuz yaşında vefât eden Mehmed Refîk Efendi “Murassa-i Osmânî” ve “Birinci Mecîdî” nişanlarına sâhib idi. Doğum yeri olan Çelebîpazarı’nda bir câmi ve bir sıbyân mektebi (ilk okul) yaptırmıştı. “Fetâvâ-i Feyziyye’den nakletmiş olduğu fetvâlarını içine alan bir eseri vardır. Bir cild olarak 1266 (m. 1849) senesinde basılmıştır.', '1288 (m. 1872)', '1249  (m.  1833)', '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:32.748323', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Son devir Osmanlı âlimlerinden. Yüzdokuzuncu Osmanlı şeyhülislâmıdır. İsmi  Refîk  olup,  El-Hâc  Mehmed  Refîk  Efendi  diye  bilinir.  Bosnalı  Hacı Abdullah  Efendi’nin  torunu  ve  Ali  Efendi’nin  oğludur.  Bugün  Yugoslavya sınırları içinde bulunan Bosna’ya bağlı Çelebîpazarı kasabasında, 1229 (m. 1813) senesinde doğdu. 1288 (m. 1872) senesinde İstanbul’da vefât etti. Fâtih Sultan Mehmed Hân türbesi civârında defnedildi. İlk  öğrenimini  yaparken  babası  vefât  ettiğinden  yetim  kaldı.  Bosna Sarayı’na gelip hem tahsiline devam etti. Hem de şer’iyye mahkemesinde me’mûr  olarak  çalıştı.  Bosna  kadısı  Ispartalı  Hüseyn  Efendi,  Mehmed Refîk’in  zekâ  ve  kabiliyetini  takdîr  edip,  1249  (m.  1833)  senesinde İstanbul’a  getirdi.  Bu  sırada  Ispartalı  Hüseyn  Efendi’nin  kızıyla  evlendi. Zamanının  âlimlerinin  ders  meclislerinde  bulunup,  aklî  ve  naklî  ilimleri tahsil etti. Müzellef Ahmed Efendi’den âlet ilimlerini ve dînî ilimleri tahsil etti.  Ferâiz  ilmini  Mehmed  Sâkıb  Efendi’den  öğrendi.  1253  (m.  1837) senesinde kayınpederinin fam kadılığına ta’yini esnasında onunla birlikte fam’a  gitti.  Orada  feyh-i  ekber  Muhyiddîn-i  Arabî,  hazretlerinin  kabrini ziyâret  edip  eserlerini  mütâlâa  etti.  Muhyiddîn-i  Arabî’yi  birkaç  defa rü’yâsında  gördü.  Yine  fam’da  medfûn  bulunan  Nakşibendiyye  yolu büyüklerinden  Mevlânâ  Hâlid-i  Bağdadî  hazretlerinin  seçkin  talebesi, Abdülfettâh-ı Bağdadî Akrî’nin sohbetlerinde bulunup, ona  talebe  oldu  ve ma’nevî  feyz  aldı.  1254  (m.  1838)  senesinde  kayınpederi  fam’da  vefât edince, İstanbul’a dönüp fıkıh ilmi tahsiline ve diğer ilmî eserleri incelemeye devam etti. Kendini daha iyi yetiştirmek için Evkaf (vakıflar) idâresi teftiş kaleminde  vazîfe  aldı.  1256  (m.  1840)  senesinde “Fetevâhâne-i  âliyye”de vazîfelendirildi. 1257 (m. 1841) senesinde Eyyûb fer’iyye mahkemesi kadı vekîlliğine  ta’yin  edildi. 1260  (m.  1844) senesinde Varna  kadı  vekîlliğine gönderildi. 1261 (m. 1845) senesinde müddetini tamamlayarak İstanbul’a dönüp,  “Fetevâhâne-i  âliyye”  yazı  işlerinde  vazîfelendirildi.  Fetvâ  emîni Meşreb-zâde  Mehmed  Ârif  Efendi’nin  vazîfeden  ayrılması  üzerine şeyhülislâm  olan  Mekkî-zâde  Mehmed  Âsım  Efendi  tarafından  imtihan edilerek, âlim, fâzıl ve fıkıh ilmindeki üstünlüğünden dolayı, 1262 (m. 1846) senesinde Fetvâ emîni olarak ta’yin edildi. Aynı sene vefât eden Mekkî-zâde Mustafa  Âsım  Efendi’nin  yerine  şeyhülislâm  olan  Ârif  Hikmet  Efendi  de onun ilmine ve ahlâkına hayran olup, vazîfesine devam etmesini istedi. 1264  (m.  1847)  senesinde,  İzmir  pâyesiyle,  Bosna,  1265  (m.  1848) senesinde Edirne, 1266 (m. 1849) senesinde Haremeyn (Mekke ve Medîne) kadılıklarında  bulundu.  1270  (m.  1853)  senesinde  İstanbul  kadılığına getirildi.  1272  (m.  1855)  senesinde  Evkaf  müfettişliğinde bulundu ise de, 1274 (m. 1857) senesinde tekrar Fetvâ emînliği vazîfesine getirildi. Aynı sene  içinde  Anadolu  kadıaskerliğine  yükseldi.  1276  (m.  1859)  senesinde sevgili  Peygamberimizin  (aleyhisselâm)  Ravda-i  mütahherâsının  ta’miri yapılıyordu. feyhülislâmlık makamında toplanan âlimler meclisinde Ravda-i mütahheranın  kapısı  üzerine;  “Benim  mescidimde  kılınan  bir  namaz, Mescid-i  Haram  hâriç  diğer  mescidlerde  kılınan  bin  namazdan  daha efdaldir” hadîs-i şerîfinin yazılmasını teklif etti. Bu teklif âlimler meclisinde kabûl  edildi.  Bu  vesileyle,  Sultan  Abdülmecîd  Hân’ın  takdîr  ve  tasvibini kazandı.  1282  (m.  1865)  senesinde  fer’iyye  Hâkimleri  Seçim  Meclisi başkanlığı (Meclis-i İntihâb-ı Hükkâm Riyaseti) vazîfesiyle birlikte, “Meclis-i Vâlây-ı  Ahkâm-ı Adliyye”  üyeliğine  getirildi.  Aynı  sene  içinde  Hicaz’a giderek  hac  ibâdetini  îfâ  edip,  Peygamber  efendimizin  (aley