INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21277, 'MÛSA FÂKİH', 'Kastamonu veli ve alimlerinden. Aslen Araç’ın tavşanlı köyündendir. 15 ve  16. yüzyıllarda yaşamıştır. Kastamonu’da bir mahalleye adını vermiştir. Bu  mahallede  ders  vermiş,  talebe  okutmuştur.  İsmini  taşıyan  caminin yanında  medfundur.  Halk  arasında  sabah  namazlarını  Ka’be’de  kıldığı rivayet edilmektedir.', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:32.993718', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Kastamonu veli ve alimlerinden. Aslen Araç’ın tavşanlı köyündendir. 15 ve  16. yüzyıllarda yaşamıştır. Kastamonu’da bir mahalleye adını vermiştir. Bu  mahallede  ders  vermiş,  talebe  okutmuştur.  İsmini  taşıyan  caminin yanında  medfundur.  Halk  arasında  sabah  namazlarını  Ka’be’de  kıldığı rivayet edilmektedir.');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21278, 'MUSLİHUDDÎN MUSTAFA NİKSÂRÎ', 'Kanunî  Sultan  Süleymân  zamanı  âlimlerinden.  Aslen  Tokat’ın  Niksar kasabasındandır.  Bu  bakımdan  Niksâri  nisbetiyle  meşhûr  oldu.  Niksar’da doğdu. Doğum târihi kaynaklarda bildirilmemektedir. 969 (m. 1562) senesi Rebî’ul-âhır  ayının  dokuzuncu  günü,  sabah  namazı  için  abdest  alırken İstanbul’da vefât etti. Edirne-kapı dışında, Emîr Buhârî Tekkesi yakınında medfûndur. Vefâtında yaşı 90 civarında idi. Ynce kendi memleketinde ilim öğrenmeye başladı. Oranın âlimlerinden ilim öğrendikten sonra, Muhyiddîn Fenârî’nin derslerine devam etti. Sonra Hocâ-zâde Mehmed Paşa’nın hizmetinde bulundu. 920 (m. 1514) târihinde Edirne’deki  oçşerefeli  Medrese’ye  müderris  olan  Tâci-zâde  Ca’fer  Çelebî yerine nişancı ve mülâzim oldu. Sonra Gelibolu’da Saruca Paşa Medresesi’ne müderris oldu. Buradan Vardar Yenicesi’ndeki Evrenos Bey Medresesi’ne, oradan  da  Edirne’de  Taşlık  Medresesi’ne  müderris  oldu.  Bu  vazîfesinden alınınca  hacca  gitti.  Hac  ibâdetini  yerine  getirdikten  sonra,  Pîri  Paşa Medresesi’ne müderris oldu. 945  (m.  1538)  senesinde, Kara Çelebî yerine Çorlu Medresesi müderrisi oldu. Aynı sene müderrislikten kadılığa geçen Niksâri, Manav Abdi yerine Manisa müftîsi oldu. 947 (m. 1540) senesinde, Bağdad kadılığı Muslihuddîn Mustafa  Niksârî’ye  verildi.  Burada  hem  kadılık,  hem  de  Mercâniyye Medresesi’nde  müderrislik  yaptı.  Daha  sonra  Bağdad  müftîliği  de  ona verildi.  953  (m.  1546)  senesinde,  Bağdad’daki  vazîfesinden,  Bursa’daki Murâdiyye  Medresesi’ne  ta’yin  edildi.  954  (m.  1547)  senesinde  Haleb kadılığına getirildi, iki ay sonra tekrar Bursa’ya ta’yin edildi, iki sene sonra vazîfesinden alındı ve emekli oldu. Yerine Kara Çelebî Efendi getirildi. 958 (m.  1551)  senesinde  Emîr  Hasen  Çelebî  yerine  Ayasofya  Medresesi müderrisi oldu. Aynı sene Edirne kadısı olan Muslihuddîn Niksâri, 961 (m. 1554)  senesinde Taşköprülüzâde yerine  İstanbul  kadılığına  ta’yin  edildi. 963  (m.  1555)  senesinde  vazîfesinden  alınarak,  yerine  Hâmid  Efendi getirildi. 967 (m. 1559) senesinde Süleymâniye Dâr-ül-hadîs Medresesi’ne müderris oldu. Bu vazîfe, son vazîfesi idi. Muslihuddîn  Mustafa  Niksârî Efendi,  Anadolu’da  yetişmiş  âlimlerin büyüklerindendi. Sâlih bir kimse olup, vera’ ve takvâ sahibi idi. İslâmiyete çok bağlı idi. Gösterişten, öğünmekten, büyüklenmekten son derece uzak idi. Oğulları da âlim idiler. Oğlu Mehmed Efendi, 40 yaşında iken, 981 (m. 1573)  senesinde  vefât  etti.  Diğer  oğlu  Ali  Çelebî,  hac  ettikten  sonra Hindistan’a gitti. Selîm fah’dan yakınlık gördü. Cunbür diyarı ona verilip, âlimlerin  reîsi  ve  müftî  oldu.  1045  (m.  1635)’de  vefât  etti.  Diğer  oğlu Mehmed Efendi, müderris, sonra Selanik ve Yenişehir kadısı oldu. 1025 (m. 1616) senesinde vefât etti. Babasının yanına defnedildi.', '920 (m. 1514)', '945  (m.  1538)', '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:32.993766', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Kanunî  Sultan  Süleymân  zamanı  âlimlerinden.  Aslen  Tokat’ın  Niksar kasabasındandır.  Bu  bakımdan  Niksâri  nisbetiyle  meşhûr  oldu.  Niksar’da doğdu. Doğum târihi kaynaklarda bildirilmemektedir. 969 (m. 1562) senesi Rebî’ul-âhır  ayının  dokuzuncu  günü,  sabah  namazı  için  abdest  alırken İstanbul’da vefât etti. Edirne-kapı dışında, Emîr Buhârî Tekkesi yakınında medfûndur. Vefâtında yaşı 90 civarında idi. Ynce kendi memleketinde ilim öğrenmeye başladı. Oranın âlimlerinden ilim öğrendikten sonra, Muhyiddîn Fenârî’nin derslerine devam etti. Sonra Hocâ-zâde Mehmed Paşa’nın hizmetinde bulundu. 920 (m. 1514) târihinde Edirne’deki  oçşerefeli  Medrese’ye  müderris  olan  Tâci-zâde  Ca’fer  Çelebî yerine nişancı ve mülâzim oldu. Sonra Gelibolu’da Saruca Paşa Medresesi’ne müderris oldu. Buradan Vardar Yenicesi’ndeki Evrenos Bey Medresesi’ne, oradan  da  Edirne’de  Taşlık  Medresesi’ne  müderris  oldu.  Bu  vazîfesinden alınınca  hacca  gitti.  Hac  ibâdetini  yerine  getirdikten  sonra,  Pîri  Paşa Medresesi’ne müderris oldu. 945  (m.  1538)  senesinde, Kara Çelebî yerine Çorlu Medresesi müderrisi oldu. Aynı sene müderrislikten kadılığa geçen Niksâri, Manav Abdi yerine Manisa müftîsi oldu. 947 (m. 1540) senesinde, Bağdad kadılığı Muslihuddîn Mustafa  Niksârî’ye  verildi.  Burada  hem  kadılık,  hem  de  Mercâniyye Medresesi’nde  müderrislik  yaptı.  Daha  sonra  Bağdad  müftîliği  de  ona verildi.  953  (m.  1546)  senesinde,  Bağdad’daki  vazîfesinden,  Bursa’daki Murâdiyye  Medresesi’ne  ta’yin  edildi.  954  (m.  1547)  senesinde  Haleb kadılığına getirildi, iki ay sonra tekrar Bursa’ya ta’yin edildi, iki sene sonra vazîfesinden alındı ve emekli oldu. Yerine Kara Çelebî Efendi getirildi. 958 (m.  1551)  senesinde  Emîr  Hasen  Çelebî  yerine  Ayasofya  Medresesi müderrisi oldu. Aynı sene Edirne kadısı olan Muslihuddîn Niksâri, 961 (m. 1554)  senesinde Taşköprülüzâde yerine  İstanbul  kadılığına  ta’yin  edildi. 963  (m.  1555)  senesinde  vazîfesinden  alınarak,  yerine  Hâmid  Efendi getirildi. 967 (m. 1559) senesinde Süleymâniye Dâr-ül-hadîs Medresesi’ne müderris oldu. Bu vazîfe, son vazîfesi idi. Muslihuddîn  Mustafa  Niksârî Efendi,  Anadolu’da  yetişmiş  âlimlerin büyüklerindendi. Sâlih bir kimse olup, vera’ ve takvâ sahibi idi. İslâmiyete çok bağlı idi. Gösterişten, öğünmekten, büyüklenmekten son derece uzak idi. Oğulları da âlim idiler. Oğlu Mehmed Efendi, 40 yaşında iken, 981 (m. 1573)  senesinde  vefât  etti.  Diğer  oğlu  Ali  Çelebî,  hac  ettikten  sonra Hindistan’a gitti. Selîm fah’dan yakınlık gördü. Cunbür diyarı ona verilip, âlimlerin  reîsi  ve  müftî  oldu.  1045  (m.  1635)’de  vefât  etti.  Diğer  oğlu Mehmed Efendi, müderris, sonra Selanik ve Yenişehir kadısı oldu. 1025 (m. 1616) senesinde vefât etti. Babasının yanına defnedildi.');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21279, 'MÛSÂ ŞEREFİ', 'Diyarbakır veli ve alimlerinden. 1891 yılında Muş’un ferefkan köyünde doğdu. İlk tahsilini amcası Molla Süleyman’dan okudu. Sonra Muş’un Keran kö-yüne  giderek  oradaki  medresede  devam  etti.  Muş  Merkez  Alaeddin Camisi  yanında  bulunan  medresede  Arapzade  Muhammed  Efendi’den  de ders  aldı.  Sonra  Bitlis’de  Nurşin  Medreselerinde  de  okudu  Diyarbakır’ın Silvan ilçesine giderek orada merhum Molla Abdurrahman’dan icazet aldı. Bundan sonra Urfa’nın çeşitli yerlerinde, Silvan’ın köylerinde, Diyarbakır’ın Sa’di  ve  Cimikan köylerinde  imamlık  ve  müderrislik  yaptı.  Bir  ara  fam’a giderek  orada  da  talebe  okuttu.  Barınlı  Molla  Abdullah,  Hasenanlı  Molla Abdülbari, Karacadağlı Molla Musa, Molla Cemil, Molla Kadri, Molla Said vb talebeleri vardır. Musa  Efendi  1971  yılında  Diyarbakır’da  vefat  etti.  Mardin  kapı mezarlığındadır. Arabi ve Farisi birkaç eseri vardır. Muhammed Sıddık ve Mustafa adlı iki oğlu vardır. Musa Efendi ilmiyle amil idi. Her gün on cüz Kur’an-ı kerim okumayı vird edinmiş  idi.  Ylene  kadar  bu  adetini  sürdürmüştü. Yetiştirdiği  yüzlerce talebesi tarafından defin işlemleri yapılmıştır.', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:32.993859', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Diyarbakır veli ve alimlerinden. 1891 yılında Muş’un ferefkan köyünde doğdu. İlk tahsilini amcası Molla Süleyman’dan okudu. Sonra Muş’un Keran kö-yüne  giderek  oradaki  medresede  devam  etti.  Muş  Merkez  Alaeddin Camisi  yanında  bulunan  medresede  Arapzade  Muhammed  Efendi’den  de ders  aldı.  Sonra  Bitlis’de  Nurşin  Medreselerinde  de  okudu  Diyarbakır’ın Silvan ilçesine giderek orada merhum Molla Abdurrahman’dan icazet aldı. Bundan sonra Urfa’nın çeşitli yerlerinde, Silvan’ın köylerinde, Diyarbakır’ın Sa’di  ve  Cimikan köylerinde  imamlık  ve  müderrislik  yaptı.  Bir  ara  fam’a giderek  orada  da  talebe  okuttu.  Barınlı  Molla  Abdullah,  Hasenanlı  Molla Abdülbari, Karacadağlı Molla Musa, Molla Cemil, Molla Kadri, Molla Said vb talebeleri vardır. Musa  Efendi  1971  yılında  Diyarbakır’da  vefat  etti.  Mardin  kapı mezarlığındadır. Arabi ve Farisi birkaç eseri vardır. Muhammed Sıddık ve Mustafa adlı iki oğlu vardır. Musa Efendi ilmiyle amil idi. Her gün on cüz Kur’an-ı kerim okumayı vird edinmiş  idi.  Ylene  kadar  bu  adetini  sürdürmüştü. Yetiştirdiği  yüzlerce talebesi tarafından defin işlemleri yapılmıştır.');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21280, 'MURTEZA ZEBİDÎ', 'Ebü’l-Feyz', '1205 (m. 1791)', '1167 (m. 1753)', '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:32.993823', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Hadîs  ve  Hanefî  mezhebi  fıkıh  âlimlerinin  büyüklerinden.  İsmi, Muhammed  bin  Muhammed  bin  Muhammed  bin  Abdürrezzâk  Hüseynî Zebîdî’dir.  Künyesi  Ebü’l-Feyz  olup,  lakabı  Murtezâ’dır.  1145  (m.  1732) senesinde, Hindistan’ın Kuzey batısında bulunan Bekerâm şehrinde doğdu. 1205 (m. 1791) senesi fa’bân ayında tâ’ûn hastalığından Mısır’da vefât etti. Murtezâ Zebîdî, Yemen’in Zebîd şehrinde büyüdü. İlim öğrenmek için çok yerler dolaştı. Zamanın büyük âlimlerinden olan feyh Abdullah Sindî, feyh Ymer  bin  Ahmed  Mekkî,  Abdullah  Sekkâf,  Muhammed  bin  Alâüddîn Nezcânî, Süleymân bin Yahyâ, İbn-üt-Tayyib, Seyyid Abdürrahmân Ayderûs, feyh  Abdullah  Mîrgânî  ve  birçok  âlimden  ilim  öğrendi.  Fıkıh  ilmini  feyh Abdullah’dan  öğrendi.  feyh  Abdullah’ın  yazmış  olduğu  eserlerin  çoğunu okuyup  icâzet  aldı.  “Muhtasar-üs-Sa’d”ı,  feyh  Abdürrahmân  Ayderûs’dan okudu. Onun uzun zaman sohbetlerinde bulunarak, bâtınî ilimlerde kemâle Murtezâ  Zebîdî  şöyle  anlatmaktadır:  “Hocam  feyh  Abdürrahmân Ayderûs,  Mısır’daki  âlimleri  ve  ileri  gelenleri medhederek,  oraya  gitmem için beni teşvik etti. Beni Mısır’a gitmek arzusu kapladı. Kısa bir süre sonra Mısır’a gittim.” Murtezâ Zebîdî, 1167 (m. 1753) senesi Safer ayının dokuzunda Mısır’a gitti.  Oradaki  âlimlerden  olan,  Ahmed  Mevlevi,  Cevherî,  Hafnâ,  Büleydî, Sa’îdî, Mûdâbigî ve başka âlimlerin sohbetlerinde bulundu. Onlardan icâzet aldı. Âlimler onun ilimdeki üstünlüğüne, faziletine ve hafızasının kuvvetine şâhid oldular. föhreti her yere yayıldı. Murtezâ  Zebîdî,  ilim  öğrenmek  için  üç  defa  yolculuğa  çıktı.  Bu seferlerinde,  gittiği  yerlerin  büyük  âlimleri  ile  görüştü.  feyh-ül-Arab Hümâm,  İsmâil  Ebû  Abdullah,  Ebû  Ali  ve  başkaları  kendisine  iyilik  ve ihsânlarda  bulundular.  Deniz  yoluyla  Dimyat,  Reşîd,  Mansûr  ve  başka Murtezâ Zebîdî, daha sonra evlenip, Atfet-il-gusâl denilen yere yerleşti. Burada  Fîrûzâbâdî’nin  “Kâmûs”  unun  şerhine  başladı.  Bu  şerhi  uzun  bir çalışmadan  sonra,  on  cild  olarak  tamamlayıp,  Tâc-ül-arûs  ismini  verdi. Eserini tamamladığı zaman, talebelerini ve zamanın âlimlerini da’vet edip, yemek verdi. Herkes onun faziletine, lügat ilmindeki üstünlüğüne hayran oldu. Birçok âlim, eserin kıymetine dâir nazım ve nesir hâlinde medhiye ve takdim yazıları yazdılar. Takriz yazan âlimlerden ba’zıları şunlardır: feyh Ali  Sa’dî,  feyh  Ahmed  Derdîr,  Seyyid  Abdürrahmân  Ayderûs,  feyh Muhammed  Emîr,  feyh  Hasen  cildâvî,  feyh  Ahmed  Beylî,  feyh  Atiyye Echûrî, feyh Îsâ Berâvî, feyh Muhammed Ziyâd, feyh Muhammed Ubâde, feyh Muhammed Mekkî, feyh Muhammed Saîd Bağdadî. İlmî  çalışmalarına  devam  eden  Murtezâ  Zebîdî,  çok  kıymetli  eserler yazdı.  Oturduğu  beldenin  ileri  gelenleri,  onun  sohbetlerine  devamlı gelirlerdi.  Murtezâ  Zebîdî,  onların  arasında  vakar  ve  kemâl  sahibi  olarak bulunur, gelenlerin makam ve zenginliklerine iltifât etmez, gönüllerine göre muâmele  ederdi.  Onlara  fâideli  olmaya  çalışırdı.  Murtezâ  Zebîdî’nin  ilim meclislerine her beldeden ilim talipleri gelirdi. Murtezâ Zebîdî, Arabca, Türkçe ve Farsçayı çok iyi bilirdi. Hadîs ilminde söz sahibi idi. Onun hadîs ilmindeki üstünlüğüne âlimler hayran kalırlardı. Ezher  âlimlerinden  ba’zısı  Murtezâ  Zebîdî’ye  giderek,  kendilerine  hadîs ilminde icâzet vermesini istediler. O zaman onlara şöyle dedi; “Size icâzet vermem  için,  hiç  olmazsa  ba’zı  hadîs  kitaplarının  baş  kısmından  benim yanımda okumanız lâzımdır.” O âlimler de bunu kabûl ettiler. Pazartesi ve Perşembe günleri Salîbe’de feyhûn Câmii’nde husûsî olarak Sahîh-i Buhârî dersi  aldılar.  Ayrıca oturduğu  semtin  sakinleri,  kendilerine  de  ders vermesini rica ettiler. O da kabûl etti. Sahîh-i  Buhârî  derslerinde,  kitaptan  bir  miktar  okuduktan  sonra, amellerin  faziletlerine  dâir  veya  daha  başka  mevzûlarda  bir  hadîs-i  şerîf okur, ezberden râvilerini söylerdi. Sonra arkasından mevzû ile alâkalı çok güzel  şiirler  okurdu.  Burada  dersini  tamamladıktan  sonra,  başka  bir mescide giderek, ayrı bir mevzûda ders verirdi. Büyük-küçük herkes ona sevgi  ve  hürmette  bulunurdu.  Gittiği  yerlerde  insanları,  dînin  emir  ve yasaklarını yerine getirmeye teşvik eden nasihatlerde bulunurdu. Derslerini Resûlullah efendimize (aleyhisselâm) salât ve selâm ile bitirirdi. Acâib-ül-âsâr  fit-terâcim  vel-ahbâr  kitabının  müellifi  Abdürrahmân Cebertî şöyle demektedir: “Ben, Murtezâ Zebîdî’nin, gerek evinde, gerekse daha başka yerlerdeki derslerinde ve sohbetlerinde bulundum. Biz, onun yanında ekseriyetle hadîs ilmi ile meşgûl olurduk. Onun büyük âlimlerden dinlediği şeyler çoktur. Hattâ bunları yazmıştır. fu âna kadar böyle dinleyip de  not  aldıkları  pekçok  kâğıt  vardır.  Mustafa  Bey,  İskenderânî  Defterdar Eyyûb  Bey  gibi,  ba’zı  devlet  ileri  gelenleri,  ondan  istifâde  etmek  için evindeki ve başka yerlerde verdiği derslerde hazır bulunurlardı.” Murtezâ Zebîdî, misâfirlerine çok ikramda bulunurdu.  Uzak  beldelerden gelenlere yemek yedirirdi. Mehmed Paşa Mısır vâlisi iken, ona çok kıymet verdi.  Maddî  ihtiyâçlarını  karşıladı.  1184  (m.  1770)  senesinde  sultan tarafından İstanbul’a da’vet edildi. Bir mazeretini öne sürerek, bu da’veti kabûl etmedi, İslâm devletlerinin sultanları ona çok hediyeler gönderirdi. Murtezâ  Zebîdî  de,  zamanın  sultânı,  Birinci  Abdülhamîd  Hân’a  çeşitli hediyeler gönderdi. Küçük-büyük herkes tarafından bilinen ve iltifât gören Murtezâ Zebîdî, bir müddet sonra evine çekildi. Kimseyle görüşmedi. Ders okutmayı bıraktı. İ’tikâfa  girdi.  Buna  rağmen,  Mısır’ın  ileri  gelenleri  devamlı  ona  hediye gönderirlerdi. Murtezâ Zebîdî’nin bedeni zayıf idi. Sakalları çabuk ağarmış idi.  Huyu  güzeldi.  Güler  yüzlü  ve  vakar  sahibi  idi.  Çok  üstün  bir  zekâya Murtezâ Zebîdî’nin yazdığı eserlerden ba’zıları şunlardır: 1- Tâc-ül-arûs fî şerh-il-kâmûs, 2- Er-Kavd-ül-mi’târ fî neseb-is-Sâdât âl-i Ca’fer-i  Tayyar, 3-İthâf-üs-sâdât-il-müstekin  fî  şerhi  İhyâ-il-ulûm  lil-Gazâlî,  4- Bulgat-ül- garîb  fî  mustalahi  âsâr-il-Habîb,  5- Ikd-ül-cevâhir-il-munifeti  fî  edilleti mezheb-il-İmâm Ebü’l-Hanîfe.');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21281, 'MUSTAFA EFENDİ', 'Bursa velîlerinden.  oftade  dergâhı  şeyhlerinden.  Hayreddin  Çelebi’nin oğludur.  İyi  bir  tahsil  gördükten  sonra  babasının  yanında  süluka başlamıştır. Babası vefât edince Eşref-zâde feyh Fahreddin Efendi’ye intisab etmiştir.  O  da  vefat  edince  Eşrefiye  Dergahı  feyhlerinden  Abdülkadir Efendi’ye intisab ederek sülukunu tamamlayıp icazet almıştır. feyh Mustafa Efendi’nin müridi olan Gazzizade Abdullatif Efendi, feyh Mustafa Efendi’nin hem Celvetiye ve hem de Kadiriye’den icazetli olduğunu feyh Mustafa Efendi, sülukunun başlangıcından ömrünün sonuna kadar kırk  yıldan  fazla  bir  zamanda  teheccüdü  bırakmamış,  sünnet-i  seniyyeye tam  manasıyla  riayet  etmiş,  nafile  namazların  terk  edilmesine  bile  cevaz vermemiştir.  Abdestsiz  gezmez,  her  abdest  alışında  şükr-i vudu  namazı kılar, kahve, tütün gibi keyif verici şeylerden kaçınırdı. feriat’ın erkanına ve tarikat adabına son derece dikkat eder, bütün vakitlerini vird, zikir, Kur’an ve kitap okumakla geçirirdi. Alim bir zattı. Abdestin sünnetleri konusunda fıkhi  bir meseleden  dolayı  amelinden  şüphe  edip  yirmi  beş  yıllık namazlarını  kaza  ettiği  rivayet  edilmektedir.  Gazzizade  Abdüllatif, kendisinin  birçok  kerametini  gördüğünü  söyleyerek  bunları  kitabında beyan etmektedir. feyh Mustafa Efendi, 1 Ramazan 1217 (m. 26 Aralık 1802) Pazar günü vefat eylemiştir, Kendisi orta boylu, hafif sakallı, kırmızı yüzlü, fukaraperver cömert  bir  kişiydi.  Cenazesini  yıkayan  Hace  Bekir  Efendi,  cenazesi yıkanırken kalbinin zikrettiğini ağlayarak anlatmıştır. oftade dergâhındadır.', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:32.993901', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Bursa velîlerinden.  oftade  dergâhı  şeyhlerinden.  Hayreddin  Çelebi’nin oğludur.  İyi  bir  tahsil  gördükten  sonra  babasının  yanında  süluka başlamıştır. Babası vefât edince Eşref-zâde feyh Fahreddin Efendi’ye intisab etmiştir.  O  da  vefat  edince  Eşrefiye  Dergahı  feyhlerinden  Abdülkadir Efendi’ye intisab ederek sülukunu tamamlayıp icazet almıştır. feyh Mustafa Efendi’nin müridi olan Gazzizade Abdullatif Efendi, feyh Mustafa Efendi’nin hem Celvetiye ve hem de Kadiriye’den icazetli olduğunu feyh Mustafa Efendi, sülukunun başlangıcından ömrünün sonuna kadar kırk  yıldan  fazla  bir  zamanda  teheccüdü  bırakmamış,  sünnet-i  seniyyeye tam  manasıyla  riayet  etmiş,  nafile  namazların  terk  edilmesine  bile  cevaz vermemiştir.  Abdestsiz  gezmez,  her  abdest  alışında  şükr-i vudu  namazı kılar, kahve, tütün gibi keyif verici şeylerden kaçınırdı. feriat’ın erkanına ve tarikat adabına son derece dikkat eder, bütün vakitlerini vird, zikir, Kur’an ve kitap okumakla geçirirdi. Alim bir zattı. Abdestin sünnetleri konusunda fıkhi  bir meseleden  dolayı  amelinden  şüphe  edip  yirmi  beş  yıllık namazlarını  kaza  ettiği  rivayet  edilmektedir.  Gazzizade  Abdüllatif, kendisinin  birçok  kerametini  gördüğünü  söyleyerek  bunları  kitabında beyan etmektedir. feyh Mustafa Efendi, 1 Ramazan 1217 (m. 26 Aralık 1802) Pazar günü vefat eylemiştir, Kendisi orta boylu, hafif sakallı, kırmızı yüzlü, fukaraperver cömert  bir  kişiydi.  Cenazesini  yıkayan  Hace  Bekir  Efendi,  cenazesi yıkanırken kalbinin zikrettiğini ağlayarak anlatmıştır. oftade dergâhındadır.');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21282, 'MUSLİHUDDÎN MUSTAFA YARHİSÂRÎ', 'Musl', NULL, '1505', '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:32.993938', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Osmanlı  âlimlerinden.  İsmi,  Mustafa  bin  Evhadüddîn’dir.  Lakabı Muslihuddîn  olup,  Yarhisârî  diye  bilinir.  Doğum  yeri ve  târihi bilinmemektedir. 911 (m. 1505) senesinde İstanbul kadısı iken vefât etti. İstanbul’da  Fâtih  semtinde  yaptırmış  olduğu  mescidinin  bahçesinde Zamanının  âlimlerinden  ilim  tahsil  ettikten  sonra,  Sahn-ı  semân müderrisi  olduğu  sırada,  Hocazâde’nin  ders  meclisine  katıldı.  Onun sohbetlerinde  bulunup,  ilmî  ve  ma’nevî  yüksekliklere  erişti.  Ba’zı medreselerde  müderris  olarak  vazîfe  yaptıktan  sonra,  Edirne’de  bulunan Eski Câmi Medresesi’ne ve Sahn-ı semân medreselerinden birine müderris olarak ta’yin edildi. Bu arada, fazileti ve ilmî üstünlüğüyle pâdişâh Sultan İkinci  Bâyezîd’in  dikkatini  çekti.  İstanbul  kadılığına  ta’yin  edildi.  On  yıl müddetle bu şerefli vazîfeyi yürütüp, fazilet ve adâletle hükm etti. Kâdılığı esnasında  insanlara,  Allahü  teâlânın  yüce  dîninin  emirlerine  uyma, yasaklarından  kaçındırma  husûsunda  yol  göstermekte  gayret  sarf  etti. Bid’atlerden  şiddetle  uzaklaştırmaya  çalıştı.  Bu  yüce  ve  şerefli  vazîfeyi yürütürken vefât etti. Nakledilir  ki:  Sultan  İkinci  Bâyezîd  Hân’ın  vezirlerinden birisi, Muslihuddîn  Mustafa  Yarhisâri’ye  İstanbul  kadılığı  vazîfesine  ta’yin edildiğini bildirip, vazîfeye başlayın diye söyleyince, bu vazîfeyi kabûl etmek istemedi.  Kabûl  etmediği  Pâdişâh’a  arz  edilince,  Pâdişâh,  bizzat  kendi  el yazısıyla bir mektûbunda; “Kâdılık makamına sen dururken başkasını ta’yin etmek büyük hatâdır. Senin bu makama ta’yin edilmeyi istememen makbûl değildir. Bu makama senin getirilmen benim üzerime vazîfedir” diye yazdı. Bu  mektûp  Muslihuddîn  Yarhisârî’nin  eline  verilince,  onu  saygı ile  öpüp yüzüne  gözüne  sürdükten  sonra  Pâdişâh’ın  fermanına  uyup  bu  vazîfeyi Muslihuddîn Mustafa Yarhisârî; âlim, faziletli, ilmiyle amel eden, güzel ahlâk sahibi bir zât idi. Zamanındaki bütün ilimlerde yüksek derece sahibi idi.  Kâdılık  yaptığı  müddet  içerisinde  herkese  karşı  iyi  huylu  ve  hoş muâmele  ile  davranırdı.  Hüküm  vermede  keskin  bir  kılıç  gibiydi.  Allahü teâlânın  dîninin  emirlerini  yüceltmek  için,  yüksek  gayret  sahibi  idi.  Bu sebeple,  zamanının  âlimleri,  onun  ilmî  ve  ma’nevî  üstünlüğünü kabûl ederlerdi. Zayıf ve kimsesizlere çok merhamet eder, onlara zulm edenleri şiddetle cezalandırmaktan çekinmezdi. Bu sebeple, zulm etmek istiyenler ondan çekinirlerdi. Mustafa Yarhisârî’nin şu kıymetli eserleri vardır: 1- Hâşiyetü alâ Tavâli- ül-envâr, 2- Hâşiyetü alet-Tavzîh, 3-Risâlet-ül-vebâ ve cevâz-ül-firâr.');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21283, 'MUSTAFA BEKRÎ', NULL, '1162 (m.  1749)', '1122  (m.  1710)', '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:32.994016', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Evliyânın  büyüklerinden.  İsmi Kutb-üd-dîn Mustafa    bin    Ali    bin Kemâlüddîn bin Abdülkâdir Muhyiddîn Sıddîki Bekrî’dir. Soyu Hazret-i Ebû Bekr’e ulaşır. 1099 (m. 1688) senesi Zilka’de ayında Kudüs’de doğdu. 1162 (m.  1749)  senesi  Rebî’ul-evvel  ayının  üçünde  Pazartesi  gecesi  yatsı namazından  sonra  Kâhire’de  vefât  etti.  Karafe-i  kübrâ  denilen  yere Mustafa  Bekrî  henüz  altı  aylık  iken  babasını  kaybetti.  Bunun  üzerine amcası Alımed bin Kemâlüddîn’in yanında büyüdü. İlk olarak, Abdürrahmân bin  Muhyiddîn  Selîmî  ve  Muhammed  İbni  Mevâhib’den  ilim  tahsîl  etti. Muhammed İbni İbrâhim ile ders müzâkeresi yaptılar. Hâfız İbni Hacer’in Sahîh-i Buhârî şerhini okudu. Büyük âlim Abdülganî Nablüsî hazretlerinin derslerini  ta’kib  ederek,  ileri  gelen  talebelerinden  oldu.  Allahü  teâlânın tevfîki ve yüksek kabiliyeti ile az zamanda birçok ilim tahsil ederek, tefsîr ve hadîs  ilimlerinde  çok  derin  bilgilere  sahip  oldu.  Abdülganî  Nablüsî hazretlerinden,  Muhyiddîn-i  Arabî’nin  “Tedbîrât-ı  ilâhiyye”  ve  “Fütûhât-ı Mekkiyye”  adlı  eserlerinin  ba’zı  bölümlerini  okudu.  Tasavvuf   yolunu, Halvetiyye  yolunun  büyüklerinden  feyh  Abdüllatîf  Halebî Halvetî’den Mustafa  Bekrî,  hac  farizasını  yerine  getirdikten  sonra  Mısır’a  gitti. Burada Hacı Baba diye meşhûr olan feyh Mustafa ile görüştü ve ona talebe oldu. Onun yanından “Erba’în” denilen riyâzetini tamamladı. Hocasının emri ile fam’a gitti ve burada insanlara doğru yolu göstermeye başladı. Mustafa  Bekrî,  hocası  Abdüllatîf  Halebî’den  hilâfet  alınca,  ma’nevî yüksekliğin verdiği aşkın te’sîri ile inzivâ hayatını tercih etti. Devamlı Allahü teâlânın zikri ile meşgûl oldu. Nefsinin arzu ve isteklerine karşı mücâdele etti. Tasavvuf yolunda talebe yetiştirme izni aldığı zaman çok gençti. Hocası vefât  ettikten  sonra,  hocasının  yerine  geçti.  1122  (m.  1710)  senesi Muharrem  ayının  ondokuzunda  Perşembe  günü  Beyt-i  Makdis’e  gitti. Burada  insanlara  doğru  yolu  anlattı.  Buradan  Yafa’ya  gitti.  Burada Necmüddîn  İbni  Hayruddîn-i  Remli  ile  görüştü.  Ondan  İmâm-ı  Mâlik hazretlerinin Muvatta’ ismindeki eserinin bir bölümünü okudu. Bu kitabın tamâmını ders olarak okutmak ve hadîs-i şerîf rivâyet etmek için izin aldı. Daha sonra fam’a dönerek, insanlara va’z ve nasihatte bulunmaya başladı. 1126  (m.  1714)  senesinde  fam’a  ve  oradan  Halep  yoluyla  Bağdat’a  gitti. Bağdat’da  Seyyid  Abdülkâdir-i  Geylânî  hazretlerinin  kabrini  ziyâret  etti. Mübârek rûhundan feyz aldı. Mustafa Bekrî, ilim öğrenmek ve büyük zâtların kabirlerini ziyâret etmek için  birçok  beldelere  gitti.  Bu  ziyâretleri  sırasında  İstanbul’a  da  gelen Mustafa  Bekrî,  1129  (m.  1717)  senesi  Muharrem  ayının   onikisinde İstanbul’dan ayrılarak fam’a gitti. Orada bulunan Hocası Abdülkâdir Nablüsî ile  görüştü.  1145  (m.  1732)  senesinde  ikinci  defa  hacca  gitti.  Dönüşte Kudüs’e uğradı. Daha sonra çeşitli yerlere seyahatler yapan Mustafa Bekrî, en sonunda Kâhire’ye yerleşti ve burada vefât etti. Sefînet-ül-evliyâ  kitabının  müellifi  onun  hakkında  şöyle  demektedir: “Çok  sayıda  zâtın  hayatını  yazdım.  Mustafa  Bekrî  hazretleri  kadar  çok seyahat etmiş olan bir zâta rastlamadım. Eşine az rastlanan bir zâttır. İlim ve  irfan bakımından  çok  yüksek  derecelere  sahiptir.  Yaptığı  çok  sayıda seyahatlere  rağmen  pekçok  eser  yazdı.  Birkaç  eserini  mütâlâa  ettim. Eserlerin herbirisi derya idi. Mustafa Bekrî hazretlerinin halîfelerinin sayısı yirmi kadardır. Her biri yüksek derecelere kavuşmuştur.” Yûsuf  Nebhânî  de  şöyle  demektedir:  “Mustafa  Bekrî’nin  çok  sayıda eserini gördüm. Bu eserlerinden, kendi el yazısı ile yazdığı “Elmakâmât-ür- rûmiyye” ismindeki eserine rastladım. ozerinde, Eşmûnî haşiyesinin sahibi Yûsuf Hafnî’nin el yazısı ile yazılmış bir takrizi vardı. Mustafa Bekrî, bütün eserlerini    Mescid-i  Aksa  civarındaki  Ebüssü’ûd  oğulları  dergâhına vakfetmiştir. fimdi bu kitapların çoğu zayi olmuştur.” Yazdığı  kitâblar  [222]  yi  aşmakdadır. (El-hikem-ül-ilâhiyye  vel- mevârid-ül-behiyye) ve (El-vasıyyet-ül-celiyye) ve (Ber-ül-eskâm) kitâbları  çok  kıymetlidir. Mustafa  Bekrî  hazretlerinin  yazmış  olduğu eserlerden ba’zıları şunlardır: 1- Elfiyetün fit-tasavvuf,  2-El-Vird-üs-seheri, 3- El-Fark-ül-mü’zin bit-tarebi  fil-farkı beynel-Acem  vel-Arab, 4- Sebîl-ün- necâ  vel-ilticâ  fit-tevessül  bi  hurûf-il-hicâ,  5-Es-Süyûf-ül-haddâd  fir-reddi ala ehl-iz-zandika vel-ilhâd, 6- ferhun ala hizb-il-İmâm eş-fa’rânî, 7- ferhun alâ  kasîdet-il-İmâm  Ebû  Hâmid  Gazâlî,  8-ferhu  kasîdet-it-tâiyye  li  İbn-i Fârıd,  9-El-Cevâb-üş-fâfi  vel-lübâb-ül-kâfi,  10-Keşf-üs-sadâ,  11- El-Hullet- ül-fâniyye, 12- El-Hediyyet-un-nediyye lil-ümmet-il-Muhammediyye. Es-Süyûf-ül-haddâd fir-reddi ehl-iz-zandika vel-ilhâd adlı eserinden ba’zı “Efendim ve büyüğüm Hamalı Ali bin Alvân, “Misbâh-ül-hidâye ve miftâh- ül-hidâye” ismindeki kitabında şöyle buyurmaktadır: “Âlim olan kimse, dînî ilimleri öğrettikten sonra talebelerini ahlâk ilmini öğrenmeye teşvik etsin. Yoksa ilimsiz, amelsiz tasavvuf zındıklıktır. Biz bunun böyle olduğuna şâhid olduk.  Hakîkî  mürşid-i  kâmil,  talebelerini,  ilk  önce  dînin  emirlerini  bilip tatbik  etmeye,  devamlı  zikr  ve  mücâhede  ile  nefsi  ve  kalbi  temizlemeye da’vet  eder.  Bunlar  elde  edildikten  sonra  hakîkat  tecellî  ederse,  bu  nûr üstüne nûr olur. Abdestsiz uyuduğum zaman  kendimde  bir  yorgunluk  hissediyor,  harabe yerlerde, sıkıntılı işler içerisinde görüyordum. Sünnet-i seniyyeye muvafık uyursam,  kendimde  bir  genişlik  ve  sevinç  hissediyordum,  kendimi  temiz yerlerde  görüyordum.  Hattâ  fazla  uyku  hâli  veya  şiddetli  soğuk gibi sebeblerle abdest almaktan âciz olursam teyemmüm yapıyordum. Abdestli olduğum  zaman  kendimde  bir  zindelik  görürdüm.  Abdestsiz  olup,  abdest almadığım zaman içimde bir darlık ve burukluk hissediyordum. Geceyi  ibâdetle  geçiremediğim  zaman,  o  gün  içimde bir  değişiklik görürdüm.  Allahü  teâlâ  ile  meşgûliyetim,  O’nu  anıp  hatırlamam,  gaflet hâlimden  daha  fazla  olunca,  kalbimde  hâsıl  olan  genişlik  ve  rahatı anlatamam. Yatsı namazından önce, uyku ve ağırlık hâli meydana gelince, yüzüme  yumuşak  bir  şeyle  vurulduğunu  hissederdim.  Bundan  dolayı uyanırdım. Bu ve benzerleri Allahü teâlânın kuluna olan lütuf ve ihsânıdır. Haram olan şeyin, kalbimde meydana getirdiği zulmeti hissederdim. Çünkü haram  olan  şey  kalbde  karanlık  bir  perde  meydana  getirir.  Bundan  ise ancak; nefsin arzu ve isteklerine mâni olmak, kalbi Allahü teâlâyı anmakla meşgûl etmek, kalbde Allah korkusu ateşini yakmak ve kalbi parlatan ilâhî muhabbetle  kurtulmak  mümkündür.  Tasavvuf  yolunda  bulunanların ekserisi,  kalblerinde  böyle  kötü  bir  hâl  hissettikleri  zaman  istiğfar etmişlerdir. Nitekim Hazret-i Ebû Bekr böyle yapmıştır. Yine  biz,  bizde  gıybet  veya  birisine  eziyet  ve  sıkıntı  vermek  gibi  hoş olmayan  bir  durum  meydana  geldiği  zaman  kalb  ahvâlimizin  değiştiğine, kalbimizin  burkulduğuna,  kalbimizde  bir  darlık  ve  donukluk  meydana geldiğine  şâhid  oluruz.  Günahın  büyüklüğüne  göre  bizde  meydana  gelen sıkıntı ve musibet de o derecede büyük olur. Bütün bu hâller, hemen tövbe ve  istiğfara  sarıldığımız,  günahımızı  i’tirâf  ettiğimiz,  günahda  ısrar etmediğimiz hâlde meydana gelirdi. Fakat bu, Allahü teâlânın kuluna lütuf ve  ihsânıdır.  Çünkü  Allahü  teâlâ  böyle  yapmakla,  o  kulunu  uyarmakta,  o kulunun günahtan dönmesine, günahları, kalblerini öldürdüğü ve kapladığı kimselere  aldanmamasına  vesile  olur.  Kalbleri  günahları  sebebiyle  ölen kimseler, işledikleri günahlar yüzünden kalblerinde herhangi bir değişiklik göremezler. İşledikleri günahların kötülüğünü hissetmezler. Nitekim hadîs-i şerîfte; “Kul bir günah işlediği zaman kalbine siyah bir nokta konur. O kul, bu günahtan vazgeçtiği, Allahü teâlâdan af ve mağfiret istediği, tövbe ettiği zaman kalbi parlar. Eğer o günaha tekrar dönerse, o siyah nokta artar, onun kalbini  kaplar.  Böyle  bir  kimse  Allahü  teâlânın  (meâlen);  “Hayır  (onların zannettikleri gibi değil)! Doğrusu onların kazandıkları günahlar, kalblerini kaplamıştır” (Mutaffif-14) buyurduğu kimselerdir” buyuruldu. Yine  şartlarına  ve  edeblerine  uygun  olarak  namaz  kıldığımız  zaman, kalbde büyük bir nûr görürüz. Ancak namazda sağa sola dönüldüğünde bu nûr sönük olur. Resûlullah efendimiz (aleyhisselâm) şöyle buyurdu: “Bir kul namazda sağa sola döndüğünde Allahü teâlâ ona; “Nereye dönüyorsun Ey Âdemoğlu? Ben senin için, döndüğün şeyden daha hayırlıyım” buyurur.” Hulâsa  İslâmiyetin  emrettiği  amellerden  herhangi  birisini,  âdabına uygun yapan kimsenin kalbinde öyle bir nûr ve sevinç olur ki, kendisinde kalb huzûru ve Allahü teâlâya yakınlık bulur. Allahü teâlâ o nûr sebebiyle, kalbindeki  ma’nevî  perdeleri  kaldırır.  Bir  kimse  dinde  riâyet  edilmesi gereken  husûslara  riâyet  etmez de,  bununla  beraber  kavuştuğunu  iddia ederse, o kimse bu iddiasında kendini haklı görmektedir. Ancak kavuştuğu şey Cehennemdir. Eğer bu kimse birşeyler elde ettiğini söylerse, hayvanî sıfatları elde etmiştir. İslâm dînine yapışmak, en nefis kokulardan daha hoş ve lezzetlidir. Kalbinin, Allahü teâlânın rızâsı ve emirleri husûsunda dağınık ve perişan olmasından çok sakınmalı ve korkmalıdır. İşte İslâm dîninin emir ve yasaklarına uymadan, onun âdabını gözetmeden, hakîkate kavuştuğunu söylemek küfürdür, öyleyse farzların ve nafilelerin şartlarına ve edeplerine riâyet etmek sûretiyle Allahü teâlânın sağlam ipine yapışmalıdır. Resûlullah efendimizin  (aleyhisselâm)  getirdiği  doğru  yolun  dışında,  şaşkınlık  ve perişanlık vardır. Muhyiddîn-i  Arabî  hazretlerinin  kabrine  gittim.  Türbenin  içerisine vardığım zaman, Muhyiddîn-i Arabî hazretlerini oturur vaziyette gördüm. Huzûruna vardım. Bana tebessüm ediyordu. Onun kitaplarını çok mütâlâa ettim ve çok faydalandım. Çok gecelerim Muhyiddîn-i Arabî hazretlerinin mescidinde    geçti.  Mescidin  kapısından  girerken,  ma’nevî  bir  elbise giydiğimi, çıkarken bu elbiseyi çıkardığımı hissediyordum. Nakşibendiyye yolunu, zâhirî olarak Muhammed Ebû Sa’îd Hindî, bâtınî olarak  Bâyezîd-i  Bistâmî  hazretlerinden  aldım.  Bir  ara  kalbim, Nakşibendiyye yolu ile meşgûldü. Birgün rü’yâmda kendimi bir cemâatin içinde  buldum.  Çoğunu  tanıyordum.  Hepsi  de  sâlih  kimselerdi.  Fakat  bir kısmını  tanımıyordum.  Sonra  onlar  dağıldılar.  Soluma  döndüğüm  zaman, orada uyuyan birisinin olduğunu gördüm. O anda, o zâtın Bâyezîd-i Bistâmî olduğu  söylendi.  O  zaman  kendi  kendime,  ondan  Nakşibendiyye  yolunun inceliklerini  öğrenmeden  ayrılmam  dedim.  Bir  müddet  sonra  Bâyezîd-i Bistâmî  uykudan  uyandı.  Fakat  ben  ona  birşey  söylemeye  cesâret edemedim. Sonunda yerinden kalktı. Birisi  gelip  onun  hizmetinde  bulundu, abdest suyunu getirdi. Bâyezîd-i Bistâmî abdestini aldı. Ben ise devamlı ona bakıyordum. Abdestini bitirip yerine oturunca yanına gittim. Ellerini öptüm. Ondan Nakşibendiyye yolunu öğretmesini istedim. “Nakşibendiyye yolunu Abdülganî anlatmadı mı?” dedi. Ben; “Evet, o bana Nakşibendiyye yolunu anlattı.  Bu  husûsta  bana  izin  verdi.  Fakat  ben  bilfiil  icâzet  istiyorum” deyince,  ellerini  bana  uzattı.  Ona  bîat  ettim.  Sonra  bana  zikr  telkin  etti. Sonra oradan ayrıldım. Biraz  sonra,  akrabâlarından  birisini  bana  gönderdi.  Ben  geri  dönüp yanına geldiğimde, tahtırevana binmiş olduğunu gördüm. Bana tahtırevanın bir  tarafını  işâret  etti.  Sonra  Bana;  “Senin  bu  yolda  kemâle  erişmen yakındır”  buyurdu.  Sonra  ben  onun  telkin  ettiği  zikirle  meşgûl  oldum. Aradan  bir  müddet  geçtikten  sonra;  “Kemâle  kavuşman  tamam  oldu” buyurdu. İçinde bulunduğum odadan çıktı. O anda uyandım.” Muhyiddîn-i Arabî hazretlerini, bir Cum’a günü ziyâret etmek nasîb oldu. Kabr-i şerîfi, fam’a yaklaşık dört saat mesafede yüksek bir tepe üzerinde bulunuyordu.  Buraya  giderken  yanımda  feyh  Abdürrahmân  Semmân  var idi.  Bana  şöyle  anlattı:  “Bir  kerre  Muhyiddîn-i  Arabî  hazretlerini  yalnız olarak ziyârete gitmiştim. Bu sırada onu mihrabda, ayakta namaz kılarken gördüm.  Yanına  varmaya  cesâret  edemedim.  Bacaklarımda  titreme meydana geldi.” Sonra birlikte çeşitli zâtların kabirlerini ziyâret ettik. Bu ziyâretimizde pekçok ma’nevî feyz ve bereketlere kavuştuk. Dört  büyük  zât  vardır  ki,  kabirlerinde  hayatta  oldukları  zamanki  gibi tasarrufta bulunurlar. Bunlar; Seyyid Abdülkâdir-i Geylânî, Ma’rûf-i Kerhî, Menbicli Ukayl, Harranlı Hayat bin Kays’dır. Yine şu dört zât, anadan kör ve alaca  hastalığına  tutulmuş  olanları,  Allahü  teâlânın  izni  ile  iyileştirirler. Bunlar, Abdülkâdir-i Geylânî, feyh Bekâ bin Batû, Ebû Sa’îd Kalyûbî, Ali bin Heyti (kuddise sirruhum).”');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21284, 'MUSTAFA HÂKİ EFENDİ', 'İstanbul velîlerinden.  Doğum  târihi  belli  değildir.  1920  (m.  1338)  de İstanbul\'da  vefât  etti.  Kabri  Fâtih  Câmii  bahçesinde,  Gazi  OsmanPaşa türbesine yakındır. Sık sık ziyâret edilmektedir. İlmi, ahlâkı, tevâzuu Tokat, Çorum,  Sivas,  Amasya  ve  Yozgat\'ta  dilden  dile  anlatılmaktadır.  Aynı zamanda feyhülislâm Mustafa Sabri Efendinin yeğenidir. Mustafa Hâki Efendi, ilk tahsilini Tokat\'ta yaptıktan sonra, Çorum feyhi fîranlı Mustafa Efendiye talebe olup icâzet aldı. Sonra Tokat\'a dönüp, talebe yetiştirmeye  başladı.  Dergahı  hak  âşıkları,  ilim  tâlipleri  ile  dolup  taşardı. Yetiştirdiği  talebeleri,  arasında  en  meşhuru  Sivaslı  Mustafa  Tâkî\'dir. Mustafa Tâkî Efendi vefât edince bâzıları; \"İlim üç Mustafa ile gitti. Bunlar Çorum  feyhi  fîranlı  Mustafa, Mustafa  Hâki  ve  Sivaslı  Mustafa  Tâkî\'dir.\" Mustafa Hâki Efendi, 1908\'de ikinci Meşrûtiyetin ilânı sebebiyle yapılan seçimde  devrin  ileri  gelenlerinin  arzûsuyla  Tokat  mebûsu  oldu.  Ancak ittihatçıların  ve  gayr-i  müslimlerin  oyları  ile  mebusluğu  düşürüldü  ve İstanbul\'da mecbûri ikâmete tâbi tutuldu. Kendisine Çarşamba\'daki Mustafa İsmet Efendi dergâhı verildi ve vefâtına kadar burada kaldı. Mustafâ  Hâki  Efendinin  oğlu  Behâeddîn  Efendi,  dînî  ilimlerin  yanında Eczâcılık mektebini  bitirmiş, siyâsî  olaylara  karışmamak için  Türkiye\'den ayrılıp önce Medîne\'ye gitmiş orada 27 sene ders okutmuş sonrada fam\'a geçmiştir.  Torunları  zaman  zaman  Tokat\'a  gelip  akrabâlarını  ziyâret Mustafa  Hâki  Efendinin  sözleri  ve  kerâmetleri  halk  arasında anlatılmaktadır. Bunlardan bâzıları şöyledir: Mustafa Hâki hazretleri Samsun\'a geldiği bir günde misâfir kaldığı evde ikram edilen meyveyi yerken buyurur ki: \"Bu gece dünyâya bir oğlum gelse gerektir.\"  Tokat\'a  gelindiğinde  görülür  ki  sözün  söylendiği  o  saatte Behâeddîn Efendi dünyâya gelmiştir. Mustafa  Hâki  hazretleri  sohbetlerde  umumiyetle  Eshâb-ı  kirâm sevgisinden bahseder, Eshâb-ı kirâm sohbet ile yükseldi. Eshâb-ı kirâm dîni bildirenlerdir. Eshâb-ı kirâma dil uzatan, dîni yıkar. Eshâb-ı kirâmın îmânda ayrılıkları yoktur. Hepsi bütün velîlerden üstündür. İnsana  lâzım  olan  önce  Ehl-i  sünnete  uygun  inanmak,  sonra  Allahü teâlânın emir ve yasaklarına uymak ve tasavvuf yolunda ilerlemektir. İslâmın  temeli;  Ehl-i  sünnet  âlimlerinin  bildirdiklerine  inanmak  ve Nasihat  istiyen  birisine buyurdu  ki:  \"Müslüman temiz  toprağa  benzer. Temiz  toprağa  her  şey  atılır.  Hakaret  görebilir,  eziyet  görebilir,  cefaya uğrayabilir.  Lâkin  ondan  hep  güzel  temiz  faydalı  şeyler  çıkar.  Müminin, insanları  ayırmadan,  hepsine  aynı  şekilde  davranması  ve  güzel  ahlâklı olması lâzımdır.\" Kerâmet hakkında da; \"Bir kimsenin havada uçtuğunu suyun üzerinde yürüdüğünü  görseniz,  İslâmiyetin  emir  ve  yasaklarına  uymaktaki hassasiyetine  bakınız.  fâyet  bu  tam  ise  ona  uyabilirsiniz.  Eğer  emir  ve yasaklarda  gevşeklik  varsa  hemen  ondan  uzaklaşınız.  Çünkü  zararı dokunur.\" derdi. Vefâtı sebebiyle yazılan mersiyeden bir bölüm: Hicrânda koydun bizleri ey Mürşîd-i ebcel Nâkısları kim eyleyecek kâmil ü ekmel Destine yapışdık ebedî bir habl-i metîne Çekdin elini nâkıs olan düşdi zemîne Eyvâh geçirdik dem-i fırsatları eyvâh Allaha ulaştırıcı sohbetleri eyvâh Feyz-i nazarın mürdeleri eyledi ihyâ Bu seng-dil Âdemliğini bulmadı hâlâ Sen bizleri cezb eder idin arş-ı berîne Biz kendimizi attırırız zîr-i zemîne Hayfâ o nezâfet o zerâfet, o cemâl Cem\' olmış idi sende hemân cümle kemâlât', NULL, '1338', '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:32.994404', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'İstanbul velîlerinden.  Doğum  târihi  belli  değildir.  1920  (m.  1338)  de İstanbul\'da  vefât  etti.  Kabri  Fâtih  Câmii  bahçesinde,  Gazi  OsmanPaşa türbesine yakındır. Sık sık ziyâret edilmektedir. İlmi, ahlâkı, tevâzuu Tokat, Çorum,  Sivas,  Amasya  ve  Yozgat\'ta  dilden  dile  anlatılmaktadır.  Aynı zamanda feyhülislâm Mustafa Sabri Efendinin yeğenidir. Mustafa Hâki Efendi, ilk tahsilini Tokat\'ta yaptıktan sonra, Çorum feyhi fîranlı Mustafa Efendiye talebe olup icâzet aldı. Sonra Tokat\'a dönüp, talebe yetiştirmeye  başladı.  Dergahı  hak  âşıkları,  ilim  tâlipleri  ile  dolup  taşardı. Yetiştirdiği  talebeleri,  arasında  en  meşhuru  Sivaslı  Mustafa  Tâkî\'dir. Mustafa Tâkî Efendi vefât edince bâzıları; \"İlim üç Mustafa ile gitti. Bunlar Çorum  feyhi  fîranlı  Mustafa, Mustafa  Hâki  ve  Sivaslı  Mustafa  Tâkî\'dir.\" Mustafa Hâki Efendi, 1908\'de ikinci Meşrûtiyetin ilânı sebebiyle yapılan seçimde  devrin  ileri  gelenlerinin  arzûsuyla  Tokat  mebûsu  oldu.  Ancak ittihatçıların  ve  gayr-i  müslimlerin  oyları  ile  mebusluğu  düşürüldü  ve İstanbul\'da mecbûri ikâmete tâbi tutuldu. Kendisine Çarşamba\'daki Mustafa İsmet Efendi dergâhı verildi ve vefâtına kadar burada kaldı. Mustafâ  Hâki  Efendinin  oğlu  Behâeddîn  Efendi,  dînî  ilimlerin  yanında Eczâcılık mektebini  bitirmiş, siyâsî  olaylara  karışmamak için  Türkiye\'den ayrılıp önce Medîne\'ye gitmiş orada 27 sene ders okutmuş sonrada fam\'a geçmiştir.  Torunları  zaman  zaman  Tokat\'a  gelip  akrabâlarını  ziyâret Mustafa  Hâki  Efendinin  sözleri  ve  kerâmetleri  halk  arasında anlatılmaktadır. Bunlardan bâzıları şöyledir: Mustafa Hâki hazretleri Samsun\'a geldiği bir günde misâfir kaldığı evde ikram edilen meyveyi yerken buyurur ki: \"Bu gece dünyâya bir oğlum gelse gerektir.\"  Tokat\'a  gelindiğinde  görülür  ki  sözün  söylendiği  o  saatte Behâeddîn Efendi dünyâya gelmiştir. Mustafa  Hâki  hazretleri  sohbetlerde  umumiyetle  Eshâb-ı  kirâm sevgisinden bahseder, Eshâb-ı kirâm sohbet ile yükseldi. Eshâb-ı kirâm dîni bildirenlerdir. Eshâb-ı kirâma dil uzatan, dîni yıkar. Eshâb-ı kirâmın îmânda ayrılıkları yoktur. Hepsi bütün velîlerden üstündür. İnsana  lâzım  olan  önce  Ehl-i  sünnete  uygun  inanmak,  sonra  Allahü teâlânın emir ve yasaklarına uymak ve tasavvuf yolunda ilerlemektir. İslâmın  temeli;  Ehl-i  sünnet  âlimlerinin  bildirdiklerine  inanmak  ve Nasihat  istiyen  birisine buyurdu  ki:  \"Müslüman temiz  toprağa  benzer. Temiz  toprağa  her  şey  atılır.  Hakaret  görebilir,  eziyet  görebilir,  cefaya uğrayabilir.  Lâkin  ondan  hep  güzel  temiz  faydalı  şeyler  çıkar.  Müminin, insanları  ayırmadan,  hepsine  aynı  şekilde  davranması  ve  güzel  ahlâklı olması lâzımdır.\" Kerâmet hakkında da; \"Bir kimsenin havada uçtuğunu suyun üzerinde yürüdüğünü  görseniz,  İslâmiyetin  emir  ve  yasaklarına  uymaktaki hassasiyetine  bakınız.  fâyet  bu  tam  ise  ona  uyabilirsiniz.  Eğer  emir  ve yasaklarda  gevşeklik  varsa  hemen  ondan  uzaklaşınız.  Çünkü  zararı dokunur.\" derdi. Vefâtı sebebiyle yazılan mersiyeden bir bölüm: Hicrânda koydun bizleri ey Mürşîd-i ebcel Nâkısları kim eyleyecek kâmil ü ekmel Destine yapışdık ebedî bir habl-i metîne Çekdin elini nâkıs olan düşdi zemîne Eyvâh geçirdik dem-i fırsatları eyvâh Allaha ulaştırıcı sohbetleri eyvâh Feyz-i nazarın mürdeleri eyledi ihyâ Bu seng-dil Âdemliğini bulmadı hâlâ Sen bizleri cezb eder idin arş-ı berîne Biz kendimizi attırırız zîr-i zemîne Hayfâ o nezâfet o zerâfet, o cemâl Cem\' olmış idi sende hemân cümle kemâlât');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21285, 'MUSTAFA İZZÎ EFENDİ', 'İstanbul’da  yetişen  evliyâdan.  İsmi  Mustafa  Izzî  olup,  Hasırcı-zâde ismiyle meşhûrdur. İstanbul’da doğdu. Doğum târihi bilinmemektedir. 1239 (m. 1823) senesinde İstanbul’da vefât etti. Sütlüce’deki türbesine defnedildi. Mustafa  Izzî  Efendi’nin  babası,  sâlih  bir  zât  olan  Halîl  Demhûrî’dir. Birâderi de, Hasırcıbaşı Emîr Ağa’dır. Babası dâima onun ticarethânesinde vakit geçirdiği için, Hasırcı feyh Halil ismiyle anıldı. Bu sebeple Mustafa Izzî Efendi de, Hasırcı-zâde diye şöhret buldu. Mustafa Izzî Efendi, tasavvuf yolunu seçip ilim ve edeb öğrendi. Birâderi ise ticâretle meşgûl oldu. Büyük âlim Süleymân Sıdki Efendi’nin terbiyesiyle yetişti.  Çok  riyâzet  ve  mücâhedede  bulundu.  İçini  ve  dışını  İslâm  dîninin güzel ahlâkı ile süsledi. Hocasından icâzet (diploma) aldı. föhreti heryere yayıldı. Hocasının emriyle Sütlüce’deki dergâha yerleşip, insanları irşâda ve talebe yetiştirmeye başladı. Dergâhı, Hasîrî-zâde dergâhı diye şöhret buldu. Mustafa Izzî Efendi, hacca gitmek için yola çıktı. Mekke-i mûkerreme ve hakkıyla  yerine  getirmeye  çalıştı.  Peygamber  efendimizin  (aleyhisselâm) mübârek  kabr-i  şerîfini  ziyâret  edip  Mısır’a  geldi.  Mısır’a geldiğinde  yol parası tükenmişti. Yoluna devam edemeyip orada kaldı. Mevsim de, Ahmed Bedevî’nin ziyâreti ve mevlîd-i şerîf cemiyetlerinin yapıldığı zamana tesadüf etmişti.  Bu  sebeple  Tanta’ya  gidip,  oradaki  Ahmed  Bedevî  hazretlerinin kabr-i  şerîfini  ziyâret  etti.  O  esnada  hâlini  arzetti.  Hüzn  ile  kendinden geçmiş iken, hiç tanımadığı birisi omuzuna eliyle dokunarak; “Hasırcıoğlu Mustafa Efendi siz misiniz?” dedi. O da; “Evet efendim” diye cevap verince, o kimse, koynundan bir kese çıkardı ve; “funu al ihtiyâcın vardır. İhtiyâcın için sarfedersin. İstanbul’da karşılaşırsak alırım, yoksa helâl olsun” dedi ve kalabalık içine karışarak kayboldu, İstanbul’da da hiç görülmedi. Mustafa  Izzi  Efendi’nin  vefâtında,  zamanın  şâirlerinden  Hayreddîn Efendi tarafından söylenen şiirde özetle şöyle denmektedir: “Bütün vakitlerini insanlara ilim ve edeb öğretmekle geçirdi. Faziletiyle zamanının  büyükleri  arasına  girdi.  Kırk  sene  irşâd  makamında  bulundu. Nice    eksik    ve    noksan    kimseler    onun    feyziyle    terbiye    oldu.    Onun rûhâniyetinden  istifâde  etmek  isteyen,  onu  vesile  edip  yardım  istesin. Hulûs-i kalb ile bu ziyâretgâha gelsin. Bu sebeple ma’nevî kemâle kavuşur.”', NULL, '1823', '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:32.995181', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'İstanbul’da  yetişen  evliyâdan.  İsmi  Mustafa  Izzî  olup,  Hasırcı-zâde ismiyle meşhûrdur. İstanbul’da doğdu. Doğum târihi bilinmemektedir. 1239 (m. 1823) senesinde İstanbul’da vefât etti. Sütlüce’deki türbesine defnedildi. Mustafa  Izzî  Efendi’nin  babası,  sâlih  bir  zât  olan  Halîl  Demhûrî’dir. Birâderi de, Hasırcıbaşı Emîr Ağa’dır. Babası dâima onun ticarethânesinde vakit geçirdiği için, Hasırcı feyh Halil ismiyle anıldı. Bu sebeple Mustafa Izzî Efendi de, Hasırcı-zâde diye şöhret buldu. Mustafa Izzî Efendi, tasavvuf yolunu seçip ilim ve edeb öğrendi. Birâderi ise ticâretle meşgûl oldu. Büyük âlim Süleymân Sıdki Efendi’nin terbiyesiyle yetişti.  Çok  riyâzet  ve  mücâhedede  bulundu.  İçini  ve  dışını  İslâm  dîninin güzel ahlâkı ile süsledi. Hocasından icâzet (diploma) aldı. föhreti heryere yayıldı. Hocasının emriyle Sütlüce’deki dergâha yerleşip, insanları irşâda ve talebe yetiştirmeye başladı. Dergâhı, Hasîrî-zâde dergâhı diye şöhret buldu. Mustafa Izzî Efendi, hacca gitmek için yola çıktı. Mekke-i mûkerreme ve hakkıyla  yerine  getirmeye  çalıştı.  Peygamber  efendimizin  (aleyhisselâm) mübârek  kabr-i  şerîfini  ziyâret  edip  Mısır’a  geldi.  Mısır’a geldiğinde  yol parası tükenmişti. Yoluna devam edemeyip orada kaldı. Mevsim de, Ahmed Bedevî’nin ziyâreti ve mevlîd-i şerîf cemiyetlerinin yapıldığı zamana tesadüf etmişti.  Bu  sebeple  Tanta’ya  gidip,  oradaki  Ahmed  Bedevî  hazretlerinin kabr-i  şerîfini  ziyâret  etti.  O  esnada  hâlini  arzetti.  Hüzn  ile  kendinden geçmiş iken, hiç tanımadığı birisi omuzuna eliyle dokunarak; “Hasırcıoğlu Mustafa Efendi siz misiniz?” dedi. O da; “Evet efendim” diye cevap verince, o kimse, koynundan bir kese çıkardı ve; “funu al ihtiyâcın vardır. İhtiyâcın için sarfedersin. İstanbul’da karşılaşırsak alırım, yoksa helâl olsun” dedi ve kalabalık içine karışarak kayboldu, İstanbul’da da hiç görülmedi. Mustafa  Izzi  Efendi’nin  vefâtında,  zamanın  şâirlerinden  Hayreddîn Efendi tarafından söylenen şiirde özetle şöyle denmektedir: “Bütün vakitlerini insanlara ilim ve edeb öğretmekle geçirdi. Faziletiyle zamanının  büyükleri  arasına  girdi.  Kırk  sene  irşâd  makamında  bulundu. Nice    eksik    ve    noksan    kimseler    onun    feyziyle    terbiye    oldu.    Onun rûhâniyetinden  istifâde  etmek  isteyen,  onu  vesile  edip  yardım  istesin. Hulûs-i kalb ile bu ziyâretgâha gelsin. Bu sebeple ma’nevî kemâle kavuşur.”');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21286, 'MÜFTİ AHMED PAŞA', 'Bursa velîlerinden.  Hızır  beyin  üçüncü  oğlu.  Babasından  ve  devrin alimlerinden  ders  gördü.  Padişahın  da  hazır  olduğu  bir  mecliste  başarılı olarak Sahn medreselerinden birine tayin oldu. osküp Kadılığı, Edirne’de Çiftelerde  müderrislik  yaptı.  Sonra  Bursa  kadılığına  tayin  edildi.  Bursa İnebey  mahallesinde  zarif  bir  medrese  yaptırmıştır.  Uzun  süre  burada kadılık  yaptı  ve  927  (m.  1521)’de  vefat  etti.  Zeyniler  Câmii  yanına  defn', NULL, '1521', '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:32.996192', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Bursa velîlerinden.  Hızır  beyin  üçüncü  oğlu.  Babasından  ve  devrin alimlerinden  ders  gördü.  Padişahın  da  hazır  olduğu  bir  mecliste  başarılı olarak Sahn medreselerinden birine tayin oldu. osküp Kadılığı, Edirne’de Çiftelerde  müderrislik  yaptı.  Sonra  Bursa  kadılığına  tayin  edildi.  Bursa İnebey  mahallesinde  zarif  bir  medrese  yaptırmıştır.  Uzun  süre  burada kadılık  yaptı  ve  927  (m.  1521)’de  vefat  etti.  Zeyniler  Câmii  yanına  defn');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21287, 'MUSTAFA MÂNEVÎ EFENDİ', 'Anadolu’da yetişen evliyânın büyüklerinden. Karabaş Ali Efendi’nin oğlu ve  halîfesidir. Babasından  ve  başka  âlimlerden  zâhirî  ilimleri  tahsil  etti. Tasavvuf  yolunda,  babasının  yanında  kemâle  geldi.  Doğum  târihi  ve  yeri kesin olarak bilinmemektedir 1102 (m. 1690) senesi Safer avında Sokullu Mehmed Paşa dergâhına hoca olarak ta’yin edildi. Beş sene burada halkı doğru  yola  sevk  etmek  için  va’z  ve  nasîhatta  bulundu.  Sonra  Ordu-yu Hümâyûn’a ta’yin edildi. Orada da va’z ve nasîhatarına devam etti. 1114 (m. 1702)  senesinde  İstanbul’da  vefât  etti.  osküdar’daki  Nasûhî  dergâhında bulunan kabristana defnedildi. Mustafa Mânevî Efendi, ârif ve kâmil bir zât idi. Doğru sözü söylemekten asla çekinmezdi. Güzel manzûmeleri vardır. Muhyiddîn-i Arabî’nin “Füsûs” adlı eserine şerh yazdı. Müretteb bir dîvânı vardır. fiirlerinden ba’zıları: Hamd lillah, kim tulû’ etti yine fems-i duhâ, Rahmeten lil-âlemîn geldi, Muhammed Mustafâ, Gül cemâli berk urûb doğdu yine bedr-i dücâ, Rahmeten lil-âlemîn geldi, Muhammed Mustafâ. “Küntü kenzen” mahzeninden “lî me’allah” mazharî, Zât-ı pâkin enveridir, enveridir, enveri. Ma’neviyâ! İns-ü-cinni rehberidir, rehberi, Rahmeten lil-âlemîn geldi, Muhammed Mustafâ. Sabâ! Vakt-i seher ol zülfü cânâne selâm eyle, Yolun uğrarsa kuş! Arş-ı Rahmâna selâm eyle, Seherde bülbül! feydây-ı tahrik eyledim bildim, iden ol galgale feryâd-u efgâne selâm eyle. Bütün eşcâr ve evrak zikr eder Allalu her dâim, Bütün eşcâr ve evrak bağ ve bostâne selâm eyle, Nesîm-i subh eser derler seher vaktinde her dâim, Dolaşıp dağ ve sahra cümle kâinata selâm eyle. Medîne şehrine var Ravda-i pâke sürüp yüzler, Varıp, ol hâk-i pây-ı rûh-ı sultâna selâm eyle. Ebû Bekr, Ymer, Osman, Ali ile Hasen ve Hüseyn, Cenâb-ı Fâtıma ol binti cânâne selâm eyle. Süheyb-i Rûm, Ammâr İbni Yâser, Hamza ve Abbâs, Bütün ahbâb ile ervâh-ı ihvana selâm eyle. Bakî’ ehline bir bir irüşüb bütün cümle, Varıp herbirine benden fakirane selâm eyle. Azîzim Hazret-i pîrim, efendim hâkine yüz sür, Derûnî iştiyâk ile o cânâne selâm eyle. Varıp ol Kâ’betullahı ziyâret kıl, tavaf eyle, Safa ve Merve’de sa’y eyle, kurbâna selâm eyle. Erişip, İbn-i Abbâs kabrini bir hoş ziyâret kıl, Bütün Eshâba, İbn-i Ammi sultâna selâm eyle. Oradan uğra Bağdad’a sürüp ol hâke hem yüzler, Dahî ol kutb-ül-aktâba feyh Geylâne selâm eyle. Eşiğine yüzünü sür feda kıl canla başı, Ol Abdülkâdiri’nin sen Asitânine selâm eyle. Eriş Mûsâ-ı Kâzım hem eimme zümresine hep, Ferîd-ud-dehr olan ol ismi Nu’mân’a selâm eyle. Cemî-i müctehidler mâ takaddem ve mâ teehhar hep, Kubûrin kıl ziyâret ehl-i irfâne selâm eyle. Bilâd-ı ehl-i İslâmın cemisini ol devvâr, Ledünnî ehline hep, pâdişâhâne selâm eyle. Tarîk-ı Nakşibendî Hâcegân serçeşme-i aktâb, O pîr-i ekreme, o bahr-ı ummana selâm eyle. Dolaşıp rûm diyârını hep ziyâret eyle onları, Gelip fam-ı şerîfe bahr-ı Kur’ân’a selâm eyle. Bilâl ile nice Eshâb ve ehlullah makbûrdur, Dahî feyh Arabî, hem feyh Arslan’a selâm eyle. Varıp kırklar makamına husûsen hazreti Yahya, Ânın ol ravda-i pâkine ridâne selâm eyle. Demişler onda yetmişbin kadar var enbiyâ cümia, Salât eyle selâm et, cümle yeksâne selâm eyle. Cemî enbiyânın merkad-i pâkine bir bir vâr, Mübârek rûhlarına pek garîbâne selâm eyle. Umûmun merkadi ma’lûm değildir, şüphesiz hakka, Umûmun rûhu pâkine habîbâne selâm eyle. Husûsan fam içinde garga-i rahmet onlardan, Ne denlî var ise, hep ehl-i îmâne selâm eyle. Erişip Tûr-i Sînâya münevver kabr-i Mûsâ’ya, Sürüp akdâmına yüzler, kelîmâne selâm eyle. Ne küllü var ise hep enbiyâ ve evliyâ cümia. Zebur, İncîl, Tevrat ve ehl-i Kur’ân’a selâm eyle, Ve “Onlardan bir kısmını kıssa ettik” dedi ki, ol hazret-i Mevlâ, Ki Yâkûb, Yûsuf ve Dâvûd ve Süleymâne selâm eyle. Varıp ol Sahretullah’a kurandan cümle ervahı. Hem İbrâhim” evlâdı şeyh ve şübbâna selâm eyle. Makâm-ı enbiyâ ve evliyâyı hep ziyâret kıl, Hulûs-ı ışk ile her ân kerîmâne selâm eyle. Yemen şehrine var Veysî’yi ziyâret eyle canım, Karin köyündedir, ona ferâvâne selâm eyle. Odur ser çeşme-i aktâb-i âlem ârif-i billah, Yemende el mesim-i feyz-ı Rahmâne selâm eyle, Habeş iklimini devr et, Cezayir semtine uğra, Velî Dede denilen dürr-i mercâne selâm eyle. Cemî-i Rûm, Acem, Fars ve Buhârâ kalmasın devr et, Diyâr-ı fam’a gel erbâb-ı Havrân’a selâm eyle. Husûsile diyâr-ı Kerbelâ’da ışk ile devr et, Kamuya şad hezâr hakkân hazînâne selâm eyle. fehîd-i Kerbelâ’nın rûh-ı pâkinden meded iste, Mecazî olmasın vallah hakîkâne selâm evle. Dolaşıp hassaten gel Konya şehrine husûs ile, O sultân-us-selâtîn nûr-i Yezdâne selâm eyle. Habîb, Dâvûd-i Tâî, feyh Cüneyd’e Merkezi ışka, Erişip Bâyezîde, feyh Ekvâne selâm eyle. Ki Necmüddîn Kübrâ’ya varıb candan ziyâret kıl, Dolaşıp Aksaray’ı arz-ı Ken’ân’e selâm eyle. Varıp Kastamonu şehrine mahsûs-i muhabbetle, Cenâb-ı Gavs-ı a’zam pîr-i fa’bân’a selâm eyle. Ânın dergâhı âlisindeki erbâb-ı tevhide, Hulûs ile muhabbetler feridâne selâm eyle. Erişip Hacı Bektâş-ı âsitânına muhabbetle, Balım Sultan’a ol meczubu Rahmân’a selâm eyle. Husûsan Hacı Bayram Velî’ye arz-ı ta’zîm et, Huzûru evliyâda ehl-i divâne selâm eyle. Var ondan hazret-i Eşref Emîr Sultan’a yüzler sür, Dolaşıp Bursa şehrini şerîfâne selâm eyle. Mükerrem şeyh hazret-i Mısrî-i Niyazi’ye, Keremler ile billâh kerîmâne selâm eyle. Diye kim yâ hazret-i Mısrî sana yüzbin selâm olsun, Kemâl-i hasret ve ışk ile sûzâne selâm eyle. Dahî ol feyh-i oftâde huzûruna se’âdetle, Kamu hep asfiyâya ehl-i îkâna selâm eyle. Erişip osküdar’a hazret-i pîr-i feyh Hüdâî’ye, Olan ol suffe-i sadrından mihmâne selâm eyle. Yüz sür türbesine ışk ile eyle tahiyyâtı, Ol sultân-ı meşâyıhtır, halîlâne selâm eyle. Oradan Rumeli’ne geç Ebû Eyyûb-el-Ensârî, Huzûru akdesine var edîbâne selâm eyle. Alemdar-ı Resûli kibriyâdır şüphesiz hakka, fehâdet şerbetin içmiş şehîdâne selâm eyle. Sa’îd’ul-Hudrî ve Câbir, sürüp yüz türabına, Kemâl-i ışk ve şevk ile Saîdâne selâm eyle. Yatur-ı Eyyûb Nişancası’nda bir nûr-i hidâyet kim, Mükerrem feyh Nûrî, nûr-i subhâne selâm eyle, Dolaşıp şehr-i İstanbul içinde cümle sükkânı, Olan aktâb ve eşrafa hazînâne selâm eyle. Dahî ol Hacı Evhad feyh-i merhum kuddisesirruh, Hüseyn’dir ism-i pâki şeyhi pîrâne selâm eyle. Husûsan hazret-i Umm-i Sinân, nâm-ı pîr-i pür feyze, Edîb-i nükte pîrâye o sultâna selâm eyle. Varıp Sünbül Sinân Halvetî’nin dergâhına, Kemâl-i hürmet ve şevkiyle ol cana selâm eyle. Cemîan şark ile garb-ı dolaş hiç kalmasın kimse, Bütün erbâb-ı tevhîde şuyûhâne selâm eyle. Gidip Cennet sarayına görüş İdris ile onda, Bütün erbâb-ı Cennete bizi ilhak ede Allah. Keremler ile Hûrî gılmâna selâm eyle, Benim maksûdum Âlemde yegâne hazret-i Allah, İlâhî, Ma’nevî’ye sen rahîmâne selâm eyle. Bütün erbâb-ı Cennete bizi ilhak ede Allah.', NULL, '1690', '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:32.996148', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Anadolu’da yetişen evliyânın büyüklerinden. Karabaş Ali Efendi’nin oğlu ve  halîfesidir. Babasından  ve  başka  âlimlerden  zâhirî  ilimleri  tahsil  etti. Tasavvuf  yolunda,  babasının  yanında  kemâle  geldi.  Doğum  târihi  ve  yeri kesin olarak bilinmemektedir 1102 (m. 1690) senesi Safer avında Sokullu Mehmed Paşa dergâhına hoca olarak ta’yin edildi. Beş sene burada halkı doğru  yola  sevk  etmek  için  va’z  ve  nasîhatta  bulundu.  Sonra  Ordu-yu Hümâyûn’a ta’yin edildi. Orada da va’z ve nasîhatarına devam etti. 1114 (m. 1702)  senesinde  İstanbul’da  vefât  etti.  osküdar’daki  Nasûhî  dergâhında bulunan kabristana defnedildi. Mustafa Mânevî Efendi, ârif ve kâmil bir zât idi. Doğru sözü söylemekten asla çekinmezdi. Güzel manzûmeleri vardır. Muhyiddîn-i Arabî’nin “Füsûs” adlı eserine şerh yazdı. Müretteb bir dîvânı vardır. fiirlerinden ba’zıları: Hamd lillah, kim tulû’ etti