INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21517, 'DUĞLU BABA', NULL, NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.096119', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Bursa’nın fethinde bulunan velilerden. Hayatı hakkında pek bilgi yoktur. Doğum ve ölüm tarihleri bilinmemektedir. Kendisinin Sultan Osman Gazi ve Orhan  Gazi  dönemlerinde  yaşadığı  göz  önüne  alınırsa  ölüm  tarihinin  en erken  1321  tarihi  sonrasında,  en  geç  1362  öncesinde  olması  gerektiğini tahmin etmek mümkündür. Tıpkı  diğer  Rum  Ebdalları  gibi  Duğlu  Baba  da  Sultan  Orhan  Gazi  ile birlikte Bursa’nın fethine katılmıştır. Kaynaklar Duğlu Baba’nın Bursa’nın fethi  sırasında  büyük  yararlılıklar  gösterdiğinden  bahsetmektedirler. Anlatıldığına göre, savaş esnasında, çarpışmaların en hareketli olduğu bir dönemde, gaziler hararetten ve aşırı sıcaktan yorgun düştükleri bir sırada, Duğlu Baba onların yardımına koşmuş, elinde bir bakraç, süte su katarak gaziler  arasında  paylaştırmış  onların  susuzluğunu  gidermiş  ve  dualarına mazhar  olmuştur.  Asıl  adı  bilinmeyen  Duğlu  Baba’nın  adı  da  bu  olaydan sonra verilmiştir. Zira, Farsçada duğ, doğ ayran anlamına gelmektedir. Duğlu  Baba,  Bursa’nın  fethi  tamamlandıktan  sonra,  Uludağ’ın  doğuya bakan  kısmında  kuytu  bir  bölgeye  yerleşerek  burayı  iskân  etmiştir. Bölgedeki kurtlar ve kuşların dahi kendisine alıştığı rivayet edilir. Sultan  Orhan  Gazi,  komutanlarından  Turgut  Alp’in  de  delaletiyle  bu bölgeyi Duğlu Baba’ya temlik olarak bağışlamıştır. Duğlu  Baba  kurduğu  tekkesinde  hayatının  sonuna  kadar  sevenlerine İslam  dinini  anlatmaya  çalışmış,  bölgenin  iskân  edilmesini  sağlamış  ve Bursa’da vefat etmiştir. Kabri, Gök Pınar veya Gölpınar denilen yerde zirve şosesi  üzerinde  970  rakımlı  Kara  Belen  mevkiindedir.  Sultan  Orhan  Gazi tarafından kendisine bir türbe, türbenin yanına da bir cami yaptırılmıştır. Ancak cami ve tekkeden eser kalmamıştır.');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21518, 'DEVECİ SULTAN', 'Kastamonu  velilerinden.  İsmi  ve  hayatı  hakkında  bilgi  yoktur.Hangi devirde  yaşadığı  bilinmeyen  Deveci  Sultan\'ın  kabri  Kastamonu  Deveciler Mahallesinde, Deveciler Câmiinin yanındadır. Asıl isminin Yûsuf Horasânî olduğu sanılmaktadır. Türbede on bir tane daha kabir vardır. Rivayete göre Horasan’dan büyük bir kafile ile Hac niyeti ile yola çıkmış. Yolda  konakladığı  bir  yerde  Rüyasında  Resulullah  efendimizi  görmüş  ve Peygamber  efendimiz  kendisine  Kastamonu’nun  fethine  katılmasını  emr etmiş ve 7 gece üst üste bu rüyayı gördükten sonra arkadaşları ile birlikte yanlarındaki  paralarla  at  ve  deve  satın  alarak  Kastamonu’nun  fethine katılmışlardır.  Deve  satın  almalarından  dolayı  Deveci  Sultan  denilmiştir. Fetihten   sonra   Atabey   Gazi   tarafından   hazineye   bakmakla vazifelendirilmiştir. Türbesi ziyaret edilmektedir.', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.096163', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Kastamonu  velilerinden.  İsmi  ve  hayatı  hakkında  bilgi  yoktur.Hangi devirde  yaşadığı  bilinmeyen  Deveci  Sultan\'ın  kabri  Kastamonu  Deveciler Mahallesinde, Deveciler Câmiinin yanındadır. Asıl isminin Yûsuf Horasânî olduğu sanılmaktadır. Türbede on bir tane daha kabir vardır. Rivayete göre Horasan’dan büyük bir kafile ile Hac niyeti ile yola çıkmış. Yolda  konakladığı  bir  yerde  Rüyasında  Resulullah  efendimizi  görmüş  ve Peygamber  efendimiz  kendisine  Kastamonu’nun  fethine  katılmasını  emr etmiş ve 7 gece üst üste bu rüyayı gördükten sonra arkadaşları ile birlikte yanlarındaki  paralarla  at  ve  deve  satın  alarak  Kastamonu’nun  fethine katılmışlardır.  Deve  satın  almalarından  dolayı  Deveci  Sultan  denilmiştir. Fetihten   sonra   Atabey   Gazi   tarafından   hazineye   bakmakla vazifelendirilmiştir. Türbesi ziyaret edilmektedir.');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21519, 'EBDAL MURÂD', NULL, NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.096202', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Bursa  velîlerinden.  İsmi  Murâd  olup  Horasan\'da  doğdu.  Bursa\'nın fethinden  önce  Buhârâ\'dan  Bursa\'ya  gelen  hak  âşığı  adı  verilen  kırk abdaldan biridir. Doğum ve vefât târihi kesin bilinmemektedir. Bursa\'nın fethinden sonra vefât etti. Ebdâl Murâd\'ın kabri, Bursa\'nın dağ yamacında Alacahırka semtinin yukarısında, hâkim bir tepe üzerindedir. Ebdal  Murâd,  Orhan  Gâzinin  Bursa\'yı  fethinde  yanında  bulunan mücâhidlerden idi. Yanında dâimâ bir tahta kılıç bulundurur, bu nasıl kılıç deyip alay edenlere; \"Siz onun ne kadar keskin olduğunu bilmezsiniz\" derdi. Ebdal  Murâd  fetih  esnâsında  Bursa  kalesini  gözetleme  vazîfesi  yaptı. \"Hıdmet-ül-Mülûk  nısf-üs-sülûk\"  (Devlet  başkanlarına  hizmet  tarîkat yolculuğunun yarısıdır) sözü gereğince fetihde Sultan Orhan Gâziye maddî ve  mânevî  yardımlarda bulundu. Dört arşın  uzunluğundaki  tahta  kılıç ile şaşılacak  kahramanlıklar  gösterdi.  Tahta  kılıcını  kocaman  bir  kaya parçasına vurmasıyla kayayı ikiye ayırması düşmanı dehşete düşürdü. Harp  bitip  Bursa  feth  olunduktan  sonra  Ebdal  Murâd\'ın,  Keşiş  Dağı eteklerindeki  tekkesine  çekildiği  ve  Orhan  Gâzinin  tekkeye  binden  fazla bakır kapkacak verdiği rivâyet edilmektedir. Eskiden bu tekkede esnafa peştemal kuşatılır ve çeşitli eğlenceler yapılır, sonra da Ebdal Murâd\'ın türbesine gidilerek duâ edilir ve; \"Destini destime vergil  destikeremdir.  Allah  bir  dedik,  pervâne  geldik,  yönümüz  dergâha döndük.  Gün  kubbe  altında,  yeşil  seccâde  üzerinde,  erenler  meydanında, sizler huzurunda peştemal kuşanıp bir murâd almaya geldik.\" denirdi. Sonra tekbirler  getirilir.  Velîlere  rahmet  okunurdu.  Kalfalar,  çıraklar  esnâfın  en yaşlısının ve ustasının elini öperlerdi. İhtiyâr usta da; \"Allah mübârek etsin oğlum, sanatına doğru ol.\" diyerek duâ ederdi.');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21520, 'EBÛ ABDULLAH SECZÎ', NULL, NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.096249', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Evliyânın  meşhurlarından.  Dokuzuncu  asırda  (hicrî  üçüncü  asırda) yaşamıştır.  Horasan  diyârında  yetişen  velîlerdendir. Horasan\'ın  Sicistan veya  Secz  şehrindendir.  Evliyânın  büyüklerinden  Ebû  Hafs  Haddâd  ve Abdullah bin Menâzil ile görüşüp, sohbet etmiştir. Onunla görüşüp sohbet eden sofîlerden bir zât şöyle anlatmıştır: Bir defâsında Ebû Abdullah Seczî ile yol arkadaşı oldum. Trablus\'tan yola çıkıp günlerce yol aldık. Hiçbir şey yemedik, yanımızda da yiyecek bir şey yoktu.  Uzun  yolculuğumuz  sırasında  bir  gün  yol  üzerinde  bir  parça  yaş meyve kabuğu gördüm. Dayanamadım ve alıp yemek istedim. Bana öyle bir baktı ki, bu bakışından meyve kabuğunu yememe râzı olmadığını anlayıp, almaktan vazgeçtim. Sonra elimize beş dinar kadar para geçti. Yolumuz bir köye uğramıştı. Köye girince, elimize geçen parayla acaba yiyecek bir şeyler satın alır mıyız diye ümid ettim. Fakat hiçbir şey almadan yola devâm etti. Bir müddet yol aldıktan sonra bana; \"Eğer aç ve yaya yürüyoruz. Hiç bir yiyecek  almadık,  diyorsan  yakında  bir  köye  daha  ulaşırız.  O  köyde  âilesi kalabalık bir kimse var. Varınca onu buluruz. Bize hizmet eder bir şeyler yedirir.  Elimizdeki  beş  dinarı  da  ona  veririz  çocukları  için  harcar”  dedi. Nihâyet köye ulaştık. Bahsettiği kimseyi bulduk ve misâfir olduk. Bize bâzı yiyecekler ikrâm etti. Yanımızdaki beş dinarı ona hediye ettik. Ertesi gün yola  devâm  etmek  üzere  misâfir  olduğumuz  evden  ayrıldık.  Bana;  \"Sen nereye  gidiyorsun?\"  dedi.  \"Seninle  birlikte  yolculuğa  devâm  etmek istiyorum” dedim. Fakat bana; \"Ben seninle yol arkadaşı olamam. Çünkü bir parça meyve kabuğunu görünce dayanamayıp ahdi bozmaya kalkıştın” dedi. Sonra  benden  ayrılıp  gitti.  Arkasından  hayran  ve  şaşkın  bir  halde Dünyâya  ve  dünyâ  malına  aslâ  düşkünlük  göstermezdi.  Tasavvufta yüksek hallere gark olmuştu. Bir gün sevenlerinden biri; \"Bir dinar param var  onu  sana  vermek  istiyorum.  Ne  dersiniz?\"  deyince;  \"Eğer  onu bana verecek olursan senin için iyi olur. Vermezsen benim için hayır olur. Sen bilirsin.\" diye cevap verdi. \"Neden sofîler gibi hırka giymiyorsun?\" diye sorulunca; \"Hırka giymek fütüvvet  sâhibi  yiğit  kimselere  yakışır.  Fütüvvet  ehlinden  olmayan kimselerin böyle şeyler giymesi nifak alâmetidir. Fütüvvet yükünün altına girmeden,  fütüvvet  ehli  gibi  gözükmek  yakışmaz”  dedi.  \"Peki  o  halde fütüvvet nedir?\" diye sorulunca; \"Fütüvvet, kendini kusurlu, insanları mâzur görmektir. Kendini noksan, başkalarını tam görmektir. İnsanların iyisi olsun kötüsü olsun hepsine merhamet ve şefkat nazarıyla bakmaktır. Fütüvvetin en yüksek derecesi ise hiç bir zaman halk seni Hak\'tan alıkoymaması, perde olmamasıdır.\" buyurdu. Talebelerine ve dostlarına en faydalı işin sâlih kimselerle,  iyi  insanlarla görüşüp  sohbet  etmek,  arkadaşlık  kurmak  olduğunu  söylerdi.  Ahlâk  ve davranış  bakımından  sâlih,  iyi  kimselere  uymak  lâzım  olduğunu  önemle tavsiye  ederdi.  Ayrıca  velîlerin  kabirlerini  ziyâreti,  arkadaş  ve  dostlara hizmeti  tavsiye  ederdi. Kendi günahlarının tamâmen bağışlandığına kanâat getirmeyen  kimsenin herhangi  bir  günahı  sebebiyle  başkasını  kınamasını doğru  bulmazdı.  Kişinin  ise  kendi  günahlarının  tamâmen  bağışlandığını bilemeyeceğine  göre,  başkalarını  kınama  husûsunda  hiç  konuşmaması gerektiğini belirtirdi. \"Evliyânın alâmeti üçtür: Birincisi, derecesi yükseldikçe, tevâzusu, alçak gönüllülüğü artar. İkincisi,  elinde  imkân  bulunduğu  halde  dünyâya  değer vermez,  düşkün  olmaz.  oçüncüsü,  intikam  almaya  gücü  yettiği  halde merhametli ve insaflı davranarak intikam almaz.\" \"İlmini, din bilgisini doğru ve sağlam öğrenmeyenin işi, ameli doğru ve sağlam olmaz. Ameli doğru olmayanın bedeni saf ve temiz olmaz ve kalbi  temizlenmez.  Kalbi  temiz  olmayanın  da  niyeti  temiz,  doğru \"Âzâlarıyla ve kalbiyle günâh işleyip de, sâdece dili ile tövbe eden, âzâsını ve kalbini günahlardan uzak tutmayan kimse ne kötü kuldur.\"');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21521, 'EBÛ BEKR BİN ALÎ HADDÂD-İ YEMENÎ', 'Hanefî fıkh âlimidir. Yemen’de Zebîd’in bir köyü olan Abbâdiye’de doğdu. Haddâdî nisbesiyle de anılır. 800 (m. 1397] senesinde vefât etdi. Babasından  ve  Ali  bin  Nûh,  Ali  bin  Ymer  Alevî  ve  Ebû  Bekir  bin  Ali Hâmilî’den ilm öğrendi. Kendisi de Zebîd’de birçok talebe yetiştirdi. Eserleri: 1- Sirâc-ül-vehhâc, Kudûrî Muhtasarının şerhi olup üç cilddir. 2- Cevheretün-neyyire Sirâc-ül-vehhâc’ın’ın muhtasarıdır. 3- Sirâc-üz-zulâm ve bedrü’t-temâm. Hocalarından Hâmilî’nin fıkha dair Dürr-ül-mühtedî ve zuhr-ül-muktedî   adlı  manzûmesinin  şerhidir.   4- Nûr-ül-müstenîr. Necmeddin  Nesefî’nin  hilâf  konusundaki  Manzûmet-ün-Nesefiyye’sinin şerhidir  5- Keşf-üt-tenzîl  fî  tahkîk-il-mebâhis  ve’t-tekvîl  adlı  tefsiridir.  6- ferh-i Kitab-in-Nafakât. 7-ferh-i  Kayd-il-evâbid fi’l-luga. İsmâil bin İbrâhim Rebaî’nin  kasidesinin  şerhidir.  8- Rahîk-ul-mahtûm.  Fıkha  dair  Kayd-ül- evâbid adlı eserin şerhidir.', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.096283', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Hanefî fıkh âlimidir. Yemen’de Zebîd’in bir köyü olan Abbâdiye’de doğdu. Haddâdî nisbesiyle de anılır. 800 (m. 1397] senesinde vefât etdi. Babasından  ve  Ali  bin  Nûh,  Ali  bin  Ymer  Alevî  ve  Ebû  Bekir  bin  Ali Hâmilî’den ilm öğrendi. Kendisi de Zebîd’de birçok talebe yetiştirdi. Eserleri: 1- Sirâc-ül-vehhâc, Kudûrî Muhtasarının şerhi olup üç cilddir. 2- Cevheretün-neyyire Sirâc-ül-vehhâc’ın’ın muhtasarıdır. 3- Sirâc-üz-zulâm ve bedrü’t-temâm. Hocalarından Hâmilî’nin fıkha dair Dürr-ül-mühtedî ve zuhr-ül-muktedî   adlı  manzûmesinin  şerhidir.   4- Nûr-ül-müstenîr. Necmeddin  Nesefî’nin  hilâf  konusundaki  Manzûmet-ün-Nesefiyye’sinin şerhidir  5- Keşf-üt-tenzîl  fî  tahkîk-il-mebâhis  ve’t-tekvîl  adlı  tefsiridir.  6- ferh-i Kitab-in-Nafakât. 7-ferh-i  Kayd-il-evâbid fi’l-luga. İsmâil bin İbrâhim Rebaî’nin  kasidesinin  şerhidir.  8- Rahîk-ul-mahtûm.  Fıkha  dair  Kayd-ül- evâbid adlı eserin şerhidir.');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21522, 'EBÛ MUHAMMED BAĞDADÎ', 'Muvaffaku', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.096453', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Bağdâd’da yetişen din ve fen âlimlerinden. İsmi, Abdüllatîf bin Yûsuf bin Muhammed bin Ali Ebî Es’ad el-Bağdâdî’dir. Künyesi Ebû Muhammed olup, lakabı  Muvaffakuddîn’dir.  Aslen  Musullu  olan  Ebû  Muhammed,  1161  (h. 557) senesinde Bağdâd’da doğdu. Babası, zamanın hadîs ve kıraat, amcası da, fıkıh âlimlerinden idiler. Ebû Muhammed, önce Arab dili ve edebiyatını öğrenerek bu sahada söz sahibi oldu. Sonra islâm dîninin temel îtikâd ve fıkıh bilgilerini öğrenen Ebû Muhammed, tahsîlini tıb alanına yöneltti. Bu sahada derinleşip söz sahibi oldu. Tahsîl için bir çok beldelere gitti. fam, Kahire, Kudüs ve Musul’da bir çok âlimle görüşerek onlardan istifâde etti. İlimle uğraşmaktan dolayı asla boş vakti olmayan Ebû Muhammed, ya araştırma ve inceleme yapar, ya eserleri inceler veya talebe okuturdu. Geri kalan zamanda eser yazmakla meşgul olurdu. Orta boylu, ince endamlı, tatlı dilli, olan bu âlimin neşteri, sözünden daha keskin ve te’sirli idi. Derslerine ilim ve irfan âşıkları koşardı. Kudüs’te bulunduğu sırada, Mescid-i Aksâ’da halka  açık  dersler  verirdi.  Sonra  Haleb’e ve  Anadolu’ya  gitti.  Ymrünün sonlarına doğru Bağdâd’a yerleşti ve 1231 (h. 629) senesinde burada vefât Ebû Muhammed’in tıb ilmine olan en büyük hizmetlerinden biri, kendi zamânına gelinceye kadar yetişen tıb âlimlerinin, anatomide tâkib ettikleri Galen  (Calinos)  nazariyelerini  kabul  etmeyip,  yeni  metodlar  geliştirerek çığır  açmasıdır.  O  devirlerde,  Galen’in  anatomi  ile  ilgili  nazariyelerine kusursuz gözüyle bakılıyordu. Bu yüzden de birçokyanlışlıklar ve hatâlar meydana gelmişti. Bağdadî, açmış olduğu yeni anatomi çığırıyla bunlara son verdi.  Yazdığı El-İfâde  vel-îtibâr adlı  eserinde  bu  hususta  şöyle demektedir: “Bizim anatomi alanındaki araştırma, inceleme ve teshillerimiz, bizden önce söylenilenlere uymuyor. Meselâ, alt çene yekpare bir parçadan meydana gelmektedir. Biz bunu bizzat incelememizle tesbit ettik ve gördük. Görmek yâni tecrübe ve müşâhade, işitmekten daha sağlam ve güvenilir bir bilgi kaynağıdır. Galen, her ne kadar bu alanda söz sahibi bir tıb bilgini ise de, müşâhade ve tecrübelerimiz onu hatalı çıkarmaktadır.” Bağdadî,  botanik  ve  zirâat  ilimlerinde  de  mütebahhirdi.  Bu  alanda yazdığı Kitâb-ül-ifâdeti  vel-îtibâr  fil-umûr-il-müşâhedeti  vel-Havâdis- il-muâyineti bi Erdi Mısr adlı eseri çok meşhûr oldu. Bu eserinde Mısır arazisini  inceleyip,  ilmî  tasnifini  yapmış  ve  buranın  toplum  yapısını, hayvanlarını  ve  iklimini  incelemiştir.  Ayrıca  Mısır’da  yetişen  bitkiler, yapılan yiyecekler, gıdalar ve içeceklerle ilgili bilgiler vermiştir. Ebû  Muhammed  Abdüllatîf  Bağdadî’nin  eserlerinin  sayısı,  yüz  otuza ulaşmaktadır. Bunların; on üçü Arab dili ve edebiyatı, ikisi İslâm hukuku, dokuzu edebî inceleme ve tenkid, elli üçü tıb ilmi, onu zooloji, üçü tevhid ve kelâm  ilmi,  üçü  târih,  üçü  matematik  ilimleri,  ikisi  mâdenler,  yirmi  üçü muhtelif  konularla  ve  kırk  sekizi  felsefeyle  ilgilidir.  Felsefeyle  ilgili eserlerinin on dokuzu mantık, onu tabîat, sekizi ilahiyat, dokuzu da siyâsî ilimlerle ilgilidir. Eserlerinden bâzıları şunlardır: 1- Câmi-ul-kebîr: On ciltlik olan bu eser mantık  ve  ilahiyatla  ilgili  olup,  yirmi  senede  hazırlanmıştır. 2- Şerhu Erbaine  Hadisen  Tayyibeten: Hadîs ilmi ile ilgilidir. 3- Şerhu Kitâb-ul- Fusûl  li-hipokrat,   4- İhtisârû  şerh-il-Câlinûs  li  Kitâb-il-Emrâr-el- Haddeti, 5- İhtisârî kitâbu menâfi-il A’za li Calinus, 6- İhtisâru kitâb-il- Cenîn, 7- İhtisârû kitâb-el-Muna,  8- İhtisâru Kitâb-il-A’dal, 9- Kitâb fi Âlât-it  Teneffüs,  10- Makale  fi  sîgat-iz-zıddi  biz-zıddi,  11- Kitâb  fil- muzil, 12- Kitâb-ul-Kifâye fit-Teşrih: oçüncü kitapdan buraya kadar olan eserler tıb ilmi ile ilgilidir. 13- Kitâb fil-Edviyet-il-müfrede: Eczacılık ile ilgilidir. 14- Kitâbu  muhtasarı  Ahbâri  Mısır,  15- Kitâb-ul-Hikmet-il- A’lâiyye, 16- Kitâbu fin-Nihâye vel-lânihâye, 17- Kitâbu Garîb-il-hadîs, 18- Makâletun  fil-Buhrân,  19- Kitâb-ul-kıyâs,  20- Kitâb-ul-Celî  fil- Hisâb-il-Hindî,  21- Kitâb-ul-umde    fis-siyâseti,  22- Muhtasar    fi maba’det-Tabî’a: Metafizik ile ilgilidir. 23- Makâletun fiş-şiir: Edebiyat ile Ebû Muhammed Bağdadî, talebelerine ve ilim taliplerine şu güzel sözleri ile nasihat edip, yol göstermektedir. “Eğer  anlayış  ve  ilimdeki  seviyeniz  yüksek  ise,  kitaplarda  yazılanları olduğu  gibi  kabul  etmeyiniz.  Çünkü  fen  ilimleri,  dâima  yenilenmeye muhtaçtır.  Dâima  kendi  hatâlarınızı  görünüz  ve  kendinizi  itham  altında tutunuz. Kendi görüş, keşi ve nazariyelerinizi âlimlerle istişare ediniz. Daha önce  yazılan  eserlerdeki  bilgilerle  karşılaştırınız.  Sebatlı  olunuz.  Başarılı olduğunuzda, kendinizi beğenme (ucb) belâsına kapılmayınız. Çünkü, ucb olunca,  işler  zorlaşır.  Aceleci  de  olmağınız.  Her  konuya  vâkıf  olduğunu sanmak,  insanı  bir  çok  hatâlara  sürükler.  Âlimlerin  eşiğinde  ömür tüketmeyen,   ilimde   fazilete   ulaşamaz.   Yğrenmenin   zorluklarına katlanamayan, ilmin tadını alamaz. İnsan,  muhtelif  ve  değerli târih  kitaplarını  okumalı,  geçmiş  milletlerin yaşayış  ve  tecrübelerinden  istifâde  etmeli,  ibret  almalıdır,  insan  böyle yapınca, sanki şu kısacık ömründe gelip geçmiş milletleri tanımış, onların devrini idrâk etmiş gibi olur. Onların başarı ve başarısızlıklarını, iyilik ve kötülüklerini öğrenmiş, içinde yaşamış gibi olur. Gerçek  bir  hayat  düzeni  kurmak  için  Peygamber  efendimizin  ve Ashabının  hayatlarını  öğrenip,  örnek  almalıyız.  Resûlullah’ın  mübârek ahlâkını,  yaşayışını  iyi  tanımalı  ve  gücümüz  yettiğince  O’nun  sünnet-i seniyyesine  uymalıyız.  O  serverin  yaşayışını,  üstün  ahlâkını,  yemekte, içmekte, giyimde, kuşamda, uykuda ve uyanıklıktaki mübârek sünnetlerini, hastalıklarındaki   âdet-i   şerîfelerini,   tedâvî   usûllerini   ve   tavsiye buyurdukları  ilâçları,  bizzat  başvurdukları  tedâvî  usûllerini:  mübârek zevcelerine,  Eshâb-ı  kirâma  ve  düşmanlarına  karşı  davranış  ve muamelelerini iyi öğrenip, bunu tatbik edince, insan tam anlamıyla mes’ûd ve bahtiyar olur, ebedî saadete kavuşur. İlmî  çalışma  ve  araştırmalarınıza  ara  verdiğinizde;  ibâdeti,  Allahü teâlânın  zikrini  artırıp,  ibâdetlerinizi  vaktinde  yapınız.  Çalışmalarınız, ibâdetlerinizi  vaktinde  yapmağa  engel  olmasın!  Uykuya  varacağınızda Allahü  teâlâyı  tesbîh  ediniz.  Dünyâ  işlerinizde  başarılı  olup  da  sevinecek olursanız, hemen ölümü hatırlayın, dünyânın aldatıcı görünüş ve zînetlerine kapılmayınız.  ozüleceğiniz  bir  şey  olunca  da,  Allahü  teâlânın  huzuruna çıkacağınızı düşünün. Gaflete daldığınızı fark edince, hemen istiğfar edin. Her  an  ölümle  burun  buruna  olduğunuzu  unutmayın.  Araştırmalarınızın âhiretlik  olmasına  çalışın,  ilim  ve  takva  (haramlardan  ve  mekruhlardan sakınmak) sizin için âhiret azığı olmalıdır. Dünyalıklar elinizden çıkınca hiç üzülmeyin. Çünkü, onlara bulaşırsanız âlim  olamaz,  Allahü  teâlâya  ibâdet  edemezsiniz.  Servet  sahibi  olanlardan ilimde  yüksek  derecelere  kavuşanlar  pek  azdır.  Zenginlerden  ancak  ve ancak; şerefli, himmeti çok yüksek ve sağlam olanlar ilim sahibi olabilmiştir. Veya ilim tahsil ettikten sonra zengin olmuşlardır. Malaya’nîden  uzak  durunuz.  Gereği  kadar  konuşunuz.  Söz  sırası  size gelmeden  hiç  bir  zaman  konuşmayınız.  Çok  gülmekten  ve  konuşmaktan uzak durunuz. Yzlü, hikmetli söz ve nasihatleri dâima hatırınızda tutunuz. Güzel şiirleri ezberleyiniz. Bir  kimse,  hakîkî  bir  âlim  olduğunda,  her  taraftan  ona  ilgi  gösterilir. Makam ve mevkî teklif edilir. Dünyâ ona hizmetçi olur. Fakat o bunlara hiç kıymet vermez. Gözünün yaşı bol, dîni korunmuş olur, âhireti mâmur olur. Âlimler, sanki ölümsüzdür. Eserleri ve te’sirleri kıyamete kadar devam eder.  Bu da örnek hayatları, üstün ahlâk ve faziletleri ile yazdıkları eserler yoluyla olur. Eserleri kalıcı, ilimleri hep faydalıdır. Hakîkî ve büyük âlim, o muazzam ilim binasına sağlam bir tuğla ile hizmette bulunandır. Selâhaddîn-i Eyyûbî, âlimlere çok hürmet eder, sözlerini dinler, işlerinde hep onlarla istişare eylerdi. Onların sohbetine koşardı. Başarılarının sırrını burada aramak lâzımdır. O, asla kendi başına karar vermemiş, hep âlimlere danıştıktan sonra iş yapmıştır. Yatağa  girdiğinizde,  kendinizi  iyice hesaba  çekin.  Hayır  ve  iyilik işledinizse, Allahü teâlâya şükredin. Bir günah ve kusur işledinizse, tövbe istiğfar eyleyin. Bir daha aynı günah ve kusuru işlemeyin. Yarın, yapacağınız işleri  güzelce  plânlayın  ve  Allahü  teâlânın  yardımına  güvenin.  O’ndan Bir eseri okuduğunuz zaman, onun muhtevasını iyice kavrayın. Sonra o kitabı artık yok bilin. Kendinizi ondan mustağnî kılın. O artık sizin malınız olmuştur.  Kitap  kaybolsa  da  ilminiz  zayi  olmaz.  Bir  eseri  tetkik  ederken yalnız onunla meşgul olun. Başka bir şeyi araya karıştırmayın. Zamanınızı hep  ona  ayırın.  Bir  anda  iki  ilimle  meşgul  olmayın.  Bir  ilmi  hazmedince diğerine geçebilirsiniz. Konuşmalarda,   ilmî   tartışmalarda   sözleri   yanlış   anlamaktan, karşınızdakine eziyet  ve hakaret etmekten son  derece sakının. Çünkü  bu kötü  bir  huydur,  ilminizin,  sözünüzün  te’sirini,  güzelliğini  giderir. Muhabbeti azaltır. Hürmetsizlik ve saygısızlık doğurur.”');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21523, 'EBÛ MUHAMMED MEDENÎ', NULL, NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.096493', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Kafkasya’da  yetişen  ve  Yalova’da  vefat  eden  mücahid  nakşilerden. Daghestan’ın Timurhansuro eyaletinin Ghunib bölgesinde Kikunu köyünde 1835 (H. 1251) yılında doğdu. 1896 yılında ailesi ile birlikte Dağıstan’dan hicret ederek önce Bursa sonra Yalova’ya 12 kilometre uzaklıktaki Reşadiye köyüne  yerleşti.  Kikunu  köyünde  yetişti.  Burada  manevi  terbiyesini  aldı. Ahmed Suguri bu köyden geçerken köye uğradı ve “Buradan yeni doğmuş bir çocuğun nuru gözüküyor. Bu nur yerden göğe her yeri aydınlatacak. O büyük bir veli olacak” buyurdu. Ebû  Muhammed  Medenî  zamanında  Dağıstan  evliyalar  beldesi  idi.  O devirde Dağıstan’da iki büyük Nakşi büyüğü var idi. Birisi feyh Muhammed Yaragi,  diğeri  de  Seyyid  cemaleddin  Gumuki  idi.  EbûMuhammed  başta Ahmed  Suguri  olmak  üzere  bütün  bu şeylerden  tasavvuf  yolunu  aldı  ve Nakşi, Kadiri, Çeşti, Halveti, Rufai ve fazili yollarında yetişti. Bir defasında feyh Muhammed medeni Nakşi yolunda hilafet almadan önce Hacı Nuri ve Hacı Murtaza onun köyüne uğradılar ve ona, Biz Ahmed suguri  hazretlerine gidip ona intisab edeceğiz. Bizimle gelmek ister misin? Dediler. O da peki deyip birlikte Ahmed Suguri hazretlerine gittiler. Ahmed Suguri  hazretleri  onlara  nasihat  etti  ve  Ebû  Muhammed  Medenî’ye  zikr talim etti. Diğer ikisine ise hiçbir vazife vermedi. Onlara dedi ki: Bendeki olanı EbûMahammed’e verdim. Size verecek bir şey kalmadı. Siz ikiniz ondan tasavvuf bilgilerini alın. Bundan böyle benden kim tasavvuf dersi almak isterse Ebû Muhammed Medenî’ye gitsin. Ebû  Muhammed  Medenî  hazretleri  hem  maddi  hem  manevi   olarak Ruslarla cihad etti. Onun bu manevi gücünden korkan Ruslar onu Sibirya’ya sürüp öldürmek istiyorlardı. Bir  defasında  Ruslar  EbûMuhammed  hazretlerinin  bulunduğu  yeri muhasara ettiler. EbûMuhammed hazretleri bir eve girdi. Bir kadın Ruslar’a eve girdi diye haber verdi. Ancak Ruslar evin içinde hiçbir şey bulamadı. O gece kadın hastalandı ve bir iki gün içinde öldü. feyh  EbûMuhammed’i  Sibirya’ya  sürmüş  iseler  de  sonra  serbest bıraktılar.  feyh  bütün  ailesini  toplayarak  gemi  ile  Trabzon’a  geldi. Trabzon’da  karaya  çıkınca  bir  kıraathaneye  uğradı.  Burada  Sibirya’da beraber  olduğu  Muhammed Tavil  adlı  birisi  kendisini  tanıdı.  Muhammed Tavil,  Elhamdülillah  sağ  salim  kurtulmuşsunuz.  Benim  misafirimsiniz, diyerek onu evine götürdü. Bu  arada  Ebû  Muhammed  Medenî  hazretlerinin  Trabzon’a  geldiğini duyan Sultan Abdülhamid Han kendisini İstanbul’a getirmesi için bir gemi gönderdi.  Gemi  gelene  kadar  EbûMuhammed  Hazretleri  Muhammed Tavil’in evinde misafir kaldı. Muhammed Tavil her gün yastığının altında iki altın buluyordu. Durumu feyhe arz edince “Kimseye söylemediği müddetçe bu yastığın altında her gün iki altın bulacaksın” dedi. feyh EbûMuhammed İstanbul’a doğru yola çıktıktan sonra Muhammed Tavil’in hanımı yatağı temizlerken iki altın buldu. Telaşla kocasına sordu. O da unutarak durumu anlattı. Karısı da komşulara anlatınca bir daha altın Sultan Abdülhamid Han onun için İstanbul’da bir zaviye kurmak istedi ise de o kabul etmedi. Yalova tarafına gitmek istediğini söyledi. Sultan da istediği  yere  yerleşme  izni  verdi.  O  da  şimdi  medfun  bulunduğu  Yalova Reşadiye köyünü (fimdi Güneyköy) yerleşti ve burada dergah kurdu. Yegeni feyh ferefeddin de yanında idi. Burada  halkı  irşad  ettikleri  gibi  Kafkasya  ve  Sibirya’dan  gelen göçmenlere  de  yardım  ediyorlardı. Onlara  dinlerini  öğretiyorlardı. Kafkasyalılar için burası ikinci bir vatan olmuştu. Orman köyü olan bu köy kısa zamanda gelişmiş iki cami, bir okul ve 700 at yetiştiren bir yer olmuştu. Okulda 6 dershane vardı. Reşadiye köyünün maddi ve manevi rehberi olan Ebû Muhammed Medenî 1913 (H.1331)’de vefat etti. Aynı köye defn edildi. Yerine feyh ferefeddin geçti.');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21524, 'EBÛ NASR-I AKTA', 'Ahmed  bin  Muhammed,  fıkh  âlimidir. Kudûrî’den  fıkıh  öğrendi ve  el- Muhtasar’ını  şerhetti. 474  (m.  1082]  senesinde İsfehânda,  Ram  Hürmüz şehrinde vefât etdi. Ebû Nasr Akta “rahmetullahi aleyh” (Kudûrî) şerhinde diyor ki, (Bir suya, temiz şeyler karışsa, su ismi değişmedikçe, rengi dönse bile, onunla abdest', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.096531', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Ahmed  bin  Muhammed,  fıkh  âlimidir. Kudûrî’den  fıkıh  öğrendi ve  el- Muhtasar’ını  şerhetti. 474  (m.  1082]  senesinde İsfehânda,  Ram  Hürmüz şehrinde vefât etdi. Ebû Nasr Akta “rahmetullahi aleyh” (Kudûrî) şerhinde diyor ki, (Bir suya, temiz şeyler karışsa, su ismi değişmedikçe, rengi dönse bile, onunla abdest');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21525, 'EBÛ SEVR', 'İbrâhîm bin Hâlid Kelebîdir. Büyük hadis âlimi. Müctehidlerden, büyük âlimlerdendir. fâfi’î  mezhebindendir. Nesebi,  Ebû  Abdullah  İbrâhîm  bin Hâlid bin Ebi\'l-Yemân Kelbî el-Bağdâdî’dir. Bağdâdda tevellüd ve 246 (m. 860] da vefât etdi. Fıkh, hadîs, usûl ve hilâf ilimlerinde çok kitâb yazmışdır. Süfyân b. Uyeyne, Vekî\' bin Cerrâh, Abdurrahman bin Mehdî gibi meşhur hadis âlimlerinden hadis dinlemiş; Müslim, Ebû Dâvûd, Tirmizî, İbni Mâce, Ebû Hâtim eRâzî gibi birçok meşhur muhaddisler de kendisinden rivayette Fıkıh ilmini önceleri Muhammed bin Hasan feybânî\'den, fâfiî Bağdat\'a geldikten sonra da ondan öğrendi. fâfiî\'nin önde gelen talebelerindendir. Ahmed bin Yahyâ Bağdâdî ve Ca\'fer bin Muhammed Hayyât talebelerinin meşhurlarındandır.', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.096563', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'İbrâhîm bin Hâlid Kelebîdir. Büyük hadis âlimi. Müctehidlerden, büyük âlimlerdendir. fâfi’î  mezhebindendir. Nesebi,  Ebû  Abdullah  İbrâhîm  bin Hâlid bin Ebi\'l-Yemân Kelbî el-Bağdâdî’dir. Bağdâdda tevellüd ve 246 (m. 860] da vefât etdi. Fıkh, hadîs, usûl ve hilâf ilimlerinde çok kitâb yazmışdır. Süfyân b. Uyeyne, Vekî\' bin Cerrâh, Abdurrahman bin Mehdî gibi meşhur hadis âlimlerinden hadis dinlemiş; Müslim, Ebû Dâvûd, Tirmizî, İbni Mâce, Ebû Hâtim eRâzî gibi birçok meşhur muhaddisler de kendisinden rivayette Fıkıh ilmini önceleri Muhammed bin Hasan feybânî\'den, fâfiî Bağdat\'a geldikten sonra da ondan öğrendi. fâfiî\'nin önde gelen talebelerindendir. Ahmed bin Yahyâ Bağdâdî ve Ca\'fer bin Muhammed Hayyât talebelerinin meşhurlarındandır.');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21526, 'EBÛ ŞEKÛR SÜLEMÎ', 'Ebû  fekûr  Muhammed  Ebû  Bekr  Sülemî,  Hanefî  kelâm  âlimidir. Muhammed  bin  Abdüsseyyid  bin fu’ayb  Keşî  olup (Temhîd  fî  beyân-it- tevhîd) kitâbının sâhibidir. Nesefî’nin Temhîd’i başkadır. Ebû fekûr  Muhammed  Sülemî  diyor  ki,  hazret-i  Mu’âviye’nin,  hazret-i Emîr  ile  muhârebesi,  hilâfet  için  idi.  Çünki,  Peygamber  “aleyhissalâtü vesselâm” ona, “İnsanların başına geçdiğin zemân, onlara yumuşak davran!” buyurmuşdu.  Bunu  işitdiği  günden  beri,  içinde  hilâfet  arzûsu  uyanmışdı. Fekat ictihâdında hatâ etmişdi. Hazret-i Emîr’in “radıyallahü anh” ictihâdı doğru idi. Çünki, onun hilâfeti zemânı, hazret-i Emîrin “radıyallahü anhümâ” hilâfetinden  sonra  idi.  Bundan  anlaşılıyor  ki,  karışıklığın  başlamasına, kısâsın  gecikmesi  sebeb  oldu.  Kısâs  yapılmayınca,  halîfe  olmak  fikri  de, ortaya  çıkdı.  Her  ne  olursa  olsun,  ictihâd  yeri  idi.  Hatâ  eden  bir  derece, doğru  olan  iki  derece  sevâb  kazandı.  Bu  işde,  bize  düşen  en  iyi  yol, Peygamber efendimizin “sallallahü aleyhi ve sellem” Eshâbının “radıyallahü anhüm”   kavgalarına   karışmamakdır.   Bunları   konuşmamalıyız. Peygamberimiz  “sallallahü  aleyhi  ve  sellem”  buyuruyor  ki,  “Eshâbım “rıdvânullahi  aleyhim  ecma’în”  arasında  olan  işlere  karışmayınız!”  Yine buyurdu ki, “Eshâbım “aleyhimürrıdvân” konuşulurken dilinizi tutunuz!) ve bir hadîs-i şerîfde, (Eshâbım için, Allahü teâlâdan korkunuz! Eshâbıma dil uzatmayınız!” buyurdu.', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.096586', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Ebû  fekûr  Muhammed  Ebû  Bekr  Sülemî,  Hanefî  kelâm  âlimidir. Muhammed  bin  Abdüsseyyid  bin fu’ayb  Keşî  olup (Temhîd  fî  beyân-it- tevhîd) kitâbının sâhibidir. Nesefî’nin Temhîd’i başkadır. Ebû fekûr  Muhammed  Sülemî  diyor  ki,  hazret-i  Mu’âviye’nin,  hazret-i Emîr  ile  muhârebesi,  hilâfet  için  idi.  Çünki,  Peygamber  “aleyhissalâtü vesselâm” ona, “İnsanların başına geçdiğin zemân, onlara yumuşak davran!” buyurmuşdu.  Bunu  işitdiği  günden  beri,  içinde  hilâfet  arzûsu  uyanmışdı. Fekat ictihâdında hatâ etmişdi. Hazret-i Emîr’in “radıyallahü anh” ictihâdı doğru idi. Çünki, onun hilâfeti zemânı, hazret-i Emîrin “radıyallahü anhümâ” hilâfetinden  sonra  idi.  Bundan  anlaşılıyor  ki,  karışıklığın  başlamasına, kısâsın  gecikmesi  sebeb  oldu.  Kısâs  yapılmayınca,  halîfe  olmak  fikri  de, ortaya  çıkdı.  Her  ne  olursa  olsun,  ictihâd  yeri  idi.  Hatâ  eden  bir  derece, doğru  olan  iki  derece  sevâb  kazandı.  Bu  işde,  bize  düşen  en  iyi  yol, Peygamber efendimizin “sallallahü aleyhi ve sellem” Eshâbının “radıyallahü anhüm”   kavgalarına   karışmamakdır.   Bunları   konuşmamalıyız. Peygamberimiz  “sallallahü  aleyhi  ve  sellem”  buyuruyor  ki,  “Eshâbım “rıdvânullahi  aleyhim  ecma’în”  arasında  olan  işlere  karışmayınız!”  Yine buyurdu ki, “Eshâbım “aleyhimürrıdvân” konuşulurken dilinizi tutunuz!) ve bir hadîs-i şerîfde, (Eshâbım için, Allahü teâlâdan korkunuz! Eshâbıma dil uzatmayınız!” buyurdu.');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21527, 'EBÜL HASEN ALİ BİN AHMED', 'Hakkari  alim  ve  velilerinden.  1018  (H.  409)yılında  Hakkari’de  doğdu. Emevi sülalesindendir. İlim tahsili için çeşitli yerler dolaşmıştır. İbni Nazif Ferra’dan ve Ebül Kasım bin Beşran’dan ilim okudu. Bir çok alim yetiştirdi. Sonra memleketine döndü. Bir müddet uzlete çekilerek ibadet ile meşgul oldu.  Halk  arasında  bazıları  kendisine  feyhulislam  dediler.  Nitekim kendisine  “feyhulislamsınız”  denilince,  “Bilakis  şeyhun  fil  İslamım  yani Müslüman olarak ihtiyarladım” demiştir. Soyundan gelenler arasında devlet adamları  katında  makbul  kimseler  yetişmiştir.  1093  (H.  486)  yılında memleketinde vefat etti. Çok abid ve iyilik yapan bir zat idi.', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.097979', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Hakkari  alim  ve  velilerinden.  1018  (H.  409)yılında  Hakkari’de  doğdu. Emevi sülalesindendir. İlim tahsili için çeşitli yerler dolaşmıştır. İbni Nazif Ferra’dan ve Ebül Kasım bin Beşran’dan ilim okudu. Bir çok alim yetiştirdi. Sonra memleketine döndü. Bir müddet uzlete çekilerek ibadet ile meşgul oldu.  Halk  arasında  bazıları  kendisine  feyhulislam  dediler.  Nitekim kendisine  “feyhulislamsınız”  denilince,  “Bilakis  şeyhun  fil  İslamım  yani Müslüman olarak ihtiyarladım” demiştir. Soyundan gelenler arasında devlet adamları  katında  makbul  kimseler  yetişmiştir.  1093  (H.  486)  yılında memleketinde vefat etti. Çok abid ve iyilik yapan bir zat idi.');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21528, 'EBÜ\'L-HASAN BA\'KÛBÎ', 'Evliyâdan. İsmi, Ali bin İdrîs Ba\'kûbî\'dir. Çok kerâmetleri görüldü. Bağdât civârında  yaşadı.  Doğum  ve  vefât  târihleri  bilinmemektedir.  Kerâmetleri Kendisi anlatır:  \"Allahü  teâlâ  bana  kâinâtın  bütün  sırlarını  bildirdi.\" Sonra  yine;  \"Cennetlik  ve  cehennemlik  olanları,  kabirdekilerin  hallerini bilirim.\" buyurdu. Muzaffer  bin  Mühezzeb  anlatır:  \"Bir  gün  Ebü\'l-Hasan   hazretlerinin dergâhına giderek zulmü herkese dokunan birini şikâyet etmek istedim. oç gün kadar o dergâhta kaldım. Ebü\'l-Hasan hazretlerinin heybetinden dolayı bir türlü bu şikâyeti dile getirmeye kâdir olamadım. Dördüncü gün Ebü\'l- Hasan  hazretleri  bir  bahçede  talebeleri  ile  akşam  namazını  kıldılar. Namazdan  sonra  orada  bir  ok  ve  bir  yay  gördüler;  \"Yayı  ve  oku  bana veriniz.\" buyurdu. Oradakiler ok ve yayı hemen verdiler. Ebü\'l-Hasan  oku yaya yerleştirip bana doğru döndüler ve; \"Atayım mı?\" buyurdular. \"Ben de; \"Siz bilirsiniz” dedim. O, bu cevâbımdan sonra oku attı. Ok bir ağacın dibine saplandı. O zaman Ebü\'l-Hasan hazretleri; \"Ey Muzaffer! Doğrusu istediğine kavuştun. O zâlim cezâsını gördü.\" buyurdu. Ben buna hayret edip; \"Allahü ekber.\"  diye  tekbir  getirdim.  Oradakiler  de  tekbir  söylediler.  O  gecenin sabahı  olduğunda  bana;  \"O  zâlim  kişi  akşam  namazı  sonrasında  evinin damında  yatarken  nereden  geldiği  bilinmeyen  bir  ok  ile  öldü.\"  haberi Ebü\'l-Hasan   hazretlerinin   ziyâretine   gelenler   pekçoktu.Bunların sayısının yedi bine ulaştığı bildirilmiştir.', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.098020', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Evliyâdan. İsmi, Ali bin İdrîs Ba\'kûbî\'dir. Çok kerâmetleri görüldü. Bağdât civârında  yaşadı.  Doğum  ve  vefât  târihleri  bilinmemektedir.  Kerâmetleri Kendisi anlatır:  \"Allahü  teâlâ  bana  kâinâtın  bütün  sırlarını  bildirdi.\" Sonra  yine;  \"Cennetlik  ve  cehennemlik  olanları,  kabirdekilerin  hallerini bilirim.\" buyurdu. Muzaffer  bin  Mühezzeb  anlatır:  \"Bir  gün  Ebü\'l-Hasan   hazretlerinin dergâhına giderek zulmü herkese dokunan birini şikâyet etmek istedim. oç gün kadar o dergâhta kaldım. Ebü\'l-Hasan hazretlerinin heybetinden dolayı bir türlü bu şikâyeti dile getirmeye kâdir olamadım. Dördüncü gün Ebü\'l- Hasan  hazretleri  bir  bahçede  talebeleri  ile  akşam  namazını  kıldılar. Namazdan  sonra  orada  bir  ok  ve  bir  yay  gördüler;  \"Yayı  ve  oku  bana veriniz.\" buyurdu. Oradakiler ok ve yayı hemen verdiler. Ebü\'l-Hasan  oku yaya yerleştirip bana doğru döndüler ve; \"Atayım mı?\" buyurdular. \"Ben de; \"Siz bilirsiniz” dedim. O, bu cevâbımdan sonra oku attı. Ok bir ağacın dibine saplandı. O zaman Ebü\'l-Hasan hazretleri; \"Ey Muzaffer! Doğrusu istediğine kavuştun. O zâlim cezâsını gördü.\" buyurdu. Ben buna hayret edip; \"Allahü ekber.\"  diye  tekbir  getirdim.  Oradakiler  de  tekbir  söylediler.  O  gecenin sabahı  olduğunda  bana;  \"O  zâlim  kişi  akşam  namazı  sonrasında  evinin damında  yatarken  nereden  geldiği  bilinmeyen  bir  ok  ile  öldü.\"  haberi Ebü\'l-Hasan   hazretlerinin   ziyâretine   gelenler   pekçoktu.Bunların sayısının yedi bine ulaştığı bildirilmiştir.');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21529, 'EBÜL-KÂSIM-I SEMERKANDÎ', 'Muhammed  bin  Yûsüf,  Hanefî  fıkh  âlimlerindendir.  556  (m.  1161] senesinde  vefât  etdi.  (Câmi’ul-fetâvâ)  kitâbı  meşhûrdur.  Buna  (Câmi’ul kebîr) de denir. (Mültekıt) ve başka kitâbları da vardır. (Rıyâdun-nâsıhîn)de,  nemâzın  ehemmiyyetini  anlatırken  diyor  ki, (İmâm-ı Nâsır-üddîn Seyyid Ebül-Kâsım Semerkandî diyor ki, “Sünnetime sarılana  yüz  şehîd  sevâbı  vardır”  hadîs-i  şerîfi,  ümmetim  arasında  fesâd çıkdığı zemân, Ehl-i sünnet ve cemâ’at i’tikâdında olup, beş vakit nemâzı cemâ’at ile kılana yüz şehîd sevâbı verilir demekdir”buyurmakdadır. Bunun için, önce ehl-i sünnete uygun îmân etmek, sonra harâmlardan sakınmak, sonra  farzları  yapmak,  sonra  mekrûhlardan  sakınmak,  sonra  müekked sünnetleri, daha sonra da müstehabları yapmak lâzımdır.', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.098051', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Muhammed  bin  Yûsüf,  Hanefî  fıkh  âlimlerindendir.  556  (m.  1161] senesinde  vefât  etdi.  (Câmi’ul-fetâvâ)  kitâbı  meşhûrdur.  Buna  (Câmi’ul kebîr) de denir. (Mültekıt) ve başka kitâbları da vardır. (Rıyâdun-nâsıhîn)de,  nemâzın  ehemmiyyetini  anlatırken  diyor  ki, (İmâm-ı Nâsır-üddîn Seyyid Ebül-Kâsım Semerkandî diyor ki, “Sünnetime sarılana  yüz  şehîd  sevâbı  vardır”  hadîs-i  şerîfi,  ümmetim  arasında  fesâd çıkdığı zemân, Ehl-i sünnet ve cemâ’at i’tikâdında olup, beş vakit nemâzı cemâ’at ile kılana yüz şehîd sevâbı verilir demekdir”buyurmakdadır. Bunun için, önce ehl-i sünnete uygun îmân etmek, sonra harâmlardan sakınmak, sonra  farzları  yapmak,  sonra  mekrûhlardan  sakınmak,  sonra  müekked sünnetleri, daha sonra da müstehabları yapmak lâzımdır.');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21530, 'EDHEM ÇELEBÎ', 'Tokat\'ta  yetişen  velîlerden.  1301  yılında  Tokat\'ta  doğdu.  Babası Muînüddîn  Halil  Efendi,  annesi  ommü  gülsüm  Hâtundur.  Küçük  yaştan îtibâren dayısı olan büyük velî Acepşir hazretlerinden ders almaya başladı. Ondan aldığı ilim ve feyzlerle kemâle erdi. Zile\'ye gitti. Bâyezîd-i Bistâmî Câmiinde  insanlara  İslâmiyeti  anlatıp  onların  doğru  yola,  din  ve  dünyâ saâdetine  kavuşmaları  için  çalıştı.  Birçok  talebe  yetiştirdi.  Otuz  beş yaşlarında iken Artovalı Seyyid Ymer\'in kızı ile evlendi. Bu hanımından olan oğlu Abdurrahmân Efendi de ilim ve ihlâsı ile tanınan büyük bir velî oldu. Uzun müddet taliblerine ders verip kıymetli talebeler yetiştiren Edhem Çelebi 1350\'de vefât etti. Kabri, Zile\'de Mûsâ Fakîh türbesindedir. (Resimde Edhem  Çelebi\'nin  ilmiye silsilesi  ise  şöyledir:  Edhem  Çelebi,  Acepşir, Osman-ı Rûmî, Aliyyül-Mücerrât, Mûsâ Fakîh, Mustafa Safiyüddîn Bistâmî, Necîbüddîn  Osman  Bistâmî,  Mehmed  Bistâmî,  Bâyezîd-i  Bistâmî,  İmâm-ı Câfer-i  Sâdık,  İmâm-ı  Muhammed  Bâkır,  İmâm-ı  Zeynel  Âbîdin,  İmâm-ı Hüseyin,  İmâm-ı  Aliyyül-Mürtezâ,  Peygamber  efendimiz  Muhammed Mustafâ (sallallahü aleyhi ve sellem).', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.098083', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Tokat\'ta  yetişen  velîlerden.  1301  yılında  Tokat\'ta  doğdu.  Babası Muînüddîn  Halil  Efendi,  annesi  ommü  gülsüm  Hâtundur.  Küçük  yaştan îtibâren dayısı olan büyük velî Acepşir hazretlerinden ders almaya başladı. Ondan aldığı ilim ve feyzlerle kemâle erdi. Zile\'ye gitti. Bâyezîd-i Bistâmî Câmiinde  insanlara  İslâmiyeti  anlatıp  onların  doğru  yola,  din  ve  dünyâ saâdetine  kavuşmaları  için  çalıştı.  Birçok  talebe  yetiştirdi.  Otuz  beş yaşlarında iken Artovalı Seyyid Ymer\'in kızı ile evlendi. Bu hanımından olan oğlu Abdurrahmân Efendi de ilim ve ihlâsı ile tanınan büyük bir velî oldu. Uzun müddet taliblerine ders verip kıymetli talebeler yetiştiren Edhem Çelebi 1350\'de vefât etti. Kabri, Zile\'de Mûsâ Fakîh türbesindedir. (Resimde Edhem  Çelebi\'nin  ilmiye silsilesi  ise  şöyledir:  Edhem  Çelebi,  Acepşir, Osman-ı Rûmî, Aliyyül-Mücerrât, Mûsâ Fakîh, Mustafa Safiyüddîn Bistâmî, Necîbüddîn  Osman  Bistâmî,  Mehmed  Bistâmî,  Bâyezîd-i  Bistâmî,  İmâm-ı Câfer-i  Sâdık,  İmâm-ı  Muhammed  Bâkır,  İmâm-ı  Zeynel  Âbîdin,  İmâm-ı Hüseyin,  İmâm-ı  Aliyyül-Mürtezâ,  Peygamber  efendimiz  Muhammed Mustafâ (sallallahü aleyhi ve sellem).');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21531, 'EMİN EFENDİ', 'Bitlis velilerinden. 1830 yılında Bitlis iline bağlı firvan Kazasının Nivin (Tatlıpayam)  köyünde  doğdu.  Baba  ve  dedeleri  hep  kadı  olarak  vazife yapmışlardır. feyh Emin Efendi civar medreselerde ilim okuyup icazet almış ve Nivin’e kadı tayin edilmiştir. O sıralarda Bitlis il merkezine yerleşen feyh Muhammed Küfrevi hazretlerinin, beni yalnız bırakma, buraya gel, demesi üzerine  görevinden  ayrılarak  Bitlis’e  gelip  yerleşti.  feyh  Küfrevi’nin  sağ kolu oldu. Nitekim feyh Küfrevi sen benim sağ kolumsun demiştir. 1890 yılında dedelerinden kalma dağınık arazilerin tamamının tapusunu bulmak için İstanbul’a geldi ve üç yıl kaldı. Bu süre zarfında Fatih kütüphanesine devam  etti.  Bir  gün  Kütüphanede  kitap  mütalaa  ederken  Darulfünun hocalarından iki kişinin bir kelime üzerinde konuşmalarını istemeden işitti. Aflarına sığınarak kelimeyi yanlış okuduklarını söyledi ve doğrusunu okudu. Kelime yanlış okunursa elbette mana yanlış olur dedi. İki Müderris onun okuduğunun doğru olduğunu ve meselenin anlaşıldığını belirterek teşekkür İstanbul’da iken Sultan Abdülhamid Hanla da görüşmüş ve büyük hürmet görmüştür.  Yıllarca  halkın  meselelerini  çözmüş  ve  insanlara  doğru  yolu göstermiştir.  1908  yılında  vefat  etmiştir.  Kabri  Bitlis’de  Küfrevi', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.098180', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Bitlis velilerinden. 1830 yılında Bitlis iline bağlı firvan Kazasının Nivin (Tatlıpayam)  köyünde  doğdu.  Baba  ve  dedeleri  hep  kadı  olarak  vazife yapmışlardır. feyh Emin Efendi civar medreselerde ilim okuyup icazet almış ve Nivin’e kadı tayin edilmiştir. O sıralarda Bitlis il merkezine yerleşen feyh Muhammed Küfrevi hazretlerinin, beni yalnız bırakma, buraya gel, demesi üzerine  görevinden  ayrılarak  Bitlis’e  gelip  yerleşti.  feyh  Küfrevi’nin  sağ kolu oldu. Nitekim feyh Küfrevi sen benim sağ kolumsun demiştir. 1890 yılında dedelerinden kalma dağınık arazilerin tamamının tapusunu bulmak için İstanbul’a geldi ve üç yıl kaldı. Bu süre zarfında Fatih kütüphanesine devam  etti.  Bir  gün  Kütüphanede  kitap  mütalaa  ederken  Darulfünun hocalarından iki kişinin bir kelime üzerinde konuşmalarını istemeden işitti. Aflarına sığınarak kelimeyi yanlış okuduklarını söyledi ve doğrusunu okudu. Kelime yanlış okunursa elbette mana yanlış olur dedi. İki Müderris onun okuduğunun doğru olduğunu ve meselenin anlaşıldığını belirterek teşekkür İstanbul’da iken Sultan Abdülhamid Hanla da görüşmüş ve büyük hürmet görmüştür.  Yıllarca  halkın  meselelerini  çözmüş  ve  insanlara  doğru  yolu göstermiştir.  1908  yılında  vefat  etmiştir.  Kabri  Bitlis’de  Küfrevi');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21532, 'EMİR ARİF EFENDİ', 'Sivas\'ın  meçhul  velilerinden.  Hayatı  ve  yaşadığı  dönem hakkında  bilgi yoktur.  Rivayete  göre  İstanbul\'un fethi  için  Anadolu\'ya  gelen  İslam ordusuna katılmış ve Sivas\'ta şehit düşmüştür. Diğer  bir  rivayette  ise  13. yüzyılda yaşayan Ahi Emir Ahmed ile kardeştir. Türbesi, Sivas ili merkez Pulur   Mahallesinde   bir  tepe  üzerindedir.  Sarılığa  yakalanan   hastalar tarafından ziyaret edilmektedir. Bunun için Sarılık Baba diye de tanınır. Halk  arasında  anlatıldığına  göre  Emir  Arif  hazretlerinin  türbesi içerisinde mezarın başına gelen herkes için sepet içerisinde sıcak çörekler bulunur  ziyaretçilere  ikram  edilirmiş.  Bir  gün  sarılık  hastası  bir  kadın türbeyi  ziyarete   gelmiş.  Kadın  hastalığından  dolayı  üç  gün  gelmesi gerektiğinden her gelişinde bu çöreklerden ikram edilmiş. Kadın çöreklerin sıcak  olmasına  şaşırmış  ve  türbedara,  \"Hergün  bu  çörekleri  nasıl hazırlıyorsunuz,  bunca  insana  nasıl  yetiştiriyorsunuz?\"  diye  sormuş. Türbedar  da  saklaması  gerektiği  halde,  \"Bu  çörekleri  biz  hazırlamıyoruz. Her gün mezarın başında buluyoruz\" demiş. Bir daha mezarın başında çörek bulunmamış.  Ondan  sonra  gelenler  çörekleri  kendileri  hazırlayarak gelenlere   ikram  etmeye  başlamışlar..  Çörek  dağıtma  adeti  de  oradan', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.098213', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Sivas\'ın  meçhul  velilerinden.  Hayatı  ve  yaşadığı  dönem hakkında  bilgi yoktur.  Rivayete  göre  İstanbul\'un fethi  için  Anadolu\'ya  gelen  İslam ordusuna katılmış ve Sivas\'ta şehit düşmüştür. Diğer  bir  rivayette  ise  13. yüzyılda yaşayan Ahi Emir Ahmed ile kardeştir. Türbesi, Sivas ili merkez Pulur   Mahallesinde   bir  tepe  üzerindedir.  Sarılığa  yakalanan   hastalar tarafından ziyaret edilmektedir. Bunun için Sarılık Baba diye de tanınır. Halk  arasında  anlatıldığına  göre  Emir  Arif  hazretlerinin  türbesi içerisinde mezarın başına gelen herkes için sepet içerisinde sıcak çörekler bulunur  ziyaretçilere  ikram  edilirmiş.  Bir  gün  sarılık  hastası  bir  kadın türbeyi  ziyarete   gelmiş.  Kadın  hastalığından  dolayı  üç  gün  gelmesi gerektiğinden her gelişinde bu çöreklerden ikram edilmiş. Kadın çöreklerin sıcak  olmasına  şaşırmış  ve  türbedara,  \"Hergün  bu  çörekleri  nasıl hazırlıyorsunuz,  bunca  insana  nasıl  yetiştiriyorsunuz?\"  diye  sormuş. Türbedar  da  saklaması  gerektiği  halde,  \"Bu  çörekleri  biz  hazırlamıyoruz. Her gün mezarın başında buluyoruz\" demiş. Bir daha mezarın başında çörek bulunmamış.  Ondan  sonra  gelenler  çörekleri  kendileri  hazırlayarak gelenlere   ikram  etmeye  başlamışlar..  Çörek  dağıtma  adeti  de  oradan');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21533, 'EMÂNULLAH LÂHORÎ', 'Hindistan’da yetişen âlimlerin ve velîlerin büyüklerinden. İsmi, Mevlânâ Emânullah,  nisbeti,  Lâhorî’dir.  Doğum  ve  vefât  târihleri  belli  değildir. Onbirinci asrın ortalarında vefât etmiş olduğu bilinmektedir. İmâm-ı  Rabbânî  hazretlerinin  huzûr  ve  sohbetlerinde  kemâle  gelen Emânullah  Lâhorî,  icâzet  almakla  ve  o  yüce  İmâmın    talebelerinin büyüklerinden  olmakla  şereflendi.  ostün  hâller,  kerâmetler  ve  yüksek dereceler  sahibi  idi.  Hocası  İmâm-ı  Rabbânî  hazretlerinin,  rûhlara  hayat veren teveccüh ve himmetleriyle yetişerek, evliyâlık yolunda çok ilerlemiş idi. Kendisi de bu yolda çok talebe yetiştirdi. İmâm-ı  Rabbânî  Müceddîd-i  elf-i  sânî  hazretleri  bu  yüksek  talebesine yazdığı mektûblardan birinde buyurdu ki: “Bismillâhirrahmânirrahîm. Allahü teâlâ, sana doğru yolu göstersin! iyi bil  ki,  Allah  yolunda  bulunmak  isteyene,  önce  lâzım  olan  şey,  i’tikâdını düzeltmektir. Doğru i’tikâd; Ehl-i sünnet âlimlerinin Kur’ân-ı kerîmden ve hadîs-i şerîflerden ve Eshâb-ı Kirâmdan öğrendikleri, anladıkları i’tikâddır. Kur’ân-ı kerîmin ve hadîs-i şerîflerin ma’nâsını doğru anlıyan, doğru yolun âlimleridir. Bunlar da, Ehl-i sünnet ve cemâat âlimleridir. Bunların anladığı, bildirdiği  ma’nâlara  uymayan  herşeye;  akla,  fikre,  hayâle  iyi  gelse  de  ve tasavvuf yolunda keşf ve ilham ile anlaşılsa da, hiç kıymet verilmemelidir. Bu büyüklerin anladığına uymıyan bilgilerden, buluşlardan Allahü teâlâya sığınmalıdır. Demek ki, tasavvuf yolcularının keşflerinin, buluşlarının doğru olup  olmadıkları,  Ehl-i  sünnet  âlimlerinin  bildirdikleri  doğru  ma’nâlara uygun  olup  olmamaları  ile  anlaşılır.  Bu  yolculara  ilham  olunan bilgilerin doğruluğu, ancak, o doğru ma’nâlara uymaları ile belli olur. Çünkü onların bildirdiği ma’nâlara uymıyan her ma’nâ, her buluş kıymetsizdir, yanlıştır. Çünkü  her  sapık  her  bozuk  kimse,  Kur’ân-ı  kerîme  ve  hadîs-i  şerîflere uyduğunu sanır ve iddia eder. Yarım aklı ve kısa görüşü ile, bu kaynaklardan yanlış ma’nâlar çıkarır. Doğru yoldan kayar, felâkete gider. Ehl-i  sünnet  âlimlerinin  anladıkları  ma’nâlar  doğrudur,  kıymetlidir. Bunlara uymıyanlar kıymetsizdir. Çünkü bu ma’nâları, Eshâb-ı Kirâmın ve Selef-i  sâlihînin  eserlerini  inceliyerek  elde  etmişlerdir.  O  hidâyet yıldızlarının ışıkları ile parlamışlardır. Bunun için, ebedî kurtuluş bunlara mahsûs  oldu.  Sonsuz  saadete  bunlar  kavuşdu.  Allah  yolunda  giden  kâfile bunlar oldu. Kurtuluş, ancak Allah yolunda bulunanlar içindir. İ’tikâdı  bunlara  uygun  olan  din  âlimlerinden  biri,  fer’ıyyâtta,  ya’nî, İslâmiyete  yapışmakta  gevşek  davranırsa,  kusurlu  olursa,  buna  bakarak, bütün  âlimleri  kötülemek  yersiz  olur.  İnâdcılık  olur.  Onların  doğru bilgilerini  inkâr  etmek,  kötülemek  olur.  Çünkü,  doğru  bilgileri  bizlere ulaştıran  onlardır.  Kurtuluş  yolunu,  bozuklarından,  sapıklarından  ayıran onlardır. Onların hidâyet ışıkları olmasaydı bizler doğru yolu bulamazdık. Doğruyu  bozuk  olanlardan  ayırmasalardı,  bizler,  taşkınlık ve  azgınlık uçurumlarına  düşerdik,  İslâmıyeti  bozulmaktan  koruyan  her  yere  yayan, onların çalışmasıdır, İnsanları kurtuluş yoluna kavuşturan onlardır. Onlara uyan kurtulur, saadete kavuşur. Onların yolundan ayrılan, sapıtır, herkesi Tasavvuf   yolcusunun,  işin  iç  yüzüne  varmadan  önce,  kendi  keşf  ve ilhamına uymasa da, Ehl-i sünnet âlimlerine tâbi olması lâzımdır. Âlimleri haklı  ve  doğru  bilip,  kendini  yanlış  bilmelidir.  Çünkü,  âlimler  bilgilerini peygamberlerden “aleyhimüssalevâtü vetteslîmat” almıştır. Bu bilgiler, vahy ile  gelmiş  olup  sağlamdır.  Yanlışlıktan,  şaşırmaktan  korunmuştur.  Bu bilgilere uymayan kendi keşf ve ilhamı ise, yanlıştır ve bozuktur. Bunun için kendi keşfini, âlimlerin sözünün üstünde tutmak, vahy ile inmiş olan sağlam bilgilerin  üstünde  tutmak  olur.  Bu  ise  sapıklığın  tâ  kendisidir,  zarar  ve ziyandan başka birşey değildir. Kitab ve sünnete, ya’nî Kur’ân-ı kerîme ve hadîs-i şerîflere uygun i’tikâd lâzım olduğu gibi, müctehidlerin kitab ve sünn’etden çıkardıkları ahkâma, ya’nî İslâmiyete uygun işleri yapmak da lâzımdır. Bu ahkâm; helâl, haram, farz, vâcib, sünnet, müstehâb, mekrûh ve şüpheli olan işler demektir. Bu ahkâmı öğrenmek de lâzımdır. İ’tikâdı  ve  ameli  doğrulttuktan,  bu  iki  kanadı  ele  geçirdikten  sonra. Allahü teâlâya yaklaştıran yolda, ilerlemek sırası gelir. Zulmânî ve nûrânî konakları aşmağa başlanabilir. Fakat şunu iyi bilmelidir ki, böyle konakları aşarak  yükselebilmek:  ancak,  yolu  bilen,  yolu  gören,  yol  gösteren,  kâmil (yetişmiş) ve mükemmil (yetiştirebilen) bir rehberin teveccühü ve tasarrufu ya’nî idâre etmesi ile olabilir. Bunun bakışları, kalb hastalıklarına şifâ verir. Onun teveccühü, yâ’ni kalbini bir kimseye çevirmesi, kötü ve çirkin huyları insandan siler, süpürür. Tasavvuf  yolcusunun,  bu  yolda  gözetilmesi  lâzım  olan  şartları  da öğrenmesi ve bunlara riâyet etmesi lâzımdır. Bu şartların en başta geleni, nefse  uymamaktır.  Bu  da,  vera’  ve  takvâ  ile  olur.  Vera’  ve  takvâ, haramlardan  sakınmak  demektir.  Haramlardan  sakınabilmek  için, mübahların  lüzumundan  fazlasını terk  etmelidir  Çünkü  mübahları  (ya’nî yasak olmıyan şeyleri), alabildiğine yapan kimse, şüpheli olanları işlemeğe başlar. Bunlar ise, harama yakındır, ya’nî haram işlemek ihtimâli çok olur. Uçurum  kenarında  yürüyen,  içine  düşebilir.  Demek  ki  haramdan sakınabilmek  için,  mübahların  fazlasından  kaçmak  lâzımdır.  Bu  yolda ilerlemek  için  vera’  sahibi  olmak  şarttır  dedik.  Çünkü  insanın  işleri,  iki şeyden  biridir.  Ya  emr  edilen  şeydir,  yâhud  yasak  edilmiş  şeylerdendir. Melekler  de,  emr  edilen  şeyleri  yapmaktadır. Bunu  yapmak  insanı ilerletseydi,  melekler  de  terakki  ederdi.  Meleklerde,  yasak  edilen  şeyden sakınmak yokdur. Çünkü onlar, yasakları yapmıyacak şekilde yaratılmıştır. Yasakları  işliyemezler.  Onun  için  meleklere  birşey  yasak  edilmemiştir. Demek ki, terakki etmek, yasaklardan sakınmakla olabilmektedir. Bu  sakınmak  ise,  nefse  uymamak  demektir.  Allahü  teâlâ  dinleri,  nefsi isteklerden kurtarmak, karanlık ve kötü âdetleri yok etmek için gönderdi. Çünkü nefs, hep haram işlemek veya mübahları lüzumundan” fazla yaparak, böylece  harama  kavuşmak  ister.  Demek  ki,  haramlardan  ve  mübahların fazlasından sakınmak, nefse uymamak demektir. [1. cild. 286 mektûb] Suâl: Nefs, ibâdet yapmak istemiyor ibâdet yapmak da, nefse uymamak oluyor. O hâlde emirleri yapmak da, terakkiye sebep olmaz mı? Meleklerin emirleri yapması, nefse uymamak olmadığı için, onlar terakki etmiyor. Cevap: Emîrleri, ya’nî ibâdetleri yapmayı nefsin istememesi, emr altına girmek istemediği içindir. Nefs bir emr altına girmek, birşeye bağlanmak istemez. Nefsin bu hâli. (ya’nî başı boş kalmak, birşeye bağlanmamak arzusu da  haramdır  veya  mübahların  fazlası  demektir.  Demek  ki,  emirleri yapmakla, bu haramdan veya mübahın fazlasından sakınılmış oluyor. Bunun için  de,  nefse  uyulmamış  oluyor.  Yoksa  nefse  uymamak,  yalnız  emirleri yapmak demek değildir. İnsanı  kemâle  kavuşturan,  olgunlaştıran  yollar  çoktur.  Bunların  en fâidelisi,  çabuk  ulaştıranı,  nefsle  mücâdelesi  çok  olanıdır.  Ruhsattan sakınan,  azîmetle  amel  edenlerin  yoludur.  Azîmet,  haramlardan  ve mübahların fazlasından sakınmak demektir. Ruhsat ise, yalnız haramlardan kaçınmaktır.  Azîmetle  hareket  eden  büyükler,  Sünnet-i  seniyyeden  ya’nî İslâmiyetten  kıl  kadar  ayrılmamıştır.  Yollarına  hiçbir  yenilik,  bid’at karıştırmamıştır. Bunların yolunda nefse uymamak, nefs mücâdelesi tamdır. O  hâlde,  yolları  en  iyi  en  fâideli  yoldur.  Çabuk  ulaştırıcıdır.  Fakat  son zamanlarda,  bu  yolu  da  bozanlar  oldu.  O  büyüklerin  izinden  ayrılanlar çoğaldı. Değişiklikler, bid’atler yapıldı. Simâ’ ve raksa ve yüksek sesle zikre başladılar. Bunları, o büyüklerin niyetlerini kavrayamadıkları için yaptılar. Bid’atler   karıştırmakla,   zamana   uymakla,   bu   yolu   daha kıymetlendirdiklerini,  olgunlaştırdıklarını  sandılar.  Bunlar  ile,  bu  yolu yıktıklarını,  ellerinden  kaçırdıklarını  anlıyamadılar.  Hakkı,  doğruyu meydana  çıkaran  ve  insanı  hidâyet  yoluna  kavuşturan,  ancak  Allahü teâlâdır.” (1. cild, 286. mektûb)', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.098150', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Hindistan’da yetişen âlimlerin ve velîlerin büyüklerinden. İsmi, Mevlânâ Emânullah,  nisbeti,  Lâhorî’dir.  Doğum  ve  vefât  târihleri  belli  değildir. Onbirinci asrın ortalarında vefât etmiş olduğu bilinmektedir. İmâm-ı  Rabbânî  hazretlerinin  huzûr  ve  sohbetlerinde  kemâle  gelen Emânullah  Lâhorî,  icâzet  almakla  ve  o  yüce  İmâmın    talebelerinin büyüklerinden  olmakla  şereflendi.  ostün  hâller,  kerâmetler  ve  yüksek dereceler  sahibi  idi.  Hocası  İmâm-ı  Rabbânî  hazretlerinin,  rûhlara  hayat veren teveccüh ve himmetleriyle yetişerek, evliyâlık yolunda çok ilerlemiş idi. Kendisi de bu yolda çok talebe yetiştirdi. İmâm-ı  Rabbânî  Müceddîd-i  elf-i  sânî  hazretleri  bu  yüksek  talebesine yazdığı mektûblardan birinde buyurdu ki: “Bismillâhirrahmânirrahîm. Allahü teâlâ, sana doğru yolu göstersin! iyi bil  ki,  Allah  yolunda  bulunmak  isteyene,  önce  lâzım  olan  şey,  i’tikâdını düzeltmektir. Doğru i’tikâd; Ehl-i sünnet âlimlerinin Kur’ân-ı kerîmden ve hadîs-i şerîflerden ve Eshâb-ı Kirâmdan öğrendikleri, anladıkları i’tikâddır. Kur’ân-ı kerîmin ve hadîs-i şerîflerin ma’nâsını doğru anlıyan, doğru yolun âlimleridir. Bunlar da, Ehl-i sünnet ve cemâat âlimleridir. Bunların anladığı, bildirdiği  ma’nâlara  uymayan  herşeye;  akla,  fikre,  hayâle  iyi  gelse  de  ve tasavvuf yolunda keşf ve ilham ile anlaşılsa da, hiç kıymet verilmemelidir. Bu büyüklerin anladığına uymıyan bilgilerden, buluşlardan Allahü teâlâya sığınmalıdır. Demek ki, tasavvuf yolcularının keşflerinin, buluşlarının doğru olup  olmadıkları,  Ehl-i  sünnet  âlimlerinin  bildirdikleri  doğru  ma’nâlara uygun  olup  olmamaları  ile  anlaşılır.  Bu  yolculara  ilham  olunan bilgilerin doğruluğu, ancak, o doğru ma’nâlara uymaları ile belli olur. Çünkü onların bildirdiği ma’nâlara uymıyan her ma’nâ, her buluş kıymetsizdir, yanlıştır. Çünkü  her  sapık  her  bozuk  kimse,  Kur’ân-ı  kerîme  ve  hadîs-i  şerîflere uyduğunu sanır ve iddia eder. Yarım aklı ve kısa görüşü ile, bu kaynaklardan yanlış ma’nâlar çıkarır. Doğru yoldan kayar, felâkete gider. Ehl-i  sünnet  âlimlerinin  anladıkları  ma’nâlar  doğrudur,  kıymetlidir. Bunlara uymıyanlar kıymetsizdir. Çünkü bu ma’nâları, Eshâb-ı Kirâmın ve Selef-i  sâlihînin  eserlerini  inceliyerek  elde  etmişlerdir.  O  hidâyet yıldızlarının ışıkları ile parlamışlardır. Bunun için, ebedî kurtuluş bunlara mahsûs  oldu.  Sonsuz  saadete  bunlar  kavuşdu.  Allah  yolunda  giden  kâfile bunlar oldu. Kurtuluş, ancak Allah yolunda bulunanlar içindir. İ’tikâdı  bunlara  uygun  olan  din  âlimlerinden  biri,  fer’ıyyâtta,  ya’nî, İslâmiyete  yapışmakta  gevşek  davranırsa,  kusurlu  olursa,  buna  bakarak, bütün  âlimleri  kötülemek  yersiz  olur.  İnâdcılık  olur.  Onların  doğru bilgilerini  inkâr  etmek,  kötülemek  olur.  Çünkü,  doğru  bilgileri  bizlere ulaştıran  onlardır.  Kurtuluş  yolunu,  bozuklarından,  sapıklarından  ayıran onlardır. Onların hidâyet ışıkları olmasaydı bizler doğru yolu bulamazdık. Doğruyu  bozuk  olanlardan  ayırmasalardı,  bizler,  taşkınlık ve  azgınlık uçurumlarına  düşerdik,  İslâmıyeti  bozulmaktan  koruyan  her  yere  yayan, onların çalışmasıdır, İnsanları kurtuluş yoluna kavuşturan onlardır. Onlara uyan kurtulur, saadete kavuşur. Onların yolundan ayrılan, sapıtır, herkesi Tasavvuf   yolcusunun,  işin  iç  yüzüne  varmad