INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21616, 'MANSÛR BABA', 'Elazığ’ın  mechul  velilerinden.  Artuklu  hanedanından  olduğu  da söylenmiştir. Hayatı hakkında kaynaklarda bir bilgi yoktur. 16. Yüzyıla ait bir vakfiyesi vardır. Rivayete göre fahende adında bir kadının gördüğü rüya üzerine, Beyzade Efendi başkanlığında yapılan kazıda bir erkek, bir kadın ve iki çocuk mezarına rastlanmıştır. Erkeğin mezarı açıldığında çürümemiş bir cesetle  karşılaşılmıştır.  Durum  feyhülislamlığa  bildirilmiş,  gelen  cevap üzerine buraya bir türbe yaptırılmış ve Mezar taşına atfen Mansur Baba adı', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.135441', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Elazığ’ın  mechul  velilerinden.  Artuklu  hanedanından  olduğu  da söylenmiştir. Hayatı hakkında kaynaklarda bir bilgi yoktur. 16. Yüzyıla ait bir vakfiyesi vardır. Rivayete göre fahende adında bir kadının gördüğü rüya üzerine, Beyzade Efendi başkanlığında yapılan kazıda bir erkek, bir kadın ve iki çocuk mezarına rastlanmıştır. Erkeğin mezarı açıldığında çürümemiş bir cesetle  karşılaşılmıştır.  Durum  feyhülislamlığa  bildirilmiş,  gelen  cevap üzerine buraya bir türbe yaptırılmış ve Mezar taşına atfen Mansur Baba adı');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21617, 'MEHMED BEHÂEDDÎN NAKŞİBENDÎ', 'Muhammed  Kudsî  Bozkırî  hazretlerinin  oğlu  olan  Mehmed  Behâeddîn Efendi 1831\'de doğmuştur. İlk derslerini babasından alıp din ilimlerinin ve tasavvufun zevkini  tadan  Mehmed  Behâeddîn  Efendi  1862\'de  Konya\'ya gelerek  uzun  müddet  Konya  Bekir  Sami  Paşa  Medresesinde  müderrislik yaptı. 1906 yılında vefât etti. Türbesi konyadadır.', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.135566', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Muhammed  Kudsî  Bozkırî  hazretlerinin  oğlu  olan  Mehmed  Behâeddîn Efendi 1831\'de doğmuştur. İlk derslerini babasından alıp din ilimlerinin ve tasavvufun zevkini  tadan  Mehmed  Behâeddîn  Efendi  1862\'de  Konya\'ya gelerek  uzun  müddet  Konya  Bekir  Sami  Paşa  Medresesinde  müderrislik yaptı. 1906 yılında vefât etti. Türbesi konyadadır.');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21618, 'MEHMED EMÎN EFENDİ', 'Doğu  Anadolu’da  yetişen  evliyânın  meşhurlarından.  Babası  Seyyid Abdülazîz  hazretleridir.  1854  (H.1270)  senesinde  Yukarı  Doğubâyezîd’de doğdu. 1914 (H.1332)de yine orada vefât etti. Tasavvufta yüksek haller ve kerâmetler  sâhibi  mübârek  bir  zâttı.  Kabri  Yukarı  Doğubâyezîd’de  âile kabristanındadır. Geceleri  parmaklarından  sızan  ışıkla  yazı  yazardı.  Bu  kerâmetini görenler bu ışıkta satırları sayardık demişlerdir. Zaif ve nazik yapılı bir zâttı. Soğuktan sıcaktan müteessir olurdu. Ekseriya evinde oturur ilimle meşgul olurdu.  Neden  çıkmadığı  sorulunca;  “Herkes  fasulyeden  patatesten  söz ediyor.  Allahü  teâlâdan  bahseden  kalmadı.”  buyururdu.  Geceleri  de uyumazdı. Oğlu Abdülhakîm Efendi; “Ben babamı hiç yatakta görmedim.”', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.135603', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Doğu  Anadolu’da  yetişen  evliyânın  meşhurlarından.  Babası  Seyyid Abdülazîz  hazretleridir.  1854  (H.1270)  senesinde  Yukarı  Doğubâyezîd’de doğdu. 1914 (H.1332)de yine orada vefât etti. Tasavvufta yüksek haller ve kerâmetler  sâhibi  mübârek  bir  zâttı.  Kabri  Yukarı  Doğubâyezîd’de  âile kabristanındadır. Geceleri  parmaklarından  sızan  ışıkla  yazı  yazardı.  Bu  kerâmetini görenler bu ışıkta satırları sayardık demişlerdir. Zaif ve nazik yapılı bir zâttı. Soğuktan sıcaktan müteessir olurdu. Ekseriya evinde oturur ilimle meşgul olurdu.  Neden  çıkmadığı  sorulunca;  “Herkes  fasulyeden  patatesten  söz ediyor.  Allahü  teâlâdan  bahseden  kalmadı.”  buyururdu.  Geceleri  de uyumazdı. Oğlu Abdülhakîm Efendi; “Ben babamı hiç yatakta görmedim.”');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21619, 'MEHMED EFENDİ', NULL, NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.135831', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Bursa velîlerinden. Celveti  şeyhlerinden.  Mehmed  oftade’nin  oğludur. Babasının vefatını müteakip bir yıl kadar şeyhlik yaptıktan sonra 26 Ekim 1913  (6  Zilhicce  1332)  Pazartesi  günü  vefat  eylemiştir.  Kabri  oftâde');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21620, 'ANNEN VE BABAN EVLİYÂ İDİLER', 'Seyyid Muhammed Berzencî müftî olarak Doğubâyezîd\'e gitmişti.fehrin eşrafı ona hoş geldine gittiler. Müftü efendi; \"Bu şehirde âlim ve âriflerden kimler vardır?\" diye sorunca, Seyyid Mehmed Emîn\'den bahsettiler. Onun husûsî hallerini bilmediği için bir müddet hoşgeldine gelmesi için bekledi. O gelmeyince,  Müftî  efendi  kendisi  ziyârete  gitti.  Evine  varınca,  ikinci  kata çıkarıp; \"Efendi içerdedir. Siz içeri buyurun” dediler. Müftî Efendi içeri girip selâm verdi. Kendini tanıttı.Sonra da hoş geldine gelmediği için sitem etti. Bu  sitem  nezâket  ehli  için  ağır  ve  incitici  bulunduğundan,  MehmedEmîn Efendi çok müteessir olup oturmasını ricâ etti. Fakat o anda Müftî efendi büyük  bir  dehşet  ve  korku  içinde  titremeye  başladı.  Mehmed  Emîn Efendinin hanımı Seyyide Medine Hanım, kerâmetiyle bu hâlin farkına varıp alt  kattan;  \"feyh  Efendi  misâfiriniz  korkuyor,  onu  teskin  ediniz.\"  diye O  sırada  Mehmed  Emîn  hazretlerinin  oturduğu  sedirin  altında,  bir arslanın saldırmaya hazır vaziyette işâret beklediği görüldü. Kalkıp eliyle sedirin  altına  işâret  etti.  Arslan  kayboldu.  Misâfiri  elinden  tutup  iltifat göstererek  teskin  etti.  Aynı  sedirin  üzerine  oturttu.  Kerâmetlerini  çok gizlediği halde, bu kerâmeti iradeleri dışında vukû bulmuştu. Müftî Seyyid Muhammed  Berzencî  başından  geçen  bu  hâdiseyi  Seyyid  MehmedEmîn hazretlerinin oğluna aynen anlattıktan sonra; \"Senin baban evliyâ idi.Annen de ondan aşağı değildi. Bunu benden işitmiş ol.\" demiştir. Seyyid Abdülhakîm Arvâsî hazretleri Doğubâyezîd’e akrabâ ziyâreti ve irşâd  faâliyeti  için  her  gidişinde  Seyyid  Mehmed  Emîn’in  evinde  misâfir olurdu.  Çok  tatlı  sohbetler  ederlerdi.  Bir  defâ  gidişinde  Mehmed  Emîn Efendinin  bir  oğlu  dünyâya  geldi.  Ona  muhabbetlerinin  çokluğundan  bu bebeği kucağına alıp ismini kendi ismi gibi Abdülhakîm koyup, hayır duâ Mehmed  Emîn  hazretlerinin  eserleri  ve  mevcud  kitapları  Rus  işgâli sırasında  yakılıp  tahrib  edilmiştir.  Malları  ve  hayvanları  da  Ermeniler tarafından talan edilmiştir. Seyyide Vesîle ve Hatice adında iki kızı ve Seyyid Abdülkâdir,  Muhammed  Mûsâ,  Abdülazîz  (Baba  Efendi),  Abdülazîz, Abdurrahîm, Abdullah (I) ve Abdullah (II) isimlerinde oğulları vardı. 1) İslâm Meşhûrları Ansiklopedisi ) Doğu Anadolu Evliyâları, I, 53-55.', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.135803', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Seyyid Muhammed Berzencî müftî olarak Doğubâyezîd\'e gitmişti.fehrin eşrafı ona hoş geldine gittiler. Müftü efendi; \"Bu şehirde âlim ve âriflerden kimler vardır?\" diye sorunca, Seyyid Mehmed Emîn\'den bahsettiler. Onun husûsî hallerini bilmediği için bir müddet hoşgeldine gelmesi için bekledi. O gelmeyince,  Müftî  efendi  kendisi  ziyârete  gitti.  Evine  varınca,  ikinci  kata çıkarıp; \"Efendi içerdedir. Siz içeri buyurun” dediler. Müftî Efendi içeri girip selâm verdi. Kendini tanıttı.Sonra da hoş geldine gelmediği için sitem etti. Bu  sitem  nezâket  ehli  için  ağır  ve  incitici  bulunduğundan,  MehmedEmîn Efendi çok müteessir olup oturmasını ricâ etti. Fakat o anda Müftî efendi büyük  bir  dehşet  ve  korku  içinde  titremeye  başladı.  Mehmed  Emîn Efendinin hanımı Seyyide Medine Hanım, kerâmetiyle bu hâlin farkına varıp alt  kattan;  \"feyh  Efendi  misâfiriniz  korkuyor,  onu  teskin  ediniz.\"  diye O  sırada  Mehmed  Emîn  hazretlerinin  oturduğu  sedirin  altında,  bir arslanın saldırmaya hazır vaziyette işâret beklediği görüldü. Kalkıp eliyle sedirin  altına  işâret  etti.  Arslan  kayboldu.  Misâfiri  elinden  tutup  iltifat göstererek  teskin  etti.  Aynı  sedirin  üzerine  oturttu.  Kerâmetlerini  çok gizlediği halde, bu kerâmeti iradeleri dışında vukû bulmuştu. Müftî Seyyid Muhammed  Berzencî  başından  geçen  bu  hâdiseyi  Seyyid  MehmedEmîn hazretlerinin oğluna aynen anlattıktan sonra; \"Senin baban evliyâ idi.Annen de ondan aşağı değildi. Bunu benden işitmiş ol.\" demiştir. Seyyid Abdülhakîm Arvâsî hazretleri Doğubâyezîd’e akrabâ ziyâreti ve irşâd  faâliyeti  için  her  gidişinde  Seyyid  Mehmed  Emîn’in  evinde  misâfir olurdu.  Çok  tatlı  sohbetler  ederlerdi.  Bir  defâ  gidişinde  Mehmed  Emîn Efendinin  bir  oğlu  dünyâya  geldi.  Ona  muhabbetlerinin  çokluğundan  bu bebeği kucağına alıp ismini kendi ismi gibi Abdülhakîm koyup, hayır duâ Mehmed  Emîn  hazretlerinin  eserleri  ve  mevcud  kitapları  Rus  işgâli sırasında  yakılıp  tahrib  edilmiştir.  Malları  ve  hayvanları  da  Ermeniler tarafından talan edilmiştir. Seyyide Vesîle ve Hatice adında iki kızı ve Seyyid Abdülkâdir,  Muhammed  Mûsâ,  Abdülazîz  (Baba  Efendi),  Abdülazîz, Abdurrahîm, Abdullah (I) ve Abdullah (II) isimlerinde oğulları vardı. 1) İslâm Meşhûrları Ansiklopedisi ) Doğu Anadolu Evliyâları, I, 53-55.');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21621, 'MEHMED EFENDİ', 'Kosava  evliyalarından.  Türbesi  Kaçanik’de  Sitniça  Deresi\'nin  sol kıyısında  osküp  istikametinde  bulunmaktadır.  Murad-ı  Hüdavendigar zamanında  şehid  olmuştur.  Hakkında  başsız  diye  birçok  menkıbe 1) Batı Anadolu Rumeli Evliyâları, II, 240.', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.135856', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Kosava  evliyalarından.  Türbesi  Kaçanik’de  Sitniça  Deresi\'nin  sol kıyısında  osküp  istikametinde  bulunmaktadır.  Murad-ı  Hüdavendigar zamanında  şehid  olmuştur.  Hakkında  başsız  diye  birçok  menkıbe 1) Batı Anadolu Rumeli Evliyâları, II, 240.');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21622, 'MEHDÎ ALEYHİRRAHME', 'Fâtıma-tüz-zehrâ  soyundan, âhir  zamanda kıyamete  yakın dünyâya gelecek,  islâmiyeti  yeryüzüne  hâkim  kılacak,  Peygamber  efendimiz tarafından haber verilen zât. Peygamber efendimizin kızı hazret-i Fâtıma’nın oğlu hazret-i Hüseynin neslinden  gelecek  yani  Seyyid  olacak,  Medîne-i  münevverede  doğacak  ve Mekke-i  mükerremede  ortaya  çıkıp  tanınacaktır.  İsmi  Muhammed, babasının ismi Abdullah olacaktır. İlimde ve evliyâlıkta derecesi çok yüksek olup  müceddîd  ve  müctehid  olacaktır. Îsâ  aleyhisselâmla  buluşacak, mezhebleri  kaldıracak, kendi içtihadı ile  bir  mezheb  kuracaktır. Kuracağı mezhebin hükümlerinin, Hanefî hükümlerine uygun olacağını, büyük İslâm âlimi  İmâm-ı  Rabbânî  hazretleri  haber  vermektedir.  Bütün  müslümanlar, hazret-i  Mehdî’ye  tâbi  olacak, her  yeri  alacak,  her  yerde  adâlet  olacak, yeryüzünün  tamâmına  hâkim  olacaktır. Çok  âdil  olacak,  hiçbir  mahlûk arasında  düşmânlık  kalmıyacakdır.  Eshâb-ı  Kehf  uyanıp,  mağaradan çıkacak, Mehdî’nin askeri olacak, Mehdî’ye hizmet edecekdir. İbni    Hacer-i  Mekkînin “Alâmet-ül-Mehdî” kitâbında  ve  Süyûtînin “Cüz’ün  minel  ehâdîs  velâsâril  vârideti  fî  alâmetil  mehdî” kitâbında bunlardan ikiyüze yakın alâmet yazılıdır. “El-fütûhât-ül-islâmiyye” ikinci cüz, ikiyüzdoksanyedinci sahîfesinde diyor ki, “Beklenilen Mehdî, hazret-i Fâtımanın  soyundan  olacakdır.  Mekkede zuhûr  edecekdir.  O  zemân, müslimânlar halîfesiz olacakdır. İstemediği hâlde, zor ile halîfe yapılacakdır. Zuhûr edeceği zemân ve yaşı ve ömrü kesin belli değildir.” Mehdî çıkacağı zemân  yeryüzünde  halîfe  bulunmıyacağı  ve  Mehdîliklerini  i’lân  edenlerin Mehdî  olmadıkları,  buradan  anlaşılmakdadır. İmâm-ı  Rabbânî  hazretleri, birinci  cildin  ikiyüzellibeşinci  mektûbunda,  Mehdî’nin  Medîne’deki  sapık din adamlarını öldüreceğini yazmakdadır. Hazret-i Mehdî geldiğinde, hak mezheplerin hükmü unutulmuş olacak, bid\'at mezhepleri ortalığı kaplayacak, ortada hak bir mezhep kalmayacaktır. Yani  mezheplerin  doğru  bilgileri  kalmayacak,  sadece  isimleri  kalıp,  din düşmanları veya sapıklar tarafından bu isimler suistimal edilecektir. Hazret-i  Mehdî,  ictihad  edecek,  ictihadı Hanefi   mezhebine   uygun olacaktır. Zaten İsa aleyhisselamın Hristiyanlığı yasak ettiği gibi, Hazret-i Mehdî de diğer bozuk fırkaları, bozuk mezhepleri yasak edecektir. Bozuk mezhepleri kaldıracağı için mezhepleri kaldıracak ifadesi kullanılmıştır. İmam-ı  Rabbani  hazretleri  buyuruyor  ki:  İşitdiğimize  göre,  hazret-i Mehdî,  hükûmet  sürdüğü  ze­mân,  dîni  yayarken  ve  sünneti  diriltirken, bid’at işlemeğe alışmış olan Medînedeki âlim, bid’ati güzel sandığı ve ibâdet olarak yapdığı için, haz­ret-i Mehdînin emrlerine şaşarak, (Bu adam, bizim dînimizi  yok  etdi  ve  milletimizi  öldürdü)  diyecekdir.  Hazret-i  Mehdî “rahmetullahi  aleyh”  bu  âlimi  öldürecekdir.  Onun  güzel  sandığı  bid’atin, kötü olduğunu bildirecekdir. Mehdî  “rahime-hullahü  teâlâ”  Deccâl’ı  öldürdükden  sonra,  Mekke’ye, Medîne’ye giderek, binlerle vehhâbî din adamını kılınçdan geçireceği hadîs-i şerîfde açıkça bildirilmekdedir. İmam-ı  Rabbani  hazretleri  buyuruyor  ki:  Resulullahın  vefatından  bin sene  geçtikten  sonra,  ümmetinden  gönderilen  âlimlerin  sayısı  azsa  da, İslamiyet’i tam kuvvetlendirmeleri için, çok yüksek olacaklardır. Resulullah efendimiz,  hazret-i  Mehdî’nin  geleceğini  haber  vermiştir.  Bin  sene  sonra gelecektir. İsa aleyhisselam da, bin sene sonra, gökten inecektir. Bin sene sonra  gelen  Evliyanın  yükseklikleri,    Eshab-ı  kiramın  yüksekliklerine “Mehdî geleceğine inanmıyan kâfir olur” denildi. Mehdînin alâmetlerini Resûlullah  “sallallahü  aleyhi  ve  sellem”  efendimiz  bildirmişdir. Hazret-i Mehdî’nin  gedeceğini  ve  yapacağı  işleri  haber  veren  bir  çok  hadîs-i  şerîf vardır.  Ebû  Sa’îd-i  Hudrî’nin  (radıyallahü  anh)  rivayet  ettiği  hadîs-i şerîflerde buyruldu ki: “Yeryüzü  zulüm  ve  düşmanlıkla  dolduktan  sonra,  benim  Ehl-i beytimden  mutlaka  birisi  çıkar.  Dünyâ  daha  önce  nasıl  zulüm  ve düşmanlık ile dolu ise, o, dünyâyı adaletle doldurur.” “Ümmetim,  bal  arılarının  beyleri  etrafında  toplanması  gibi, Mehdî’ye sığınırlar. O daha önce zulümle dolu olan dünyâyı adaletle doldurur. Uykuda olan uyandırılmaz ve bir damla bile kan dökülmez.” İbn-i  Mes’ûd’dan  rivayet  edilen  bir  hadîs-i  şerîfde  de  şöyle  buyruldu: “Mehdî ile müjdelenmiş olunuz. Mehdî, Kureyş kabilesinden ve benim Ehl-i beytimden biridir. O, insanların ihtilâf içinde oldukları ve ictimâî sarsıntılar içinde bulundukları bir zamanda çıkar. Mehdî, daha önce zulüm  ve  cevr  ile  dolu  olan  dünyâyı,  adalet  ve  insaf  ile  doldurur. Ondan  yer  ve  gök  ehli (insanlar,  cinler  ve  melekler) razıdır.  O,  malı insanlar arağında adaletle dağıtır. Ümmet-i Muhammed’in kalblerini zenginlik  île  doldurur  ve  onları  adaletiyle  kuşatır.  O  kadar  ki,  bir münâdîye; “Kimin ihtiyâcı varsa bana gelsin” diye nida (îlân) etmesi emrolunduğunda,  bir  kişiden  başka  kimse  gelmez.  O  kimse  istekte bulunur.  Mehdî (rahmetullahi   aleyh) de  ona;  “Hazinedara  git  sana versin”  der.  O  kişi,  hazinedara  gidip,  Mehdî’nin (aleyhirrahme) gönderdiğini söyleyip, hazinedardan götürmeye gücünün yettiği kadar mal alır. Fakat daha sonra pişman olarak; “Ben, herkesden daha mı muhtacım, kimse gitmedi, ben gittim!” diyerek aldığı malı iade etmek ister, o zaman hazinedar; “Biz verdiğimizi geri almayız” der. Bu devir; altı, yedi, sekiz veya dokuz sene devam eder. Bundan sonraki hayatta, Târihte bâzı câhiller, büyük zannettikleri kimselere Mehdî demişlerdir. Mehdî’nin  alâmetlerini  Resûlullah  efendimiz  (sallallahü  aleyhi  ve  sellem) bildirmiştir. İbn-i  Hacer-i Mekkî hazretlerinin Alâmât-ül-Mehdî kitabında ve İmâm-ı Süyûtî’nin El-Bürhân kitabında, bu alâmetlerden iki yüze yakını yazılıdır.  Büyük  âlim  Ahmed  Zeynî  Dahlân, Fütûhât-ül-İslâmiyye adlı eserinin,  ikinci  cüz,  297.  sayfasında  diyor  ki:  “Beklenilen  Mehdî  hazret-i Fâtıma’nın  soyundan  olacaktır.  Mekke’de  zuhur  edecektir.  O  zaman, müslümanlar  halisesiz  olacaktır.  O  istemediği  hâlde,  zor  ile  halîfe yapılacaktır.  Zuhur  edeceği  zaman,  yaşı  ve  ömrü  kesin  olarak  bildirilmiş İmâm-ı Rabbânî hazretleri, Mehdî’nin, Medîne’deki sapık din adamlarını öldüreceğini yazmakta ve şöyle buyurmaktadır: “Hazret-i Mehdî, hükümet sürdüğü  zaman,  dîni  yayarken  vesünnetleri  ortaya  çıkarırken,  bid’at işlemeğe  alışmış  olan  Medîne’deki  âlim  tanınan  bir  kimse,  bid’ati  güzel sandığı ve ibâdet olarak yaptığı için, hazret-i Mehdî’nin emirlerine şaşarak; “Bu  adam,  bizim  dînimizi  yok  etti  ve  milletimizi  öldürdü”  diyecektir.” Hazret-i  Mehdî,  bu  kimseyi  öldürüp,  onun  güzel  sandığı  bid’atlerin kötülüğünü insanlara bildirecektir.” (Cild-1, mektub: 255) İmâm-ı  Rabbânî  (rahmetullahi  aleyh),  yine  buyuruyor  ki:  “Hadîs-i şerîfde; “Yeryüzünü küfür kaplamadıkça ve her yerde küfür ve kâfirlik yayılmadıkça,  hazret-i  Mehdî  gelmez”buyruldu.  Bundan  anlaşılıyor  ki, hazret-i Mehdî çıkmadan evvel, küfür ve kâfirlik her tarafa yayılacak, İslâm ve müslümanlar garîb olacaktır. Peygamberimiz sallallahü aleyhi ve sellem âhır zamanda, müslümanların garîb olacaklarını haber vermiştir.” (Cild-2, İbn-i  Hacer-i Mekkî Heytemî hazretleri El-Kavl-ül-muhtasar fî alâmet- il-Mehdî kitabında şöyle buyurdu: “Mehdî, Ehl-i beytten olacaktır. Hazret-i Hüseyn’in  neslinden  gelecektir,  ismi,  Resûlullah  efendimizin  ism-i şerîflerinden yâni Muhammed olacaktır. Babasının ismi de, Resûl-i ekremin mübârek  babasının  ismi  gibi  Abdullah  olacaktır.  Hazret-i  Mehdî’nin  alnı geniş ve dişleri seyrektir.” Hadîs-i şerîflerde buyruldu ki: “Mehdî’nin  babasının  ismi  Abdullah’dır  ve  Eshâb-ı  Kehf  arkadaşı “Eshab-ı  Kehf,  Mehdî’nin  yardımcıları  olacak  ve  İsâ  bunun  zamanında gökten inecek ve Deccâl ile harb ederken, Mehdî, onunla beraber olacaktır.) “Horasan  tarafından  gelen  siyah  sancaklılara  katılın.  Onların  içinde Allah\'ın halifesi Mehdî vardır.) [Hakîm, İmâm-ı Ahmed, Deylemî] “Horasan  tarafından  gelen  siyah  sancaklılara  katılın.  Onların  içinde Allah\'ın halifesi Mehdî vardır.” [Hakîm, İmâm-ı Ahmed, Deylemî] “Nasıl helak olur bir ümmet ki, başında ben, sonunda Meryem oğlu İsa ve ortasında da ehl-i beytimden Mehdî vardır.” [Hâkim, İbni Asâkir] “farktan çıkan bir grup, Mehdî’ye yardım ederler.” [İbni Mâce, Taberânî] “Mehdî  çıkınca,  Allahü  teâlâ  ona  rahmetini  indirir.”  [İmâm-ı  Ahmed, “Mehdî gelince, bir bereket olacak, ümmetim rahat edecektir.”[İbni Ebî “Mehdî bendendir, yeryüzünü hak ve adaletle doldurur.” [Ebû Davud] “Mehdî, Kureyşten ve ehl-i beytimdendir.” [İmâm-ı Ahmed, Baverdi] “Mehdî ehl-i beyttendir. Allahü teâlâ onu bir gecede olgunlaştırır.”[İbni Mâce, İmâm-ı Ahmed] “Deccal’ın  veya  Mehdî’nin  geleceğine  inanmayan  kâfir  olur.”  [Fevâid-il Ehbar - ferh’is-Siyer] “Mehdî benim soyumdandır.” [İbni Mâce] “Mehdî evladı Fâtıma’dandır.” [Ebu Davud, Hakîm] Kütüb-i sitteden Buhari, Müslim, Ebu Davud, İbni Mâce, Tirmizi ve diğer hadis âlimlerinin bildirdikleri bu hadis-i şerifleri ve Ehl-i sünnet âlimlerinin açıklamalarını akıl ve iman sahibi hiç kimse inkâr edemez. Tevil etmek de dinimize aykırıdır. Herkes dinin hükümlerini tevil etmeye kalkarsa ortada din diye bir şey kalmaz. “Nefsim  yed-i  kudretinde  olan  Allahü  teâlâya  yemin  ederim  ki, Allahü  leâlâ  benim  neslimden,  dişleri  aralıklı,  alnı  acık,  yeryüzünü adaletle dolduracak, malı ve mülkü insanlara bol bol ikram edecek bir evlâdımı gönderecektir. Zulüm ve fıskla dolu olan dünyâ, o geldikten sonra adaletle dolup taşacaktır.” “Mehdî’nin başı hizasında bir bulut olacaktır. Buluttan bir melek; “Bu Mehdî’dir. Sözünü dinleyiniz!” diyecektir. Hazret-i  Mehdî’nin  alâmetlerinden  biri  de,  Deccal’in  onun  zamanında ortaya  çıkmasıdır.  Hadîs-i  şerîfde; “On  büyük  alâmet  görülmeyince kıyamet  kopmaz;  Duhân,  Deccâl,  Dâbbel-ül-erd,  güneşin  batıdan doğması,  Îsâ’nın (aleyhisselâm) gökten  inmesi,  Ye’cüc  ve  Me’cüc’ün çıkması, doğuda, batıda ve Arabistan’da yer batması, bunlardan sonra Yemen’den bir ateş çıkıp, halkı bir araya getirecektir” buyruldu. Muhbir-i sâdık [ya’nî hep doğru haber verici] “sallallahü teâlâ aleyhi ve sellem”  kıyâmet  alâmetlerinden  her  ne  haber  verdi  ise,  hepsi  doğrudur. Yanlışlık  olamaz.  O  zemân  güneş,  âdet  dışı  olarak  garbdan  doğacakdır. Hazret-i Mehdî “aleyhirrıdvân” çıkacak, Îsâ “aleyhisselâm” gökden inecek, Deccâl çıkacak, (Ye’cûc ve Me’cûc) denilen insanlar yeryüzüne yayılacakdır. Ali  Müttekî  Hindî  hazretleri  de; Mehdîyi  âhır  zaman adlı  kıymetli eserinde,  âhır  zamanda  hazret-i  Mehdî’nin,  geleceğini  uzun  olarak anlatmaktadır. Bu kitapda, hazret-i Mehdî’nin bir çok alâmetleri yazılmıştır. Bunlardan bâzıları şunlardır: 1- Kıyamet  kopmadan  önce,  Mehdî  muhakkak  gelecektir.  Ebü  Sa’îd-i Hudrî’den rivayet edilen hadîs-i şerîfde buyruldu ki: “Benim ümmetimden Mehdî gelecektir. Ömrü uzasa da kısalsa da, altı, yedi, sekiz veya dokuz yıl saltanat sürecektir. Daha önce zulümle dolu olan dünyâyı, adaletle dolduracaktır...” 2- Hazret-i  Mehdî,  yeryüzünün  zulürn  ve  fitnelerle  dolu  olduğu  bir zamanda gelip, dünyâyı adaletle dolduracaktır. Hadîs-i şerîfte buyruldu ki: “Âhır zamanda, ümmetimin başına sultanlardan şiddetli belâlar gelir. Öyle  ki,  yerler  müslümanlara  dar  gelir.  O  zaman  Allahü teâlâ,  daha önce zulümle dolu olan dünyâyı adaletle dolduran, benim soyumdan birisini  gönderecektir.  O  zaman  gökyüzü  yağmur  damlasını esirgemeyecek, yer de bereketlenecektir. O, dünyâda altı, yedi, sekiz veya dokuz yıl hüküm sürecektir.” 3- Hazret-i Mehdî’nin ismi Muhammed  olup,  hazret-i Fâtıma evlâdından olacaktır. Hadîs-i şerîfde de buyruldu ki: “Mehdî’nin adı Muhammed’dir. Mehdî benim neslimdendir ve Fâtıma’nın evlâdındandır.” 4- Hazret-i Mehdî’nin özellikleri hakkında hadîs-i şerîfde; “Mehdî benim evlâdımdandır.  Yüzü  nurlu,  alnı  açıktır.  Burnunun  üst  tarafı yüksekçedir.  Yeryüzünü  adalet  ve  doğrulukla  doldurur.  Nitekim ondan önce dünyâ, zulüm ve cefâ ile dolu olur..” buyruldu. 5- Hazret-i Mehdî gelmeden önce, fitne fesâd çok olacaktır. Hakem bin Uyeyne’den  rivayet  edilir:  O  dedi  ki:  Ben  Seyyid  Muhammed  bin  Ali’ye “İşittiğimize göre sizden (peygamberimizin soyundan) bir zât çıkıp, bu ümmet arasında adalet yapacak.” O dedi ki: “Biz de insanların umduğunu ummaktayız ve amid ediyoruz ki, dünyâda bir gün bile kalsa, Allahü teâlâ o günü uzatır, tâ ki bu ammetin umduğu olsun. Ancak, ondan önce fitneler görülecektir.  Bu  fitnelerin  içinde  en  şerlisi;  bir  kişinin  mü’min  olarak akşama ermesi, ama sabah kâfir olarak kalkması, mü’min olarak sabahlayıp, kâfir olarak akşama ulaşmasıdır.” 6- O zaman açıkça Allahü teâlâyı inkâr eden kişiler çok olacaktır. Hadîs-i şerîfde buyruldu ki: “Açıkça Allahü teâlâ inkâr edilmedikçe, Mehdî’ye 7- Hazret-i  Mehdî  çıkacağı  zaman,  sünnetler  unutulup,  bid’atler yaygınlaşmış olacaktır. Hadîs-i  şerîfde; “Kıyamete  yakın  mü’minlerin  kalbi;  ölüm,  açlık, fitneler, sünnetlerin kaybolması, bid’atlerin yaygınlaşması, emr-i  bil- ma’rûf  ve  nehy-i     anil-münkerin  terkedilmesi  gibi  sebeplerle zayıfladığı  zaman,  benim  evlâdımdan  Muhammed  bin  Abdullah’la (Mehdî), cenâb-ı Hak, sünnetleri ihya eder. Onun adalet ve bereketiyle, mü’minlerin kalbi ferahlar. Acem ve Arab milletleri arasında ülfet ve muhabbet  yerleşir.  Bu  durum  bir  müddet  devam  ettikten  sonra,  o vefât eder” buyruldu. Hazret-i  Mehdî,  Îsâ  aleyhisselâmla  buluşacak;  Îsâ  aleyhisselâm  onun arkasında namaz kılacaktır. İmâm-ı Rabbânî hazretleri, buyudu ki: “Mehdî hakkında, şeyh ibni Hacer bir risâle yazmışdır. Alâmeti ikiyüze bâliğ olur [ulaşır].” “Mehdî aleyhirrahme nübüvvet yolu ile vâsıl olmuş, kavuşmuşdur.” “Hakîkat-i Mehdî, sıfat-ül-ilmdir [ilim sıfatıdır.” “Mehdî’nin gelişi, yüzyıl başında olacakdır. Dahâ evvel doğuda, kuyruklu yıldız görülecekdir.” Fütûhât-ül-Mekkiyye  kitâbının  sâhibi  Muhyiddîn-i  Arabî  “rahmetullahi aleyh”  Mehdîden  “aleyhirrahme”  bahs  ederken  şöyle  bildirmişdir: Mehdî’nin  “aleyhirrahme”  yanında  ricâlullahdan  kâmil  ve  çok  ilm  sâhibi üçyüz  altmış  kişi  bulunacakdır  “eyyedekellahu  ve  iyyânâ”.  Allahü  teâlâ yeryüzünde bir halîfe yaratır. Yeryüzü zulmle dolmuş iken, o yer yüzünü adâletle  doldurur.  fâyet  dünyânın  bir  gün  ömrü  kalsa  bile,  Resûlullahın nesebinden olan o zât ortaya çıkıncaya kadar Allahü teâlâ o günü uzatır. O zât  hazret-i  Fâtıma  “radıyallahü  anhâ”  evlâdındandır.  İsmi  Resûlullahın “sallallahü aleyhi ve sellem” ismine, künyesi de künyesine uyar. Onun ceddi Hasen bin Alîdir “radıyallahü anhümâ”. Kâ’bede Hacer-ül Esved rüknü ile makâm-ı  İbrâhîm  arasında  Ona  bî’at  edilir.  Yaratılışı,  bedeni,  Resûlullaha “sallallahü aleyhi ve sellem” benzer. Ancak ahlâkı aynı derecede olmaz. Hiç kimse  huluk,  huy  bakımından  Resûlullahın  “sallallahü  aleyhi  ve  sellem” derecesine  ulaşamaz.  Çünki,  Allahü  teâlâ  [Kalem  sûresi  4.cü  âyetinde meâlen] (fübhesiz ki sen huluk-ı azîm üzeresin) buyurdu. Hakîkat ehli, keşf ve  şühûd  sâhibi  ârifler  ona  bî’at  ederler.  Allah  adamları  onun  da’vetine icâbet ederler ve ona yardımcı olurlar. Memleketin yükünü çekmekde ve Allahü  teâlânın  ona  yüklediği  sorumlulukda  ona  yardımcı  olurlar.  Allahü teâlâ,  başkalarından  gizlediği,  keşf  ve  şühûd  yoluyla,  hakîkatlere  muttali’ kıldığı kullarını, ona vezîrler, yardımcılar yapar. O da onlarla istişâre ederek isâbetli  kararlar  verir.  Çünki  Onlar,  hakîkatı  bilen  âriflerdir.  Mehdî  de “aleyhirrahme” lâzım olduğu kadar herşeye Allahü teâlâ tarafından muttali’ kılınır.  Çünki,  o  kendisine hak  bildirilmiş  olan  bir  halîfedir.  Hayvânların konuşmalarını anlar. Adâleti insanlar ve cinler arasında yayılır.” Yine  nakledilen  hadîs-i  şerifde  ve  hazret-i  Alî’nin  “radıyallahü  anh” sözünde,  Mehdî’nin  “aleyhirrahme”  âhır  zemânda  geleceği,  zulm  ile  dolu olan yeryüzünü adâletle dolduracağı bildirildi. Mehdînin ismi Muhammed, babasının  ismi  Abdullah  olacakdır.  Hazret-i  Alînin  “radıyallahü  anh” neslinden olacak, künyesi de hazret-i Hüseynin “radıyallahü anh” künyesi gibi Ebû Muhammed olacakdır. Hadîs-i şerîfde buyruldu ki: “Mehdî, bu ümmettendir ve Îsâ’ya imâm olacaktır.” Kendisinde bu alâmetlerin hiç biri bulunmadığı hâlde, târihte değişik  zamanlarda  Mehdî  olduğunu  iddia  eden  birçok  kimseler,  çeşitli maksatlarla ortaya çıkmıştır. Bunlar bâzı câhilleri etraflarında toplamışlarsa da,  islâm  âlimleri  ve  sâlih  müslümanlar  tarafından  bunlara  lüzumlu cevaplar  verilmiş,  fitneleri  önlenmiş  ve  isimleri  unutulmuştur.  Geleceği bildirilen Mehdî’nin alâmetleri meydandadır ve bunlar açıkça bildirilmiştir. Bu  ölçülere  göre  ve  alâmetleri  belli  iken  hiç  alâkası  bulunmayan  çeşitli kimseleri Mehdî sanmak ve Mehdî demek, doğru yoldan ayrılmak olur. İmâm-ı  Rabbânî  hazretleri, Mektûbât’ının  ikinci  cild,  altmış  yedinci mektubunda şöyle buyurmaktadır: “Hindistan’da birisi, Mehdî olduğunu iddia etmişti. Bir çok câhiller de, ona  inanmıştı.  Bunlara  göre,  Mehdî  gelmiş  ve  ölmüş,  mezarı  da  Fere şehrinde  imiş.  Meşhûr,  hattâ  mânâsı  tevatür  derecesine  varmış  birçok hadîs-i  şerîfler,  böylelerinin  bu  îtikâd  ve  sözlerini  yalanlamaktadır. [Memleketimizde de, bazı câhiller, tasavvuf kitâblarından tercüme ederek söyliyen  ve  yazan  kimselere  Mehdî  diyor.  Bunları,  kendileri  yazıyor sanıyorlar.] Hâlbuki birçok hadîs-i şerîflerde buyruldu ki: “Mehdî’nin başı hizasında bir bulut olacaktır. Buluttan  bir  melek; “Bu Mehdîdir, sözünü dinleyiniz!” diyecektir.” “İsmini duyduğunuz kimselerden, yeryüzüne dört kişi mâlik oldu. İkisi  mü’min,  ikisi  de  kâfir  idi.  Mü’min  olan  iki  kişi,  Zülkarneyn  ile Süleyman (aleyhisselâm) idi.  Kâfir  olan  ikisi  de,  Nemrûd ile Buhtunnasar  idi.  Beşinci  olarak,  yeryüzüne,  benim  evlâdımdan  biri yâni Mehdî de mâlik olacaktır.” “Kıyamet  kopmadan  önce,  Allahü  teâlâ,  benim  evlâdımdan  birini yaratır ki, ismi, benim ismim gibi, babasının ismi, benim babamın ismi gibi  olur  ve  dünyâyı adaletle  doldurur.  Ondan  önce  dünyâ  zulümle dolu iken, onun zamanında adalet ile dolar.” “Eshâb-ı  kehf, (hazret-i) Mehdî’nin  yardımcıları  olacaktır  ve  Îsâ (aleyhisselâm) bunun  zamanında  gökten  inecektir.  Îsâ (aleyhisselâm), Deccâl ile harb ederken,  (hazret-i) Mehdî, onunla (Îsâ aleyhisselâm ile) beraber  olacaktır.  Bunun  hükümdarlığı  zamanında,  her  zamankinin aksine  ve  hesâbların  tersine  olarak,  Ramazân-ı  şerîfin  on dördüncü günü güneş tutulacaktır ve birinci gecesinde ay tutulacaktır.” O hâlde, insâf etsinler ki, bu alâmetler, [câhillerin, Mehdî zan etdikleri kimselerde ve] o ölen adamda var mıdır, yok mudur. fiir: Büyük alâmet Deccâldir, çıkacagı yer, Horasân. Sonra, Sâmdaki Câmi’e Îsâ inecek semâdan. Bir hadîsde buyuruldu, (Kızım Fâtıma evlâdından, Babası Abdullah olan, Mehdî adında bir civân. Çıkıp dine kuvvet verir, cihâna yayılır îmân, Îsâ aleyhisselâmla, birleserek ol pehlivân. Deccâlı da öldürürler, dünyâ dolar adl-ü emân. Ye’cüc Me’cüc adındaki, kavim çıkar sed ardından.', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.135544', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Fâtıma-tüz-zehrâ  soyundan, âhir  zamanda kıyamete  yakın dünyâya gelecek,  islâmiyeti  yeryüzüne  hâkim  kılacak,  Peygamber  efendimiz tarafından haber verilen zât. Peygamber efendimizin kızı hazret-i Fâtıma’nın oğlu hazret-i Hüseynin neslinden  gelecek  yani  Seyyid  olacak,  Medîne-i  münevverede  doğacak  ve Mekke-i  mükerremede  ortaya  çıkıp  tanınacaktır.  İsmi  Muhammed, babasının ismi Abdullah olacaktır. İlimde ve evliyâlıkta derecesi çok yüksek olup  müceddîd  ve  müctehid  olacaktır. Îsâ  aleyhisselâmla  buluşacak, mezhebleri  kaldıracak, kendi içtihadı ile  bir  mezheb  kuracaktır. Kuracağı mezhebin hükümlerinin, Hanefî hükümlerine uygun olacağını, büyük İslâm âlimi  İmâm-ı  Rabbânî  hazretleri  haber  vermektedir.  Bütün  müslümanlar, hazret-i  Mehdî’ye  tâbi  olacak, her  yeri  alacak,  her  yerde  adâlet  olacak, yeryüzünün  tamâmına  hâkim  olacaktır. Çok  âdil  olacak,  hiçbir  mahlûk arasında  düşmânlık  kalmıyacakdır.  Eshâb-ı  Kehf  uyanıp,  mağaradan çıkacak, Mehdî’nin askeri olacak, Mehdî’ye hizmet edecekdir. İbni    Hacer-i  Mekkînin “Alâmet-ül-Mehdî” kitâbında  ve  Süyûtînin “Cüz’ün  minel  ehâdîs  velâsâril  vârideti  fî  alâmetil  mehdî” kitâbında bunlardan ikiyüze yakın alâmet yazılıdır. “El-fütûhât-ül-islâmiyye” ikinci cüz, ikiyüzdoksanyedinci sahîfesinde diyor ki, “Beklenilen Mehdî, hazret-i Fâtımanın  soyundan  olacakdır.  Mekkede zuhûr  edecekdir.  O  zemân, müslimânlar halîfesiz olacakdır. İstemediği hâlde, zor ile halîfe yapılacakdır. Zuhûr edeceği zemân ve yaşı ve ömrü kesin belli değildir.” Mehdî çıkacağı zemân  yeryüzünde  halîfe  bulunmıyacağı  ve  Mehdîliklerini  i’lân  edenlerin Mehdî  olmadıkları,  buradan  anlaşılmakdadır. İmâm-ı  Rabbânî  hazretleri, birinci  cildin  ikiyüzellibeşinci  mektûbunda,  Mehdî’nin  Medîne’deki  sapık din adamlarını öldüreceğini yazmakdadır. Hazret-i Mehdî geldiğinde, hak mezheplerin hükmü unutulmuş olacak, bid\'at mezhepleri ortalığı kaplayacak, ortada hak bir mezhep kalmayacaktır. Yani  mezheplerin  doğru  bilgileri  kalmayacak,  sadece  isimleri  kalıp,  din düşmanları veya sapıklar tarafından bu isimler suistimal edilecektir. Hazret-i  Mehdî,  ictihad  edecek,  ictihadı Hanefi   mezhebine   uygun olacaktır. Zaten İsa aleyhisselamın Hristiyanlığı yasak ettiği gibi, Hazret-i Mehdî de diğer bozuk fırkaları, bozuk mezhepleri yasak edecektir. Bozuk mezhepleri kaldıracağı için mezhepleri kaldıracak ifadesi kullanılmıştır. İmam-ı  Rabbani  hazretleri  buyuruyor  ki:  İşitdiğimize  göre,  hazret-i Mehdî,  hükûmet  sürdüğü  ze­mân,  dîni  yayarken  ve  sünneti  diriltirken, bid’at işlemeğe alışmış olan Medînedeki âlim, bid’ati güzel sandığı ve ibâdet olarak yapdığı için, haz­ret-i Mehdînin emrlerine şaşarak, (Bu adam, bizim dînimizi  yok  etdi  ve  milletimizi  öldürdü)  diyecekdir.  Hazret-i  Mehdî “rahmetullahi  aleyh”  bu  âlimi  öldürecekdir.  Onun  güzel  sandığı  bid’atin, kötü olduğunu bildirecekdir. Mehdî  “rahime-hullahü  teâlâ”  Deccâl’ı  öldürdükden  sonra,  Mekke’ye, Medîne’ye giderek, binlerle vehhâbî din adamını kılınçdan geçireceği hadîs-i şerîfde açıkça bildirilmekdedir. İmam-ı  Rabbani  hazretleri  buyuruyor  ki:  Resulullahın  vefatından  bin sene  geçtikten  sonra,  ümmetinden  gönderilen  âlimlerin  sayısı  azsa  da, İslamiyet’i tam kuvvetlendirmeleri için, çok yüksek olacaklardır. Resulullah efendimiz,  hazret-i  Mehdî’nin  geleceğini  haber  vermiştir.  Bin  sene  sonra gelecektir. İsa aleyhisselam da, bin sene sonra, gökten inecektir. Bin sene sonra  gelen  Evliyanın  yükseklikleri,    Eshab-ı  kiramın  yüksekliklerine “Mehdî geleceğine inanmıyan kâfir olur” denildi. Mehdînin alâmetlerini Resûlullah  “sallallahü  aleyhi  ve  sellem”  efendimiz  bildirmişdir. Hazret-i Mehdî’nin  gedeceğini  ve  yapacağı  işleri  haber  veren  bir  çok  hadîs-i  şerîf vardır.  Ebû  Sa’îd-i  Hudrî’nin  (radıyallahü  anh)  rivayet  ettiği  hadîs-i şerîflerde buyruldu ki: “Yeryüzü  zulüm  ve  düşmanlıkla  dolduktan  sonra,  benim  Ehl-i beytimden  mutlaka  birisi  çıkar.  Dünyâ  daha  önce  nasıl  zulüm  ve düşmanlık ile dolu ise, o, dünyâyı adaletle doldurur.” “Ümmetim,  bal  arılarının  beyleri  etrafında  toplanması  gibi, Mehdî’ye sığınırlar. O daha önce zulümle dolu olan dünyâyı adaletle doldurur. Uykuda olan uyandırılmaz ve bir damla bile kan dökülmez.” İbn-i  Mes’ûd’dan  rivayet  edilen  bir  hadîs-i  şerîfde  de  şöyle  buyruldu: “Mehdî ile müjdelenmiş olunuz. Mehdî, Kureyş kabilesinden ve benim Ehl-i beytimden biridir. O, insanların ihtilâf içinde oldukları ve ictimâî sarsıntılar içinde bulundukları bir zamanda çıkar. Mehdî, daha önce zulüm  ve  cevr  ile  dolu  olan  dünyâyı,  adalet  ve  insaf  ile  doldurur. Ondan  yer  ve  gök  ehli (insanlar,  cinler  ve  melekler) razıdır.  O,  malı insanlar arağında adaletle dağıtır. Ümmet-i Muhammed’in kalblerini zenginlik  île  doldurur  ve  onları  adaletiyle  kuşatır.  O  kadar  ki,  bir münâdîye; “Kimin ihtiyâcı varsa bana gelsin” diye nida (îlân) etmesi emrolunduğunda,  bir  kişiden  başka  kimse  gelmez.  O  kimse  istekte bulunur.  Mehdî (rahmetullahi   aleyh) de  ona;  “Hazinedara  git  sana versin”  der.  O  kişi,  hazinedara  gidip,  Mehdî’nin (aleyhirrahme) gönderdiğini söyleyip, hazinedardan götürmeye gücünün yettiği kadar mal alır. Fakat daha sonra pişman olarak; “Ben, herkesden daha mı muhtacım, kimse gitmedi, ben gittim!” diyerek aldığı malı iade etmek ister, o zaman hazinedar; “Biz verdiğimizi geri almayız” der. Bu devir; altı, yedi, sekiz veya dokuz sene devam eder. Bundan sonraki hayatta, Târihte bâzı câhiller, büyük zannettikleri kimselere Mehdî demişlerdir. Mehdî’nin  alâmetlerini  Resûlullah  efendimiz  (sallallahü  aleyhi  ve  sellem) bildirmiştir. İbn-i  Hacer-i Mekkî hazretlerinin Alâmât-ül-Mehdî kitabında ve İmâm-ı Süyûtî’nin El-Bürhân kitabında, bu alâmetlerden iki yüze yakını yazılıdır.  Büyük  âlim  Ahmed  Zeynî  Dahlân, Fütûhât-ül-İslâmiyye adlı eserinin,  ikinci  cüz,  297.  sayfasında  diyor  ki:  “Beklenilen  Mehdî  hazret-i Fâtıma’nın  soyundan  olacaktır.  Mekke’de  zuhur  edecektir.  O  zaman, müslümanlar  halisesiz  olacaktır.  O  istemediği  hâlde,  zor  ile  halîfe yapılacaktır.  Zuhur  edeceği  zaman,  yaşı  ve  ömrü  kesin  olarak  bildirilmiş İmâm-ı Rabbânî hazretleri, Mehdî’nin, Medîne’deki sapık din adamlarını öldüreceğini yazmakta ve şöyle buyurmaktadır: “Hazret-i Mehdî, hükümet sürdüğü  zaman,  dîni  yayarken  vesünnetleri  ortaya  çıkarırken,  bid’at işlemeğe  alışmış  olan  Medîne’deki  âlim  tanınan  bir  kimse,  bid’ati  güzel sandığı ve ibâdet olarak yaptığı için, hazret-i Mehdî’nin emirlerine şaşarak; “Bu  adam,  bizim  dînimizi  yok  etti  ve  milletimizi  öldürdü”  diyecektir.” Hazret-i  Mehdî,  bu  kimseyi  öldürüp,  onun  güzel  sandığı  bid’atlerin kötülüğünü insanlara bildirecektir.” (Cild-1, mektub: 255) İmâm-ı  Rabbânî  (rahmetullahi  aleyh),  yine  buyuruyor  ki:  “Hadîs-i şerîfde; “Yeryüzünü küfür kaplamadıkça ve her yerde küfür ve kâfirlik yayılmadıkça,  hazret-i  Mehdî  gelmez”buyruldu.  Bundan  anlaşılıyor  ki, hazret-i Mehdî çıkmadan evvel, küfür ve kâfirlik her tarafa yayılacak, İslâm ve müslümanlar garîb olacaktır. Peygamberimiz sallallahü aleyhi ve sellem âhır zamanda, müslümanların garîb olacaklarını haber vermiştir.” (Cild-2, İbn-i  Hacer-i Mekkî Heytemî hazretleri El-Kavl-ül-muhtasar fî alâmet- il-Mehdî kitabında şöyle buyurdu: “Mehdî, Ehl-i beytten olacaktır. Hazret-i Hüseyn’in  neslinden  gelecektir,  ismi,  Resûlullah  efendimizin  ism-i şerîflerinden yâni Muhammed olacaktır. Babasının ismi de, Resûl-i ekremin mübârek  babasının  ismi  gibi  Abdullah  olacaktır.  Hazret-i  Mehdî’nin  alnı geniş ve dişleri seyrektir.” Hadîs-i şerîflerde buyruldu ki: “Mehdî’nin  babasının  ismi  Abdullah’dır  ve  Eshâb-ı  Kehf  arkadaşı “Eshab-ı  Kehf,  Mehdî’nin  yardımcıları  olacak  ve  İsâ  bunun  zamanında gökten inecek ve Deccâl ile harb ederken, Mehdî, onunla beraber olacaktır.) “Horasan  tarafından  gelen  siyah  sancaklılara  katılın.  Onların  içinde Allah\'ın halifesi Mehdî vardır.) [Hakîm, İmâm-ı Ahmed, Deylemî] “Horasan  tarafından  gelen  siyah  sancaklılara  katılın.  Onların  içinde Allah\'ın halifesi Mehdî vardır.” [Hakîm, İmâm-ı Ahmed, Deylemî] “Nasıl helak olur bir ümmet ki, başında ben, sonunda Meryem oğlu İsa ve ortasında da ehl-i beytimden Mehdî vardır.” [Hâkim, İbni Asâkir] “farktan çıkan bir grup, Mehdî’ye yardım ederler.” [İbni Mâce, Taberânî] “Mehdî  çıkınca,  Allahü  teâlâ  ona  rahmetini  indirir.”  [İmâm-ı  Ahmed, “Mehdî gelince, bir bereket olacak, ümmetim rahat edecektir.”[İbni Ebî “Mehdî bendendir, yeryüzünü hak ve adaletle doldurur.” [Ebû Davud] “Mehdî, Kureyşten ve ehl-i beytimdendir.” [İmâm-ı Ahmed, Baverdi] “Mehdî ehl-i beyttendir. Allahü teâlâ onu bir gecede olgunlaştırır.”[İbni Mâce, İmâm-ı Ahmed] “Deccal’ın  veya  Mehdî’nin  geleceğine  inanmayan  kâfir  olur.”  [Fevâid-il Ehbar - ferh’is-Siyer] “Mehdî benim soyumdandır.” [İbni Mâce] “Mehdî evladı Fâtıma’dandır.” [Ebu Davud, Hakîm] Kütüb-i sitteden Buhari, Müslim, Ebu Davud, İbni Mâce, Tirmizi ve diğer hadis âlimlerinin bildirdikleri bu hadis-i şerifleri ve Ehl-i sünnet âlimlerinin açıklamalarını akıl ve iman sahibi hiç kimse inkâr edemez. Tevil etmek de dinimize aykırıdır. Herkes dinin hükümlerini tevil etmeye kalkarsa ortada din diye bir şey kalmaz. “Nefsim  yed-i  kudretinde  olan  Allahü  teâlâya  yemin  ederim  ki, Allahü  leâlâ  benim  neslimden,  dişleri  aralıklı,  alnı  acık,  yeryüzünü adaletle dolduracak, malı ve mülkü insanlara bol bol ikram edecek bir evlâdımı gönderecektir. Zulüm ve fıskla dolu olan dünyâ, o geldikten sonra adaletle dolup taşacaktır.” “Mehdî’nin başı hizasında bir bulut olacaktır. Buluttan bir melek; “Bu Mehdî’dir. Sözünü dinleyiniz!” diyecektir. Hazret-i  Mehdî’nin  alâmetlerinden  biri  de,  Deccal’in  onun  zamanında ortaya  çıkmasıdır.  Hadîs-i  şerîfde; “On  büyük  alâmet  görülmeyince kıyamet  kopmaz;  Duhân,  Deccâl,  Dâbbel-ül-erd,  güneşin  batıdan doğması,  Îsâ’nın (aleyhisselâm) gökten  inmesi,  Ye’cüc  ve  Me’cüc’ün çıkması, doğuda, batıda ve Arabistan’da yer batması, bunlardan sonra Yemen’den bir ateş çıkıp, halkı bir araya getirecektir” buyruldu. Muhbir-i sâdık [ya’nî hep doğru haber verici] “sallallahü teâlâ aleyhi ve sellem”  kıyâmet  alâmetlerinden  her  ne  haber  verdi  ise,  hepsi  doğrudur. Yanlışlık  olamaz.  O  zemân  güneş,  âdet  dışı  olarak  garbdan  doğacakdır. Hazret-i Mehdî “aleyhirrıdvân” çıkacak, Îsâ “aleyhisselâm” gökden inecek, Deccâl çıkacak, (Ye’cûc ve Me’cûc) denilen insanlar yeryüzüne yayılacakdır. Ali  Müttekî  Hindî  hazretleri  de; Mehdîyi  âhır  zaman adlı  kıymetli eserinde,  âhır  zamanda  hazret-i  Mehdî’nin,  geleceğini  uzun  olarak anlatmaktadır. Bu kitapda, hazret-i Mehdî’nin bir çok alâmetleri yazılmıştır. Bunlardan bâzıları şunlardır: 1- Kıyamet  kopmadan  önce,  Mehdî  muhakkak  gelecektir.  Ebü  Sa’îd-i Hudrî’den rivayet edilen hadîs-i şerîfde buyruldu ki: “Benim ümmetimden Mehdî gelecektir. Ömrü uzasa da kısalsa da, altı, yedi, sekiz veya dokuz yıl saltanat sürecektir. Daha önce zulümle dolu olan dünyâyı, adaletle dolduracaktır...” 2- Hazret-i  Mehdî,  yeryüzünün  zulürn  ve  fitnelerle  dolu  olduğu  bir zamanda gelip, dünyâyı adaletle dolduracaktır. Hadîs-i şerîfte buyruldu ki: “Âhır zamanda, ümmetimin başına sultanlardan şiddetli belâlar gelir. Öyle  ki,  yerler  müslümanlara  dar  gelir.  O  zaman  Allahü teâlâ,  daha önce zulümle dolu olan dünyâyı adaletle dolduran, benim soyumdan birisini  gönderecektir.  O  zaman  gökyüzü  yağmur  damlasını esirgemeyecek, yer de bereketlenecektir. O, dünyâda altı, yedi, sekiz veya dokuz yıl hüküm sürecektir.” 3- Hazret-i Mehdî’nin ismi Muhammed  olup,  hazret-i Fâtıma evlâdından olacaktır. Hadîs-i şerîfde de buyruldu ki: “Mehdî’nin adı Muhammed’dir. Mehdî benim neslimdendir ve Fâtıma’nın evlâdındandır.” 4- Hazret-i Mehdî’nin özellikleri hakkında hadîs-i şerîfde; “Mehdî benim evlâdımdandır.  Yüzü  nurlu,  alnı  açıktır.  Burnunun  üst  tarafı yüksekçedir.  Yeryüzünü  adalet  ve  doğrulukla  doldurur.  Nitekim ondan önce dünyâ, zulüm ve cefâ ile dolu olur..” buyruldu. 5- Hazret-i Mehdî gelmeden önce, fitne fesâd çok olacaktır. Hakem bin Uyeyne’den  rivayet  edilir:  O  dedi  ki:  Ben  Seyyid  Muhammed  bin  Ali’ye “İşittiğimize göre sizden (peygamberimizin soyundan) bir zât çıkıp, bu ümmet arasında adalet yapacak.” O dedi ki: “Biz de insanların umduğunu ummaktayız ve amid ediyoruz ki, dünyâda bir gün bile kalsa, Allahü teâlâ o günü uzatır, tâ ki bu ammetin umduğu olsun. Ancak, ondan önce fitneler görülecektir.  Bu  fitnelerin  içinde  en  şerlisi;  bir  kişinin  mü’min  olarak akşama ermesi, ama sabah kâfir olarak kalkması, mü’min olarak sabahlayıp, kâfir olarak akşama ulaşmasıdır.” 6- O zaman açıkça Allahü teâlâyı inkâr eden kişiler çok olacaktır. Hadîs-i şerîfde buyruldu ki: “Açıkça Allahü teâlâ inkâr edilmedikçe, Mehdî’ye 7- Hazret-i  Mehdî  çıkacağı  zaman,  sünnetler  unutulup,  bid’atler yaygınlaşmış olacaktır. Hadîs-i  şerîfde; “Kıyamete  yakın  mü’minlerin  kalbi;  ölüm,  açlık, fitneler, sünnetlerin kaybolması, bid’atlerin yaygınlaşması, emr-i  bil- ma’rûf  ve  nehy-i     anil-münkerin  terkedilmesi  gibi  sebeplerle zayıfladığı  zaman,  benim  evlâdımdan  Muhammed  bin  Abdullah’la (Mehdî), cenâb-ı Hak, sünnetleri ihya eder. Onun adalet ve bereketiyle, mü’minlerin kalbi ferahlar. Acem ve Arab milletleri arasında ülfet ve muhabbet  yerleşir.  Bu  durum  bir  müddet  devam  ettikten  sonra,  o vefât eder” buyruldu. Hazret-i  Mehdî,  Îsâ  aleyhisselâmla  buluşacak;  Îsâ  aleyhisselâm  onun arkasında namaz kılacaktır. İmâm-ı Rabbânî hazretleri, buyudu ki: “Mehdî hakkında, şeyh ibni Hacer bir risâle yazmışdır. Alâmeti ikiyüze bâliğ olur [ulaşır].” “Mehdî aleyhirrahme nübüvvet yolu ile vâsıl olmuş, kavuşmuşdur.” “Hakîkat-i Mehdî, sıfat-ül-ilmdir [ilim sıfatıdır.” “Mehdî’nin gelişi, yüzyıl başında olacakdır. Dahâ evvel doğuda, kuyruklu yıldız görülecekdir.” Fütûhât-ül-Mekkiyye  kitâbının  sâhibi  Muhyiddîn-i  Arabî  “rahmetullahi aleyh”  Mehdîden  “aleyhirrahme”  bahs  ederken  şöyle  bildirmişdir: Mehdî’nin  “aleyhirrahme”  yanında  ricâlullahdan  kâmil  ve  çok  ilm  sâhibi üçyüz  altmış  kişi  bulunacakdır  “eyyedekellahu  ve  iyyânâ”.  Allahü  teâlâ yeryüzünde bir halîfe yaratır. Yeryüzü zulmle dolmuş iken, o yer yüzünü adâletle  doldurur.  fâyet  dünyânın  bir  gün  ömrü  kalsa  bile,  Resûlullahın nesebinden olan o zât ortaya çıkıncaya kadar Allahü teâlâ o günü uzatır. O zât  hazret-i  Fâtıma  “radıyallahü  anhâ”  evlâdındandır.  İsmi  Resûlullahın “sallallahü aleyhi ve sellem” ismine, künyesi de künyesine uyar. Onun ceddi Hasen bin Alîdir “radıyallahü anhümâ”. Kâ’bede Hacer-ül Esved rüknü ile makâm-ı  İbrâhîm  arasında  Ona  bî’at  edilir.  Yaratılışı,  bedeni,  Resûlullaha “sallallahü aleyhi ve sellem” benzer. Ancak ahlâkı aynı derecede olmaz. Hiç kimse  huluk,  huy  bakımından  Resûlullahın  “sallallahü  aleyhi  ve  sellem” derecesine  ulaşamaz.  Çünki,  Allahü  teâlâ  [Kalem  sûresi  4.cü  âyetinde meâlen] (fübhesiz ki sen huluk-ı azîm üzeresin) buyurdu. Hakîkat ehli, keşf ve  şühûd  sâhibi  ârifler  ona  bî’at  ederler.  Allah  adamları  onun  da’vetine icâbet ederler ve ona yardımcı olurlar. Memleketin yükünü çekmekde ve Allahü  teâlânın  ona  yüklediği  sorumlulukda  ona  yardımcı  olurlar.  Allahü teâlâ,  başkalarından  gizlediği,  keşf  ve  şühûd  yoluyla,  hakîkatlere  muttali’ kıldığı kullarını, ona vezîrler, yardımcılar yapar. O da onlarla istişâre ederek isâbetli  kararlar  verir.  Çünki  Onlar,  hakîkatı  bilen  âriflerdir.  Mehdî  de “aleyhirrahme” lâzım olduğu kadar herşeye Allahü teâlâ tarafından muttali’ kılınır.  Çünki,  o  kendisine hak  bildirilmiş  olan  bir  halîfedir.  Hayvânların konuşmalarını anlar. Adâleti insanlar ve cinler arasında yayılır.” Yine  nakledilen  hadîs-i  şerifde  ve  hazret-i  Alî’nin  “radıyallahü  anh” sözünde,  Mehdî’nin  “aleyhirrahme”  âhır  zemânda  geleceği,  zulm  ile  dolu olan yeryüzünü adâletle dolduracağı bildirildi. Mehdînin ismi Muhammed, babasının  ismi  Abdullah  olacakdır.  Hazret-i  Alînin  “radıyallahü  anh” neslinden olacak, künyesi de hazret-i Hüseynin “radıyallahü anh” künyesi gibi Ebû Muhammed olacakdır. Hadîs-i şerîfde buyruldu ki: “Mehdî, bu ümmettendir ve Îsâ’ya imâm olacaktır.” Kendisinde bu alâmetlerin hiç biri bulunmadığı hâlde, târihte değişik  zamanlarda  Mehdî  olduğunu  iddia  eden  birçok  kimseler,  çeşitli maksatlarla ortaya çıkmıştır. Bunlar bâzı câhilleri etraflarında toplamışlarsa da,  islâm  âlimleri  ve  sâlih  müslümanlar  tarafından  bunlara  lüzumlu cevaplar  verilmiş,  fitneleri  önlenmiş  ve  isimleri  unutulmuştur.  Geleceği bildirilen Mehdî’nin alâmetleri meydandadır ve bunlar açıkça bildirilmiştir. Bu  ölçülere  göre  ve  alâmetleri  belli  iken  hiç  alâkası  bulunmayan  çeşitli kimseleri Mehdî sanmak ve Mehdî demek, doğru yoldan ayrılmak olur. İmâm-ı  Rabbânî  hazretleri, Mektûbât’ının  ikinci  cild,  altmış  yedinci mektubunda şöyle buyurmaktadır: “Hindistan’da birisi, Mehdî olduğunu iddia etmişti. Bir çok câhiller de, ona  inanmıştı.  Bunlara  göre,  Mehdî  gelmiş  ve  ölmüş,  mezarı  da  Fere şehrinde  imiş.  Meşhûr,  hattâ  mânâsı  tevatür  derecesine  varmış  birçok hadîs-i  şerîfler,  böylelerinin  bu  îtikâd  ve  sözlerini  yalanlamaktadır. [Memleketimizde de, bazı câhiller, tasavvuf kitâblarından tercüme ederek söyliyen  ve  yazan  kimselere  Mehdî  diyor.  Bunları,  kendileri  yazıyor sanıyorlar.] Hâlbuki birçok hadîs-i şerîflerde buyruldu ki: “Mehdî’nin başı hizasında bir bulut olacaktır. Buluttan  bir  melek; “Bu Mehdîdir, sözünü dinleyiniz!” diyecektir.” “İsmini duyduğunuz kimselerden, yeryüzüne dört kişi mâlik oldu. İkisi  mü’min,  ikisi  de  kâfir  idi.  Mü’min  olan  iki  kişi,  Zülkarneyn  ile Süleyman (aleyhisselâm) idi.  Kâfir  olan  ikisi  de,  Nemrûd ile Buhtunnasar  idi.  Beşinci  olarak,  yeryüzüne,  benim  evlâdımdan  biri yâni Mehdî de mâlik olacaktır.” “Kıyamet  kopmadan  önce,  Allahü  teâlâ,  benim  evlâdımdan  birini yaratır ki, ismi, benim ismim gibi, babasının ismi, benim babamın ismi gibi  olur  ve  dünyâyı adaletle  doldurur.  Ondan  önce  dünyâ  zulümle dolu iken, onun zamanında adalet ile dolar.” “Eshâb-ı  kehf, (hazret-i) Mehdî’nin  yardımcıları  olacaktır  ve  Îsâ (aleyhisselâm) bunun  zamanında  gökten  inecektir.  Îsâ (aleyhisselâm), Deccâl ile harb ederken,  (hazret-i) Mehdî, onunla (Îsâ aleyhisselâm ile) beraber  olacaktır.  Bunun  hükümdarlığı  zamanında,  her  zamankinin aksine  ve  hesâbların  tersine  olarak,  Ramazân-ı  şerîfin  on dördüncü günü güneş tutulacaktır ve birinci gecesinde ay tutulacaktır.” O hâlde, insâf etsinler ki, bu alâmetler, [câhillerin, Mehdî zan etdikleri kimselerde ve] o ölen adamda var mıdır, yok mudur. fiir: Büyük alâmet Deccâldir, çıkacagı yer, Horasân. Sonra, Sâmdaki Câmi’e Îsâ inecek semâdan. Bir hadîsde buyuruldu, (Kızım Fâtıma evlâdından, Babası Abdullah olan, Mehdî adında bir civân. Çıkıp dine kuvvet verir, cihâna yayılır îmân, Îsâ aleyhisselâmla, birleserek ol pehlivân. Deccâlı da öldürürler, dünyâ dolar adl-ü emân. Ye’cüc Me’cüc adındaki, kavim çıkar sed ardından.');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21623, 'MEHMED EMİN GAZİYANLI', 'Kaşkal', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.136807', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Muş’un meşhur alim ve velilerinden. Babası Abdüllatif Efendidir. 1931 yılında  Gaziyan  köyünde  doğdu. Molla  Azdin sülalesindendir.  İlk  tahsilini babasından aldı. Sonra eski adı Kaşkaldak yeni adı Kıyık köyüne giderek Molla Mustafa Çağlayan’dan okudu. Sonra Diyarbakır ili Varto ilçesinde Hacı Fettah  Efendiden  okudu.  Sonra  Malazgirt  kazasının  Tandürek  köyünde bulunan meşhur  Molla  Zahir’den  okudu. Sonra Muş merkeze  bağlı Tifnik köyünde  bulunan  Muhammed  Mahfuz’dan  okudu.  Bir  müddet  Mehmed Çağla-yan’dan  okudu.  Sonra  Dadina  adıyla  bilinen  Diyadin  köyünde  Mela Selim’den  okuyup  icazet  aldı.  Hocası  ile  beraber  hacca  gitti.  Orada Melekanlı Ebu Bekr Efendiden Nakşi yolunda icazet aldı. Mehmed  Emin  Efendi  ilmi  ve  takvasıyla  tanınan,  halim  selim  bir müslüman idi. Edeb, cömertlik ve ihsanın canlı bir örneği idi. Ona karşı edebsizlik edenlerin hepsi bir vesile ile musibetlere duçar oldular. Mehmed  Emin  efendi  siyasetten  uzak  durmuş  idi.  Eski  dostlarını ziyaret eder helallik dilerdi. Nitekim İstanbul’a gelip, bir çok dostu ile vedalaştı. Bütün ısrarlara rağmen geri dön-meye ısrar etti. Yldürülürsem baba ve dedelerimin yanına defn edin dedi. Mehmed Emin efendi elinin emeği ile çalışarak geçimini temin ederdi. Haksızlığa karşı dururdu. Doğru bildiğini çekinmeden söylerdi. 5 Kasım  1993  günü  başına  kurşun  sıkılarak  şehid  edildi.  Cesedi Muş’un dışında Köykent civarında tanınmaz bir halde bulundu. Vasiyeti gibi defn edildi.');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21624, 'MEHMED RÜŞDÜ ÂŞIKKUTLU', 'Ahme', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.137532', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Son asır kırâat âlimlerinden. Trabzon’un Of ilçesinin Uğurlu (Çifaruksa) kasabasında  1901  târihinde  doğdu.  Babasının  adı  Ahmed  Cemâleddîn, annesinin adı Hanîfe’dir. İlk tahsîlini doğum yeri olan Uğurlu kasabasında babasından yaptı. Daha sonra aynı yerde Kur’ân-ı kerîmi de ezberleyerek hâfız  oldu.  Of  çevresinin  tanınmış  âlimlerinden  Çalıkzâde  Tâhir  Efendi, Çalekli  Dursun  Feyzi  Efendi  ve  Kasımzâde  Hasan  Efendiden  Arapça, Bakkalzâde Paçanlı İsmâil Hakkı’dan feraiz dersleri aldı. Arapça ve ferâiz ilimlerinde kendini yetiştirdi. İmtihanla Çifaruksa Medresesinin dördüncü sınıfına talebe olarak kaydını yaptırdı. Bu medresenin altıncı sınıfındayken, medreseler kapatıldı (1924). Mehmed Rüşdü, okuduğu medrese kapatılınca, bir müddet Dursun Feyzi Efendiden  tefsir,  akâid  ve  fıkıh  okudu.  Daha  sonra  İstanbul’a  gitti. İstanbul’da Ahmed fükrü ve yeğeni Hâfız İsmâil Hakkı Bayrî’den Aşere ve Takrîb, Varnalızâde Hâfız Ahmed Hamdi’den de İbnü’l-Cezerî’nin Tayyibet- ün-Neşr’ini okudu. Mehmed Rüşdü Âşıkkutlu, bu şekilde ilim tahsîlinden sonra, doğum yeri olan  Uğurlu  kasabası  Merkez  Câmiinde  fahri  (ücretsiz)  İmâm-Hatiplik görevinde  bulundu.  1936  yılında  Uğurlu  Kur’ân-ı  Kerîm  Kursu Yğretmenliğine,  1941’de  Of  Merkez  Vâizliğine  tâyin  edildi.  Bu  resmî görevlerini yürütürken, değişik hocalardan öğrendiği kırâat, fıkıh ve Arapça dersler  vermeyi  de  ihmâl  etmedi.  1976  yılında  vaizlikten  emekli  oldu. Diyânet İşleri Başkanlığınca İstanbul (Haseki), Ankara’da açılan hizmet içi eğitim kurslarında 1974-1979 yılları arasında, bütün rivâyet ve tarikleriyle aşere dersi verdi. Tayyibet-ün-Neşr adlı kitabı da aynı eğitim yerlerinde okuttu. Kendi sahasında pekçok öğrenci yetiştiren Mehmed Rüşdü Âşıkkutlu’nun kırâat konusunda Aşere Kaideleri, Tahrib Kaideleri,Tayyibe Tercümesi ve Tayyibe Şerhi isimlerinde eserleri vardır. Fakat bu eserleri basılmamış, Uğurlu’da vârislerinin elinde bulunmaktadır. Âşıkkutlu  hoca  efendi,  Trabzon’dan  İstanbul’a  tedâvî  için  giderken  28 Ağustos  1980  yılında  Uçak’ta vefât  etti.  Mezarı  doğum  yeri  olan  Of’un Uğurlu kasabasındadır.');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21625, 'MEKÂRİM NEHR', 'Irak\'ta yetişen büyük velîlerden. İsmi, Mekârim bin İdris\'tir. Irak\'ta En- Nehr-ul-Hâlis adlı yerde yaşadı. Doğum ve vefât târihleri bilinmemektedir. Kabri orada olup ziyâret edilmektedir. Mekârim hazretleri evliyânın büyüklerinden Ali bin el-Hiytî hazretlerinin mânevî  terbiyelerinde  yetişti.  İlim,  edep  ve  mânevî  yükseklikler  sâhibi zâtlar kendisini övmüştür. Hocası onun hakkında; \"Kardeşim feyh Mekârim cidden  büyük  ve  fazîletli  bir  zâttır.  Lâkin  o  bizden  sonra  anlaşılacaktır.\" Nehr-i  Hâlis  beldesindeki  talebelerin  yetiştirilme  vazîfesi  kendisine verildi. Pek çok kimse gelip talebesi olmakla şereflendi. Hikmetli sözleriyle insanlara hak yolun bilgilerini öğretti. Ebû  Muhammed  bin  İdris  anlatır:  \"Mekârim  hazretleri  bir  gün sevdiklerine  Cehennem\'i  ve  orada  yapılacak  azâbı  anlatıyordu.  Herkes korkmaya  ve  ağlamaya  başladı.  Lâkin  orada  yabancı  birisi  vardı.  O bu anlatılalardan hiç etkilenmedi ve kendi kendine; \"Bu korkutmaktır. Yoksa gerçekten  kimseyi  yakacak  bir  ateş  değildir.\"  diye  mırıldandı.  Mekârim hazretleri onun bu inkârını anlayıp ona Kur\'ân-ı kerîmdeki meâlen; \"Yemin olsun ki, onlara Rabbinin azâbından  bir  nefha  esinti  dokunsa,  elbette derler ki: \"Vay hâlimize biz hakikaten zâlimlerden olmuşuz.\"(Enbiyâ sûresi: 46) âyet-i kerîmesini okudular ve sükût ettiler. Onların susmasıyla oradakilerin hepsi sustu. Bu sırada inkarcının renginin solduğu ve titremeye başladığı  görüldü.  Sonra  da;  \"İmdâd,  imdât!\"  diye  bağırmaya  başladı.  Bu sırada  adamın  burnundan  etrâfa  fenâ  kokulu  bir  duman  çıktı.  Bu  sırada Mekârim  hazretleri  tekrar  Kur\'ân-ı  kerîmde  meâlen; \"Rabbimiz  bizden azâbı kaldır. Şüphe yok ki biz müminleriz.\" (Duhân sûresi:  12)  âyet-i kerîmesini  okudu.  Bunun  üzerine  adam  sükûnete  kavuştu.  Korku  ve endişesi  kalmadı.  Sonra  ayağa  kalkıp  Mekârim  hazretlerinin  ayaklarına kapandı.  Îmân  etti.  Biraz  önce  karşılaştığı  durumunu  anlattı  ve;  \"Ben anlatılanları inkâr edince, içimde ateşten bir kıvılcımın kalbime doğru hızla yaklaştığını  hissettim.  İçim  dumanla  dolmuştu.  Boğulacak  gibi  oldum.  O sırada; \"İşte yalanladığınız ateştir. Bu bir sihir mi? Yoksa siz görmüyor musunuz.\" meâlindeki  (Tûr  sûresi:  14)  kelâmı  işittim.  İşin  hakikatını anladım.  Mekârim  hazretlerinin  sözleriyle  kalbim  açıldı  ve  şimdi  îmân etmekle şereflendim” dedi.\" Ebü\'l-Hasan  Cesûkî  anlatır:  \"Bir  zaman  Mekârim  hazretlerinin yanındaydım. Allahü teâlâya olan sevgi ve muhabbetten konuştular. Bir ara; \"Kalbi,   Allahü  teâlânın  aşkıyla  yanan  âşıkların  nûru  gizlense,  her  yer karanlık  olur.\"  buyurdu.  Birden  mesciddeki  bütün  kandiller  sönüverdi. Herkes karanlıkta kaldı. Mekârim hazretleri bir müddet sessizce beklediler. Sonra;  \"Âşıkların  nûru  ortaya  çıkınca,  bütün  kandiller  pırıl  pırıl  yanar.\" buyurdu. Birden kandiller yanıverdi. Mescidin içi ışıkla dolmuştu.\" Ebü\'l-Mâcid Mübârek anlatır: \"Mekârim hazretlerinin yanındaydım. Biri gelip ona; \"Efendim! Mânevî sırlara âşinâ, hakîkatı bilenin alâmeti nedir?\" dedi. Mekârim hazretleri de; \"Sen hıristiyan birisin. Belinde zünnârın var. Ateş  ehli  olmuşsun.\"  buyurdu.  O  kişi  feryâd  edip  Mekârim  hazretlerinin ellerine kapandı ve belindeki zünnârı kesip müslüman oldu. Kendisine; \"Sâdık mürid kimdir?\" dediler. O; \"Sâdık mürîd yâni talebe kalbinden  her  şeyi  çıkaran  kimsedir.  Kadere  rızâ  gösterir.\"  buyurdu. Zâhidden sorulduğunda ise; \"Nefsiyle uğraşıp, rahatı terkeden, makam ve mevkiye  îtibâr  etmeyen,  şehvetlerden  ve  arzularından  uzak,  cihâd  eden, tefekkür  sâhibi,  istikâmetten  ayrılmayan, hakîkatı  kendine  şiâr  edinmiş, kadere inanmış, mevlâdan hayâ eden kimsedir.\" buyurdu. Muhlisi de şöyle anlattı: \"Muhlis, Allahü teâlânın rahmeti ile mahlûkâtın şerrinden  kurtulan  ve  bütün  insanların  efendisi  olan  Peygamber efendimizin emirlerine uyandır.\" buyurdu.\" Ebü\'l-Mecd  el-Mübârek bin Ahmed anlatır: \"Onun huzûrunda idim. Ah kerâmetini  bir  görsem,  diye  içimden  geçirdim.  O  sırada  bana  dönerek; \"Evlâdım!  fimdi  içeriye  şu  vasıflarda  beş  kişi  girecek  ve  yaşları  da  şu kadardır, şu kadar ömürleri kalmıştır. fu gibi şeylere temayülleri vardır.\" buyurdu. Hakîkaten buyurduğu gibi çıktı.\"', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.137616', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Irak\'ta yetişen büyük velîlerden. İsmi, Mekârim bin İdris\'tir. Irak\'ta En- Nehr-ul-Hâlis adlı yerde yaşadı. Doğum ve vefât târihleri bilinmemektedir. Kabri orada olup ziyâret edilmektedir. Mekârim hazretleri evliyânın büyüklerinden Ali bin el-Hiytî hazretlerinin mânevî  terbiyelerinde  yetişti.  İlim,  edep  ve  mânevî  yükseklikler  sâhibi zâtlar kendisini övmüştür. Hocası onun hakkında; \"Kardeşim feyh Mekârim cidden  büyük  ve  fazîletli  bir  zâttır.  Lâkin  o  bizden  sonra  anlaşılacaktır.\" Nehr-i  Hâlis  beldesindeki  talebelerin  yetiştirilme  vazîfesi  kendisine verildi. Pek çok kimse gelip talebesi olmakla şereflendi. Hikmetli sözleriyle insanlara hak yolun bilgilerini öğretti. Ebû  Muhammed  bin  İdris  anlatır:  \"Mekârim  hazretleri  bir  gün sevdiklerine  Cehennem\'i  ve  orada  yapılacak  azâbı  anlatıyordu.  Herkes korkmaya  ve  ağlamaya  başladı.  Lâkin  orada  yabancı  birisi  vardı.  O bu anlatılalardan hiç etkilenmedi ve kendi kendine; \"Bu korkutmaktır. Yoksa gerçekten  kimseyi  yakacak  bir  ateş  değildir.\"  diye  mırıldandı.  Mekârim hazretleri onun bu inkârını anlayıp ona Kur\'ân-ı kerîmdeki meâlen; \"Yemin olsun ki, onlara Rabbinin azâbından  bir  nefha  esinti  dokunsa,  elbette derler ki: \"Vay hâlimize biz hakikaten zâlimlerden olmuşuz.\"(En