INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21629, 'MUALLİM-ZÂDE AHMED EFENDİ', 'Zeyniler tarıkatı büyüklerinden ve kazasker. 1504 yılında (910 hicride) doğdu.  feyh  Muslihuddin  Efendi’nin  oğludur.  Soyu  İbrahim  Edhem hazretlerine  kadar  uzanır.  Sa’di  efendiden  ders  okudu.  Daha  sonra  Hacı Hasan   Efendinin  oğlu  Dabih  Çelebi’nin  derslerine  katıldı.  Sonra  O’nun asistanı  oldu.  Hocasının  vefatından  sonra  Bursa’da  Bayezid  Paşa medresesinde, sonra Kütahya, Tire, sonra Tekrar Bursa, Manisa ve Halep’te müderrislik yapmıştır. Sonra Bursa kadısı, daha sonra Anadolu  Kazaskeri olmuştur. Sultan ikinci Selim’in hocası Ataullah Efendiye damat olmuştur. 1572 de  (m.  980)  vefat etmiştir. Cenazesi  Bursa’ya  nakledilerek  Zeyniler mezarlığına defn edilmiştir. Makarrı olsun ona firdevsi a’la beyti vefatına tarih  düşürmüştür.  Muallimzade  Efendi  alim  ve  fetvaları  çok  sağlam güvenilir idi. Cömert ve ihsanları bol idi. Bu konuda şöhreti vardı. Temiz ve güzel giyinirdi. Vefat esnasında abdest alıp yeni elbiseler giyip, namaz kılıp kenarda tesbih ile meşgul iken vefat etti.', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.138439', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Zeyniler tarıkatı büyüklerinden ve kazasker. 1504 yılında (910 hicride) doğdu.  feyh  Muslihuddin  Efendi’nin  oğludur.  Soyu  İbrahim  Edhem hazretlerine  kadar  uzanır.  Sa’di  efendiden  ders  okudu.  Daha  sonra  Hacı Hasan   Efendinin  oğlu  Dabih  Çelebi’nin  derslerine  katıldı.  Sonra  O’nun asistanı  oldu.  Hocasının  vefatından  sonra  Bursa’da  Bayezid  Paşa medresesinde, sonra Kütahya, Tire, sonra Tekrar Bursa, Manisa ve Halep’te müderrislik yapmıştır. Sonra Bursa kadısı, daha sonra Anadolu  Kazaskeri olmuştur. Sultan ikinci Selim’in hocası Ataullah Efendiye damat olmuştur. 1572 de  (m.  980)  vefat etmiştir. Cenazesi  Bursa’ya  nakledilerek  Zeyniler mezarlığına defn edilmiştir. Makarrı olsun ona firdevsi a’la beyti vefatına tarih  düşürmüştür.  Muallimzade  Efendi  alim  ve  fetvaları  çok  sağlam güvenilir idi. Cömert ve ihsanları bol idi. Bu konuda şöhreti vardı. Temiz ve güzel giyinirdi. Vefat esnasında abdest alıp yeni elbiseler giyip, namaz kılıp kenarda tesbih ile meşgul iken vefat etti.');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21630, 'MUHAMMED BİN AHMED ZÂHİD', 'Hindistânda  632  (m.  1234]  de  vefât  etdi.  Hanefî  fıkh  âlimlerindendir. (Tergîb-üs-salât) kitâbı  meşhûrdur.  Nûr-i  Osmâniyye  kütübhânesinde Fârisî  (Tergîb-üs-salât)  kitâbının  altıncı  sahîfesinde  diyor  ki: Peygamberimiz “sallallahü aleyhi ve sellem” buyurdu ki; “İki farz nemâzı bir araya getirmek, büyük günahlardandır.” Yanî, bir nemâzı vaktinde kılmayıp, vaktinden sonra kılmak, ekber-i kebâirdir, en büyük günâhdır.', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.138469', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Hindistânda  632  (m.  1234]  de  vefât  etdi.  Hanefî  fıkh  âlimlerindendir. (Tergîb-üs-salât) kitâbı  meşhûrdur.  Nûr-i  Osmâniyye  kütübhânesinde Fârisî  (Tergîb-üs-salât)  kitâbının  altıncı  sahîfesinde  diyor  ki: Peygamberimiz “sallallahü aleyhi ve sellem” buyurdu ki; “İki farz nemâzı bir araya getirmek, büyük günahlardandır.” Yanî, bir nemâzı vaktinde kılmayıp, vaktinden sonra kılmak, ekber-i kebâirdir, en büyük günâhdır.');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21631, 'MUHAMMED BİN ALİYYÂN NESEVÎ', 'Evliyânın büyüklerinden. Bisme ilinin önde gelen âlimlerinden idi. Ebû Osman Hayrî ve Cüneyd-i Bağdâdi’nin sohbetlerinde bulundu ve onlardan ders  aldı.  Muhammed  bin  Aliyyân  ma’rifet  ehlinin  imâmı  idi.  Himmeti yüksek  ve  kerâmetleri  açık  bir  âlim  idi.  Kerâmetlerini  hiç  gizlemezdi. Muhammed bin Aliyyân’ın doğum ve vefât târihleri bilinmemekle beraber, dördüncü asırda yaşamıştır. föyle anlatılır: “Birgün aklına bir suâl geldi. Düşündü taşındı, buna bir türlü  cevap  bulamadı.  Bu  suâlinin  cevâbını  hoca  Ebû  Osman  Hayrî’den başka kimse halledemez dedi. Bulunduğu yerden suâline cevap almak için Nişâbur’a  gitti.  Suâllerinin  cevaplarını  alıncaya  kadar  yolda  hiçbir  şey yemedi ve içmedi.” Muhammed bin Aliyyân buyurdu ki: “Harama  düşerim  korkusuyla  mübahların  çoğunu  terk  etmek,  âhıret arzusunun anahtarıdır.” “Gözünün gördüğü ni’metleri senden esirgemeyeni nasıl sevmezsin? Yine O’na uymadığın hâlde, O’nu sevdiğini nasıl iddia edersin?” “Allahü teâlânın kulundan râzı olmasının alâmeti nedir?” diye sorulunca, buyurdu ki: “İbâdetlerin tatlı ve rahat, günahların zehir ve ağır gelmesidir.” “Cömert, cömertliğini küçük görmedikçe ve onu kabûl edeni kendinden üstün görmedikçe sofi olamaz.” “Fakirlerle sohbet eden kimse, onlarla; sırrın selâmeti, nefsin cömertliği, gönlün genişliği, ni’metlerle mihnetin kabûlü husûsunda sohbet etsin.” “Fakirlerin  en  fakîri,  kendisini  ganî  edecek  kimseye  (Allahü  teâlâya) ulaşamayan (hidâyet bulamayan)’dır.” “İyilik  ve  mürüvvet,  dinin  muhafızı,  insanın  koruyucusu,  mü’minin “Mevcût olan şeyde cömertlik, kendisinde olan her türlü işleri  kusurlu “Allahü  teâlâya  sevâb  umarak  veya  azâbından  korkarak  hizmet  eden, tamahını ve hasisliğini ortaya koyar. Kulun efendisine bir bedel (menfaat) karşılığı hizmet etmesi ne kötü şeydir.” “Bu yolun başlangıcında iken, nefsin âfetlerini görür ve onun gizlendiği yerleri bilir vaziyete gelmiştim. Ona karşı kalbimde dâimi sûrette bir kin vardı. Bir gün boğazımdan tilki yavrusunun çıkardığı ses gibi bir şey çıktı. Allahü teâlâ beni, onu tanır hâle getirdi. Anladım ki o, nefsdir, ayaklarımın altına  aldım,  çiğnemeye  başladım,  ama  her  tekme  atışımda  daha  da büyüyordu. Ona “Hey sana ne oluyor, her şey döğmek ve sıkıntı çekmekle helak oluyor. Sen ise daha da fazlalaşıyorsun?” dedim. Bana dedi ki: “Benim yaratılışım terstir. Bir şeye sıkıntı ve üzüntü veren bir şey, bana rahat ve zevk verir. Diğer şeylere rahatlık temin eden birşey, bana meşakkat getirir.” “Mürüvvet;  dinini  korumak  ve  nefsini  tanımak,  mü’minlere  hürmet etmek, kendi kusurlarını görmektir.”', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.138522', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Evliyânın büyüklerinden. Bisme ilinin önde gelen âlimlerinden idi. Ebû Osman Hayrî ve Cüneyd-i Bağdâdi’nin sohbetlerinde bulundu ve onlardan ders  aldı.  Muhammed  bin  Aliyyân  ma’rifet  ehlinin  imâmı  idi.  Himmeti yüksek  ve  kerâmetleri  açık  bir  âlim  idi.  Kerâmetlerini  hiç  gizlemezdi. Muhammed bin Aliyyân’ın doğum ve vefât târihleri bilinmemekle beraber, dördüncü asırda yaşamıştır. föyle anlatılır: “Birgün aklına bir suâl geldi. Düşündü taşındı, buna bir türlü  cevap  bulamadı.  Bu  suâlinin  cevâbını  hoca  Ebû  Osman  Hayrî’den başka kimse halledemez dedi. Bulunduğu yerden suâline cevap almak için Nişâbur’a  gitti.  Suâllerinin  cevaplarını  alıncaya  kadar  yolda  hiçbir  şey yemedi ve içmedi.” Muhammed bin Aliyyân buyurdu ki: “Harama  düşerim  korkusuyla  mübahların  çoğunu  terk  etmek,  âhıret arzusunun anahtarıdır.” “Gözünün gördüğü ni’metleri senden esirgemeyeni nasıl sevmezsin? Yine O’na uymadığın hâlde, O’nu sevdiğini nasıl iddia edersin?” “Allahü teâlânın kulundan râzı olmasının alâmeti nedir?” diye sorulunca, buyurdu ki: “İbâdetlerin tatlı ve rahat, günahların zehir ve ağır gelmesidir.” “Cömert, cömertliğini küçük görmedikçe ve onu kabûl edeni kendinden üstün görmedikçe sofi olamaz.” “Fakirlerle sohbet eden kimse, onlarla; sırrın selâmeti, nefsin cömertliği, gönlün genişliği, ni’metlerle mihnetin kabûlü husûsunda sohbet etsin.” “Fakirlerin  en  fakîri,  kendisini  ganî  edecek  kimseye  (Allahü  teâlâya) ulaşamayan (hidâyet bulamayan)’dır.” “İyilik  ve  mürüvvet,  dinin  muhafızı,  insanın  koruyucusu,  mü’minin “Mevcût olan şeyde cömertlik, kendisinde olan her türlü işleri  kusurlu “Allahü  teâlâya  sevâb  umarak  veya  azâbından  korkarak  hizmet  eden, tamahını ve hasisliğini ortaya koyar. Kulun efendisine bir bedel (menfaat) karşılığı hizmet etmesi ne kötü şeydir.” “Bu yolun başlangıcında iken, nefsin âfetlerini görür ve onun gizlendiği yerleri bilir vaziyete gelmiştim. Ona karşı kalbimde dâimi sûrette bir kin vardı. Bir gün boğazımdan tilki yavrusunun çıkardığı ses gibi bir şey çıktı. Allahü teâlâ beni, onu tanır hâle getirdi. Anladım ki o, nefsdir, ayaklarımın altına  aldım,  çiğnemeye  başladım,  ama  her  tekme  atışımda  daha  da büyüyordu. Ona “Hey sana ne oluyor, her şey döğmek ve sıkıntı çekmekle helak oluyor. Sen ise daha da fazlalaşıyorsun?” dedim. Bana dedi ki: “Benim yaratılışım terstir. Bir şeye sıkıntı ve üzüntü veren bir şey, bana rahat ve zevk verir. Diğer şeylere rahatlık temin eden birşey, bana meşakkat getirir.” “Mürüvvet;  dinini  korumak  ve  nefsini  tanımak,  mü’minlere  hürmet etmek, kendi kusurlarını görmektir.”');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21632, 'MEVLÂNÂ EBÛ SAÎD EVBEHÎ', 'Ubeydullah-ı Ahrâr\'ın talebelerinden büyük velî. Doğum ve vefât târihleri belli değildir. Hayâtı hakkında fazla bilgi yoktur. On beşinci asrın sonlarında Küçük yaşta tahsil hayâtına başlayan Mevlânâ Ebû Saîd\'de, medresede okurken bir gün zâhirî ilimlere karşı soğukluk, tasavvufa ise bir rağbet hâsıl oldu.  Medreseden  ayrılıp,  gönül  ehli  rehber  aramaya  başladı.  Yolda giderken,  ilim  talebelerinden  birine  rastladı.  \"Nereden  geliyorsun?\"  diye sorunca;   \"Kuh-i  Nûr  denilen  yerde  feyh  İlyâs  Işkî  nâmında  bir  zâtın yanından geliyorum” dedi ve o zâtı anlata anlata bitiremedi. Bunun üzerine gayr-i ihtiyâri bu zatın sohbetinde bulunmak için huzuruna gitmeye karar verdi.  Kuh-i Nûr\'a doğru yola çıktı. Yolda Ubeydullah-ı Ahrâr hazretlerinin dergâhına  uğradı.  Bu  sırada  Ubeydullah-ı  Ahrâr  bir  yerden  gelmiş,  attan iniyordu. Kendi kendine; \"Hâce hazretlerini hiç görmedim. Ynce onu görüp, sohbetini   dinleleyim,   sonra   Kuh-i  Nûr\'a  gideyim”  dedi.Bu  düşünce  ile Hâce\'nin  peşinden  dergâha  girdi.Hâce\'nin  karşısına  oturdu.  Bir  müddet sükûttan  sonra  Hâce  Ubeydullah  mübârek  başını  kaldırıp,  ona  doğru Sohbetimde kal, ne işin var dağda Sığınak yok, bugün gördüğün dağda. beytini  okuyunca,  hâli  değişti.  İçinden;  \"Eğer  bu  beyti  benim  için okudularsa,  bir kere daha okusalar” dedi. Bunun üzerine Hâce Ubeydullah, Mevlânâ  Ebû  Saîd\'e  doğru  dönüp;  \"Mevlânâ  Ebû  Saîd!  Bu  beyit  senin içindir.\"  diyerek  tekrar  okudu.  Daha  sonra  Hâce  Ubeydullah  dergâhtan ayrıldı. Mevlânâ Ebû Saîd, ismini söylemesinden ve Kûh\'e gideceğini  kimse bilmediği  halde,  oraya  gitmemesine  işâret  etmesinden  dolayı  hayret  etti. Hemen kaldığı medrese talebelerine, kitaplarım ve eşyâlarım sizlerin olsun diye haber gönderdi. Bu karşılamadan sonra Mevlânâ Ebû Saîd, Hâce Ubeydullah\'a bağlanarak, derslerine devâm etti. Bir sene sonra, zaman zaman hocasının iltifatlarına kavuştu. Bu iltifatları bir ara kesildi. Bunun üzerine Mevlânâ Ebû Saîd\'de öyle bir kabz, sıkıntı ve daralma hâli meydana gelip helâk olma noktasına geldi. Bu hal yirmi gün kadar devâm etti. Mevlânâ Ebû Saîd bâzı büyüklerin; \"Teheccüd namazından sonra Yâsîn-i şerîf okuyup sonra her ne duâ edilirse, makbûl  olur.\"  sözüne  izâfeten  bir  gece  teheccüd  vaktinde  Yâsîn-i  şerîf okuyup;  \"Yâ  Rabbî!  Eğer  bende  hocam  Ubeydullah-ı  Ahrâr  hazretlerini rahatsız  eden  bir  şey  varsa,  onu  benden  gider.  Eğer  benim  istidâd  ve kâbiliyetimde hocamı rahatsız edecek bir hâlim varsa vücûdumu ortadan kaldır veya beni bu dergâhtan uzak eyle.\" diye yalvardı. Çok ağlayıp göz yaşı döktü. Sabahleyin Ubeydullah-ı Ahrâr\'ın sohbetine gittiğinde, hocasının ilk sözleri şu oldu: \"Bir şeyden sıkıldığınızda, ya ölümünüzü yâhut dergâhtan uzaklaşmayı   istiyorsunuz.\"   buyurdu.   Bundan,   Ubeydullah-ı   Ahrâr hazretlerinin böyle sıkıntılarla kendisini terbiye etmekte olduğunu anladı. Bundan sonra yine önceki rahatlık hâli hâsıl oldu. Mevlânâ Ebû Saîd, Hâce Ubeydullah\'ın sohbetlerinde kemâle geldikten sonra hocasından diploma alarak, insanlara doğru yolu anlatmaya çalıştı. Ymrünün sonuna kadar talebe yetiştirmekle meşgûl oldu.', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.138575', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Ubeydullah-ı Ahrâr\'ın talebelerinden büyük velî. Doğum ve vefât târihleri belli değildir. Hayâtı hakkında fazla bilgi yoktur. On beşinci asrın sonlarında Küçük yaşta tahsil hayâtına başlayan Mevlânâ Ebû Saîd\'de, medresede okurken bir gün zâhirî ilimlere karşı soğukluk, tasavvufa ise bir rağbet hâsıl oldu.  Medreseden  ayrılıp,  gönül  ehli  rehber  aramaya  başladı.  Yolda giderken,  ilim  talebelerinden  birine  rastladı.  \"Nereden  geliyorsun?\"  diye sorunca;   \"Kuh-i  Nûr  denilen  yerde  feyh  İlyâs  Işkî  nâmında  bir  zâtın yanından geliyorum” dedi ve o zâtı anlata anlata bitiremedi. Bunun üzerine gayr-i ihtiyâri bu zatın sohbetinde bulunmak için huzuruna gitmeye karar verdi.  Kuh-i Nûr\'a doğru yola çıktı. Yolda Ubeydullah-ı Ahrâr hazretlerinin dergâhına  uğradı.  Bu  sırada  Ubeydullah-ı  Ahrâr  bir  yerden  gelmiş,  attan iniyordu. Kendi kendine; \"Hâce hazretlerini hiç görmedim. Ynce onu görüp, sohbetini   dinleleyim,   sonra   Kuh-i  Nûr\'a  gideyim”  dedi.Bu  düşünce  ile Hâce\'nin  peşinden  dergâha  girdi.Hâce\'nin  karşısına  oturdu.  Bir  müddet sükûttan  sonra  Hâce  Ubeydullah  mübârek  başını  kaldırıp,  ona  doğru Sohbetimde kal, ne işin var dağda Sığınak yok, bugün gördüğün dağda. beytini  okuyunca,  hâli  değişti.  İçinden;  \"Eğer  bu  beyti  benim  için okudularsa,  bir kere daha okusalar” dedi. Bunun üzerine Hâce Ubeydullah, Mevlânâ  Ebû  Saîd\'e  doğru  dönüp;  \"Mevlânâ  Ebû  Saîd!  Bu  beyit  senin içindir.\"  diyerek  tekrar  okudu.  Daha  sonra  Hâce  Ubeydullah  dergâhtan ayrıldı. Mevlânâ Ebû Saîd, ismini söylemesinden ve Kûh\'e gideceğini  kimse bilmediği  halde,  oraya  gitmemesine  işâret  etmesinden  dolayı  hayret  etti. Hemen kaldığı medrese talebelerine, kitaplarım ve eşyâlarım sizlerin olsun diye haber gönderdi. Bu karşılamadan sonra Mevlânâ Ebû Saîd, Hâce Ubeydullah\'a bağlanarak, derslerine devâm etti. Bir sene sonra, zaman zaman hocasının iltifatlarına kavuştu. Bu iltifatları bir ara kesildi. Bunun üzerine Mevlânâ Ebû Saîd\'de öyle bir kabz, sıkıntı ve daralma hâli meydana gelip helâk olma noktasına geldi. Bu hal yirmi gün kadar devâm etti. Mevlânâ Ebû Saîd bâzı büyüklerin; \"Teheccüd namazından sonra Yâsîn-i şerîf okuyup sonra her ne duâ edilirse, makbûl  olur.\"  sözüne  izâfeten  bir  gece  teheccüd  vaktinde  Yâsîn-i  şerîf okuyup;  \"Yâ  Rabbî!  Eğer  bende  hocam  Ubeydullah-ı  Ahrâr  hazretlerini rahatsız  eden  bir  şey  varsa,  onu  benden  gider.  Eğer  benim  istidâd  ve kâbiliyetimde hocamı rahatsız edecek bir hâlim varsa vücûdumu ortadan kaldır veya beni bu dergâhtan uzak eyle.\" diye yalvardı. Çok ağlayıp göz yaşı döktü. Sabahleyin Ubeydullah-ı Ahrâr\'ın sohbetine gittiğinde, hocasının ilk sözleri şu oldu: \"Bir şeyden sıkıldığınızda, ya ölümünüzü yâhut dergâhtan uzaklaşmayı   istiyorsunuz.\"   buyurdu.   Bundan,   Ubeydullah-ı   Ahrâr hazretlerinin böyle sıkıntılarla kendisini terbiye etmekte olduğunu anladı. Bundan sonra yine önceki rahatlık hâli hâsıl oldu. Mevlânâ Ebû Saîd, Hâce Ubeydullah\'ın sohbetlerinde kemâle geldikten sonra hocasından diploma alarak, insanlara doğru yolu anlatmaya çalıştı. Ymrünün sonuna kadar talebe yetiştirmekle meşgûl oldu.');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21633, 'MUHAMMED BİN FADL BELHÎ', 'Muhamme', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.138904', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Evliyânın büyüklerinden. Künyesi Ebû Abdullah olup, adı Muhammed bin Fadl bin Abbâs bin Hafs’dır. Aslen Belhlidir. Belh’de onu anlıyamadıkları için şehirden sürmüşler, o da Semerkand’a yerleşmiştir. Muhammed bin Fadl, Ahmed  bin  Hadraveyh’in  talebesi  olup,  daha  birçok  âlimin  sohbetinde bulunmuştur. Semerkand’da kadılık yaptı. 319 (m. 9311 senesinde burada Ebû Osman, Muhammed bin Fadl için şöyle demiştir: “fayet kendimde biraz kuvvet bulsam, kardeşim Muhammed bin Fadl’a giderim. Çünkü onu görmekle  kalbim  ferah  buluyor.”  Ayrıca  şöyle  demiştir:  “Muhammed  bin Fadl, insanların iyisini kötüsünden seçip ayırandır.” Hacca  giderken  Nişâbûr’a  uğradığında,  sohbet  etmesini  istediler. Muhammed  bin  Fadl,  Kürsiye  çıkarak  “Allahü  teâlâ  büyüktür.  Allahü teâlânın  zikri  büyüktür.  Rızâ,  en  büyük  olan  Allahü  teâlâdandır”  dedi  ve Ebû  Osman  Hayra,  Muhammed  bin  Fadl’a  yazdığı  bir  mektûbta “Bedbahlığın  alâmeti  nedir?”  diye sorduğunda,  cevâb  olarak  “Bedbahlığın alâmeti üçtür: Bir kimseye ilim verilir ama amel etmek için yardım edilmez. Amel  etmeye  yardım  edilir  ama  bu  sefer  de  ihlâsdan  mahrûm  edilir. oçüncüsü  ise  âlimler  ile sohbet  etmek  nasîb  olur,  fakat  onlara  hürmet etmekten mahrûm edilir.” Muhammed bin Fadl’ın rivâyet ettiği hadîs-i şerîfte Peygamber efendimiz (aleyhisselâm),  “Her  peygambere,  peygamberliğini  isbât  ederek,  kendi zamanına göre yepyeni ve kimsenin yapamıyacağı (harikulade) bir takım mu’cizeler  verilmiştir.  füphesiz  bana  verilen  en  büyük  mu’cize,  Kur’ân-ı kerîm mu’cizesidir. Umarım, kıyâmet günü peygamberler arasından en çok ümmeti bulunan ben olacağım.” buyurdular. Muhammed bin Fadl buyurdu ki: “İslâmiyet nûrlarının kalblerden ayrılıp, kalblerin kararmasına dört şey sebeb oldu: Bildikleri ile amel etmemek. Bilmiyerek yapmak. Bilmediklerini öğrenmemek. Başkalarının öğrenmelerine mâni olmak.” “İnsanların en ârifi, Allahü teâlânın emirlerini yerine getirme husûsunda gayret  sarf  eden  ve  Peygamber  efendimizin  (aleyhisselâm)  sünnet-i seniyyesine tâbi olanlardır. “Errahmân demek; Allahü teâlânın, dünyâda iyi ve kötü herkese ihsân etmesi demektir.” “İnsanların,  nefsin  istek  ve  arzularından  uzaklaşmak  için  ıssız  çöllere çekilmesi,  ne  kadar  şaşılacak  bir  şeydir.  Zira  insanların  arasına  çıkmak, Peygamberlerin sünnetidir.” “İlim kaledir. Cehâlet meçhûldür. İyi arkadaş rızıkdır. Kötü arkadaş keder ve  üzüntüdür.  Akrabayı  ziyâret  etmek  hasenedir.  Sıla-i   rahmi   kesmek musîbettir.  Sabır  kuvvettir.  Cür’et  acizliktir.  Doğruluk  kuvvettir.  Yalan zayıflıktır. Ma’rifet doğruluktur. Akıl tecrübedir.” “İlmin  tadından  zevk  alan  kişi,  onsuz  yapamaz.  Devamlı ilimle meşgûl “Zâhidlerin gözleri ağlar. Âriflerin ise kalbleri ağlar.” “Bir müridi (talebeyi) dünyâ malı toplamaya istekli görürsen, bil ki, onun bu isteği aşağılık, Rabbine sırt çevirme ve başaşağı dönme nişanıdır.” “İlim üç kısımdır: İlm-i billah; Allahü teâlâyı kâmil sıfatlarıyla bilmektir. İlm-i  minallah;  zâhirî  ve  batınî  bilgiler,  haram  ve  helâl  bilgileri,  emir  ve yasaklar  ile  alâkalı  bilgilerdir.  İlm-i  meâllah;  havf  ve  recâ  ilmi,  Allahü teâlâdan  korkup  bununla  beraber  O’ndan  ümidi  kesmeme,  O’na  sevgi  ve muhabbet ilmidir.” “fükrün neticesi; Allahü teâlâyı sevmek ve O’ndan korkmaktır.” “Dil  ile  zikretmek,  günahlara  keffârettir.  Kalb  ile  zikr,  Allahü  teâlâya yakınlık ve mertebenin yükselmesidir.” “Güneşin doğuşundan, güneşe gözle bakılabildiği sürede (işrak zamanına kadar) namaz kılmak haramdır. Ancak işrak vaktinden sonra nafile kılmak');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21634, 'MUHAMMED BİN NADR HÂRİSÎ', 'Tebe-i tabiînden. Zamanında, Kûfe’nin en çok ibâdet edeni diye tanınırdı. Her yerde hakkı konuşarak, emr-i bi’l-ma’rûf ve nehyi ani’l-münkeri (Allahü teâlânın  emirlerinin  yapılmasını,  yasakladıklarından  da  sakınılmasım) Künyesi Ebû Abdurrahmân’dır. Doğumu, tahsili ve vefât târihi hakkında bilgi  verilmemekle  beraber,  Kûfe’de  yaşadığı  ve  orada  vefât  ettiği bilinmektedir.  Evzâî’den  (radıyallahü  anh)  hadîs-i  şerîfler  rivâyet  etmiş, ondan da, Ebü’l-Ahvâz, Yahyâ bin Ymer es-Sekâfî ve Abdullah İbni Mübârek (radıyallahü  anh)  rivâyette  bulunmuştur.  Yanlış  nakletme  korkusunun çokluğundan  dolayı,  çok  az  sayıda  hadîs-i şerîf  rivâyet  etmiştir.  Kütüb-i sitte’de rivâyeti yoktur. İbâd  bin  Kuleyb  (radıyallahü  anh)  anlatır:  Muhammed  bin  Nadr, Abdullah  bin  Mübârek  ve  Fudayl  bin  Iyâd’la  birlikte  uzun  zaman  yemek yaptık, yedik, içtik. Muhammed bin Nadr’ın bize hiç itiraz edip, muhalefet ettiğini görmedik. Abdullah bin Mübârek sebebini sorunca buyurdu ki: “Yâ Abdullah! Bir insan iyi kimselerle beraber olduğu zaman onlara muhalefet etmekten  haya  eder  ve  kerem  sahibi  olur.”  Abdullah  bin  Mübârek,  “O, sizsiniz” deyince, “Hayır ben değilim. Fakat iyi insanlar “evet” derlerse ben de “evet” derim. “Hayır” derlerse ben de “hayır” derim” buyurdu. Hasan bin Rebiî anlatır: Bir zaman Zübeyroğullarından bir şahıs Kûfe’ye gelip Muhammed bin Nadr’ın yanında misâfir kaldı. Kûfe’den ayrılışında, o şahısla yol arkadaşlığı yaptık. O’ndan Muhammed bin Nadr hazretlerinin ne konuştuğunu  sorduk.  O  da  “Yemîn  ederim.  Ben  epeyce  yanında  kaldım. Fakat,  ağzından  tek  kelime  çıktığını  görmedim.  Hep  ibâdet  eder  veya zikrederdi.”  “Hiçbir  ihtiyâcı  olmaz  mıydı?”  diye  sordum.  O  da,  “Evet ihtiyâçları  olurdu.  Bir  ihtiyâcı  olduğu  zaman  oğluna  bakar,  o  da  hemen kalkıp, gider babasının ihtiyâcını görürdü” dedi. Muhammed bin Nadr hazretleri, yazın sıcak günlerinde hep oruç tutardı. Ba’zan çeşmenin başına gelir serinlemek için üzerine su dökerdi. Kûfeliler de O’nu seyreder, bu soğuk suyu ne kadar canı çeker derlerdi. O da onlara bakar “Hayır hiç iştahım çekmez” buyururdu. Abdullah  bin  Mübârek  (radıyallahü  anh)  anlatır:  Ylümünden  iki  sene önce  gece  uykusunu  tamamen  terk  etmişti.  Bir  müddet’  sonra  Kaylûle uykusunu da terk etti. Ebû Refid anlatır: Birgün Muhammed’in (radıyallahü anh) kabristandan geldiğini  görüp,  “Bu  öğle  vakti  orada  ne  yaptığını”  sordum.  Cevaben “Kabristana  gidince  gözlerim  dünyâya  bakmaktan  iğrenir  ve  her  zaman gözlerimin kapalı olup, orada açılmasını arzularım.” Ubeydullah bin Muhammed el-Kirmânî’den   nakledilir:   Birgün Muhammed  bin  Nadr’ın  evine  gittim,  yalnızdı.  Niye  insanlardan  uzlet ettiğini  sordum,  beni  yanlarına  çağırdılar.  “Siz  insanlardan  uzak duruyorsunuz,  beni  niçin  yanınıza  çağırıyorsunuz?”  dedim.  O  da,  “Ben Allahü teâlâyı zikretmeyenlerden kaçarım. Zikredenlerden değil” buyurdu. Abdullah  bin  Mübârek  hazretleri  anlatır:  Muhammed  bin  Nadr hazretleriyle bir gemide gidiyorduk. Bir ara neş’eli bir şekilde konuşmaya başladı. Tanıyamadığım bir ses de ona cevap veriyordu. Zekeriyya  bin  Adî  anlatır:  Muhammed  bin  Nadr  hazretlerinin  yanında ölümden bahsedildiği zaman, çok mahzûnlaşır kemiklerinden ses gelirdi. Müslim  isminde  birinden  alacağı  vardı.  Haber  gönderip “Falan  gün geleceğim,  alacağımı  hazırla”  dedi.  O  da  hazırlığını  yaptı.  Söylediği  gün Müslim’e “Benim sendeki alacağımı hediye etmem, teslim almamdan daha hayırlıdır. Sana onu hediye ettim” buyurdu. Buyurdu ki: “İlmin  evveli  sükûttur.  Sonra  onunla  uğraşmaktır.  Sonra  ezberlemek, sonra onunla amel etmek, sonra da başkalarına öğretmektir.” “Allahü teâlâ, Hazret-i Musa’ya (aleyhisselâm): “Uyanık ol, kendine dost ara,  sevincine  katılarak  seninle  neş’elenmeyen  bir  dostu  yanından uzaklaştır. Onunla arkadaşlık yapma, çünkü böyle dost kalbine sıkıntı verir. O, senin dostun değil, düşmanındır. Beni çok an ki, bana şükretmiş olasın ve ben de ni’metimi arttırmış olayım” diye vahyetti.” Duâ ederken, “Yazıklar olsun bana! İnsanlara emîn oldum da, Rabbime karşı ihânet ettim. Ne olurdu. İnsanlar bana “O adam hâindir!” deselerdi de, Allahü  teâlânın  emânetlerine  hiyânet  etmeseydim”  derdi.  Çok  ibâdet etmesine rağmen hepsini az görür, devamlı tövbe ve istiğfar ederdi.', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.139808', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Tebe-i tabiînden. Zamanında, Kûfe’nin en çok ibâdet edeni diye tanınırdı. Her yerde hakkı konuşarak, emr-i bi’l-ma’rûf ve nehyi ani’l-münkeri (Allahü teâlânın  emirlerinin  yapılmasını,  yasakladıklarından  da  sakınılmasım) Künyesi Ebû Abdurrahmân’dır. Doğumu, tahsili ve vefât târihi hakkında bilgi  verilmemekle  beraber,  Kûfe’de  yaşadığı  ve  orada  vefât  ettiği bilinmektedir.  Evzâî’den  (radıyallahü  anh)  hadîs-i  şerîfler  rivâyet  etmiş, ondan da, Ebü’l-Ahvâz, Yahyâ bin Ymer es-Sekâfî ve Abdullah İbni Mübârek (radıyallahü  anh)  rivâyette  bulunmuştur.  Yanlış  nakletme  korkusunun çokluğundan  dolayı,  çok  az  sayıda  hadîs-i şerîf  rivâyet  etmiştir.  Kütüb-i sitte’de rivâyeti yoktur. İbâd  bin  Kuleyb  (radıyallahü  anh)  anlatır:  Muhammed  bin  Nadr, Abdullah  bin  Mübârek  ve  Fudayl  bin  Iyâd’la  birlikte  uzun  zaman  yemek yaptık, yedik, içtik. Muhammed bin Nadr’ın bize hiç itiraz edip, muhalefet ettiğini görmedik. Abdullah bin Mübârek sebebini sorunca buyurdu ki: “Yâ Abdullah! Bir insan iyi kimselerle beraber olduğu zaman onlara muhalefet etmekten  haya  eder  ve  kerem  sahibi  olur.”  Abdullah  bin  Mübârek,  “O, sizsiniz” deyince, “Hayır ben değilim. Fakat iyi insanlar “evet” derler