INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21652, 'MUSTAFA İMÂDÎ', 'Anadolu  velîlerinden.  İsmi, Mustafa  bin  Muhammed,  nisbesi  İmâdî’dir. Meşrebi,  Zeyniyye’dir.  Ali  Kuçcu’nun  kardeşi,  feyh  Yavsî  Muhyiddîn-i İskilîbî’nin babası, Ebüssü’ûd Efendi’nin dedesidir. Doğum ve vefât tarihleri belli değildir. Semerkand’da doğdu. İskilip’te vefât tetti. Kabri feyh Yavsî Camii bitişiğindedir. Babası Muhammed Efendi, Semerkand Valisi Uluğ Bey’in doğancıbaşısı idi. İlk tahsilini babasından alan Mustafa Efendi, Uluğ Beyin elinde yetişip ilim  öğrendi.  Zeynüddîn  el-Hâfînin  halifelerinin  sohbetinde  kemâle  geldi. Uluğ Bey’in 1449 senesinde öldürülmesinden sonra Semerkandı terkedip kardeşleri Ali Kuşçu ve Abdünnebî ile birlikte Anadolu’ya geldiler. Ali Kuşcu, Akkoyunlu  Hasan  Beyin elçisi sıfatıyla  İstanbul’a gitmiş,  kendisi  İskilib’in İmâd  köyüne  yerleşerek  burada  evlenmiştir.  İskilip’te  Zeyniyye  tarikatı şeyhliği yapmış ve burada vefat etmiştir.', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.143735', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Anadolu  velîlerinden.  İsmi, Mustafa  bin  Muhammed,  nisbesi  İmâdî’dir. Meşrebi,  Zeyniyye’dir.  Ali  Kuçcu’nun  kardeşi,  feyh  Yavsî  Muhyiddîn-i İskilîbî’nin babası, Ebüssü’ûd Efendi’nin dedesidir. Doğum ve vefât tarihleri belli değildir. Semerkand’da doğdu. İskilip’te vefât tetti. Kabri feyh Yavsî Camii bitişiğindedir. Babası Muhammed Efendi, Semerkand Valisi Uluğ Bey’in doğancıbaşısı idi. İlk tahsilini babasından alan Mustafa Efendi, Uluğ Beyin elinde yetişip ilim  öğrendi.  Zeynüddîn  el-Hâfînin  halifelerinin  sohbetinde  kemâle  geldi. Uluğ Bey’in 1449 senesinde öldürülmesinden sonra Semerkandı terkedip kardeşleri Ali Kuşçu ve Abdünnebî ile birlikte Anadolu’ya geldiler. Ali Kuşcu, Akkoyunlu  Hasan  Beyin elçisi sıfatıyla  İstanbul’a gitmiş,  kendisi  İskilib’in İmâd  köyüne  yerleşerek  burada  evlenmiştir.  İskilip’te  Zeyniyye  tarikatı şeyhliği yapmış ve burada vefat etmiştir.');
INSERT INTO `scholars` (`id`, `fullName`, `lineage`, `birthDate`, `deathDate`, `photoUrl`, `createdAt`, `updatedAt`, `latitude`, `longitude`, `locationName`, `locationDescription`, `coverImage`, `biography`) VALUES (21653, 'MUSLİHUDDÎN TAVÎL', 'Osmanlı  âlimlerinden ve  Bursa  velîlerinden. İsmi  Muslihuddîn’dir. Muslihuddîn Tavîl diye bilinir. Kastamonu’ya bağlı Küre’de doğdu. Doğum ve  vefât  târihleri  kesin  olarak  bilinmemektedir.  Onuncu  asrın  başlarında Bursa’da vefât etti. Orada medfûndur. Zamanının  âlimlerinden  aklî  ve  naklî  ilimleri  tahsil  etti.  Birçok  ilmî eserleri  okuyup  müzâkere  etti  ve  yüksek  derecelere  ulaştı.  föhreti  her tarafta duyulup, âlimler arasında yüksek bir dereceye sahip olduktan sonra tasavvufa  yöneldi.  Zamanındaki  tasavvuf ehli  birçok  zâtların  sohbetinde bulundu. Fakat hiçbirinden kalbi mutmain olup feyz alamadı. En sonunda feyh  ilâhî  hazretlerine  talebe  olup,  hizmetinde  bulundu.  Ondan  feyz  alıp yükseldi. Vefât  edinceye kadar  onun  yanından  ve  hizmetinden  ayrılmadı. Tasavvufda yüksek mertebelere ulaştı ve kemâle erdi. Ymrü boyunca kötü insanlardan uzak oldu. Muslihuddîn  Tavîl,  heybetli  ve  celâl  sahibi  idi.  Ama  sohbet  esnasında yumuşak  ve  güleryüzlü  idi.  fakâyik  müellifi Taşköprülüzâde anlatır: “Küçüklüğümde feyh Muslihuddîn Tavîl’in huzûruna gidip, heybetli yüzünü görmüş  idim.  O  zaman  görünüşünün  celâlinden  korktum.  O  heybet  ve celâlinden olan korku hâlen içimde durmaktadır.” Muslihuddîn Tavîl hazretleri, Sultan II. Bâyezîd’e saltanatı zamanında bir mektûp  gönderip,  bu  mektûbun baş  tarafında  Arş  ve  Kürsî  ile  ilgili  bilgi verdikten  sonra,  mektûbun  sonuna  doğru;  “Bir  yerde  zulüm  ve  bid’atler yaygınlaşsa,  o  beldenin  sâlihleri  ve  âlimleri  Peygamber  efendimizi (aleyhisselâm) rü’yâsında üzgün ve hüzünlü bir şekilde görseler, mübârek yüzlerinin  bu  hâli  gazâb  işâretidir.  Resûlullah’ı  (aleyhisselâm)  rü’yâmda üzüntülü  ve  hüzünlü  gördüm.  Zulüm  ve  bid’at  karanlığından  kalblerin karardığını, Küre’de birçok zulüm ve bid’atin yaygınlaştığını anladım” diye yazıp, Pâdişâh’a genişçe bildirdi. Bunun üzerine Pâdişâh da, zulüm ve bid’at azgınlıklarını adâlet ve ihsânla yok edip, haksızlıkları ortadan kaldırdı. Nakledilir ki, Zâhir ilminde âlim olan bir kimse, feyh Muslihuddîn Tavîl’e gelip,  “Ben  bu  yolu  terk  etmek  istiyorum”  dedi.  Muslihuddîn  Tavîl  ona; “Hangi yolu terk etmek istiyorsun?” diye sorunca, o da; “İlim yolunu terk etmek istiyorum” dedi. Muslihuddîn Tavîl kızarak; “Bundan güzel yol mu vardır ki onu terk etmek istersin? ilim yolu öyle bir yoldur ki, o yola giren dünyâ  ve  âhıret  saadetine  kavuşur.  Onu  terk  etmek,  doğru  yoldan ayrılmaktır”  buyurdu.  Bu  cevap  karşısında  o  kimse  utanıp  birşey söyliyemedi. Bu sırada mecliste bulunanlara; “Kâdılardan Germiyanlı Sinân Çelebî  diye  bir  zât  vardır  bilir  misiniz?”  diye  sordu.  Orada  hazır bulunanlardan ba’zı kimseler; “İlim ehli bir kadıdır, yüksek derece sahibidir. Biz onun adâletli ve yüksek bir zât olduğunu biliriz dediler. Muslihuddîn Tavîl  hazretleri  buyurdu  ki:  “Sinân  Çelebî,  tasavvuf  yolunu  tamamlayıp, birçok yüksek derecelere ulaştı ve kerâmetler sahibi oldu. Zâhiren kadılık vazîfesini yürütüp, adâletle hükm eder, Allahü teâlânın dîninin emirlerini ve Peygamber efendimizin (aleyhisselâm) sünnetini anlatmakla meşgûl olurdu. Bâtınen nefsini tezkiye ile ma’nevî saadetlere kavuşmağa çalışırdı. Zâhirde olan hâllerinden, bâtında olan güzel hâlleri daha çoktu. Ama sizden onun bu hâlini bilen yoktur.” Bu sözü bittikten sonra; “Yüksek gayret ve arzusu olan talebe,  ister  kadı,  ister  müderris  olsun,  yüksek  ve  olgun  bir  zâta  tâbi olduktan  sonra,  farkında  olmadan tasavvuf  yolunu  tamamlayıp  kemâle ulaşır. Dünyevî ve dînî vazîfeler onun Hak yoluna girmesine mâni değildir. Yüksek rütbeler gayeye ulaşmaya perde olmaz” buyurdu. Nakledilir ki, Muslihuddîn Tavîl, Bursa’da feyh Tâceddîn Efendi’nin kabri yanına bir hasır serip, kırk gün müddetle sabah namazı zamanında gelip, o hasırın üzerinde Yâsîn sûresini okuyup ibâdet etti. Kırk gün tamâm olunca vefât edip, o hasırın bulunduğu yerde defn olundu.', NULL, NULL, '/uploads/pexels-photo-133172.jpeg', '2025-09-22 18:55:33.143805', '2025-09-22 19:29:45.040062', NULL, NULL, NULL, NULL, 'uploads/coverImage/coverImage.jpg', 'Osmanlı  âlimlerinden ve  Bursa  velîlerinden. İsmi  Muslihuddîn’dir. Muslihuddîn Tavîl diye bilinir. Kastamonu’ya bağlı Küre’de doğdu. Doğum ve  vefât  târihleri  kesin  olarak  bilinmemektedir.  Onuncu  asrın  başlarında Bursa’da vefât etti. Orada medfûndur. Zamanının  âlimlerinden  aklî  ve  naklî  ilimleri  tahsil  etti.  Birçok  ilmî eserleri  okuyup  müzâkere  etti  ve  yüksek  derecelere  ulaştı.  föhreti  her tarafta duyulup, âlimler arasında yüksek bir dereceye sahip olduktan sonra tasavvufa  yöneldi.  Zamanındaki  tasavvuf ehli  birçok  zâtların  sohbetinde bulundu. Fakat hiçbirinden kalbi mutmain olup feyz alamadı. En sonunda feyh  ilâhî  hazretlerine  talebe  olup,  hizmetinde  bulundu.  Ondan  feyz  alıp yükseldi. Vefât  edinceye kadar  onun  yanından  ve  hizmetinden  ayrılmadı. Tasavvufda yüksek mertebelere ulaştı ve kemâle erdi. Ymrü boyunca kötü insanlardan uzak oldu. Muslihuddîn  Tavîl,  heybetli  ve  celâl  sahibi  idi.  Ama  sohbet  esnasında yumuşak  ve  güleryüzlü  idi.  fakâyik  müellifi Taşköprülüzâde anlatır: “Küçüklüğümde feyh Muslihuddîn Tavîl’in huzûruna gidip, heybetli yüzünü görmüş  idim.  O  zaman  görünüşünün  celâlinden  korktum.  O  heybet  ve celâlinden olan korku hâlen içimde durmaktadır.” Muslihuddîn Tavîl hazretleri, Sultan II. Bâyezîd’e saltanatı zamanında bir mektûp  gönderip,  bu  mektûbun baş  tarafında  Arş  ve  Kürsî  ile  ilgili  bilgi verdikten  sonra,  mektûbun  sonuna  doğru;  “Bir  yerde  zulüm  ve  bid’atler yaygınlaşsa,  o  beldenin  sâlihleri  ve  âlimleri  Peygamber  efendimizi (aleyhisselâm) rü’yâsında üzgün ve hüzünlü bir şekilde görseler, mübârek yüzlerinin  bu  hâ